DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `departments`;
DROP TABLE IF EXISTS `campuses`;
DROP TABLE IF EXISTS `roles`;
DROP TABLE IF EXISTS `gallery_item_tts_audios`;
DROP TABLE IF EXISTS `gallery_images`;
DROP TABLE IF EXISTS `galleries`;
-- Legacy email draft tables — removed from current schema.
-- Retained in reset section to clean databases created by older versions.
DROP TABLE IF EXISTS `email_draft_attachments`;
DROP TABLE IF EXISTS `email_draft_recipients`;
DROP TABLE IF EXISTS `email_drafts`;
SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================================
-- 1. RBAC
-- =====================================================================

CREATE TABLE roles (
  role_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  role_code VARCHAR(30) NOT NULL COMMENT 'ADMIN, HO, STAFF, DEPARTMENT, STUDENT, VISITOR',
  name VARCHAR(100) NOT NULL,
  description VARCHAR(255) NULL,
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (role_id),
  UNIQUE KEY uq_roles_code (role_code),
  KEY idx_roles_status (status),
  CHECK (role_code IN ('ADMIN','HO','STAFF','DEPARTMENT','STUDENT','VISITOR'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Fixed system roles for account classification. No DB-backed dynamic permission matrix.';

-- =====================================================================
-- 2. ORGANIZATION
-- =====================================================================

CREATE TABLE campuses (
  campus_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_code VARCHAR(20) NOT NULL COMMENT 'HN, HCM, DN, CT, QN',
  name VARCHAR(150) NOT NULL,
  city VARCHAR(100) NULL,
  address VARCHAR(255) NULL,
  phone VARCHAR(30) NULL,
  email VARCHAR(150) NULL,
  ic_head_user_id BIGINT UNSIGNED NULL COMMENT 'FK added after users table',
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (campus_id),
  UNIQUE KEY uq_campuses_code (campus_code),
  KEY idx_campuses_status (status),
  KEY idx_campuses_city_status (city, status),
  KEY idx_campuses_ic_head (ic_head_user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Danh mục campus';

CREATE TABLE departments (
  department_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_id BIGINT UNSIGNED NOT NULL,
  name VARCHAR(150) NOT NULL,
  department_type ENUM('IC','GENERAL') NOT NULL COMMENT 'IC=International Cooperation; GENERAL=other departments',
  head_user_id BIGINT UNSIGNED NULL COMMENT 'FK added after users table',
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (department_id),
  UNIQUE KEY uq_departments_campus_name (campus_id, name),
  KEY idx_departments_campus_type (campus_id, department_type),
  KEY idx_departments_status (status),
  KEY idx_departments_head (head_user_id),
  CONSTRAINT fk_departments_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Phòng ban theo campus. STAFF thuộc IC, DEPARTMENT thuộc GENERAL';

-- =====================================================================
-- 3. USERS + AUTH
-- =====================================================================

CREATE TABLE users (
  user_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(150) NOT NULL,
  email VARCHAR(150) NOT NULL,
  phone VARCHAR(30) NULL,
  nationality VARCHAR(100) NULL COMMENT 'Quốc tịch của user/visitor',
  password_hash VARCHAR(255) NULL COMMENT 'DEV/local password hash only. Production SSO-only accounts keep this NULL.',
  role_id BIGINT UNSIGNED NOT NULL,
  sub_role ENUM('LEADER','STAFF') NULL COMMENT 'Only for STAFF/DEPARTMENT',
  primary_campus_id BIGINT UNSIGNED NULL COMMENT 'Campus duy nhất của user nội bộ. VISITOR phải NULL.',
  department_id BIGINT UNSIGNED NULL COMMENT 'STAFF = IC department; DEPARTMENT = GENERAL department',
  gender ENUM('MALE','FEMALE','OTHER') NULL COMMENT 'NULL=chưa cung cấp; OTHER=khác Nam/Nữ',
  avatar_url VARCHAR(500) NULL,
  student_code VARCHAR(30) NULL,
  fe_id VARCHAR(100) NULL,
  status ENUM('ACTIVE','INACTIVE','LOCKED','PENDING_EMAIL_CONFIRMATION') NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE=hoạt động, INACTIVE=tạm ngưng, LOCKED=bị khóa, PENDING_EMAIL_CONFIRMATION=chờ xác nhận email',
  email_verified_at DATETIME NULL COMMENT 'Thời điểm email được xác thực qua SSO lần đầu hoặc xác nhận bởi hệ thống',
  failed_login_count INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Số lần đăng nhập sai local password liên tiếp; reset khi login thành công',
  locked_until DATETIME NULL COMMENT 'Thời điểm hết khóa tạm thời nếu bị lock',
  created_via ENUM('MANUAL_CREATED','VISITOR_FORM','SSO_AUTO_PROVISION') NOT NULL DEFAULT 'MANUAL_CREATED' COMMENT 'MANUAL_CREATED=HO/Staff Leader tạo, VISITOR_FORM=tạo từ form visitor, SSO_AUTO_PROVISION=tạo tự động khi đăng nhập SSO ở cổng Visitor',
  first_login_at DATETIME NULL,
  last_login_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_users_email (email),
  UNIQUE KEY uq_users_student_code (student_code),
  UNIQUE KEY uq_users_fe_id (fe_id),
  KEY idx_users_role_sub_role (role_id, sub_role),
  KEY idx_users_primary_campus (primary_campus_id),
  KEY idx_users_department (department_id),
  KEY idx_users_status (status),
  KEY idx_users_email_status (email, status),
  KEY idx_users_campus_role_status (primary_campus_id, role_id, status),
  KEY idx_users_department_status (department_id, status),
  KEY idx_users_created_via (created_via),
  KEY idx_users_last_login (last_login_at),
  KEY idx_users_nationality (nationality),
  CONSTRAINT fk_users_role
    FOREIGN KEY (role_id) REFERENCES roles(role_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_users_primary_campus
    FOREIGN KEY (primary_campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_users_department
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
    ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Tài khoản chính. Production dùng SSO; LOCAL_PASSWORD chỉ dùng DEV/test.';


CREATE TABLE user_auth_providers (
  auth_provider_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  provider_type ENUM('LOCAL_PASSWORD','GOOGLE_SSO','FEID') NOT NULL,
  provider_subject VARCHAR(255) NULL COMMENT 'Required for GOOGLE_SSO/FEID',
  provider_email VARCHAR(150) NULL,
  is_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  linked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_used_at DATETIME NULL,
  PRIMARY KEY (auth_provider_id),
  UNIQUE KEY uq_user_auth_provider_type (user_id, provider_type),
  UNIQUE KEY uq_auth_provider_subject (provider_type, provider_subject),
  KEY idx_auth_provider_email (provider_email),
  KEY idx_auth_provider_type_email_enabled (provider_type, provider_email, is_enabled),
  CONSTRAINT fk_auth_providers_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Provider đăng nhập của user. Production dùng GOOGLE_SSO/FEID; LOCAL_PASSWORD chỉ dùng DEV/test.';

CREATE TABLE user_sessions (
  session_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  login_portal ENUM('VISITOR','INTERNAL') NOT NULL,
  selected_campus_id BIGINT UNSIGNED NULL COMMENT 'Auto set to users.primary_campus_id for INTERNAL, NULL for VISITOR',
  auth_provider_id BIGINT UNSIGNED NULL,
  refresh_token_hash VARCHAR(255) NULL COMMENT 'Refresh token hash merged into session',
  refresh_expires_at DATETIME NULL,
  refresh_revoked_at DATETIME NULL,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at DATETIME NOT NULL,
  revoked_at DATETIME NULL,
  revoked_by BIGINT UNSIGNED NULL,
  revoked_reason VARCHAR(255) NULL,
  PRIMARY KEY (session_id),
  UNIQUE KEY uq_sessions_refresh_hash (refresh_token_hash),
  KEY idx_sessions_user_active (user_id, revoked_at, expires_at),
  KEY idx_sessions_portal_campus (login_portal, selected_campus_id),
  KEY idx_sessions_refresh_active (refresh_token_hash, refresh_revoked_at, refresh_expires_at),
  KEY idx_sessions_ip_time (ip_address, created_at),
  KEY idx_sessions_expires_at (expires_at),
  KEY idx_sessions_revoked_at (revoked_at),
  CONSTRAINT fk_sessions_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_sessions_selected_campus
    FOREIGN KEY (selected_campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_sessions_auth_provider
    FOREIGN KEY (auth_provider_id) REFERENCES user_auth_providers(auth_provider_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_sessions_revoked_by
    FOREIGN KEY (revoked_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Session + refresh token hash';

CREATE TABLE otp_tokens (
  otp_token_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NULL,
  email VARCHAR(150) NOT NULL,
  token_type ENUM('OTP_CODE','MAGIC_LINK') NOT NULL DEFAULT 'OTP_CODE',
  purpose ENUM('VISIT_REQUEST_VERIFY','CHANGE_SENSITIVE_ACTION') NOT NULL,
  token_hash VARCHAR(255) NOT NULL,
  challenge_token_hash CHAR(64) NULL COMMENT 'SHA-256 của opaque challenge token; không lưu raw token',
  submission_id CHAR(36) NULL COMMENT 'UUID của submit intent UC17',
  issue_reason VARCHAR(30) NOT NULL DEFAULT 'INITIAL' COMMENT 'INITIAL, RESEND hoặc HUMAN_RECOVERY',
  expires_at DATETIME NOT NULL,
  used_at DATETIME NULL,
  attempt_count INT UNSIGNED NOT NULL DEFAULT 0,
  last_attempt_at DATETIME NULL,
  next_attempt_allowed_at DATETIME NULL COMMENT 'Server-enforced progressive cooldown; verify trước thời điểm này bị 429',
  human_verification_required_at DATETIME NULL COMMENT 'Set khi sai lần thứ max_attempts — challenge chỉ phục hồi qua human verification',
  human_verified_at DATETIME NULL,
  invalidated_at DATETIME NULL,
  invalidation_reason VARCHAR(40) NULL COMMENT 'MAX_ATTEMPTS, HUMAN_RECOVERY, SUPERSEDED_BY_RESEND, ...',
  max_attempts INT UNSIGNED NOT NULL DEFAULT 10,
  resend_count INT UNSIGNED NOT NULL DEFAULT 0,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (otp_token_id),
  UNIQUE KEY uq_otp_tokens_hash (token_hash),
  UNIQUE KEY uq_otp_challenge_token_hash (challenge_token_hash),
  KEY idx_otp_submission (submission_id),
  KEY idx_otp_email_purpose_time (email, purpose, created_at),
  KEY idx_otp_email_purpose_active (email, purpose, used_at, expires_at),
  KEY idx_otp_email_purpose_active_v2 (email, purpose, invalidated_at, expires_at),
  KEY idx_otp_issue_limit (email, purpose, issue_reason, created_at),
  KEY idx_otp_user_purpose_active (user_id, purpose, used_at, expires_at),
  KEY idx_otp_ip_time (ip_address, created_at),
  CONSTRAINT fk_otp_tokens_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='OTP, magic link, set password token, reset password token';

CREATE TABLE login_logs (
  login_log_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NULL,
  email VARCHAR(150) NOT NULL,
  login_portal ENUM('VISITOR','INTERNAL') NOT NULL,
  selected_campus_id BIGINT UNSIGNED NULL,
  provider_type ENUM('LOCAL_PASSWORD','GOOGLE_SSO','FEID') NULL,
  status ENUM('SUCCESS','FAILED','BLOCKED') NOT NULL,
  failure_reason VARCHAR(255) NULL,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  session_id BIGINT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (login_log_id),
  KEY idx_login_logs_user_time (user_id, created_at),
  KEY idx_login_logs_email_status_time (email, status, created_at),
  KEY idx_login_logs_ip_status_time (ip_address, status, created_at),
  KEY idx_login_logs_portal_campus (login_portal, selected_campus_id),
  KEY idx_login_logs_provider_time (provider_type, created_at),
  CONSTRAINT fk_login_logs_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_login_logs_campus
    FOREIGN KEY (selected_campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Lịch sử đăng nhập';

CREATE TABLE security_events (
  security_event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NULL,
  email_snapshot VARCHAR(150) NULL COMMENT 'Email nhận từ SSO hoặc email đang được kiểm tra tại thời điểm xảy ra sự kiện',
  event_type ENUM(
    'SSO_LOGIN',
    'PORTAL_VALIDATION',
    'CAMPUS_VALIDATION',
    'VISITOR_AUTO_PROVISION',
    'SESSION_CREATED',
    'SESSION_REVOKED',
    'SESSION_EXPIRED',
    'TOKEN_REFRESH',
    'SECURITY_POLICY_CHECK'
  ) NOT NULL COMMENT 'Loại sự kiện bảo mật theo mô hình SSO-only',
  result ENUM('SUCCESS','FAILED','BLOCKED') NOT NULL DEFAULT 'SUCCESS' COMMENT 'Kết quả xử lý sự kiện',
  failure_reason_code ENUM(
    'ACCOUNT_NOT_FOUND',
    'ACCOUNT_DISABLED',
    'PORTAL_MISMATCH',
    'CAMPUS_MISMATCH',
    'ROLE_MISMATCH',
    'SSO_PROVIDER_ERROR',
    'INVALID_SSO_CLAIMS',
    'VISITOR_AUTO_PROVISION_DISABLED',
    'SESSION_EXPIRED',
    'TOKEN_REVOKED',
    'SUSPICIOUS_IP',
    'UNKNOWN'
  ) NULL COMMENT 'Mã lý do thất bại/chặn; NULL khi SUCCESS',
  severity ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW',
  login_portal ENUM('VISITOR','INTERNAL') NULL COMMENT 'Portal được dùng khi phát sinh sự kiện',
  selected_campus_id BIGINT UNSIGNED NULL COMMENT 'Campus người dùng chọn ở Internal Portal; NULL với Visitor Portal',
  provider_type ENUM('GOOGLE_SSO','FEID') NULL COMMENT 'Nguồn định danh SSO; không dùng LOCAL_PASSWORD trong security_events',
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  session_id BIGINT UNSIGNED NULL,
  detail_text TEXT NULL COMMENT 'Ghi chú debug ngắn, không lưu JSON metadata',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (security_event_id),
  KEY idx_security_user_time (user_id, created_at),
  KEY idx_security_email_time (email_snapshot, created_at),
  KEY idx_security_type_result_time (event_type, result, created_at),
  KEY idx_security_portal_campus_time (login_portal, selected_campus_id, created_at),
  KEY idx_security_failure_reason_time (failure_reason_code, created_at),
  KEY idx_security_ip_time (ip_address, created_at),
  KEY idx_security_severity_time (severity, created_at),
  KEY idx_security_session_time (session_id, created_at),
  CONSTRAINT fk_security_events_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_security_events_selected_campus
    FOREIGN KEY (selected_campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_security_events_session
    FOREIGN KEY (session_id) REFERENCES user_sessions(session_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='SSO-only security events: portal/campus validation, Visitor auto-provisioning, and session lifecycle. No local password tracking and no metadata JSON.';

-- =====================================================================
-- 4. PARTNER + FILE
-- =====================================================================

CREATE TABLE files (
  file_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  storage_provider ENUM('LOCAL','S3','AZURE','GCS','GOOGLE_DRIVE','OTHER') NOT NULL DEFAULT 'LOCAL',
  bucket_name VARCHAR(150) NULL,
  object_key VARCHAR(700) NOT NULL COMMENT 'Max 700 chars to keep UNIQUE index safe under utf8mb4',
  original_filename VARCHAR(255) NOT NULL,
  mime_type VARCHAR(150) NULL,
  file_size BIGINT UNSIGNED NULL,
  checksum_sha256 CHAR(64) NULL,
  uploaded_by BIGINT UNSIGNED NULL,
  uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  external_file_id VARCHAR(255) NULL COMMENT 'External provider file id, e.g., Google Drive file id',
  web_view_url VARCHAR(700) NULL COMMENT 'Open/view URL from external storage provider',
  download_url VARCHAR(700) NULL COMMENT 'Direct download URL when provider allows it',
  thumbnail_url VARCHAR(700) NULL COMMENT 'Thumbnail URL for image/video preview',
  file_purpose VARCHAR(100) NULL COMMENT 'Technical/business file purpose used by referencing entity',
  PRIMARY KEY (file_id),
  UNIQUE KEY uq_files_object_key (object_key),
  KEY idx_files_uploaded_by (uploaded_by, uploaded_at),
  KEY idx_files_mime_time (mime_type, uploaded_at),
  KEY idx_files_checksum (checksum_sha256),
  KEY idx_files_external_file_id (external_file_id),
  KEY idx_files_purpose_time (file_purpose, uploaded_at),
  CONSTRAINT fk_files_uploaded_by
    FOREIGN KEY (uploaded_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='File metadata only. Binary file is stored outside DB.';

CREATE TABLE partners (
  partner_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  owner_campus_id BIGINT UNSIGNED NOT NULL
    COMMENT 'Campus sở hữu/quản lý partner request; dùng để Staff Leader duyệt đúng campus',
  partner_code VARCHAR(50) NULL,
  name VARCHAR(200) NOT NULL,
  short_name VARCHAR(100) NULL,
  country VARCHAR(100) NULL,
  city VARCHAR(100) NULL,
  website_url VARCHAR(500) NULL,
  partner_type ENUM('UNIVERSITY','COMPANY','GOVERNMENT','NGO','OTHER') NOT NULL DEFAULT 'UNIVERSITY',
  cooperation_status ENUM('POTENTIAL','ACTIVE','INACTIVE','BLACKLISTED') NOT NULL DEFAULT 'POTENTIAL',
  description TEXT NULL,
  logo_file_id BIGINT UNSIGNED NULL COMMENT 'Partner logo file, references files.file_id',
  cover_file_id BIGINT UNSIGNED NULL COMMENT 'Partner cover/banner file, references files.file_id',
  address VARCHAR(500) NULL,
  public_slug VARCHAR(180) NULL COMMENT 'Public URL slug for partner profile',
  profile_status ENUM('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED') NOT NULL DEFAULT 'APPROVED',
  review_note TEXT NULL,
  reviewed_by BIGINT UNSIGNED NULL,
  reviewed_at DATETIME NULL,
  visibility ENUM('PRIVATE','INTERNAL','PUBLIC') NOT NULL DEFAULT 'PUBLIC',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (partner_id),
  UNIQUE KEY uq_partners_code (partner_code),
  KEY idx_partners_owner_status (owner_campus_id, profile_status),
  KEY idx_partners_owner_created (owner_campus_id, created_at),
  KEY idx_partners_country (country),
  KEY idx_partners_status (cooperation_status),
  KEY idx_partners_type_status (partner_type, cooperation_status),
  KEY idx_partners_created_at (created_at),
  UNIQUE KEY uq_partners_public_slug (public_slug),
  KEY idx_partners_profile_status (profile_status),
  KEY idx_partners_visibility (visibility),
  KEY idx_partners_logo_file (logo_file_id),
  KEY idx_partners_cover_file (cover_file_id),
  KEY idx_partners_reviewed_by (reviewed_by, reviewed_at),
  FULLTEXT KEY ft_partners_search (name, short_name, description),
  CONSTRAINT fk_partners_owner_campus FOREIGN KEY (owner_campus_id) REFERENCES campuses(campus_id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_partners_logo_file FOREIGN KEY (logo_file_id) REFERENCES files(file_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_partners_cover_file FOREIGN KEY (cover_file_id) REFERENCES files(file_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_partners_reviewed_by FOREIGN KEY (reviewed_by) REFERENCES users(user_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Hồ sơ đối tác; owner_campus_id dùng để Staff Leader duyệt đúng campus';

CREATE TABLE partner_translations (
  partner_translation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  partner_id BIGINT UNSIGNED NOT NULL,
  language_code ENUM('vi','en') NOT NULL,

  name VARCHAR(200) NOT NULL,
  short_name VARCHAR(100) NULL,
  country VARCHAR(100) NULL,
  city VARCHAR(100) NULL,
  description TEXT NULL,
  address VARCHAR(500) NULL,

  translation_source ENUM('AUTO','MANUAL','LEGACY') NOT NULL DEFAULT 'AUTO',
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  source_hash CHAR(64) NULL
    COMMENT 'SHA-256 của nội dung nguồn VI tại lần dịch gần nhất; tránh gọi API khi nội dung không đổi',
  translated_at DATETIME NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (partner_translation_id),
  UNIQUE KEY uq_partner_translations_lang (partner_id, language_code),
  KEY idx_partner_translations_lang_status (language_code, translation_status),
  FULLTEXT KEY ft_partner_translations_search (name, short_name, description, address),

  CONSTRAINT fk_partner_translations_partner
    FOREIGN KEY (partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_partner_translations_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_partner_translations_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Nội dung Partner theo ngôn ngữ. Public read chỉ đọc DB, Translation API chỉ chạy khi tạo/sửa nội dung.';


CREATE TABLE partner_contacts (
  contact_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  partner_id BIGINT UNSIGNED NOT NULL,
  full_name VARCHAR(150) NOT NULL,
  email VARCHAR(150) NULL,
  phone VARCHAR(50) NULL,
  job_title VARCHAR(150) NULL,
  department_name VARCHAR(150) NULL,
  source_type ENUM('MANUAL','BUSINESS_CARD_OCR','IMPORT') NOT NULL DEFAULT 'MANUAL',
  scanned_card_file_id BIGINT UNSIGNED NULL,
  avatar_file_id BIGINT UNSIGNED NULL COMMENT 'Optional contact avatar stored in files',
  ocr_confidence DECIMAL(5,2) NULL,
  note TEXT NULL,
  is_primary BOOLEAN NOT NULL DEFAULT FALSE,
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (contact_id),
  UNIQUE KEY uq_partner_contacts_partner_email (partner_id, email),
  KEY idx_partner_contacts_partner (partner_id),
  KEY idx_partner_contacts_email (email),
  KEY idx_partner_contacts_status (status),
  KEY idx_partner_contacts_source_type (source_type),
  KEY idx_partner_contacts_scanned_card (scanned_card_file_id),
  KEY idx_partner_contacts_avatar_file (avatar_file_id),
  CONSTRAINT fk_partner_contacts_partner
    FOREIGN KEY (partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_partner_contacts_scanned_card
    FOREIGN KEY (scanned_card_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_partner_contacts_avatar_file
    FOREIGN KEY (avatar_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Người liên hệ đối tác. OCR final confirmed data saved here.';


-- ---------------------------------------------------------------------
-- Partner module: partner_aliases
-- ---------------------------------------------------------------------
CREATE TABLE partner_aliases (
  partner_alias_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  partner_id BIGINT UNSIGNED NOT NULL,

  alias_name VARCHAR(255) NOT NULL,
  alias_name_key VARCHAR(300) NOT NULL COMMENT 'Normalized key: lower-case, remove accents, punctuation, repeated spaces',

  source ENUM('MANUAL','OCR','AUTO_MATCH','IMPORT') NOT NULL DEFAULT 'MANUAL',
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (partner_alias_id),
  UNIQUE KEY uq_partner_alias_key (partner_id, alias_name_key),
  KEY idx_partner_alias_lookup (alias_name_key, status),
  KEY idx_partner_alias_partner (partner_id),

  CONSTRAINT fk_partner_alias_partner
    FOREIGN KEY (partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_partner_alias_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_partner_alias_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Alternative names of partners for matching organization names from guests/OCR.';

CREATE TABLE documents (
  document_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  file_id BIGINT UNSIGNED NOT NULL,
  owner_type ENUM('GENERAL','VISIT','PARTNER','MINUTES','NEWS','LOGISTICS','REPORT','VISIT_INSTANCE_MEDIA') NOT NULL DEFAULT 'GENERAL',
  owner_id BIGINT UNSIGNED NULL,
  campus_id BIGINT UNSIGNED NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  document_category VARCHAR(100) NULL,
  status ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (document_id),
  KEY idx_documents_owner (owner_type, owner_id),
  KEY idx_documents_campus_status (campus_id, status),
  KEY idx_documents_category_status (document_category, status),
  KEY idx_documents_created_by_time (created_by, created_at),
  FULLTEXT KEY ft_documents_search (title, description),
  CONSTRAINT fk_documents_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_documents_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_documents_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Tài liệu nghiệp vụ. partner_documents/reports/logistics documents merged by owner_type.';

-- =====================================================================
-- 5. VISIT / DELEGATION
-- =====================================================================
-- Approval flow updated for campus-level processing:
-- SINGLE_CAMPUS and MULTI_CAMPUS both create one visit_request_campuses row per selected campus.
-- HO no longer approves/rejects multi-campus requests. HO may monitor read-only if the application exposes that view.
-- Each campus instance is approved/rejected independently by the Staff Leader of that campus.
-- Approve always requires selecting the official host in the same transaction. No WAITING_HOST_ASSIGNMENT status.


CREATE TABLE visit_requests (
  visit_request_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  request_code VARCHAR(50) NOT NULL,
  submission_id CHAR(36) NULL COMMENT 'UUID idempotency cho một submit intent',
  business_fingerprint CHAR(64) NULL COMMENT 'SHA-256 fingerprint V2 của core visit identity; non-unique để cho phép gửi lại hợp lệ',
  registrant_user_id BIGINT UNSIGNED NULL COMMENT 'Tài khoản NGƯỜI ĐĂNG KÝ (submitter) — chủ sở hữu DUY NHẤT ở cấp request: xem toàn bộ campus, sửa phần request-level, đổi đầu mối, hủy toàn request theo rule. Có thể là VISITOR, STAFF hoặc STAFF LEADER; role người tạo KHÔNG bypass cổng xác nhận đầu mối. Quyền vận hành từng campus thuộc visit_request_campuses.operational_contact_user_id.',
  partner_id BIGINT UNSIGNED NULL,
  created_source ENUM('VISITOR_SUBMITTED','STAFF_CREATED') NOT NULL DEFAULT 'VISITOR_SUBMITTED',

  -- Pure per-campus form runtime. The parent has no form-version discriminator;
  -- all active form fields live in visit_instance_form_details.
  has_mixed_campus_details TINYINT(1) NOT NULL DEFAULT 0
    COMMENT 'Backend-derived: 1 when campus detail snapshots differ. Never accepted from the client.',

  -- 1. Registrant information from the Campus Visit form
  registrant_full_name VARCHAR(150) NOT NULL COMMENT 'Họ và tên người đăng ký',
  registrant_organization VARCHAR(200) NOT NULL COMMENT 'Đơn vị công tác người đăng ký',
  registrant_job_title VARCHAR(150) NOT NULL COMMENT 'Chức danh/phòng ban người đăng ký',
  registrant_phone VARCHAR(50) NOT NULL COMMENT 'SĐT người đăng ký',
  registrant_email VARCHAR(150) NOT NULL COMMENT 'Email người đăng ký',
  registrant_nationality VARCHAR(100) NOT NULL COMMENT 'Quốc tịch người đăng ký',

  -- 2. Request scope. All form content is stored per campus in
  -- visit_instance_form_details; no global-form projection exists here.
  visit_scope ENUM('SINGLE_CAMPUS','MULTI_CAMPUS') NOT NULL DEFAULT 'SINGLE_CAMPUS'
    COMMENT 'SINGLE_CAMPUS/MULTI_CAMPUS mô tả số campus được chọn; từng campus instance được route độc lập.',

  -- There is NO request-level contact. Each campus carries its own operational contact
  -- snapshot in visit_instance_form_details.operational_contact_* and its own confirmed
  -- account link in visit_request_campuses.operational_contact_user_id.

  -- Global confirmation gate revision. Bumped in the SAME transaction that opens the gate
  -- (last operational contact confirmed) and every time the gate closes again (a confirmed
  -- contact is replaced before any campus decision). Used as the approval-notification
  -- dedupe key APPROVAL_READY:{requestId}:{visitInstanceId}:{gateRevision}.
  contact_gate_revision INT UNSIGNED NOT NULL DEFAULT 0
    COMMENT 'Số hiệu lần mở cổng xác nhận đầu mối; dùng làm dedupe key cho notification duyệt',

  status ENUM('PENDING_CONTACT_CONFIRMATION','PENDING_APPROVAL','PARTIALLY_APPROVED','APPROVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING_CONTACT_CONFIRMATION' COMMENT 'Aggregate request status. PENDING_CONTACT_CONFIRMATION=còn campus chưa có đầu mối xác nhận (Staff Leader chưa thấy đơn); các trạng thái sau derive từ quyết định từng campus.',
  submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  email_verified_at DATETIME NULL,

  resubmission_count INT UNSIGNED NOT NULL DEFAULT 0
    COMMENT 'Số lần Visitor sửa và gửi lại request sau khi toàn bộ campus bị từ chối',
  last_resubmitted_at DATETIME NULL
    COMMENT 'Thời điểm gần nhất Visitor gửi lại request sau khi bị từ chối',
  last_resubmitted_by BIGINT UNSIGNED NULL
    COMMENT 'Visitor gần nhất gửi lại request sau khi bị từ chối',

  cancelled_by BIGINT UNSIGNED NULL COMMENT 'Visitor hủy toàn bộ request/delegation',
  cancelled_at DATETIME NULL COMMENT 'Thời điểm visitor hủy toàn bộ request/delegation',
  cancellation_reason TEXT NULL COMMENT 'Lý do hủy toàn bộ request/delegation. Người hủy = người đăng ký (registrant_user_id). Trigger trg_visit_requests_cancel_validate_bu enforce actor + guard 24h/started-campus.',

  row_version INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Optimistic concurrency token',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (visit_request_id),
  UNIQUE KEY uq_visit_requests_code (request_code),
  UNIQUE KEY uq_visit_requests_submission_id (submission_id),
  -- business_fingerprint: NORMAL index only — a UNIQUE index would permanently block
  -- legitimate re-submissions after 15 minutes or after reject/cancel. Do NOT make it unique.
  KEY idx_visit_requests_fingerprint_time_status (business_fingerprint, submitted_at, status),
  KEY idx_visit_requests_registrant_user (registrant_user_id, submitted_at),
  KEY idx_visit_requests_partner (partner_id),
  KEY idx_visit_requests_status_submitted (status, submitted_at),
  KEY idx_visit_requests_registrant_email (registrant_email),
  KEY idx_visit_requests_scope_status (visit_scope, status),
  KEY idx_visit_requests_scope_status_submitted (visit_scope, status, submitted_at),
  KEY idx_visit_requests_created_source (created_source),
  KEY idx_visit_requests_mixed_details (has_mixed_campus_details, status, submitted_at),
  KEY idx_visit_requests_gate (status, contact_gate_revision),
  KEY idx_visit_requests_cancelled (cancelled_by, cancelled_at),
  KEY idx_visit_requests_resubmission (resubmission_count, last_resubmitted_at),
  KEY idx_visit_requests_last_resubmitted_by (last_resubmitted_by, last_resubmitted_at),
  -- Parent FULLTEXT covers request code / registrant identity only. Delegation/purpose/
  -- content/operational-contact search is exclusively per campus through
  -- visit_instance_form_details.ft_vifd_search.
  FULLTEXT KEY ft_visit_requests_frontend_search (request_code, registrant_full_name, registrant_organization, registrant_email),

  CHECK (TRIM(registrant_job_title) <> ''),
  CHECK (TRIM(registrant_phone) <> ''),
  CHECK (TRIM(registrant_nationality) <> ''),
  CONSTRAINT fk_visit_requests_registrant_user
    FOREIGN KEY (registrant_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_requests_partner
    FOREIGN KEY (partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_requests_cancelled_by
    FOREIGN KEY (cancelled_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_requests_last_resubmitted_by
    FOREIGN KEY (last_resubmitted_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='V2-only request parent: registrant snapshot, scope, aggregate status, cổng xác nhận đầu mối, idempotency và lifecycle metadata. KHÔNG có đầu mối cấp request — mọi form content và đầu mối vận hành nằm per campus.';

CREATE TABLE visit_request_campuses (
  visit_instance_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  campus_id BIGINT UNSIGNED NOT NULL,
  planned_start_at DATETIME NOT NULL COMMENT 'Ngày giờ bắt đầu dự kiến tại campus',
  planned_end_at DATETIME NOT NULL COMMENT 'Ngày giờ kết thúc dự kiến tại campus',

  status ENUM(
    'WAITING_CONTACT_CONFIRMATION',
    'WAITING_REQUEST_APPROVAL',
    'ASSIGNED',
    'BEFORE_VISIT',
    'DURING_VISIT',
    'AFTER_VISIT',
    'CLOSED',
    'CANCELLED',
    'REJECTED'
  ) NOT NULL DEFAULT 'WAITING_CONTACT_CONFIRMATION'
    COMMENT 'WAITING_CONTACT_CONFIRMATION=đầu mối vận hành campus chưa xác nhận; WAITING_REQUEST_APPROVAL=đã có đầu mối, chờ Staff Leader campus xử lý; ASSIGNED=Staff Leader đã duyệt và gán Host trong cùng transaction, Host CHƯA bắt đầu chuẩn bị; BEFORE_VISIT=Host đã bấm Bắt đầu chuẩn bị, các thao tác setup mới mở; REJECTED=Staff Leader campus từ chối tiếp nhận.',

  -- Đầu mối VẬN HÀNH của campus này, sau khi đã xác nhận. NULL = chưa xác nhận.
  -- KHÔNG UNIQUE: một người có thể phụ trách nhiều campus (kể cả trong cùng request).
  -- RESTRICT cả hai chiều: một đầu mối đang giữ campus không được xóa/đổi khóa âm thầm.
  operational_contact_user_id BIGINT UNSIGNED NULL
    COMMENT 'Tài khoản đầu mối vận hành đã xác nhận cho ĐÚNG campus này. NULL khi chưa xác nhận (status=WAITING_CONTACT_CONFIRMATION). Tự khớp registrant thì set ngay lúc submit, không gửi email.',
  operational_contact_confirmed_at DATETIME NULL
    COMMENT 'Thời điểm đầu mối vận hành được liên kết (giờ VN)',
  operational_contact_confirmation_source ENUM('REGISTRANT_SELF_MATCH','EMAIL_CONFIRMATION','TRANSFER') NULL
    COMMENT 'REGISTRANT_SELF_MATCH=email trùng registrant đã xác thực, auto-link không gửi mail; EMAIL_CONFIRMATION=accept qua link; TRANSFER=chuyển đầu mối sau khi đã có quyết định campus',

  coordinator_user_id BIGINT UNSIGNED NULL
    COMMENT 'Staff Leader điều phối campus instance; được route theo campus ngay sau khi submit.',
  coordinator_assigned_by BIGINT UNSIGNED NULL COMMENT 'Người/tiến trình route coordinator; không còn là bước Staff Leader xử lý multi-campus',
  coordinator_assigned_at DATETIME NULL COMMENT 'Thời điểm gán coordinator',

  current_host_user_id BIGINT UNSIGNED NULL
    COMMENT 'Host chính thức của campus instance. Set một lần tại thời điểm Staff Leader approve; có thể là IC Staff hoặc chính Staff Leader đang duyệt.',
  host_assigned_by BIGINT UNSIGNED NULL COMMENT 'Staff Leader approve và gán host chính thức',
  host_assigned_at DATETIME NULL COMMENT 'Thời điểm host chính thức được gán',

  -- ── Host DỰ KIẾN (proposed host) — KHÔNG phải Host chính thức ────────────────────────────────
  -- Người tạo đơn nội bộ nêu trước ai sẽ tiếp đón campus này. Đây mới chỉ là ĐỀ XUẤT: nó nằm ở
  -- cột riêng đúng vì current_host_user_id mang nghĩa "đã được phân công chính thức", và ghi đè
  -- lên đó trước khi cổng xác nhận mở sẽ làm một người chưa ai xác nhận trông như đã nhận việc.
  -- Chỉ khi đầu mối cuối cùng của REQUEST xác nhận (cổng mở) thì proposal mới được revalidate và
  -- kích hoạt thành current_host_user_id trong cùng transaction đó.
  host_selection_mode ENUM('SELF','SELECTED','WAIT_FOR_LATER') NOT NULL DEFAULT 'WAIT_FOR_LATER'
    COMMENT 'Phương án người phụ trách tiếp đón do người tạo chọn: SELF=tự nhận; SELECTED=Staff Leader chỉ định IC Staff cùng campus; WAIT_FOR_LATER=chờ Staff Leader phân công sau khi cổng mở. KHÔNG phải lifecycle status.',
  proposed_host_user_id BIGINT UNSIGNED NULL
    COMMENT 'Host dự kiến của campus này. NULL bắt buộc khi host_selection_mode=WAIT_FOR_LATER. Không bao giờ mang nghĩa đã phân công — xem current_host_user_id.',
  proposed_host_by_user_id BIGINT UNSIGNED NULL
    COMMENT 'Người đề xuất Host dự kiến (Staff Leader hoặc chính IC Staff tự nhận). Là actor được preauthorize; khi kích hoạt sẽ trở thành decided_by.',
  proposed_host_at DATETIME NULL COMMENT 'Thời điểm lưu/cập nhật đề xuất Host dự kiến (giờ VN)',
  proposed_host_activation_status ENUM('PENDING','ACTIVATED','NEEDS_RESELECTION') NULL
    COMMENT 'PENDING=đã lưu, chờ cổng xác nhận mở; ACTIVATED=đã kích hoạt thành current host; NEEDS_RESELECTION=cổng đã mở nhưng proposal không còn hợp lệ, Staff Leader phải chọn lại. NULL khi WAIT_FOR_LATER.',
  proposed_host_activated_at DATETIME NULL
    COMMENT 'Thời điểm proposal được kích hoạt thành Host chính thức; dùng làm bằng chứng idempotency khi confirmation bị replay.',

  decided_by BIGINT UNSIGNED NULL COMMENT 'Người xử lý campus instance (Staff Leader duyệt/từ chối, hoặc IC Staff tự nhận host trong transaction tạo đơn của chính mình)',
  decided_at DATETIME NULL COMMENT 'Thời điểm campus instance được xử lý',
  decision_actor_role ENUM('STAFF_LEADER','STAFF') NULL COMMENT 'STAFF_LEADER = duyệt chuẩn/gán host/leader self-host, hoặc kích hoạt proposal của Leader; STAFF = IC Staff thường tự nhận host qua Host dự kiến trên đơn chính mình đăng ký (decision_source=PREAUTHORIZED_HOST_ACTIVATION).',
  decision_source ENUM('STANDARD_CAMPUS_REVIEW','PREAUTHORIZED_HOST_ACTIVATION') NULL COMMENT 'Nguồn quyết định: STANDARD_CAMPUS_REVIEW=Staff Leader duyệt instance pending sau khi cổng mở; PREAUTHORIZED_HOST_ACTIVATION=Host dự kiến đã được preauthorize lúc tạo/sửa đơn, được revalidate và kích hoạt tại đúng thời điểm cổng xác nhận đầu mối mở. Hai nguồn cũ INTERNAL_SELF_HOST/INTERNAL_LEADER_ASSIGN đã bỏ cùng direct processing: chúng gán Host TRƯỚC cổng.',
  decision_note TEXT NULL COMMENT 'Ghi chú duyệt hoặc lý do từ chối; REJECTED bắt buộc có lý do',

  closed_by BIGINT UNSIGNED NULL,
  closed_at DATETIME NULL,
  close_note TEXT NULL,
  news_not_required TINYINT(1) NOT NULL DEFAULT 0
    COMMENT 'Host xác nhận chuyến này không cần tạo/duyệt bài tin tức; backend dùng khi đóng đoàn: có news PUBLISHED hoặc news_not_required = 1',

  cancelled_by BIGINT UNSIGNED NULL COMMENT 'Visitor hoặc Host thực hiện hủy campus instance',
  cancelled_at DATETIME NULL COMMENT 'Thời điểm hủy campus instance',
  cancellation_actor_type ENUM('VISITOR','HOST') NULL COMMENT 'VISITOR=khách tự hủy; HOST=Staff được gán làm host hủy thay khách theo xác nhận ngoài hệ thống',
  cancellation_source ENUM('SELF_SERVICE','EXTERNAL_CONFIRMATION') NULL COMMENT 'SELF_SERVICE=Visitor tự hủy; EXTERNAL_CONFIRMATION=Host hủy sau khi khách xác nhận ngoài hệ thống',
  cancellation_reason TEXT NULL COMMENT 'Lý do hủy; nếu EXTERNAL_CONFIRMATION thì ghi rõ kênh xác nhận, thời điểm, người xác nhận và lý do.',
  preparation_note TEXT NULL COMMENT 'Ghi chú chuẩn bị nội bộ của Host cho campus visit instance',

  row_version INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Optimistic concurrency token',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (visit_instance_id),
  UNIQUE KEY uq_visit_instance_request_campus (visit_request_id, campus_id),
  -- Composite unique so per-campus v2 tables can carry a (visit_request_id, visit_instance_id)
  -- FK. visit_instance_id is already the PK, so this composite is trivially unique.
  UNIQUE KEY uq_vrc_request_instance (visit_request_id, visit_instance_id),
  KEY idx_visit_instances_campus_status_time (campus_id, status, planned_start_at),
  KEY idx_visit_instances_request (visit_request_id),
  KEY idx_visit_instances_status_time (status, planned_start_at),
  KEY idx_visit_instances_coordinator (coordinator_user_id, status),
  KEY idx_visit_instances_coordinator_assigned (coordinator_assigned_by, coordinator_assigned_at),
  KEY idx_visit_instances_current_host (current_host_user_id, status),
  KEY idx_visit_instances_host_assigned (host_assigned_by, host_assigned_at),
  KEY idx_visit_instances_decision (decided_by, decided_at),
  KEY idx_visit_instances_decision_role (decision_actor_role, decided_at),
  KEY idx_visit_instances_decision_source (decision_source, decided_at),
  KEY idx_visit_instances_cancelled (cancelled_by, cancelled_at),
  KEY idx_visit_instances_cancel_actor (cancellation_actor_type, cancelled_at),
  KEY idx_visit_instances_visibility_campus_request (campus_id, visit_request_id, status, current_host_user_id),
  -- Own-scope lookup của đầu mối vận hành (plan §4.2).
  KEY idx_visit_instances_op_contact (operational_contact_user_id, visit_instance_id),
  -- Hàng chờ Staff Leader theo campus (plan §4.2).
  KEY idx_visit_instances_leader_queue (campus_id, status, visit_request_id),
  -- "Những campus nào đang chờ tôi làm Host dự kiến" + quét proposal khi cổng vừa mở.
  KEY idx_visit_instances_proposed_host (proposed_host_user_id, proposed_host_activation_status),

  CHECK (planned_end_at > planned_start_at),
  -- Mode và người đề xuất phải khớp nhau, nếu không "chờ phân công sau" và "đã chọn ai đó" sẽ
  -- cùng tồn tại trên một dòng và không đường đọc nào phân biệt được.
  CONSTRAINT ck_vrc_proposed_host_mode CHECK (
    (host_selection_mode = 'WAIT_FOR_LATER' AND proposed_host_user_id IS NULL)
    OR (host_selection_mode IN ('SELF','SELECTED') AND proposed_host_user_id IS NOT NULL)),
  -- Có Host dự kiến thì phải biết AI đề xuất, LÚC NÀO và proposal đang ở trạng thái nào —
  -- đó là toàn bộ bằng chứng cho việc kích hoạt sau này (plan §7.1).
  CONSTRAINT ck_vrc_proposed_host_meta CHECK (
    (proposed_host_user_id IS NULL
      AND proposed_host_by_user_id IS NULL
      AND proposed_host_at IS NULL
      AND proposed_host_activation_status IS NULL
      AND proposed_host_activated_at IS NULL)
    OR (proposed_host_user_id IS NOT NULL
      AND proposed_host_by_user_id IS NOT NULL
      AND proposed_host_at IS NOT NULL
      AND proposed_host_activation_status IS NOT NULL)),
  -- Chỉ proposal ĐÃ kích hoạt mới có thời điểm kích hoạt.
  CONSTRAINT ck_vrc_proposed_host_activated_at CHECK (
    (proposed_host_activation_status = 'ACTIVATED' AND proposed_host_activated_at IS NOT NULL)
    OR (COALESCE(proposed_host_activation_status,'') <> 'ACTIVATED' AND proposed_host_activated_at IS NULL)),
  -- Minimum visit duration 30 minutes (per-campus form v2, §4.5). The end>start
  -- check above is retained; this adds the named minimum-duration rule.
  CONSTRAINT ck_visit_instance_min_duration_30m
    CHECK (TIMESTAMPDIFF(MINUTE, planned_start_at, planned_end_at) >= 30),

  CONSTRAINT fk_visit_instances_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_instances_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_instances_operational_contact
    FOREIGN KEY (operational_contact_user_id) REFERENCES users(user_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_visit_instances_coordinator
    FOREIGN KEY (coordinator_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_instances_coordinator_assigned_by
    FOREIGN KEY (coordinator_assigned_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_instances_current_host
    FOREIGN KEY (current_host_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_instances_host_assigned_by
    FOREIGN KEY (host_assigned_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  -- RESTRICT cả hai chiều, không CASCADE và không SET NULL. Hai lý do:
  --   1. Nghiệp vụ: xóa người đang được đề xuất mà im lặng bỏ proposal sẽ để lại mode SELF/SELECTED
  --      với proposed_host_user_id NULL — đúng thứ ck_vrc_proposed_host_mode tồn tại để chặn.
  --   2. MySQL: một cột vừa nằm trong CHECK vừa nằm trong FK có referential action (CASCADE/SET NULL)
  --      bị từ chối ngay lúc CREATE TABLE (ER_CHECK_CONSTRAINT_CLAUSE_USING_FK_REFER_ACTION_COLUMN).
  CONSTRAINT fk_visit_instances_proposed_host
    FOREIGN KEY (proposed_host_user_id) REFERENCES users(user_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_visit_instances_proposed_host_by
    FOREIGN KEY (proposed_host_by_user_id) REFERENCES users(user_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_visit_instances_decided_by
    FOREIGN KEY (decided_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_instances_closed_by
    FOREIGN KEY (closed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_instances_cancelled_by
    FOREIGN KEY (cancelled_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Mỗi campus trong request có một instance riêng, mang đầu mối vận hành + Host dự kiến + quyết định riêng. Staff Leader campus xử lý approve/reject độc lập và CHỈ sau khi mọi đầu mối của request đã xác nhận. Hai đường tới ASSIGNED: (a) Staff Leader duyệt + gán Host (STANDARD_CAMPUS_REVIEW), (b) Host dự kiến đã preauthorize được revalidate và kích hoạt ngay khi cổng mở (PREAUTHORIZED_HOST_ACTIVATION). ASSIGNED -> BEFORE_VISIT vẫn phải do Host bấm Bắt đầu chuẩn bị.';

CREATE TABLE visit_guest_members (
  guest_member_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  member_type ENUM('GUEST','EXTERNAL_SUPPORT') NOT NULL DEFAULT 'GUEST',
  full_name VARCHAR(150) NOT NULL,
  organization VARCHAR(200) NOT NULL,
  job_title VARCHAR(150) NOT NULL,
  nationality VARCHAR(100) NOT NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (guest_member_id),
  -- Composite unique so visit_instance_guest_members can carry a
  -- (visit_request_id, guest_member_id) FK. guest_member_id is already unique.
  UNIQUE KEY uq_vgm_request_member (visit_request_id, guest_member_id),
  KEY idx_guest_members_request (visit_request_id),
  KEY idx_guest_members_type_order (visit_request_id, member_type, display_order),
  CHECK (TRIM(full_name) <> ''),
  CHECK (TRIM(organization) <> ''),
  CHECK (TRIM(job_title) <> ''),
  CHECK (TRIM(nationality) <> ''),
  CONSTRAINT fk_guest_members_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Danh sách từng người trong đoàn khách. Không lưu consent hình ảnh vì form đã bỏ phần xác nhận sử dụng hình ảnh/thông tin.';

CREATE TABLE visit_participants (
  participant_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  user_id BIGINT UNSIGNED NOT NULL,
  participant_role ENUM('IC_HOST','IC_SUPPORT','DEPT_SUPPORT','STUDENT') NOT NULL DEFAULT 'IC_SUPPORT',
  is_host BOOLEAN NOT NULL DEFAULT FALSE,
  status ENUM('INVITED','ACCEPTED','DECLINED','ASSIGNED','REMOVED') NOT NULL DEFAULT 'INVITED',
  invited_by BIGINT UNSIGNED NULL,
  invited_at DATETIME NULL,
  responded_at DATETIME NULL,
  assigned_by BIGINT UNSIGNED NULL,
  assigned_at DATETIME NULL,
  note TEXT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (participant_id),
  UNIQUE KEY uq_visit_participants_user (visit_instance_id, user_id),
  KEY idx_visit_participants_one_host_lookup (visit_instance_id, is_host),
  KEY idx_visit_participants_user_status (user_id, status),
  KEY idx_visit_participants_instance (visit_instance_id),
  KEY idx_visit_participants_role_status (participant_role, status),
  CONSTRAINT fk_visit_participants_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_participants_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_participants_invited_by
    FOREIGN KEY (invited_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_participants_assigned_by
    FOREIGN KEY (assigned_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Người nội bộ tham gia visit instance. Chỉ gồm IC_HOST, IC_SUPPORT, DEPT_SUPPORT, STUDENT. Host chính lưu bằng is_host.';

-- =====================================================================
-- STUDENT VISIT PHOTO STORAGE (GOOGLE DRIVE, INDEPENDENT FROM GALLERY)
-- =====================================================================
-- Binary images are stored on Google Drive. The files table stores the
-- provider metadata. These two tables only model the business ownership:
-- one Drive child folder per visit request/delegation, and photo rows per
-- campus instance. Nothing here creates or publishes Gallery content.

CREATE TABLE visit_photo_folders (
  visit_photo_folder_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,

  storage_provider ENUM('GOOGLE_DRIVE') NOT NULL DEFAULT 'GOOGLE_DRIVE',
  external_folder_id VARCHAR(255) NOT NULL
    COMMENT 'Google Drive folder id below configured VisitRequestPhotoFolderId root',
  folder_name VARCHAR(255) NOT NULL
    COMMENT 'Stable application-generated name, recommended: VR-{visit_request_id or request_code}',
  web_view_url VARCHAR(700) NULL,

  status ENUM('ACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (visit_photo_folder_id),
  UNIQUE KEY uq_visit_photo_folders_request (visit_request_id),
  UNIQUE KEY uq_visit_photo_folders_external (external_folder_id),
  UNIQUE KEY uq_visit_photo_folders_folder_request (visit_photo_folder_id, visit_request_id),
  KEY idx_visit_photo_folders_status (status, created_at),
  KEY idx_visit_photo_folders_created_by (created_by, created_at),

  CONSTRAINT fk_visit_photo_folders_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_photo_folders_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_photo_folders_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CHECK (TRIM(external_folder_id) <> ''),
  CHECK (TRIM(folder_name) <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='One private Google Drive child folder per visit request/delegation; root folder id is application configuration, not Gallery data.';

CREATE TABLE visit_photos (
  visit_photo_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  visit_photo_folder_id BIGINT UNSIGNED NOT NULL,
  file_id BIGINT UNSIGNED NOT NULL,

  caption VARCHAR(500) NULL,
  taken_at DATETIME NULL,

  status ENUM('ACTIVE','REMOVED') NOT NULL DEFAULT 'ACTIVE',
  uploaded_by BIGINT UNSIGNED NOT NULL
    COMMENT 'Student user who uploaded the image; validated against ACCEPTED STUDENT participation by trigger and backend',
  uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  removed_at DATETIME NULL,
  removed_by BIGINT UNSIGNED NULL,
  removal_reason VARCHAR(500) NULL,

  PRIMARY KEY (visit_photo_id),
  UNIQUE KEY uq_visit_photos_file (file_id),
  UNIQUE KEY uq_visit_photos_face_scan_scope
    (visit_photo_id, visit_request_id, visit_instance_id, file_id),
  KEY idx_visit_photos_request_time (visit_request_id, uploaded_at),
  KEY idx_visit_photos_instance_time (visit_instance_id, uploaded_at),
  KEY idx_visit_photos_folder_time (visit_photo_folder_id, uploaded_at),
  KEY idx_visit_photos_uploader_time (uploaded_by, uploaded_at),
  KEY idx_visit_photos_status_time (status, uploaded_at),

  CONSTRAINT fk_visit_photos_request_instance
    FOREIGN KEY (visit_request_id, visit_instance_id)
    REFERENCES visit_request_campuses(visit_request_id, visit_instance_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_photos_folder_request
    FOREIGN KEY (visit_photo_folder_id, visit_request_id)
    REFERENCES visit_photo_folders(visit_photo_folder_id, visit_request_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_photos_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_photos_uploaded_by
    FOREIGN KEY (uploaded_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_visit_photos_removed_by
    FOREIGN KEY (removed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CHECK (caption IS NULL OR TRIM(caption) <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Private visit/delegation photos uploaded by an ACCEPTED Student participant. Binary is on Drive and metadata is in files; independent from Gallery.';

-- =====================================================================
-- PER-CAMPUS FORM v2 + IDENTITY EDIT + AMENDMENT MODULE
-- (docs/ChangeSauHopChiQUyen/sauhop_13-07/PEMS_MULTI_CAMPUS_PER_CAMPUS_FORM_AND_IDENTITY_EDIT_PLAN.md)
-- Additive tables. Standalone patch/backfill/verify/rollback live in
-- docs/database/scripts/percampus_v2_migration/. These CREATE TABLEs are the
-- fresh-create equivalent of 02_up_additive.sql sections 3-6.
-- =====================================================================

-- One full form snapshot PER campus instance (active v2 data).
CREATE TABLE visit_instance_form_details (
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  delegation_name VARCHAR(200) NOT NULL COMMENT 'Tên đoàn hiển thị tại campus này',
  visit_type ENUM('CAMPUS_TOUR','MEETING','WORKSHOP','SIGNING_CEREMONY','EXCHANGE','OTHER') NOT NULL DEFAULT 'CAMPUS_TOUR',
  visit_type_other VARCHAR(255) NULL,
  purpose TEXT NOT NULL COMMENT 'Mục đích tại campus này',
  working_content TEXT NULL COMMENT 'Nội dung làm việc tại campus này',
  operational_contact_full_name VARCHAR(150) NOT NULL COMMENT 'Tên đầu mối làm việc tại cơ sở (snapshot). Tên trùng KHÔNG phải bằng chứng cùng người.',
  operational_contact_organization VARCHAR(255) NULL
    COMMENT 'Optional; blank normalized to NULL by the create/edit service (ck rejects empty string)',
  operational_contact_job_title VARCHAR(150) NOT NULL
    COMMENT 'BẮT BUỘC. Chức vụ đầu mối (snapshot). Là thứ cho campus biết người bên kia đầu dây tự quyết được lịch hay phải đi hỏi; màn chi tiết luôn hiển thị đủ Họ tên/Đơn vị/Chức vụ/SĐT/Email.',
  operational_contact_phone VARCHAR(50) NULL
    COMMENT 'SĐT đầu mối (snapshot, optional — đầu mối chỉ có email vẫn dùng được). SĐT trùng KHÔNG phải bằng chứng cùng người; blank normalize thành NULL.',
  operational_contact_email VARCHAR(150) NOT NULL
    COMMENT 'BẮT BUỘC. Normalize tại application boundary; là email duy nhất dùng để bind lời mời xác nhận đầu mối cho campus này. Danh tính runtime đọc từ visit_request_campuses.operational_contact_user_id, KHÔNG từ email này.',
  working_language ENUM('VI','EN') NOT NULL DEFAULT 'EN',
  transportation_note TEXT NULL,
  media_consent_status ENUM('AGREED','DECLINED') NOT NULL DEFAULT 'DECLINED',
  notes TEXT NULL
    COMMENT 'Ghi chú bổ sung chung của khách gửi FPTU tại campus này',
  form_revision INT UNSIGNED NOT NULL DEFAULT 1,
  approval_revision INT UNSIGNED NOT NULL DEFAULT 1,
  row_version INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (visit_instance_id),
  KEY idx_vifd_visit_type (visit_type),
  KEY idx_vifd_language (working_language),
  KEY idx_vifd_media_consent (media_consent_status),
  KEY idx_vifd_op_contact_email (operational_contact_email),
  FULLTEXT KEY ft_vifd_search (delegation_name, purpose, working_content,
    operational_contact_full_name, operational_contact_organization, operational_contact_email),
  CONSTRAINT ck_vifd_visit_type_other CHECK (visit_type <> 'OTHER'
    OR (visit_type_other IS NOT NULL AND TRIM(visit_type_other) <> '')),
  CONSTRAINT ck_vifd_delegation_name CHECK (TRIM(delegation_name) <> ''),
  CONSTRAINT ck_vifd_purpose CHECK (TRIM(purpose) <> ''),
  CONSTRAINT ck_vifd_op_contact_name CHECK (TRIM(operational_contact_full_name) <> ''),
  CONSTRAINT ck_vifd_op_contact_org CHECK (
    operational_contact_organization IS NULL OR TRIM(operational_contact_organization) <> ''),
  CONSTRAINT ck_vifd_op_contact_job_title CHECK (TRIM(operational_contact_job_title) <> ''),
  CONSTRAINT ck_vifd_op_contact_phone CHECK (
    operational_contact_phone IS NULL OR TRIM(operational_contact_phone) <> ''),
  CONSTRAINT ck_vifd_op_contact_email CHECK (TRIM(operational_contact_email) <> ''),
  CONSTRAINT fk_vifd_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses (visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Snapshot form đầy đủ, độc lập cho từng campus instance (v2). Mỗi row là bản hoàn chỉnh; không có cờ same_as_other_campus.';

-- Per-campus guest/support links; composite FKs bind member+instance to the same request.
CREATE TABLE visit_instance_guest_members (
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  guest_member_id BIGINT UNSIGNED NOT NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (visit_instance_id, guest_member_id),
  KEY idx_vigm_request (visit_request_id),
  KEY idx_vigm_member (guest_member_id),
  KEY idx_vigm_instance_order (visit_instance_id, display_order),
  CONSTRAINT fk_vigm_instance
    FOREIGN KEY (visit_request_id, visit_instance_id)
    REFERENCES visit_request_campuses (visit_request_id, visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_vigm_member
    FOREIGN KEY (visit_request_id, guest_member_id)
    REFERENCES visit_guest_members (visit_request_id, guest_member_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Bảng nối khách/đội hỗ trợ theo campus instance. Composite FK chống cross-request link; copy-on-write khi campus dùng chung member cũ được sửa.';

-- Operational-contact INITIAL_CONFIRMATION / TRANSFER state machine, scoped to ONE campus
-- instance (NOT a token store — the single-use hashed token lives in email_action_tokens).
CREATE TABLE visit_request_identity_changes (
  identity_change_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL
    COMMENT 'Campus mà lời mời này thuộc về. Một email phụ trách N campus vẫn có N row riêng.',
  change_kind ENUM('INITIAL_CONFIRMATION','TRANSFER') NOT NULL,
  token_version INT UNSIGNED NOT NULL DEFAULT 1
    COMMENT 'Tăng mỗi lần resend. Dùng trong dedupe key OP_CONTACT_CONFIRM:{id}:{tokenVersion} và để supersede token cũ.',
  confirmation_method ENUM('GOOGLE_SSO','OTP_FALLBACK') NOT NULL DEFAULT 'GOOGLE_SSO',
  old_user_id BIGINT UNSIGNED NULL,
  new_user_id BIGINT UNSIGNED NULL,
  old_email_normalized VARCHAR(150) NULL,
  new_email_normalized VARCHAR(150) NULL COMMENT 'Required while PENDING; NULL after 90-day retention redaction',
  new_email_masked VARCHAR(150) NOT NULL,
  pending_snapshot_json JSON NULL,
  status ENUM('PENDING','APPLIED','DECLINED','EXPIRED','CANCELLED','SUPERSEDED') NOT NULL DEFAULT 'PENDING',
  expected_request_row_version INT UNSIGNED NOT NULL,
  requested_by BIGINT UNSIGNED NOT NULL,
  requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at DATETIME NOT NULL,
  applied_at DATETIME NULL,
  declined_at DATETIME NULL,
  cancelled_at DATETIME NULL,
  superseded_at DATETIME NULL,
  retention_until DATETIME NULL,
  redacted_at DATETIME NULL,
  reason VARCHAR(500) NULL,
  resend_count INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  -- Mỗi campus chỉ được có ĐÚNG MỘT identity change PENDING tại một thời điểm.
  pending_guard VARCHAR(80) GENERATED ALWAYS AS (
    CASE WHEN status = 'PENDING' THEN CONCAT('I:', visit_instance_id) ELSE NULL END
  ) VIRTUAL,
  PRIMARY KEY (identity_change_id),
  UNIQUE KEY uq_identity_change_pending (pending_guard),
  KEY idx_identity_change_instance_status (visit_instance_id, status),
  KEY idx_identity_change_request_status (visit_request_id, status),
  KEY idx_identity_change_status_expires (status, expires_at),
  KEY idx_identity_change_retention (status, retention_until),
  KEY idx_identity_change_new_email (new_email_normalized),
  -- "TRANSFER requires old_user_id" enforced by trg_identity_changes_transfer_bi/bu
  -- (a CHECK on old_user_id is rejected by MySQL 8.0 error 3823 — FK action column).
  -- Composite FK: lời mời luôn trỏ tới ĐÚNG campus của ĐÚNG request; payload sibling campus
  -- không thể tạo được row hợp lệ.
  CONSTRAINT fk_identity_change_instance
    FOREIGN KEY (visit_request_id, visit_instance_id)
    REFERENCES visit_request_campuses (visit_request_id, visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_identity_change_old_user
    FOREIGN KEY (old_user_id) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_identity_change_new_user
    FOREIGN KEY (new_user_id) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_identity_change_requested_by
    FOREIGN KEY (requested_by) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Trạng thái xác nhận/chuyển đầu mối vận hành THEO TỪNG CAMPUS. visit_request_campuses.operational_contact_user_id chỉ được set trong đúng transaction chuyển row này sang APPLIED.';

-- Append-only identity-change transition log (theo campus).
CREATE TABLE visit_request_identity_change_events (
  identity_change_event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  identity_change_id BIGINT UNSIGNED NOT NULL,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL COMMENT 'Campus của sự kiện; audit luôn truy được về đúng cơ sở',
  event_type VARCHAR(80) NOT NULL,
  from_status VARCHAR(30) NULL,
  to_status VARCHAR(30) NULL,
  actor_user_id BIGINT UNSIGNED NULL,
  email_masked VARCHAR(150) NULL,
  reason VARCHAR(500) NULL,
  correlation_id VARCHAR(100) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (identity_change_event_id),
  KEY idx_ice_change (identity_change_id, created_at),
  KEY idx_ice_request (visit_request_id, created_at),
  KEY idx_ice_instance (visit_instance_id, created_at),
  KEY idx_ice_correlation (correlation_id),
  CONSTRAINT fk_ice_change
    FOREIGN KEY (identity_change_id) REFERENCES visit_request_identity_changes (identity_change_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_ice_actor
    FOREIGN KEY (actor_user_id) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Append-only: mọi transition identity-change. Không update/delete ngoài retention job.';

-- Post-approval amendment (approval-sensitive change proposal) per campus instance.
CREATE TABLE visit_instance_amendments (
  amendment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  amendment_no INT UNSIGNED NOT NULL,
  status ENUM('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','WITHDRAWN','EXPIRED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
  base_form_revision INT UNSIGNED NOT NULL,
  base_approval_revision INT UNSIGNED NOT NULL,
  requested_by BIGINT UNSIGNED NOT NULL,
  requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reason VARCHAR(500) NULL,
  decided_by BIGINT UNSIGNED NULL,
  decided_at DATETIME NULL,
  decision_note VARCHAR(500) NULL,
  expires_at DATETIME NULL,
  withdrawn_at DATETIME NULL,
  expected_instance_row_version INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  amendment_pending_guard BIGINT UNSIGNED GENERATED ALWAYS AS (
    CASE WHEN status = 'PENDING_APPROVAL' THEN visit_instance_id ELSE NULL END
  ) VIRTUAL,
  PRIMARY KEY (amendment_id),
  UNIQUE KEY uq_amendment_pending (amendment_pending_guard),
  UNIQUE KEY uq_amendment_instance_no (visit_instance_id, amendment_no),
  KEY idx_amendment_instance_status_time (visit_instance_id, status, requested_at),
  KEY idx_amendment_request (visit_request_id, status),
  CONSTRAINT fk_amendment_instance
    FOREIGN KEY (visit_request_id, visit_instance_id)
    REFERENCES visit_request_campuses (visit_request_id, visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_amendment_requested_by
    FOREIGN KEY (requested_by) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_amendment_decided_by
    FOREIGN KEY (decided_by) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Đề xuất thay đổi approval-sensitive cho campus instance đã duyệt. Chỉ một PENDING_APPROVAL/instance.';

CREATE TABLE visit_instance_amendment_changes (
  amendment_change_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  amendment_id BIGINT UNSIGNED NOT NULL,
  field_path VARCHAR(150) NOT NULL,
  change_class VARCHAR(40) NOT NULL COMMENT 'SAFE | APPROVAL_SENSITIVE | STRUCTURAL | PRIVACY_URGENT',
  old_value_json JSON NULL,
  new_value_json JSON NULL,
  is_sensitive TINYINT(1) NOT NULL DEFAULT 0,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (amendment_change_id),
  KEY idx_amendment_change_amendment (amendment_id, display_order),
  CONSTRAINT fk_amendment_change_amendment
    FOREIGN KEY (amendment_id) REFERENCES visit_instance_amendments (amendment_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Field-level proposal của một amendment (immutable sau PENDING_APPROVAL).';

CREATE TABLE visit_instance_form_revision_history (
  revision_history_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  form_revision INT UNSIGNED NOT NULL,
  approval_revision INT UNSIGNED NOT NULL,
  source_type ENUM('CREATE','SAFE_EDIT','PENDING_EDIT','AMENDMENT_APPLIED','MIGRATION','RESUBMIT') NOT NULL,
  source_id BIGINT UNSIGNED NULL,
  snapshot_json JSON NOT NULL,
  applied_by BIGINT UNSIGNED NULL,
  applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reason VARCHAR(500) NULL,
  PRIMARY KEY (revision_history_id),
  UNIQUE KEY uq_vifrh_instance_form_revision (visit_instance_id, form_revision),
  KEY idx_vifrh_request_time (visit_request_id, applied_at),
  KEY idx_vifrh_source (source_type, source_id),
  CONSTRAINT fk_vifrh_instance
    FOREIGN KEY (visit_request_id, visit_instance_id)
    REFERENCES visit_request_campuses (visit_request_id, visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_vifrh_applied_by
    FOREIGN KEY (applied_by) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Lịch sử revision per-instance; mỗi form_revision là snapshot immutable.';

CREATE TABLE visit_request_revision_history (
  request_revision_history_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  request_revision INT UNSIGNED NOT NULL,
  source_type ENUM('CREATE','SAFE_EDIT','PENDING_EDIT','MIGRATION','RESUBMIT') NOT NULL,
  source_id BIGINT UNSIGNED NULL,
  snapshot_json JSON NOT NULL,
  applied_by BIGINT UNSIGNED NULL,
  applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reason VARCHAR(500) NULL,
  PRIMARY KEY (request_revision_history_id),
  UNIQUE KEY uq_vrrh_request_revision (visit_request_id, request_revision),
  KEY idx_vrrh_request_time (visit_request_id, applied_at),
  CONSTRAINT fk_vrrh_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests (visit_request_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_vrrh_applied_by
    FOREIGN KEY (applied_by) REFERENCES users (user_id) ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Lịch sử snapshot cấp request (display fields). Quan hệ email/account lấy identity-change events làm lịch sử chính.';

-- Public per-campus form v2 pending submission store (Phase G-4A).
-- Binds the full canonical v2 snapshot and fingerprint to the submit intent at
-- initiate, so verify creates the request from exactly the OTP-verified data.
-- Standalone by design: it belongs to a pre-create submission intent, not yet
-- to a persisted visit_request.
CREATE TABLE visit_request_pending_forms (
  pending_form_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  submission_id VARCHAR(36) NOT NULL,
  registrant_email VARCHAR(255) NOT NULL,
  fingerprint_v2 CHAR(64) NOT NULL,
  snapshot_json LONGTEXT NOT NULL,
  created_at DATETIME NOT NULL,
  expires_at DATETIME NOT NULL,
  consumed_at DATETIME NULL,
  PRIMARY KEY (pending_form_id),
  UNIQUE KEY uq_pending_forms_submission (submission_id),
  KEY idx_pending_forms_expires (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Bind snapshot v2 vào submit intent lúc initiate; verify tạo request từ snapshot đã bind. Consumed at verify.';

-- ── Fingerprint Guard (duplicate-submission row-level lock table) ────
CREATE TABLE visit_request_fingerprint_guards (
  fingerprint VARCHAR(64) NOT NULL,
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL,
  PRIMARY KEY (fingerprint)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Row-level lock table for 15-minute duplicate visit-request guard. INSERT IGNORE + SELECT … FOR UPDATE sequences concurrent submits.';


-- =====================================================================
-- AGENDA TEMPLATE MODULE (4 tables: agenda_templates, agenda_template_items,
-- agenda_template_defaults, visit_agendas).
-- Created here (before visit_agendas) so visit_agendas.source_template_item_id
-- can FK agenda_template_items. agenda_templates/agenda_template_defaults depend
-- only on campuses + users, both created earlier.
-- NOTE: the (campus_id NULL <=> campus_scope_key='GLOBAL') invariant is enforced
-- by BEFORE INSERT/UPDATE triggers (see trg_agenda_templates_scope_* /
-- trg_agenda_template_defaults_scope_*), NOT by a CHECK constraint, because
-- MySQL 8.0 forbids a CHECK on a column that also carries FK referential actions
-- (campus_id has ON UPDATE CASCADE / ON DELETE SET NULL). Same workaround as feedbacks.
-- =====================================================================

CREATE TABLE agenda_templates (
  agenda_template_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_id BIGINT UNSIGNED NULL,
  campus_scope_key VARCHAR(36) NOT NULL DEFAULT 'GLOBAL',
  visit_type ENUM('CAMPUS_TOUR','MEETING','WORKSHOP','SIGNING_CEREMONY','EXCHANGE','OTHER') NOT NULL,
  name VARCHAR(150) NOT NULL,
  description TEXT NULL,
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  deleted_at DATETIME NULL,
  deleted_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (agenda_template_id),
  UNIQUE KEY uq_agenda_template_scope_type_name (campus_scope_key, visit_type, name),
  KEY idx_agenda_templates_status (status),
  KEY idx_agenda_templates_scope_type_status (campus_scope_key, visit_type, status),
  KEY idx_agenda_templates_campus_type_status (campus_id, visit_type, status),
  CONSTRAINT fk_agenda_templates_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_templates_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_templates_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_templates_deleted_by
    FOREIGN KEY (deleted_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Agenda template header by campus/global scope and visit type. campus_scope_key derived by trigger.';

CREATE TABLE agenda_template_items (
  agenda_template_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  agenda_template_id BIGINT UNSIGNED NOT NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  start_offset_minutes INT UNSIGNED NOT NULL DEFAULT 0,
  duration_minutes INT UNSIGNED NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  location VARCHAR(255) NULL,
  responsible_role_label VARCHAR(150) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (agenda_template_item_id),
  UNIQUE KEY uq_agenda_template_items_order (agenda_template_id, display_order),
  KEY idx_agenda_template_items_template_offset (agenda_template_id, start_offset_minutes),
  CONSTRAINT fk_agenda_template_items_template
    FOREIGN KEY (agenda_template_id) REFERENCES agenda_templates(agenda_template_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_agenda_template_items_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_template_items_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CHECK (duration_minutes > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Agenda template timeline items using relative offset from campus planned_start_at.';

CREATE TABLE agenda_template_defaults (
  agenda_template_default_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_id BIGINT UNSIGNED NULL,
  campus_scope_key VARCHAR(36) NOT NULL DEFAULT 'GLOBAL',
  visit_type ENUM('CAMPUS_TOUR','MEETING','WORKSHOP','SIGNING_CEREMONY','EXCHANGE','OTHER') NOT NULL,
  agenda_template_id BIGINT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (agenda_template_default_id),
  UNIQUE KEY uq_agenda_template_default_scope_type (campus_scope_key, visit_type),
  KEY idx_agenda_template_defaults_template (agenda_template_id),
  KEY idx_agenda_template_defaults_campus_type (campus_id, visit_type),
  CONSTRAINT fk_agenda_template_defaults_template
    FOREIGN KEY (agenda_template_id) REFERENCES agenda_templates(agenda_template_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_agenda_template_defaults_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_template_defaults_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_agenda_template_defaults_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Default agenda template mapping by campus/global scope and visit type. campus_scope_key derived by trigger.';

CREATE TABLE visit_agendas (
  agenda_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  sequence_order INT UNSIGNED NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  start_time DATETIME NOT NULL,
  end_time DATETIME NULL,
  location VARCHAR(255) NULL,
  responsible_user_id BIGINT UNSIGNED NULL,
  responsible_name VARCHAR(255) NULL COMMENT 'Tên người phụ trách (nhập tay tự do, không ràng buộc user thật)',
  source_template_item_id BIGINT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (agenda_id),
  UNIQUE KEY uq_visit_agendas_order (visit_instance_id, sequence_order),
  KEY idx_visit_agendas_time (visit_instance_id, start_time),
  KEY idx_visit_agendas_responsible (responsible_user_id, start_time),
  KEY idx_visit_agendas_source_template_item (source_template_item_id),
  CONSTRAINT fk_visit_agendas_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_visit_agendas_responsible_user
    FOREIGN KEY (responsible_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_agendas_source_template_item
    FOREIGN KEY (source_template_item_id) REFERENCES agenda_template_items(agenda_template_item_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_agendas_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_agendas_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CHECK (end_time IS NULL OR end_time > start_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Concrete visit agenda rows per campus instance. start_time/end_time are absolute DATETIME computed from visit_request_campuses.planned_start_at + template offsets.';

CREATE TABLE visit_logistics_items (
  logistics_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,

  item_type ENUM('ROOM','TRANSPORT','MEAL','EQUIPMENT','BANNER','LED','OTHER') NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL COMMENT 'Nội dung chi tiết công việc gốc',
  coordination_mode ENUM('SYSTEM_REQUEST','OFFLINE_COORDINATED') NOT NULL DEFAULT 'SYSTEM_REQUEST'
    COMMENT 'SYSTEM_REQUEST=gửi yêu cầu xử lý qua hệ thống, OFFLINE_COORDINATED=đã trao đổi/xử lý bên ngoài hệ thống',
  offline_coordination_note TEXT NULL COMMENT 'Ghi chú khi yêu cầu đã được trao đổi/xử lý bên ngoài hệ thống',
  quantity INT UNSIGNED NULL COMMENT 'Số lượng yêu cầu gốc',

  usage_start_at DATETIME NULL COMMENT 'Thời gian bắt đầu sử dụng resource',
  usage_end_at DATETIME NULL COMMENT 'Thời gian kết thúc sử dụng resource',
  -- UPDATED 2026-06-26:
  -- Department Leader flow không dùng PLANNED/RECEIVED/READY.
  -- REQUESTED = đơn/thư đã gửi trực tiếp tới phòng ban.
  -- DECLINED = nhân sự từ chối lần phân công.
  -- REJECTED = từ chối toàn bộ đơn yêu cầu.
  status ENUM(
    'REQUESTED',
    'CHANGE_PROPOSED',
    'ASSIGNED',
    'ACCEPTED',
    'IN_PROGRESS',
    'DONE',
    'REJECTED',
    'DECLINED',
    'CANCELLED'
  ) NOT NULL DEFAULT 'REQUESTED'
    COMMENT 'REQUESTED=đơn đã gửi tới phòng ban; DECLINED=nhân sự từ chối lần phân công; REJECTED=từ chối toàn bộ đơn yêu cầu',

  priority ENUM('LOW','MEDIUM','HIGH','URGENT') NOT NULL DEFAULT 'MEDIUM',

  requested_by BIGINT UNSIGNED NULL COMMENT 'Người gửi yêu cầu hậu cần/resource',
  requested_to_department_id BIGINT UNSIGNED NULL COMMENT 'Phòng ban được yêu cầu xử lý',
  requested_at DATETIME NULL COMMENT 'Thời điểm gửi yêu cầu',

  received_by BIGINT UNSIGNED NULL COMMENT 'Trưởng phòng/người tiếp nhận yêu cầu',
  received_at DATETIME NULL COMMENT 'Thời điểm tiếp nhận yêu cầu',

  assigned_to_user_id BIGINT UNSIGNED NULL COMMENT 'Nhân viên được giao xử lý chính',
  assigned_by BIGINT UNSIGNED NULL COMMENT 'Người phân công',
  assigned_at DATETIME NULL COMMENT 'Thời điểm phân công',

  assignee_accepted_at DATETIME NULL COMMENT 'Thời điểm nhân viên xác nhận nhận nhiệm vụ',
  assignee_response_note TEXT NULL COMMENT 'Ghi chú khi nhân viên nhận/từ chối nếu có',

  due_at DATETIME NULL COMMENT 'Deadline hoàn thành hạng mục',
  completed_at DATETIME NULL COMMENT 'Thời điểm hoàn thành',

  proposed_by BIGINT UNSIGNED NULL COMMENT 'Người gửi đề xuất thay đổi',
  proposed_at DATETIME NULL COMMENT 'Thời điểm gửi đề xuất thay đổi',
  proposed_quantity INT UNSIGNED NULL COMMENT 'Số lượng được đề xuất thay đổi',
  proposed_usage_start_at DATETIME NULL COMMENT 'Thời gian bắt đầu sử dụng được đề xuất',
  proposed_usage_end_at DATETIME NULL COMMENT 'Thời gian kết thúc sử dụng được đề xuất',
  proposed_description TEXT NULL COMMENT 'Nội dung chi tiết công việc được đề xuất thay đổi',
  proposal_note TEXT NULL COMMENT 'Lý do/ghi chú đề xuất thay đổi',

  proposal_responded_by BIGINT UNSIGNED NULL COMMENT 'Người xác nhận/từ chối đề xuất',
  proposal_responded_at DATETIME NULL COMMENT 'Thời điểm xác nhận/từ chối đề xuất',
  proposal_response ENUM('ACCEPTED','REJECTED') NULL COMMENT 'Kết quả phản hồi đề xuất',
  proposal_response_note TEXT NULL COMMENT 'Ghi chú phản hồi đề xuất',


  decision_note TEXT NULL COMMENT 'Lý do reject/cancel hoặc ghi chú xử lý',

  row_version INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Optimistic concurrency token',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (logistics_item_id),

  KEY idx_logistics_instance_status (visit_instance_id, status),
  KEY idx_logistics_item_status (item_type, status),
  KEY idx_logistics_department_status (requested_to_department_id, status),
  KEY idx_logistics_assignee_status (assigned_to_user_id, status),
  KEY idx_logistics_requested_by_time (requested_by, requested_at),
  KEY idx_logistics_received_by_time (received_by, received_at),
  KEY idx_logistics_usage_time (usage_start_at, usage_end_at),
  KEY idx_logistics_due (due_at),
  KEY idx_logistics_priority_due (priority, due_at),
  KEY idx_logistics_proposed_by_time (proposed_by, proposed_at),
  CHECK (quantity IS NULL OR quantity >= 1),
  CHECK (usage_end_at IS NULL OR usage_start_at IS NULL OR usage_end_at > usage_start_at),
  CHECK (proposed_quantity IS NULL OR proposed_quantity >= 0),
  CHECK (proposed_usage_end_at IS NULL OR proposed_usage_start_at IS NULL OR proposed_usage_end_at > proposed_usage_start_at),

  CONSTRAINT fk_logistics_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_logistics_requested_by
    FOREIGN KEY (requested_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_requested_to_department
    FOREIGN KEY (requested_to_department_id) REFERENCES departments(department_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_received_by
    FOREIGN KEY (received_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_assigned_to
    FOREIGN KEY (assigned_to_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_assigned_by
    FOREIGN KEY (assigned_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_proposed_by
    FOREIGN KEY (proposed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_logistics_proposal_responded_by
    FOREIGN KEY (proposal_responded_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Yêu cầu hậu cần/resource cho visit: gửi yêu cầu, đề xuất thay đổi, tiếp nhận, phân công, xác nhận và hoàn thành. Ký mượn/ký trả lưu ở visit_logistics_item_handovers.';

CREATE TABLE visit_logistics_item_handovers (
  handover_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  logistics_item_id BIGINT UNSIGNED NOT NULL,

  handover_type ENUM('BORROW','RETURN') NOT NULL
    COMMENT 'BORROW=lúc giao/mượn đồ, RETURN=lúc trả/nhận lại đồ',

  borrower_signed_by BIGINT UNSIGNED NULL
    COMMENT 'Bên mượn ký: BORROW=ký nhận, RETURN=ký trả',
  borrower_signed_at DATETIME NULL,

  provider_signed_by BIGINT UNSIGNED NULL
    COMMENT 'Bên cho mượn ký: BORROW=ký bàn giao, RETURN=ký nhận lại',
  provider_signed_at DATETIME NULL,

  item_condition ENUM('GOOD','DAMAGED','MISSING','OTHER') NULL,
  condition_note TEXT NULL,
  attachment_file_id BIGINT UNSIGNED NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (handover_id),

  UNIQUE KEY uq_logistics_handover_type (logistics_item_id, handover_type),
  KEY idx_handover_item_type (logistics_item_id, handover_type),
  KEY idx_handover_borrower_signed (borrower_signed_by, borrower_signed_at),
  KEY idx_handover_provider_signed (provider_signed_by, provider_signed_at),
  KEY idx_handover_attachment_file (attachment_file_id),
  KEY idx_handover_created_by (created_by),

  CONSTRAINT fk_lh_item
    FOREIGN KEY (logistics_item_id) REFERENCES visit_logistics_items(logistics_item_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_lh_borrower_signed_by
    FOREIGN KEY (borrower_signed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_lh_provider_signed_by
    FOREIGN KEY (provider_signed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_lh_attachment_file
    FOREIGN KEY (attachment_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_lh_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Bảng lưu ký nhận/ký trả đồ mượn cho logistics item';

-- =====================================================================
-- VISIT EXPENSE STATISTICS (ADDITIVE)
-- GENERAL: Host/Staff/Staff Leader records costs in AFTER_VISIT.
-- LOGISTICS: Department records costs after logistics handover/signing.
-- =====================================================================

CREATE TABLE visit_expense_reports (
  expense_report_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  report_scope ENUM('GENERAL','LOGISTICS') NOT NULL,
  logistics_item_id BIGINT UNSIGNED NULL,
  department_id BIGINT UNSIGNED NULL,
  status ENUM('DRAFT','SAVED','FINALIZED','CANCELLED') NOT NULL DEFAULT 'DRAFT',
  report_note TEXT NULL,
  no_expense TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 = phòng ban/host xác nhận không phát sinh chi phí cho báo cáo này',
  currency_code CHAR(3) NOT NULL DEFAULT 'VND',
  saved_at DATETIME NULL,
  saved_by BIGINT UNSIGNED NULL,
  finalized_at DATETIME NULL,
  finalized_by BIGINT UNSIGNED NULL,
  cancelled_at DATETIME NULL,
  cancelled_by BIGINT UNSIGNED NULL,
  cancellation_reason TEXT NULL,
  row_version INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  general_instance_guard BIGINT UNSIGNED NULL
    COMMENT 'Trigger-maintained uniqueness guard: visit_instance_id for GENERAL, otherwise NULL',
  logistics_item_guard BIGINT UNSIGNED NULL
    COMMENT 'Trigger-maintained uniqueness guard: logistics_item_id for LOGISTICS, otherwise NULL',

  PRIMARY KEY (expense_report_id),
  UNIQUE KEY uq_expense_general_instance (general_instance_guard),
  UNIQUE KEY uq_expense_logistics_item (logistics_item_guard),
  KEY idx_expense_reports_instance_scope_status (visit_instance_id, report_scope, status),
  KEY idx_expense_reports_department_status (department_id, status),
  KEY idx_expense_reports_logistics_item (logistics_item_id),
  KEY idx_expense_reports_saved_time (saved_at),

  CONSTRAINT ck_expense_report_currency CHECK (currency_code = 'VND'),

  CONSTRAINT fk_expense_reports_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_expense_reports_logistics
    FOREIGN KEY (logistics_item_id) REFERENCES visit_logistics_items(logistics_item_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_expense_reports_department
    FOREIGN KEY (department_id) REFERENCES departments(department_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_expense_reports_saved_by
    FOREIGN KEY (saved_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_expense_reports_finalized_by
    FOREIGN KEY (finalized_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_expense_reports_cancelled_by
    FOREIGN KEY (cancelled_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_expense_reports_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_expense_reports_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Bảng đầu chi phí theo campus instance; GENERAL do Host nhập, LOGISTICS do Department nhập theo đơn hậu cần.';

CREATE TABLE visit_expense_items (
  expense_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  expense_report_id BIGINT UNSIGNED NOT NULL,
  item_origin ENUM('REQUEST_ITEM','MANUAL','ADDITIONAL','DAMAGE_LOSS','OTHER') NOT NULL DEFAULT 'MANUAL',
  item_name VARCHAR(255) NOT NULL,
  description TEXT NULL,
  quantity DECIMAL(12,2) NOT NULL DEFAULT 1,
  unit_name VARCHAR(50) NULL,
  unit_price DECIMAL(18,2) NOT NULL DEFAULT 0,
  total_amount DECIMAL(18,2) GENERATED ALWAYS AS (ROUND(quantity * unit_price, 2)) STORED,
  item_note TEXT NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  row_version INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (expense_item_id),
  KEY idx_expense_items_report_order (expense_report_id, display_order, expense_item_id),
  KEY idx_expense_items_origin (item_origin),
  CONSTRAINT ck_expense_item_name CHECK (CHAR_LENGTH(TRIM(item_name)) > 0),
  CONSTRAINT ck_expense_item_quantity CHECK (quantity > 0),
  CONSTRAINT ck_expense_item_unit_price CHECK (unit_price >= 0),
  CONSTRAINT fk_expense_items_report
    FOREIGN KEY (expense_report_id) REFERENCES visit_expense_reports(expense_report_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_expense_items_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_expense_items_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Chi tiết các khoản chi; thành tiền được tính tự động bằng số lượng nhân đơn giá.';

CREATE TABLE visit_expense_report_events (
  expense_event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  expense_report_id BIGINT UNSIGNED NOT NULL,
  event_type ENUM('CREATED','SAVED','UPDATED','FINALIZED','REOPENED','CANCELLED','EXPORTED') NOT NULL,
  event_note TEXT NULL,
  snapshot_json JSON NULL,
  performed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  performed_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (expense_event_id),
  KEY idx_expense_events_report_time (expense_report_id, performed_at),
  KEY idx_expense_events_actor_time (performed_by, performed_at),
  CONSTRAINT fk_expense_events_report
    FOREIGN KEY (expense_report_id) REFERENCES visit_expense_reports(expense_report_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_expense_events_actor
    FOREIGN KEY (performed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Lịch sử lưu/chốt/mở lại/xuất thống kê chi phí.';


-- =====================================================================
-- ADDED 2026-06-25 — Department Leader logistics assignment attempts
-- Purpose:
--   - Lưu từng lần Department Leader phân công đơn yêu cầu logistics cho nhân sự phòng ban.
--   - Cho phép phân công lại nếu nhân sự được giao trước đó DECLINED và có lý do.
--   - Không phải task transfer sau khi ACCEPTED/IN_PROGRESS/DONE.
--   - Giữ visit_logistics_items là trạng thái hiện tại; bảng này lưu lịch sử từng lần giao.
-- Business flow:
--   PENDING  = đã giao, đang chờ nhân sự phản hồi
--   ACCEPTED = nhân sự đã nhận nhiệm vụ
--   DECLINED = nhân sự từ chối, bắt buộc có response_note
--   CANCELLED = lần giao bị hủy trước khi phản hồi, nếu cần
-- =====================================================================
CREATE TABLE visit_logistics_assignment_attempts (
  assignment_attempt_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  logistics_item_id BIGINT UNSIGNED NOT NULL,

  assignee_user_id BIGINT UNSIGNED NOT NULL
    COMMENT 'Nhân sự phòng ban được Department Leader phân công trong lần giao này',
  assigned_by BIGINT UNSIGNED NOT NULL
    COMMENT 'Department Leader hoặc người có quyền đã phân công',
  assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    COMMENT 'Thời điểm phân công',

  status ENUM('PENDING','ACCEPTED','DECLINED','CANCELLED') NOT NULL DEFAULT 'PENDING'
    COMMENT 'Trạng thái phản hồi của riêng lần phân công này',

  responded_at DATETIME NULL
    COMMENT 'Thời điểm nhân sự phản hồi ACCEPTED/DECLINED',
  response_note TEXT NULL
    COMMENT 'Lý do từ chối hoặc ghi chú phản hồi; bắt buộc khi status=DECLINED',

  response_source ENUM('PORTAL','EMAIL_TOKEN','SYSTEM') NULL
    COMMENT 'Nguồn phản hồi: trong portal, nút email token, hoặc hệ thống',
  cancelled_by BIGINT UNSIGNED NULL
    COMMENT 'Người hủy lần phân công khi cần, không dùng cho transfer nhiệm vụ đã nhận',
  cancelled_at DATETIME NULL
    COMMENT 'Thời điểm hủy lần phân công',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (assignment_attempt_id),

  KEY idx_vla_item_status (logistics_item_id, status),
  KEY idx_vla_assignee_status (assignee_user_id, status),
  KEY idx_vla_assigned_by_time (assigned_by, assigned_at),
  KEY idx_vla_responded_at (responded_at),
  KEY idx_vla_cancelled_by (cancelled_by),

  CONSTRAINT fk_vla_item
    FOREIGN KEY (logistics_item_id) REFERENCES visit_logistics_items(logistics_item_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_vla_assignee
    FOREIGN KEY (assignee_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_vla_assigned_by
    FOREIGN KEY (assigned_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_vla_cancelled_by
    FOREIGN KEY (cancelled_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Lịch sử từng lần phân công logistics item cho nhân sự phòng ban; cho phép phân công lại sau khi lần trước DECLINED.';


-- =====================================================================
-- 6. MINUTES + FEEDBACK
-- =====================================================================
-- Final simplified design:
-- - minutes: main meeting minutes only; no embedded attachment/action JSON fields.
-- - minute_action_items: separate CRUD for action items with note, deadline, status.
-- - feedbacks: one row per submitted feedback with typed business target.
--   Visitor submits overall visit feedback; Host submits overall delegation feedback, participant/support feedback, and logistics/resource feedback.
-- - feedbacks.rating remains required 1..5 stars; feedbacks.comment is optional text.
-- - feedback_rating_items keeps normalized per-criterion 1..5 star ratings when a detailed form is used.

CREATE TABLE minutes (
  minutes_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,

  title VARCHAR(255) NOT NULL,
  content LONGTEXT NULL,

  status ENUM('DRAFT','SAVED') NOT NULL DEFAULT 'DRAFT'
    COMMENT 'DRAFT=biên bản nháp, SAVED=đã lưu nội dung; quyền sửa bị khóa khi visit instance CLOSED',

  edit_locked_by BIGINT UNSIGNED NULL COMMENT 'User hiện đang giữ quyền sửa biên bản',
  edit_locked_at DATETIME NULL COMMENT 'Thời điểm bắt đầu giữ quyền sửa',
  edit_lock_expires_at DATETIME NULL COMMENT 'Thời điểm lock sửa hết hạn',
  edit_lock_token CHAR(36) NULL COMMENT 'Token phiên sửa, dùng để xác nhận đúng người đang giữ lock',
  row_version INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Version chống ghi đè khi cập nhật đồng thời',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (minutes_id),

  UNIQUE KEY uq_minutes_visit_instance (visit_instance_id),
  KEY idx_minutes_visit_status (visit_instance_id, status),
  KEY idx_minutes_created_by_time (created_by, created_at),
  KEY idx_minutes_edit_lock (edit_locked_by, edit_lock_expires_at),

  FULLTEXT KEY ft_minutes_search (title, content),

  CONSTRAINT fk_minutes_visit_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_minutes_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_minutes_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_minutes_edit_locked_by
    FOREIGN KEY (edit_locked_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Biên bản chuyến thăm. Không lưu file đính kèm và không lưu action item dạng JSON; action item tách bảng riêng.';

CREATE TABLE minute_participants (
  minute_participant_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  minutes_id BIGINT UNSIGNED NOT NULL,
  user_id BIGINT UNSIGNED NULL,
  guest_member_id BIGINT UNSIGNED NULL,
  full_name_snapshot VARCHAR(255) NOT NULL,
  role_snapshot VARCHAR(120) NULL,
  organization_snapshot VARCHAR(255) NULL,
  email_snapshot VARCHAR(150) NULL,
  attendance_status ENUM('PRESENT','ABSENT','EXCUSED') NOT NULL DEFAULT 'PRESENT' COMMENT 'PRESENT=có mặt, ABSENT=vắng mặt, EXCUSED=vắng có lý do',
  attendance_note TEXT NULL COMMENT 'Ghi chú điểm danh/lý do vắng nếu có',
  checked_at DATETIME NULL COMMENT 'Thời điểm ghi nhận điểm danh',
  checked_by BIGINT UNSIGNED NULL COMMENT 'Người thực hiện điểm danh',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (minute_participant_id),
  KEY idx_minute_participants_minutes_order (minutes_id, display_order),
  KEY idx_minute_participants_user (user_id),
  KEY idx_minute_participants_guest_member (guest_member_id),
  KEY idx_minute_participants_attendance (minutes_id, attendance_status),
  KEY idx_minute_participants_checked_by (checked_by),
  CONSTRAINT fk_minute_participants_minutes
    FOREIGN KEY (minutes_id) REFERENCES minutes(minutes_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_minute_participants_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_minute_participants_guest_member
    FOREIGN KEY (guest_member_id) REFERENCES visit_guest_members(guest_member_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_minute_participants_checked_by
    FOREIGN KEY (checked_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Snapshot participant list for meeting minutes; replaces minutes.participants_json.';


-- ---------------------------------------------------------------------
-- Partner module: visit_guest_partner_links
-- ---------------------------------------------------------------------
CREATE TABLE visit_guest_partner_links (
  link_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NULL,

  guest_member_id BIGINT UNSIGNED NULL,
  minute_participant_id BIGINT UNSIGNED NULL,

  partner_id BIGINT UNSIGNED NOT NULL,
  partner_contact_id BIGINT UNSIGNED NULL,

  match_source ENUM(
    'AUTO_NAME',
    'AUTO_EMAIL_DOMAIN',
    'MANUAL',
    'CREATED_FROM_GUEST',
    'BUSINESS_CARD_OCR'
  ) NOT NULL DEFAULT 'MANUAL',

  match_status ENUM('SUGGESTED','CONFIRMED','REJECTED') NOT NULL DEFAULT 'CONFIRMED',

  confidence_score DECIMAL(5,2) NULL,
  note TEXT NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (link_id),

  KEY idx_vgpl_visit_request (visit_request_id),
  KEY idx_vgpl_visit_instance (visit_instance_id),
  KEY idx_vgpl_guest_member (guest_member_id),
  KEY idx_vgpl_minute_participant (minute_participant_id),
  KEY idx_vgpl_partner (partner_id),
  KEY idx_vgpl_contact (partner_contact_id),
  KEY idx_vgpl_status (match_status),
  KEY idx_vgpl_source (match_source),

  CONSTRAINT fk_vgpl_visit_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_vgpl_visit_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_vgpl_guest_member
    FOREIGN KEY (guest_member_id) REFERENCES visit_guest_members(guest_member_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_vgpl_minute_participant
    FOREIGN KEY (minute_participant_id) REFERENCES minute_participants(minute_participant_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_vgpl_partner
    FOREIGN KEY (partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_vgpl_partner_contact
    FOREIGN KEY (partner_contact_id) REFERENCES partner_contacts(contact_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_vgpl_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_vgpl_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL

  -- NOTE: MySQL 8 rejects CHECK (guest_member_id IS NOT NULL OR minute_participant_id IS NOT NULL)
  -- because both columns join FKs with ON DELETE SET NULL (error 3823). The rule
  -- "at least one of guest_member_id / minute_participant_id" is enforced by the backend validator.
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Links visit guests/minute participants to partner profiles for partner labels and partner history.';

CREATE TABLE minute_action_items (
  action_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  minutes_id BIGINT UNSIGNED NOT NULL,

  title VARCHAR(255) NOT NULL COMMENT 'Tên đầu việc',
  note TEXT NULL COMMENT 'Ghi chú thêm cho đầu việc',

  assigned_to_user_id BIGINT UNSIGNED NULL COMMENT 'Người phụ trách đầu mục — Host hoặc participant ACCEPTED (IC_SUPPORT/DEPT_SUPPORT/STUDENT) của chuyến thăm',

  due_date DATETIME NULL COMMENT 'Deadline ngày giờ của đầu việc',
  due_reminder_sent_at DATETIME NULL COMMENT 'Thời điểm đã gửi mail/thông báo nhắc hạn cho người phụ trách; NULL = chưa nhắc',

  status ENUM('TODO','IN_PROGRESS','DONE','CANCELLED') NOT NULL DEFAULT 'TODO'
    COMMENT 'TODO=chưa làm, IN_PROGRESS=đang làm, DONE=hoàn thành, CANCELLED=đã hủy/không cần làm nữa',

  completed_at DATETIME NULL COMMENT 'Thời điểm hoàn thành; backend tự set khi status chuyển sang DONE',

  display_order INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Thứ tự hiển thị trong biên bản',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (action_item_id),

  KEY idx_action_items_minutes (minutes_id),
  KEY idx_action_items_status_due (status, due_date),
  KEY idx_action_items_order (minutes_id, display_order),
  KEY idx_action_items_created_by_time (created_by, created_at),
  KEY idx_action_items_assignee (assigned_to_user_id, status),

  CONSTRAINT fk_action_items_minutes
    FOREIGN KEY (minutes_id) REFERENCES minutes(minutes_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_action_items_assignee
    FOREIGN KEY (assigned_to_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_action_items_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_action_items_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Các đầu việc sau biên bản. Không gán người phụ trách; chỉ có note, deadline và trạng thái hoàn thành.';

CREATE TABLE feedbacks (
  feedback_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NULL,

  feedback_type ENUM('VISITOR_OVERALL','HOST_DELEGATION_OVERALL','HOST_PARTICIPANT','HOST_LOGISTICS') NOT NULL
    COMMENT 'VISITOR_OVERALL=Visitor đánh giá chung chuyến thăm; HOST_DELEGATION_OVERALL=Host đánh giá chung đoàn khách; HOST_PARTICIPANT=Host đánh giá các bên tham gia/hỗ trợ; HOST_LOGISTICS=Host đánh giá bên cho mượn đồ/hậu cần',

  submitted_by_user_id BIGINT UNSIGNED NOT NULL COMMENT 'User gửi feedback; Visitor hoặc Host phải có tài khoản hệ thống',
  submitter_role ENUM('VISITOR','HOST') NOT NULL COMMENT 'Vai trò người gửi feedback trong rule hiện tại',
  submitter_context VARCHAR(120) NOT NULL DEFAULT ''
    COMMENT 'Ngữ cảnh vai trò người gửi, ví dụ: Host chính, Khách đại diện',
  submitter_name_snapshot VARCHAR(255) NOT NULL
    COMMENT 'Tên người gửi tại thời điểm gửi feedback',

  target_type ENUM('VISIT_REQUEST','VISIT_INSTANCE','VISIT_PARTICIPANT','GUEST_MEMBER','LOGISTICS_ITEM','LOGISTICS_HANDOVER','USER','DEPARTMENT') NOT NULL
    COMMENT 'Loại đối tượng nghiệp vụ được đánh giá. GUEST_MEMBER giữ để tương thích dữ liệu nhưng không dùng trong rule active hiện tại',
  target_user_id BIGINT UNSIGNED NULL COMMENT 'User được đánh giá nếu target là cá nhân; NULL đối với feedback tổng thể của Visitor',
  target_participant_id BIGINT UNSIGNED NULL COMMENT 'Participant nội bộ được Host đánh giá',
  target_guest_member_id BIGINT UNSIGNED NULL COMMENT 'Không dùng trong rule hiện tại; Host đánh giá chung đoàn khách qua VISIT_INSTANCE/VISIT_REQUEST, không đánh giá từng guest member',
  target_logistics_item_id BIGINT UNSIGNED NULL COMMENT 'Hạng mục logistics/resource được Host đánh giá',
  target_handover_id BIGINT UNSIGNED NULL COMMENT 'Lần ký mượn/trả cụ thể được Host đánh giá nếu cần',
  target_department_id BIGINT UNSIGNED NULL COMMENT 'Phòng ban/bên cho mượn đồ được Host đánh giá nếu đánh giá theo đơn vị',

  target_role VARCHAR(80) NULL COMMENT 'Snapshot vai trò/nhóm đối tượng hiển thị; không dùng làm rule chính',
  target_context VARCHAR(120) NOT NULL DEFAULT ''
    COMMENT 'Ngữ cảnh đối tượng được đánh giá, ví dụ: Đoàn khách, Student support, Teabreak, Phòng họp',
  target_name_snapshot VARCHAR(255) NOT NULL
    COMMENT 'Tên hoặc nhãn đối tượng được đánh giá tại thời điểm gửi feedback',

  rating TINYINT UNSIGNED NOT NULL COMMENT 'Số sao tổng thể từ 1 đến 5; bắt buộc',
  comment TEXT NULL COMMENT 'Nội dung nhận xét dạng text; không bắt buộc',

  submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (feedback_id),

  KEY idx_feedbacks_visit_request (visit_request_id),
  KEY idx_feedbacks_visit_instance (visit_instance_id),
  KEY idx_feedbacks_type (feedback_type),
  KEY idx_feedbacks_submitter (submitted_by_user_id),
  KEY idx_feedbacks_target_type (target_type),
  KEY idx_feedbacks_target_user (target_user_id),
  KEY idx_feedbacks_target_participant (target_participant_id),
  KEY idx_feedbacks_target_guest_member (target_guest_member_id),
  KEY idx_feedbacks_target_logistics_item (target_logistics_item_id),
  KEY idx_feedbacks_target_handover (target_handover_id),
  KEY idx_feedbacks_target_department (target_department_id),
  KEY idx_feedbacks_submitter_flow (submitter_role, feedback_type),
  KEY idx_feedbacks_rating (rating),
  KEY idx_feedbacks_submitted_at (submitted_at),

  CONSTRAINT chk_feedbacks_rating
    CHECK (rating BETWEEN 1 AND 5),

  CONSTRAINT chk_feedbacks_flow
    CHECK (
      (feedback_type = 'VISITOR_OVERALL'
        AND submitter_role = 'VISITOR'
        AND target_type IN ('VISIT_REQUEST','VISIT_INSTANCE'))
      OR
      (feedback_type = 'HOST_DELEGATION_OVERALL'
        AND submitter_role = 'HOST'
        AND target_type IN ('VISIT_REQUEST','VISIT_INSTANCE'))
      OR
      (feedback_type = 'HOST_PARTICIPANT'
        AND submitter_role = 'HOST'
        AND target_type IN ('VISIT_PARTICIPANT','USER','DEPARTMENT'))
      OR
      (feedback_type = 'HOST_LOGISTICS'
        AND submitter_role = 'HOST'
        AND target_type IN ('LOGISTICS_ITEM','LOGISTICS_HANDOVER','DEPARTMENT','USER'))
    ),

  -- Target-specific required-field mapping is intentionally validated in Backend (CQRS Validator/Handler),
  -- not in MySQL CHECK, because MySQL forbids CHECK constraints that reference columns used by FK referential actions.

  CONSTRAINT fk_feedbacks_visit_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_visit_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_submitter
    FOREIGN KEY (submitted_by_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_user
    FOREIGN KEY (target_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_participant
    FOREIGN KEY (target_participant_id) REFERENCES visit_participants(participant_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_guest_member
    FOREIGN KEY (target_guest_member_id) REFERENCES visit_guest_members(guest_member_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_logistics_item
    FOREIGN KEY (target_logistics_item_id) REFERENCES visit_logistics_items(logistics_item_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_handover
    FOREIGN KEY (target_handover_id) REFERENCES visit_logistics_item_handovers(handover_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_feedbacks_target_department
    FOREIGN KEY (target_department_id) REFERENCES departments(department_id)
    ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Feedback theo rule mới: Visitor đánh giá chung chuyến thăm; Host đánh giá chung đoàn khách, các bên tham gia/hỗ trợ và bên cho mượn đồ/hậu cần. Rating sao bắt buộc 1..5; comment text không bắt buộc.';

CREATE TABLE feedback_rating_items (
  feedback_rating_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  feedback_id BIGINT UNSIGNED NOT NULL,
  criterion_code VARCHAR(80) NOT NULL,
  criterion_label VARCHAR(150) NOT NULL,
  rating TINYINT UNSIGNED NOT NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (feedback_rating_item_id),
  UNIQUE KEY uq_feedback_rating_criterion (feedback_id, criterion_code),
  KEY idx_feedback_rating_feedback (feedback_id),
  CHECK (rating BETWEEN 1 AND 5),
  CONSTRAINT fk_feedback_rating_items_feedback
    FOREIGN KEY (feedback_id) REFERENCES feedbacks(feedback_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Normalized per-criterion ratings for a feedback submission.';

-- =====================================================================
-- 7. PUBLIC CONTENT
-- =====================================================================

CREATE TABLE news (
  news_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_id BIGINT UNSIGNED NULL COMMENT 'Campus liên quan đến bài viết. NULL nếu bài toàn hệ thống',
  visit_instance_id BIGINT UNSIGNED NULL COMMENT 'Visit instance liên quan nếu bài viết được tạo từ một chuyến tiếp đón',
  author_user_id BIGINT UNSIGNED NOT NULL COMMENT 'Người tạo/viết bài',
  cover_file_id BIGINT UNSIGNED NULL COMMENT 'Ảnh bìa bài viết, trỏ tới files.file_id',
  status ENUM('PENDING_REVIEW','REJECTED','PUBLISHED','HIDDEN') NOT NULL DEFAULT 'PENDING_REVIEW'
    COMMENT 'PENDING_REVIEW=chờ host duyệt, REJECTED=bị từ chối, PUBLISHED=đã đăng, HIDDEN=ẩn khỏi trang tin',
  submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Thời điểm người viết gửi bài cho host duyệt',

  reviewed_by BIGINT UNSIGNED NULL COMMENT 'Host duyệt hoặc từ chối bài viết',
  reviewed_at DATETIME NULL COMMENT 'Thời điểm host duyệt hoặc từ chối',
  review_note TEXT NULL COMMENT 'Ghi chú duyệt hoặc lý do từ chối',

  published_at DATETIME NULL COMMENT 'Thời điểm bài viết được đăng',
  is_featured BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Bài viết nổi bật',
  is_pinned BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Bài viết được ghim ở Dấu ấn các chuyến thăm',
  row_version INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Optimistic concurrency token, chống ghi đè khi cập nhật đồng thời',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (news_id),
  KEY idx_news_public (status, campus_id, published_at),
  KEY idx_news_author_status (author_user_id, status),
  KEY idx_news_visit_instance_status (visit_instance_id, status),
  KEY idx_news_review (reviewed_by, reviewed_at),
  KEY idx_news_featured (is_featured, status, published_at),
  KEY idx_news_pinned (is_pinned, status, published_at),

  CONSTRAINT fk_news_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_news_visit_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_news_author
    FOREIGN KEY (author_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_news_cover_file
    FOREIGN KEY (cover_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_news_reviewed_by
    FOREIGN KEY (reviewed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='News metadata. Người tham gia gửi bài, host duyệt/từ chối; nội dung chia theo section.';

CREATE TABLE news_translations (
  news_translation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  news_id BIGINT UNSIGNED NOT NULL,
  language_code VARCHAR(20) NOT NULL DEFAULT 'vi',
  title VARCHAR(255) NOT NULL COMMENT 'Tiêu đề chính của bài viết',
  slug VARCHAR(255) NOT NULL COMMENT 'Đường dẫn SEO của bài viết',
  summary TEXT NULL COMMENT 'Tóm tắt bài viết',
  seo_title VARCHAR(255) NULL,
  seo_description VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (news_translation_id),
  UNIQUE KEY uq_news_translation_lang (news_id, language_code),
  UNIQUE KEY uq_news_translation_slug_lang (slug, language_code),
  KEY idx_news_translations_lang (language_code),
  FULLTEXT KEY ft_news_translations_search (title, summary),
  CONSTRAINT fk_news_translations_news
    FOREIGN KEY (news_id) REFERENCES news(news_id)
    ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Tiêu đề, slug, tóm tắt và SEO của bài viết theo ngôn ngữ';

CREATE TABLE news_content_sections (
  section_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  news_translation_id BIGINT UNSIGNED NOT NULL,
  section_order TINYINT UNSIGNED NOT NULL COMMENT 'Thứ tự section, từ 1 đến 10',
  section_title VARCHAR(255) NOT NULL COMMENT 'Tiêu đề section',
  section_body_html LONGTEXT NOT NULL COMMENT 'Nội dung rich text dạng HTML đã sanitize, có thể chứa paragraph, bold, italic, color, link, image',
  section_body_text TEXT NULL COMMENT 'Plain text tách từ HTML để search hoặc preview',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (section_id),
  UNIQUE KEY uq_news_section_order (news_translation_id, section_order),
  KEY idx_news_sections_translation (news_translation_id),
  FULLTEXT KEY ft_news_sections_search (section_title, section_body_text),
  CHECK (section_order BETWEEN 1 AND 10),
  CONSTRAINT fk_news_sections_translation
    FOREIGN KEY (news_translation_id) REFERENCES news_translations(news_translation_id)
    ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Các khối nội dung chi tiết của bài viết, tối đa 10 section mỗi bản dịch';

CREATE TABLE news_section_files (
  section_file_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  section_id BIGINT UNSIGNED NOT NULL,
  file_id BIGINT UNSIGNED NOT NULL,
  usage_type ENUM('INLINE_IMAGE','ATTACHMENT') NOT NULL DEFAULT 'INLINE_IMAGE'
    COMMENT 'INLINE_IMAGE=ảnh chèn trong nội dung, ATTACHMENT=file đính kèm',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (section_file_id),
  UNIQUE KEY uq_news_section_file (section_id, file_id),
  KEY idx_news_section_files_section (section_id),
  KEY idx_news_section_files_file (file_id),
  CONSTRAINT fk_news_section_files_section
    FOREIGN KEY (section_id) REFERENCES news_content_sections(section_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_news_section_files_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='File/ảnh được dùng trong từng section của bài news';

CREATE TABLE faqs (
  faq_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  faq_type ENUM(
    'ACCOUNT_ACCESS',
    'VISIT_REQUEST',
    'DELEGATION_MANAGEMENT',
    'LOGISTICS_RESOURCE',
    'DOCUMENT_MEDIA',
    'NOTIFICATION_EMAIL',
    'OTHER'
  ) NOT NULL DEFAULT 'OTHER'
    COMMENT 'Loại FAQ theo nhóm chức năng hệ thống PEMS',
  question VARCHAR(500) NOT NULL COMMENT 'Câu hỏi FAQ',
  answer TEXT NOT NULL COMMENT 'Câu trả lời FAQ',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  status ENUM('PUBLISHED','HIDDEN') NOT NULL DEFAULT 'HIDDEN'
    COMMENT 'PUBLISHED=hiển thị trên trang FAQ, HIDDEN=ẩn khỏi người xem thường nhưng người quản lý vẫn thấy',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (faq_id),
  KEY idx_faqs_status_order (status, display_order),
  KEY idx_faqs_type_status (faq_type, status),
  FULLTEXT KEY ft_faqs_search (question, answer)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='FAQ tiếng Việt theo nhóm chức năng hệ thống PEMS';

CREATE TABLE faq_translations (
  faq_translation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  faq_id BIGINT UNSIGNED NOT NULL,
  language_code ENUM('vi','en') NOT NULL,

  question VARCHAR(500) NOT NULL,
  answer TEXT NOT NULL,

  translation_source ENUM('AUTO','MANUAL','LEGACY') NOT NULL DEFAULT 'AUTO',
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  source_hash CHAR(64) NULL
    COMMENT 'SHA-256 của question + answer nguồn VI tại lần dịch gần nhất',
  translated_at DATETIME NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (faq_translation_id),
  UNIQUE KEY uq_faq_translations_lang (faq_id, language_code),
  KEY idx_faq_translations_lang_status (language_code, translation_status),
  FULLTEXT KEY ft_faq_translations_search (question, answer),

  CONSTRAINT fk_faq_translations_faq
    FOREIGN KEY (faq_id) REFERENCES faqs(faq_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_faq_translations_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_faq_translations_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Nội dung FAQ theo ngôn ngữ. Public read không gọi Translation API.';

-- =====================================================================
-- 8. GALLERY + PHOTO TAGGING
-- =====================================================================
-- Gallery v10 final:
-- - Do not recreate old galleries/gallery_images tables.
-- - Use normalized gallery_areas/gallery_locations/gallery_items/gallery_item_media.
-- - Keep photo_face_tags as a shared file-based photo tag module.

CREATE TABLE gallery_areas (
  area_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  campus_id BIGINT UNSIGNED NOT NULL,

  area_name VARCHAR(150) NOT NULL,
  -- 255 (not 150): translated English can be longer than the Vietnamese source; never truncate it.
  area_name_en VARCHAR(255) NULL COMMENT 'Tên tiếng Anh đã dịch và lưu trong DB',
  area_key VARCHAR(180) NOT NULL,
  cover_file_id BIGINT UNSIGNED NULL COMMENT 'Ảnh đại diện khu vực/tòa/khu lớn',

  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,

  translation_source ENUM('AUTO','MANUAL') NULL,
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  translation_source_hash CHAR(64) NULL,
  translated_at DATETIME NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (area_id),
  UNIQUE KEY uq_gallery_areas_campus_key (campus_id, area_key),
  KEY idx_gallery_areas_campus_status (campus_id, status),
  KEY idx_gallery_areas_order (campus_id, display_order),
  KEY idx_gallery_areas_cover_file (cover_file_id),

  CONSTRAINT fk_gallery_areas_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_areas_cover_file
    FOREIGN KEY (cover_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_areas_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_areas_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Gallery master data: khu vực/tòa/khu lớn theo campus';

CREATE TABLE gallery_locations (
  location_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  area_id BIGINT UNSIGNED NOT NULL,

  location_name VARCHAR(150) NOT NULL,
  -- 255 (not 150): translated English can be longer than the Vietnamese source; never truncate it.
  location_name_en VARCHAR(255) NULL COMMENT 'Tên tiếng Anh đã dịch và lưu trong DB',
  location_key VARCHAR(180) NOT NULL,
  cover_file_id BIGINT UNSIGNED NULL COMMENT 'Ảnh đại diện vị trí cụ thể',

  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,

  translation_source ENUM('AUTO','MANUAL') NULL,
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  translation_source_hash CHAR(64) NULL,
  translated_at DATETIME NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (location_id),
  UNIQUE KEY uq_gallery_locations_area_key (area_id, location_key),
  KEY idx_gallery_locations_area_status (area_id, status),
  KEY idx_gallery_locations_order (area_id, display_order),
  KEY idx_gallery_locations_cover_file (cover_file_id),

  CONSTRAINT fk_gallery_locations_area
    FOREIGN KEY (area_id) REFERENCES gallery_areas(area_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_locations_cover_file
    FOREIGN KEY (cover_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_locations_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_locations_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Gallery master data: vị trí cụ thể thuộc khu vực';

CREATE TABLE gallery_items (
  gallery_item_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  location_id BIGINT UNSIGNED NOT NULL,

  title VARCHAR(255) NOT NULL,
  -- 500 (not 255): translated English can be longer than the Vietnamese source; never truncate it.
  title_en VARCHAR(500) NULL COMMENT 'Tiêu đề tiếng Anh đã dịch và lưu trong DB',
  -- Bilingual descriptions live in gallery_item_contents (1:1); the legacy single `description`
  -- column was removed when the manual bilingual audio mechanism replaced EverAI TTS.
  item_type ENUM('MEDIA','VISIT_DELEGATION') NOT NULL DEFAULT 'MEDIA'
    COMMENT 'MEDIA=ảnh/video giới thiệu vị trí; VISIT_DELEGATION=ảnh/video đoàn khách',

  media_kind ENUM('IMAGE','VIDEO','MIXED') NOT NULL DEFAULT 'IMAGE',
  status ENUM('PUBLISHED','HIDDEN') NOT NULL DEFAULT 'PUBLISHED',
  display_order INT UNSIGNED NOT NULL DEFAULT 0,

  translation_source ENUM('AUTO','MANUAL') NULL,
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  translation_source_hash CHAR(64) NULL,
  translated_at DATETIME NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  deleted_at DATETIME NULL,
  deleted_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (gallery_item_id),
  -- A location can have 0, 1 or many gallery items (no unique constraint on location_id).
  KEY idx_gallery_items_location_status (location_id, status, deleted_at),
  KEY idx_gallery_items_item_type (item_type, status, deleted_at),
  KEY idx_gallery_items_media_kind (media_kind),
  KEY idx_gallery_items_created_at (created_at),
  FULLTEXT KEY ft_gallery_items_search (title),
  FULLTEXT KEY ft_gallery_items_search_en (title_en),

  CONSTRAINT fk_gallery_items_location
    FOREIGN KEY (location_id) REFERENCES gallery_locations(location_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_items_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_items_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_items_deleted_by
    FOREIGN KEY (deleted_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Gallery item/bài media thuộc một vị trí cụ thể';

CREATE TABLE gallery_item_media (
  media_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  gallery_item_id BIGINT UNSIGNED NOT NULL,

  file_id BIGINT UNSIGNED NOT NULL,
  media_type ENUM('IMAGE','VIDEO') NOT NULL,
  thumbnail_file_id BIGINT UNSIGNED NULL,

  caption VARCHAR(500) NULL,
  caption_en VARCHAR(500) NULL COMMENT 'Caption tiếng Anh đã dịch và lưu trong DB',
  alt_text VARCHAR(255) NULL,
  alt_text_en VARCHAR(255) NULL COMMENT 'Alt text tiếng Anh đã dịch và lưu trong DB',

  translation_source ENUM('AUTO','MANUAL') NULL,
  translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
  translation_source_hash CHAR(64) NULL,
  translated_at DATETIME NULL,

  is_primary TINYINT(1) NOT NULL DEFAULT 0,

  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  taken_at DATETIME NULL,
  status ENUM('ACTIVE','HIDDEN') NOT NULL DEFAULT 'ACTIVE',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  deleted_at DATETIME NULL,
  deleted_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (media_id),
  UNIQUE KEY uq_gallery_item_media_file (file_id),
  KEY idx_gallery_item_media_primary (gallery_item_id, is_primary),
  KEY idx_gallery_item_media_item_order (gallery_item_id, display_order),
  KEY idx_gallery_item_media_type (media_type),
  KEY idx_gallery_item_media_status (status, deleted_at),
  KEY idx_gallery_item_media_thumbnail (thumbnail_file_id),

  CONSTRAINT fk_gallery_item_media_item
    FOREIGN KEY (gallery_item_id) REFERENCES gallery_items(gallery_item_id)
    ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT fk_gallery_item_media_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_gallery_item_media_thumbnail
    FOREIGN KEY (thumbnail_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_item_media_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_item_media_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_gallery_item_media_deleted_by
    FOREIGN KEY (deleted_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Ảnh/video thuộc gallery item, liên kết file metadata dùng chung';

-- Nội dung mô tả + bản ghi âm song ngữ (VI/EN) của gallery item — thay thế cơ chế
-- EverAI TTS. Quan hệ 1:1 với gallery_items (PK = gallery_item_id); cả hai ngôn ngữ bắt buộc.
CREATE TABLE gallery_item_contents (
    gallery_item_id  BIGINT UNSIGNED NOT NULL,

    description_vi   TEXT NOT NULL
        COMMENT 'Mô tả tiếng Việt, bắt buộc',
    audio_vi_file_id BIGINT UNSIGNED NOT NULL
        COMMENT 'files.file_id của bản ghi âm tiếng Việt, bắt buộc',

    description_en   TEXT NOT NULL
        COMMENT 'Mô tả tiếng Anh, bắt buộc',
    audio_en_file_id BIGINT UNSIGNED NOT NULL
        COMMENT 'files.file_id của bản ghi âm tiếng Anh, bắt buộc',

    translation_source ENUM('AUTO','MANUAL') NULL,
    translation_status ENUM('PENDING','READY','FAILED','OUTDATED') NOT NULL DEFAULT 'PENDING',
    translation_source_hash CHAR(64) NULL,
    translated_at DATETIME NULL,

    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by BIGINT UNSIGNED NULL,
    updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
    updated_by BIGINT UNSIGNED NULL,

    PRIMARY KEY (gallery_item_id),
    KEY idx_gallery_item_contents_audio_vi (audio_vi_file_id),
    KEY idx_gallery_item_contents_audio_en (audio_en_file_id),
    FULLTEXT KEY ft_gallery_item_contents_descriptions (description_vi, description_en),

    CONSTRAINT chk_gallery_item_description_vi_not_blank CHECK (CHAR_LENGTH(TRIM(description_vi)) > 0),
    CONSTRAINT chk_gallery_item_description_en_not_blank CHECK (CHAR_LENGTH(TRIM(description_en)) > 0),

    CONSTRAINT fk_gallery_item_contents_item
        FOREIGN KEY (gallery_item_id) REFERENCES gallery_items(gallery_item_id)
        ON UPDATE RESTRICT ON DELETE CASCADE,
    CONSTRAINT fk_gallery_item_contents_audio_vi
        FOREIGN KEY (audio_vi_file_id) REFERENCES files(file_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_gallery_item_contents_audio_en
        FOREIGN KEY (audio_en_file_id) REFERENCES files(file_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_gallery_item_contents_created_by
        FOREIGN KEY (created_by) REFERENCES users(user_id)
        ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT fk_gallery_item_contents_updated_by
        FOREIGN KEY (updated_by) REFERENCES users(user_id)
        ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Nội dung mô tả và bản ghi âm song ngữ của Gallery Item (1:1)';

CREATE TABLE photo_face_tags (
  face_tag_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  file_id BIGINT UNSIGNED NOT NULL,

  tagged_user_id BIGINT UNSIGNED NULL COMMENT 'User nội bộ được tag nếu người này có tài khoản hệ thống',
  visit_request_id BIGINT UNSIGNED NULL,
  guest_member_id BIGINT UNSIGNED NULL,
  partner_contact_id BIGINT UNSIGNED NULL,

  display_name VARCHAR(150) NOT NULL COMMENT 'Tên hiển thị của người được tag trong ảnh',
  person_name_key VARCHAR(180) NULL COMMENT 'Tên đã normalize để tìm kiếm không phân biệt dấu/hoa thường',

  bounding_box_x DECIMAL(8,4) NULL,
  bounding_box_y DECIMAL(8,4) NULL,
  bounding_box_width DECIMAL(8,4) NULL,
  bounding_box_height DECIMAL(8,4) NULL,

  tag_status ENUM('ACTIVE','REMOVED') NOT NULL DEFAULT 'ACTIVE',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  removed_at DATETIME NULL,
  removed_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (face_tag_id),
  KEY idx_face_tags_file (file_id),
  KEY idx_face_tags_display_name (display_name),
  KEY idx_face_tags_name_key (person_name_key),
  KEY idx_face_tags_user (tagged_user_id),
  KEY idx_face_tags_visit_request (visit_request_id),
  KEY idx_face_tags_guest (guest_member_id),
  KEY idx_face_tags_partner_contact (partner_contact_id),
  KEY idx_face_tags_status (tag_status),

  CONSTRAINT fk_face_tags_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_face_tags_user
    FOREIGN KEY (tagged_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_face_tags_visit_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_face_tags_guest
    FOREIGN KEY (guest_member_id) REFERENCES visit_guest_members(guest_member_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_face_tags_partner_contact
    FOREIGN KEY (partner_contact_id) REFERENCES partner_contacts(contact_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_face_tags_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_face_tags_removed_by
    FOREIGN KEY (removed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Tag người xuất hiện trong ảnh theo file; dùng để tìm ảnh theo tên, không lưu vector sinh trắc học';
-- =====================================================================
-- 9. EMAIL + NOTIFICATION
-- =====================================================================

CREATE TABLE email_templates (
  email_template_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  template_code VARCHAR(100) NOT NULL,
  name VARCHAR(150) NOT NULL,
  purpose VARCHAR(100) NOT NULL,
  campus_id BIGINT UNSIGNED NULL,
  description VARCHAR(500) NULL,
  status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  subject_vi VARCHAR(255) NULL,
  body_vi LONGTEXT NULL,
  subject_en VARCHAR(255) NULL,
  body_en LONGTEXT NULL,
  body_format ENUM('PLAIN_TEXT','HTML') NOT NULL DEFAULT 'HTML'
    COMMENT 'Định dạng nội dung email template; HTML dùng cho rich text editor',
  variables_text VARCHAR(700) NULL,
  revision INT UNSIGNED NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (email_template_id),
  UNIQUE KEY uq_email_templates_code (template_code),
  KEY idx_email_templates_status (status),
  KEY idx_email_templates_purpose_status (purpose, status),
  KEY idx_email_templates_campus_status (campus_id, status),
  CONSTRAINT fk_email_templates_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Email templates with explicit VI/EN subject/body fields';

CREATE TABLE sent_emails (
  sent_email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  email_template_id BIGINT UNSIGNED NULL,
  related_type VARCHAR(80) NULL,
  related_id BIGINT UNSIGNED NULL,
  subject VARCHAR(255) NOT NULL,
  body_snapshot LONGTEXT NULL,
  body_format ENUM('PLAIN_TEXT','HTML') NOT NULL DEFAULT 'HTML'
    COMMENT 'Định dạng body_snapshot sau khi merge template/editor',
  provider_thread_id VARCHAR(255) NULL,
  provider_message_id VARCHAR(255) NULL,
  retry_count INT UNSIGNED NOT NULL DEFAULT 0,
  last_attempt_at DATETIME NULL,
  delivered_at DATETIME NULL,
  status ENUM('QUEUED','SENT','DELIVERED','FAILED','PARTIAL_FAILED','BOUNCED') NOT NULL DEFAULT 'QUEUED',
  error_message TEXT NULL,
  sent_by BIGINT UNSIGNED NULL,
  sent_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (sent_email_id),
  KEY idx_sent_emails_template (email_template_id),
  KEY idx_sent_emails_related (related_type, related_id),
  KEY idx_sent_emails_status_time (status, created_at),
  KEY idx_sent_emails_sent_by_time (sent_by, sent_at),
  KEY idx_sent_emails_provider_thread (provider_thread_id),
  KEY idx_sent_emails_provider_message (provider_message_id),
  CONSTRAINT fk_sent_emails_template
    FOREIGN KEY (email_template_id) REFERENCES email_templates(email_template_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_sent_emails_sent_by
    FOREIGN KEY (sent_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Sent email log; recipients stored in sent_email_recipients';


CREATE TABLE sent_email_recipients (
  sent_email_recipient_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  sent_email_id BIGINT UNSIGNED NOT NULL,
  recipient_email VARCHAR(150) NOT NULL,
  recipient_name VARCHAR(150) NULL,
  recipient_type ENUM('TO','CC','BCC') NOT NULL DEFAULT 'TO',
  delivery_status ENUM('QUEUED','SENT','DELIVERED','FAILED','BOUNCED') NOT NULL DEFAULT 'QUEUED',
  provider_message_id VARCHAR(255) NULL,
  error_message TEXT NULL,
  sent_at DATETIME NULL,
  delivered_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (sent_email_recipient_id),
  KEY idx_sent_email_recipients_sent_email (sent_email_id),
  KEY idx_sent_email_recipients_email_status (recipient_email, delivery_status),
  FULLTEXT KEY ft_sent_email_recipients_search (recipient_email, recipient_name),
  CONSTRAINT fk_sent_email_recipients_email
    FOREIGN KEY (sent_email_id) REFERENCES sent_emails(sent_email_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='One row per recipient; replaces sent_emails.recipients_json.';

CREATE TABLE sent_email_attachments (
  sent_email_attachment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  sent_email_id BIGINT UNSIGNED NOT NULL,
  file_id BIGINT UNSIGNED NOT NULL,
  attachment_type ENUM('ATTACHMENT','INLINE_IMAGE') NOT NULL DEFAULT 'ATTACHMENT'
    COMMENT 'ATTACHMENT=file đính kèm; INLINE_IMAGE=ảnh hiển thị trong nội dung HTML bằng cid',
  content_id VARCHAR(120) NULL
    COMMENT 'Content-ID dùng cho ảnh inline, ví dụ <img src="cid:pems-image-001">',
  display_name VARCHAR(255) NULL,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (sent_email_attachment_id),
  UNIQUE KEY uq_sent_email_attachments_content (sent_email_id, content_id),
  KEY idx_sent_email_attachments_email (sent_email_id),
  KEY idx_sent_email_attachments_file (file_id),
  KEY idx_sent_email_attachments_type (sent_email_id, attachment_type),
  CONSTRAINT fk_sent_email_attachments_email
    FOREIGN KEY (sent_email_id) REFERENCES sent_emails(sent_email_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_sent_email_attachments_file
    FOREIGN KEY (file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Files/images attached to sent emails; binary content is stored in files/external storage';

CREATE TABLE email_action_tokens (
  email_action_token_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  token_hash VARCHAR(255) NOT NULL
    COMMENT 'Hash của token trong link email; không lưu token raw',

  action_group_key VARCHAR(180) NOT NULL
    COMMENT 'Nhóm các nút cùng một quyết định, ví dụ PARTICIPATION:123:user@example.com',

  action_context ENUM(
    'PARTICIPATION_RESPONSE',
    'LOGISTICS_REQUEST_RESPONSE',
    'LOGISTICS_ASSIGNEE_RESPONSE',
    'LOGISTICS_NEGOTIATION',
    'LOGISTICS_PROPOSAL_RESPONSE',
    'LOGISTICS_HANDOVER_SIGNATURE',
    'VISIT_CONTACT_CLAIM',
    'VISIT_CONTACT_TRANSFER'
  ) NOT NULL,

  target_type ENUM(
    'VISIT_PARTICIPANT',
    'LOGISTICS_ITEM',
    'LOGISTICS_HANDOVER',
    'VISIT_REQUEST_IDENTITY_CHANGE'
  ) NOT NULL,

  target_id BIGINT UNSIGNED NOT NULL,

  intended_action ENUM(
    'ACCEPT',
    'DECLINE',
    'NEGOTIATE',
    'APPROVE_PROPOSAL',
    'REJECT_PROPOSAL',
    'CONFIRM_BORROW',
    'CONFIRM_RETURN'
  ) NOT NULL,

  recipient_user_id BIGINT UNSIGNED NULL,
  recipient_email VARCHAR(150) NOT NULL,

  sent_email_id BIGINT UNSIGNED NULL,
  sent_email_recipient_id BIGINT UNSIGNED NULL,

  expires_at DATETIME NOT NULL,
  used_at DATETIME NULL,
  used_action VARCHAR(50) NULL,

  result_status ENUM(
    'PENDING',
    'SUCCESS',
    'ALREADY_RESPONDED',
    'EXPIRED',
    'INVALID',
    'FAILED'
  ) NOT NULL DEFAULT 'PENDING',

  result_message VARCHAR(500) NULL,

  used_ip VARCHAR(45) NULL,
  used_user_agent VARCHAR(500) NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (email_action_token_id),

  UNIQUE KEY uq_email_action_token_hash (token_hash),
  KEY idx_email_action_group_used (action_group_key, used_at),
  KEY idx_email_action_target (target_type, target_id),
  KEY idx_email_action_recipient (recipient_email),
  KEY idx_email_action_context_status (action_context, result_status),
  KEY idx_email_action_expires (expires_at),
  KEY idx_email_action_sent_email (sent_email_id),
  KEY idx_email_action_sent_recipient (sent_email_recipient_id),
  KEY idx_email_action_recipient_user (recipient_user_id),

  CONSTRAINT fk_email_action_recipient_user
    FOREIGN KEY (recipient_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_email_action_sent_email
    FOREIGN KEY (sent_email_id) REFERENCES sent_emails(sent_email_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_email_action_sent_recipient
    FOREIGN KEY (sent_email_recipient_id) REFERENCES sent_email_recipients(sent_email_recipient_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='One-time action tokens for email buttons: accept, decline, negotiate, handover signature.';

-- P0 #1: one-time email-ownership proof for newly-created internal accounts. An account is created
-- with users.status = 'PENDING_EMAIL_CONFIRMATION' and activated only when a matching, unexpired,
-- PENDING token is confirmed. Only the token HASH is stored; the raw token lives solely in the emailed link.
CREATE TABLE account_email_confirmations (
  confirmation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  user_id         BIGINT UNSIGNED NOT NULL
    COMMENT 'Tài khoản đang chờ xác nhận email',
  target_email    VARCHAR(255) NOT NULL
    COMMENT 'Email được chứng minh quyền sở hữu (email chuẩn hoá tại thời điểm phát hành)',
  token_hash      CHAR(64) NOT NULL
    COMMENT 'SHA-256 (hex) của token gốc — KHÔNG bao giờ lưu token gốc',

  status          VARCHAR(20) NOT NULL DEFAULT 'PENDING'
    COMMENT 'PENDING / CONFIRMED / EXPIRED / SUPERSEDED / CANCELLED',

  expires_at      DATETIME NOT NULL,
  resend_count    INT NOT NULL DEFAULT 0,

  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  confirmed_at    DATETIME NULL DEFAULT NULL,
  cancelled_at    DATETIME NULL DEFAULT NULL,

  PRIMARY KEY (confirmation_id),

  UNIQUE KEY uq_account_email_confirmations_token_hash (token_hash),
  KEY idx_account_email_confirmations_user (user_id),
  KEY idx_account_email_confirmations_status_expiry (status, expires_at),

  CONSTRAINT chk_account_email_confirmations_status
    CHECK (status IN ('PENDING','CONFIRMED','EXPIRED','SUPERSEDED','CANCELLED')),
  CONSTRAINT chk_account_email_confirmations_target_email_not_blank
    CHECK (CHAR_LENGTH(TRIM(target_email)) > 0),

  CONSTRAINT fk_account_email_confirmations_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Bằng chứng sở hữu email một-lần cho tài khoản nội bộ mới (P0 #1).';

-- G11 (R-103): one reservation per logical "gửi báo cáo/hóa đơn" action. The client sends an opaque
-- Idempotency-Key and reuses it when retrying THE SAME action, so a network timeout can no longer turn
-- one click into two outbound messages. Only hashes are stored — never the key, the note text, the
-- recipient address or any monetary value.
CREATE TABLE email_send_idempotency (
  email_send_idempotency_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  actor_user_id BIGINT UNSIGNED NOT NULL
    COMMENT 'Người bấm gửi, đọc từ JWT đã xác thực — không bao giờ từ payload',
  operation_code VARCHAR(64) NOT NULL
    COMMENT 'Một trong sáu hành động gửi báo cáo/hóa đơn, ví dụ REPORT_HO_CAMPUS',
  idempotency_key_hash CHAR(64) NOT NULL
    COMMENT 'SHA-256 (hex) của Idempotency-Key — KHÔNG lưu key gốc',
  request_fingerprint CHAR(64) NOT NULL
    COMMENT 'SHA-256 (hex) của nội dung nghiệp vụ đã chuẩn hoá; cùng key khác fingerprint = từ chối, không gửi',

  state VARCHAR(32) NOT NULL DEFAULT 'RESERVED'
    COMMENT 'RESERVED / PREPARING / DISPATCHING / SUCCEEDED / FAILED_BEFORE_DISPATCH / OUTCOME_UNKNOWN',

  sent_email_id BIGINT UNSIGNED NULL
    COMMENT 'Bản ghi lịch sử của lần gửi thành công, để đối chiếu',
  result_message VARCHAR(500) NULL
    COMMENT 'Thông báo thành công, phát lại nguyên văn cho lần gọi trùng',
  failure_code VARCHAR(64) NULL
    COMMENT 'Mã lỗi ổn định; không chứa địa chỉ, số tiền, token hay nội dung thư',

  attempt_count INT UNSIGNED NOT NULL DEFAULT 0
    COMMENT 'Số lần handler thực sự chạy dưới key này (chỉ tăng khi retry sau FAILED_BEFORE_DISPATCH)',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  dispatch_started_at DATETIME NULL
    COMMENT 'Thời điểm ngay trước lời gọi ra ngoài; có giá trị nghĩa là không thể khẳng định chưa gửi',
  completed_at DATETIME NULL,

  PRIMARY KEY (email_send_idempotency_id),

  -- The whole contract rests on this one constraint: two concurrent requests carrying the same key
  -- collide in the database, not in application code.
  UNIQUE KEY uq_email_send_idempotency_actor_op_key
    (actor_user_id, operation_code, idempotency_key_hash),

  KEY idx_email_send_idempotency_state (state, created_at),
  KEY idx_email_send_idempotency_sent_email (sent_email_id),

  CONSTRAINT chk_email_send_idempotency_state
    CHECK (state IN ('RESERVED','PREPARING','DISPATCHING','SUCCEEDED',
                     'FAILED_BEFORE_DISPATCH','OUTCOME_UNKNOWN')),

  -- RESTRICT, not CASCADE: this table records what a person sent. Deleting the person must not delete
  -- the evidence, and PEMS hard-deletes no user anywhere in the backend.
  CONSTRAINT fk_email_send_idempotency_actor
    FOREIGN KEY (actor_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  -- SET NULL: if a history row is ever removed the reservation survives, because the fact that a send
  -- happened is exactly what must not be lost.
  CONSTRAINT fk_email_send_idempotency_sent_email
    FOREIGN KEY (sent_email_id) REFERENCES sent_emails(sent_email_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Chống gửi trùng cho sáu hành động gửi báo cáo/hóa đơn (G11 / R-103). Chỉ lưu hash của key và của yêu cầu.';

-- ---------------------------------------------------------------------------
-- Chính sách khối "thông tin liên hệ" trong email.
--
-- Bảng này lưu CHÍNH SÁCH, không lưu DỮ LIỆU liên hệ. Không có cột nào chứa họ
-- tên, email hay số điện thoại: quản trị viên được chọn "mẫu này hiển thị email
-- công việc của Host", nhưng KHÔNG được tự gõ một địa chỉ rồi gán cho Host. Giá
-- trị thật đọc từ users / campuses / departments tại thời điểm gửi, nên nó cũng
-- tự đúng khi người giữ vai trò thay đổi.
--
-- Mọi cột tuỳ chọn đều NULL được, để phân biệt "chưa đặt" với "tắt". Một dòng
-- cấp campus ghi show_phone=0 là một quyết định; một dòng không nói gì về
-- show_phone phải kế thừa cấp dưới. Gộp hai trạng thái đó vào NOT NULL sẽ khiến
-- mọi trường không khai báo lặng lẽ mang nghĩa "không hiển thị".
--
-- Thứ tự kế thừa: TEMPLATE → CAMPUS → DEPARTMENT → SYSTEM → mặc định trong code.
-- Việc ghép được thực hiện THEO TỪNG TRƯỜNG (xem EmailContactPolicyStore).
-- ---------------------------------------------------------------------------
CREATE TABLE email_contact_policies (
  email_contact_policy_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  scope_type ENUM('TEMPLATE','CAMPUS','DEPARTMENT','SYSTEM') NOT NULL
    COMMENT 'Cấp trong chuỗi kế thừa',
  scope_key VARCHAR(64) NULL
    COMMENT 'template_code / campus_id / department_id dạng chuỗi; NULL cho dòng SYSTEM duy nhất',

  requirement ENUM('NONE','OPTIONAL','REQUIRED') NULL
    COMMENT 'NONE=không hiển thị; OPTIONAL=hiện nếu tìm được; REQUIRED=hiện, không tìm được thì chặn gửi',
  contact_source ENUM('HOST','SENDER','HOST_THEN_SENDER',
                      'CAMPUS_DEFAULT','DEPARTMENT_DEFAULT','SUPPORT_CONTACT') NULL
    COMMENT 'Nguồn tra cứu đầu mối. Là enum chứ không phải user_id: đầu mối đúng phụ thuộc chuyến thăm và cơ sở',

  show_email      TINYINT(1) NULL COMMENT 'NULL = kế thừa cấp dưới',
  show_phone      TINYINT(1) NULL COMMENT 'NULL = kế thừa cấp dưới',
  show_department TINYINT(1) NULL COMMENT 'NULL = kế thừa cấp dưới',
  show_campus     TINYINT(1) NULL COMMENT 'NULL = kế thừa cấp dưới',
  show_sender     TINYINT(1) NULL COMMENT 'Dòng "Được gửi bởi"; NULL = kế thừa cấp dưới',

  heading_vi VARCHAR(150) NULL,
  heading_en VARCHAR(150) NULL,

  reply_to_source ENUM('NONE','CONTACT','SENDER') NULL
    COMMENT 'Địa chỉ đặt vào header Reply-To của thư',

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (email_contact_policy_id),

  -- Mỗi cấp chỉ có tối đa một dòng. Đây cũng là chỗ patch dựa vào để chạy lại
  -- an toàn (INSERT ... ON DUPLICATE KEY UPDATE).
  UNIQUE KEY uq_email_contact_policies_scope (scope_type, scope_key),

  CONSTRAINT fk_email_contact_policies_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_email_contact_policies_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Chính sách hiển thị khối thông tin liên hệ trong email. Chỉ lưu chính sách, không lưu dữ liệu liên hệ.';

CREATE TABLE notifications (
  notification_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  recipient_user_id BIGINT UNSIGNED NOT NULL,
  actor_user_id BIGINT UNSIGNED NULL COMMENT 'User who caused the notification, if applicable.',

  title VARCHAR(255) NOT NULL,
  message TEXT NULL,

  notification_type VARCHAR(80) NOT NULL COMMENT 'Specific business event type, for example VISIT_CANCELLED, INVITATION_RECEIVED, HOST_FEEDBACK_RECEIVED.',
  category VARCHAR(80) NOT NULL DEFAULT 'GENERAL' COMMENT 'UI grouping: VISIT, INVITATION, REMINDER, FEEDBACK, LOGISTICS, HANDOVER, NEWS, PARTNER, ACCOUNT, SYSTEM, GENERAL.',
  priority ENUM('LOW','NORMAL','HIGH','URGENT') NOT NULL DEFAULT 'NORMAL',
  is_action_required BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'TRUE when the recipient should take an action, not just read the notification.',

  related_type VARCHAR(80) NULL COMMENT 'Backward-compatible generic target type.',
  related_id BIGINT UNSIGNED NULL COMMENT 'Backward-compatible generic target id.',

  visit_request_id BIGINT UNSIGNED NULL COMMENT 'Direct visit request context for filtering and navigation.',
  visit_instance_id BIGINT UNSIGNED NULL COMMENT 'Direct campus visit instance context for filtering and navigation.',
  campus_id BIGINT UNSIGNED NULL COMMENT 'Direct campus context for Staff Leader/HO filtering.',

  action_type VARCHAR(80) NULL COMMENT 'Frontend action, for example OPEN_VISIT_DETAIL, OPEN_INVITATION_MODAL, OPEN_HOST_FEEDBACK_MODAL.',
  action_url VARCHAR(500) NULL COMMENT 'Frontend route to open when the notification is clicked.',
  metadata_json JSON NULL COMMENT 'Small UI payload for modal/detail rendering; do not store source-of-truth business data here.',
  dedupe_key VARCHAR(255) NULL COMMENT 'Idempotency key to prevent duplicate notifications, especially reminders/background jobs.',

  is_read BOOLEAN NOT NULL DEFAULT FALSE,
  read_at DATETIME NULL,
  archived_at DATETIME NULL COMMENT 'Soft archive/hide timestamp for the recipient.',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (notification_id),

  KEY idx_notifications_user_read_time (recipient_user_id, is_read, created_at),
  KEY idx_notifications_related (related_type, related_id),
  KEY idx_notifications_type_time (notification_type, created_at),
  KEY idx_notifications_user_category_time (recipient_user_id, category, created_at),
  KEY idx_notifications_user_action_time (recipient_user_id, is_action_required, is_read, created_at),
  KEY idx_notifications_actor (actor_user_id, created_at),
  KEY idx_notifications_visit_request (visit_request_id, created_at),
  KEY idx_notifications_visit_instance (visit_instance_id, created_at),
  KEY idx_notifications_campus (campus_id, created_at),
  UNIQUE KEY uq_notifications_recipient_dedupe (recipient_user_id, dedupe_key),

  CONSTRAINT fk_notifications_user
    FOREIGN KEY (recipient_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_notifications_actor_user
    FOREIGN KEY (actor_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_notifications_visit_request
    FOREIGN KEY (visit_request_id) REFERENCES visit_requests(visit_request_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_notifications_visit_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_notifications_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='In-app notifications. Global notification center table; supports role/context filtering, click actions, modal metadata, reminders and idempotency.';

-- =====================================================================
-- 10. CALENDAR + API + AGENDA TEMPLATE
-- =====================================================================

CREATE TABLE calendar_events (
  calendar_event_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  owner_user_id BIGINT UNSIGNED NOT NULL,
  campus_id BIGINT UNSIGNED NULL,
  visit_instance_id BIGINT UNSIGNED NULL,
  logistics_item_id BIGINT UNSIGNED NULL,
  source_type ENUM('PERSONAL','VISIT','LOGISTICS','DEADLINE') NOT NULL DEFAULT 'PERSONAL',
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  location VARCHAR(255) NULL,
  start_at DATETIME NOT NULL,
  end_at DATETIME NOT NULL,
  timezone VARCHAR(50) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  is_all_day BOOLEAN NOT NULL DEFAULT FALSE,
  recurrence_rule VARCHAR(500) NULL,
  visibility ENUM('PRIVATE','INTERNAL') NOT NULL DEFAULT 'PRIVATE',
  status ENUM('ACTIVE','CANCELLED','DONE') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  deleted_at DATETIME NULL,
  deleted_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (calendar_event_id),
  KEY idx_calendar_owner_time (owner_user_id, start_at),
  KEY idx_calendar_campus_time (campus_id, start_at),
  KEY idx_calendar_visit (visit_instance_id),
  KEY idx_calendar_logistics (logistics_item_id),
  KEY idx_calendar_source_status_time (source_type, status, start_at),
  CHECK (end_at > start_at),
  CONSTRAINT fk_calendar_owner
    FOREIGN KEY (owner_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_calendar_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_calendar_visit
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_calendar_logistics
    FOREIGN KEY (logistics_item_id) REFERENCES visit_logistics_items(logistics_item_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Calendar events. Attendees/reminders are normalized in child tables.';

CREATE TABLE calendar_event_attendees (
  calendar_event_attendee_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  calendar_event_id BIGINT UNSIGNED NOT NULL,
  user_id BIGINT UNSIGNED NULL,
  attendee_email VARCHAR(150) NULL,
  attendee_name VARCHAR(150) NULL,
  attendee_role VARCHAR(80) NULL,
  response_status ENUM('NEEDS_ACTION','ACCEPTED','DECLINED','TENTATIVE') NOT NULL DEFAULT 'NEEDS_ACTION',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (calendar_event_attendee_id),
  KEY idx_calendar_attendees_event (calendar_event_id),
  KEY idx_calendar_attendees_user (user_id),
  KEY idx_calendar_attendees_email (attendee_email),
  CONSTRAINT fk_calendar_attendees_event
    FOREIGN KEY (calendar_event_id) REFERENCES calendar_events(calendar_event_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_calendar_attendees_user
    FOREIGN KEY (user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Calendar attendees; replaces calendar_events.attendees_json.';

CREATE TABLE calendar_event_reminders (
  calendar_event_reminder_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  calendar_event_id BIGINT UNSIGNED NOT NULL,
  reminder_type ENUM('EMAIL','POPUP','IN_APP') NOT NULL DEFAULT 'IN_APP',
  minutes_before INT UNSIGNED NOT NULL DEFAULT 0,
  scheduled_at DATETIME NULL,
  sent_at DATETIME NULL,
  status ENUM('PENDING','SENT','CANCELLED','FAILED') NOT NULL DEFAULT 'PENDING',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (calendar_event_reminder_id),
  KEY idx_calendar_reminders_event (calendar_event_id),
  KEY idx_calendar_reminders_status_schedule (status, scheduled_at),
  CONSTRAINT fk_calendar_reminders_event
    FOREIGN KEY (calendar_event_id) REFERENCES calendar_events(calendar_event_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Calendar reminders; replaces calendar_events.reminders_json.';

CREATE TABLE visit_instance_reminder_settings (
  reminder_setting_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  visit_instance_id BIGINT UNSIGNED NOT NULL,

  channel ENUM('IN_APP','EMAIL') NOT NULL
    COMMENT 'IN_APP=thông báo trong hệ thống, EMAIL=gửi email',

  target_group ENUM('HOST','PARTICIPANTS','HOST_AND_PARTICIPANTS') NOT NULL
    COMMENT 'Nhóm người nhận cảnh báo',

  days_before INT UNSIGNED NOT NULL DEFAULT 0
    COMMENT 'Số ngày trước planned_start_at',

  reminder_time TIME NOT NULL
    COMMENT 'Giờ gửi trong ngày',

  scheduled_at DATETIME NOT NULL
    COMMENT 'Thời điểm hệ thống sẽ gửi nhắc',

  status ENUM('PENDING','SENT','CANCELLED','FAILED') NOT NULL DEFAULT 'PENDING'
    COMMENT 'PENDING=chờ gửi, SENT=đã gửi, CANCELLED=đã hủy, FAILED=gửi lỗi',

  last_dispatched_at DATETIME NULL,
  error_message TEXT NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,

  PRIMARY KEY (reminder_setting_id),
  UNIQUE KEY uq_visit_reminder_channel_target (visit_instance_id, channel, target_group),
  KEY idx_visit_reminder_schedule (status, scheduled_at),
  KEY idx_visit_reminder_instance (visit_instance_id),
  KEY idx_visit_reminder_created_by (created_by),
  KEY idx_visit_reminder_updated_by (updated_by),

  CONSTRAINT fk_visit_reminder_instance
    FOREIGN KEY (visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_visit_reminder_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_visit_reminder_updated_by
    FOREIGN KEY (updated_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Cấu hình lịch gửi cảnh báo/email cho Host và người tham gia theo campus visit instance.';

CREATE TABLE api_configurations (
  api_config_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  api_code VARCHAR(100) NOT NULL,
  name VARCHAR(150) NOT NULL,
  provider_name VARCHAR(150) NULL,
  purpose VARCHAR(150) NULL,
  base_url VARCHAR(500) NOT NULL,
  default_method ENUM('GET','POST','PUT','PATCH','DELETE') NOT NULL DEFAULT 'POST',
  auth_type ENUM('NONE','API_KEY','BEARER_TOKEN','BASIC','OAUTH2','CUSTOM') NOT NULL DEFAULT 'NONE',
  api_key_encrypted VARCHAR(700) NULL,
  bearer_token_encrypted VARCHAR(700) NULL,
  basic_username VARCHAR(150) NULL,
  basic_password_encrypted VARCHAR(700) NULL,
  oauth_client_id VARCHAR(255) NULL,
  oauth_client_secret_encrypted VARCHAR(700) NULL,
  oauth_token_url VARCHAR(700) NULL,
  oauth_scope VARCHAR(500) NULL,
  body_template_text LONGTEXT NULL,
  settings_json JSON NULL
    COMMENT 'Non-secret provider settings such as project_id, location, processor_id, endpoint',
  credentials_json_encrypted LONGTEXT NULL
    COMMENT 'Encrypted credential payload; never expose raw value',
  secret_ref VARCHAR(255) NULL
    COMMENT 'Reference to server env/secret manager when credentials are not stored in DB',
  data_sensitivity ENUM('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED') NOT NULL DEFAULT 'CONFIDENTIAL',
  allows_provider_training BOOLEAN NOT NULL DEFAULT FALSE,
  retention_days INT UNSIGNED NULL
    COMMENT 'How long raw OCR text/draft should be retained before purge',
  rate_limit_per_minute INT UNSIGNED NULL,
  monthly_quota INT UNSIGNED NULL,
  retry_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  max_retries INT UNSIGNED NOT NULL DEFAULT 0,
  cache_ttl_seconds INT UNSIGNED NULL,
  last_test_status ENUM('SUCCESS','FAILED') NULL,
  last_tested_at DATETIME NULL,
  last_test_message TEXT NULL,
  timeout_seconds INT UNSIGNED NOT NULL DEFAULT 30,
  status ENUM('ACTIVE','INACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  deleted_at DATETIME NULL,
  deleted_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (api_config_id),
  UNIQUE KEY uq_api_config_code (api_code),
  KEY idx_api_config_status (status),
  KEY idx_api_config_test_status (last_test_status, last_tested_at),
  KEY idx_api_provider_status (provider_name, status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='API config + encrypted credentials JSON';

CREATE TABLE visit_photo_face_scans (
  face_scan_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  visit_photo_id BIGINT UNSIGNED NOT NULL,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  file_id BIGINT UNSIGNED NOT NULL,
  api_config_id BIGINT UNSIGNED NOT NULL,

  status ENUM('PENDING','PROCESSING','SUCCEEDED','FAILED','CONFIRMED')
    NOT NULL DEFAULT 'PENDING',

  provider_name VARCHAR(150) NOT NULL DEFAULT 'GOOGLE_CLOUD_VISION',
  provider_request_id VARCHAR(255) NULL,
  feature_type VARCHAR(80) NOT NULL DEFAULT 'FACE_DETECTION',

  image_width INT UNSIGNED NULL,
  image_height INT UNSIGNED NULL,
  detected_face_count INT UNSIGNED NOT NULL DEFAULT 0,
  reviewed_face_count INT UNSIGNED NOT NULL DEFAULT 0,
  ignored_face_count INT UNSIGNED NOT NULL DEFAULT 0,

  error_code VARCHAR(100) NULL,
  error_message TEXT NULL,

  requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  requested_by BIGINT UNSIGNED NULL,
  completed_at DATETIME NULL,
  confirmed_at DATETIME NULL,
  confirmed_by BIGINT UNSIGNED NULL,

  row_version INT UNSIGNED NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (face_scan_id),
  UNIQUE KEY uq_visit_photo_face_scans_scope
    (face_scan_id, visit_request_id, visit_instance_id, file_id),
  KEY idx_visit_photo_face_scans_photo_time (visit_photo_id, created_at),
  KEY idx_visit_photo_face_scans_instance_time (visit_instance_id, created_at),
  KEY idx_visit_photo_face_scans_request_time (visit_request_id, created_at),
  KEY idx_visit_photo_face_scans_status_time (status, created_at),
  KEY idx_visit_photo_face_scans_api_time (api_config_id, created_at),
  KEY idx_visit_photo_face_scans_requested_by (requested_by, requested_at),
  KEY idx_visit_photo_face_scans_confirmed_by (confirmed_by, confirmed_at),

  CONSTRAINT fk_visit_photo_face_scans_photo_scope
    FOREIGN KEY (visit_photo_id, visit_request_id, visit_instance_id, file_id)
    REFERENCES visit_photos
      (visit_photo_id, visit_request_id, visit_instance_id, file_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_visit_photo_face_scans_api_config
    FOREIGN KEY (api_config_id) REFERENCES api_configurations(api_config_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_visit_photo_face_scans_requested_by
    FOREIGN KEY (requested_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_visit_photo_face_scans_confirmed_by
    FOREIGN KEY (confirmed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT ck_visit_photo_face_scans_dimensions CHECK (
    (image_width IS NULL AND image_height IS NULL)
    OR (image_width > 0 AND image_height > 0)
  ),

  CONSTRAINT ck_visit_photo_face_scans_counts CHECK (
    reviewed_face_count + ignored_face_count <= detected_face_count
  ),

  CONSTRAINT ck_visit_photo_face_scans_feature CHECK (
    feature_type = 'FACE_DETECTION'
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='One Google Cloud Vision FACE_DETECTION execution for one private visit photo. Stores scan state/counts only; no face embedding or automatic identity recognition.';

CREATE TABLE visit_photo_face_detections (
  face_detection_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  face_scan_id BIGINT UNSIGNED NOT NULL,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  file_id BIGINT UNSIGNED NOT NULL,

  face_index INT UNSIGNED NOT NULL
    COMMENT 'One-based stable index inside this scan result',

  bounding_box_x DECIMAL(10,8) NOT NULL
    COMMENT 'Normalized left coordinate from 0 to 1',
  bounding_box_y DECIMAL(10,8) NOT NULL
    COMMENT 'Normalized top coordinate from 0 to 1',
  bounding_box_width DECIMAL(10,8) NOT NULL
    COMMENT 'Normalized width from 0 to 1',
  bounding_box_height DECIMAL(10,8) NOT NULL
    COMMENT 'Normalized height from 0 to 1',
  detection_confidence DECIMAL(6,5) NOT NULL
    COMMENT 'Google Vision detection confidence from 0 to 1',

  guest_member_id BIGINT UNSIGNED NULL
    COMMENT 'Manual selection; must belong to this exact visit instance',
  face_tag_id BIGINT UNSIGNED NULL
    COMMENT 'Final canonical photo_face_tags row created after confirmation',

  review_status ENUM('DETECTED','CONFIRMED','IGNORED')
    NOT NULL DEFAULT 'DETECTED',
  review_note VARCHAR(500) NULL,
  reviewed_at DATETIME NULL,
  reviewed_by BIGINT UNSIGNED NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (face_detection_id),
  UNIQUE KEY uq_visit_photo_face_detection_index (face_scan_id, face_index),
  UNIQUE KEY uq_visit_photo_face_detection_guest (face_scan_id, guest_member_id),
  UNIQUE KEY uq_visit_photo_face_detection_tag (face_tag_id),
  KEY idx_visit_photo_face_detection_instance (visit_instance_id, review_status),
  KEY idx_visit_photo_face_detection_guest (guest_member_id),
  KEY idx_visit_photo_face_detection_status (review_status, created_at),
  KEY idx_visit_photo_face_detection_reviewer (reviewed_by, reviewed_at),

  CONSTRAINT fk_visit_photo_face_detection_scan_scope
    FOREIGN KEY (face_scan_id, visit_request_id, visit_instance_id, file_id)
    REFERENCES visit_photo_face_scans
      (face_scan_id, visit_request_id, visit_instance_id, file_id)
    ON UPDATE CASCADE ON DELETE CASCADE,

  CONSTRAINT fk_visit_photo_face_detection_instance_guest
    FOREIGN KEY (visit_instance_id, guest_member_id)
    REFERENCES visit_instance_guest_members(visit_instance_id, guest_member_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,

  CONSTRAINT fk_visit_photo_face_detection_tag
    FOREIGN KEY (face_tag_id) REFERENCES photo_face_tags(face_tag_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,

  CONSTRAINT fk_visit_photo_face_detection_reviewed_by
    FOREIGN KEY (reviewed_by) REFERENCES users(user_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,

  CONSTRAINT ck_visit_photo_face_detection_index CHECK (face_index > 0),

  CONSTRAINT ck_visit_photo_face_detection_x CHECK (
    bounding_box_x >= 0 AND bounding_box_x <= 1
  ),
  CONSTRAINT ck_visit_photo_face_detection_y CHECK (
    bounding_box_y >= 0 AND bounding_box_y <= 1
  ),
  CONSTRAINT ck_visit_photo_face_detection_width CHECK (
    bounding_box_width > 0
    AND bounding_box_width <= 1
    AND bounding_box_x + bounding_box_width <= 1
  ),
  CONSTRAINT ck_visit_photo_face_detection_height CHECK (
    bounding_box_height > 0
    AND bounding_box_height <= 1
    AND bounding_box_y + bounding_box_height <= 1
  ),
  CONSTRAINT ck_visit_photo_face_detection_confidence CHECK (
    detection_confidence >= 0 AND detection_confidence <= 1
  ),

  CONSTRAINT ck_visit_photo_face_detection_review_state CHECK (
    (
      review_status = 'DETECTED'
      AND face_tag_id IS NULL
      AND reviewed_by IS NULL
      AND reviewed_at IS NULL
    )
    OR
    (
      review_status = 'CONFIRMED'
      AND guest_member_id IS NOT NULL
      AND face_tag_id IS NOT NULL
      AND reviewed_by IS NOT NULL
      AND reviewed_at IS NOT NULL
    )
    OR
    (
      review_status = 'IGNORED'
      AND guest_member_id IS NULL
      AND face_tag_id IS NULL
      AND reviewed_by IS NOT NULL
      AND reviewed_at IS NOT NULL
    )
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Individual Google Vision face boxes awaiting manual assignment to a guest in the exact campus visit instance. Confirmed rows link to existing photo_face_tags.';


-- ---------------------------------------------------------------------
-- Business Card OCR: business_card_ocr_jobs
-- ---------------------------------------------------------------------
CREATE TABLE business_card_ocr_jobs (
  ocr_job_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  scanned_card_file_id BIGINT UNSIGNED NOT NULL,
  api_config_id BIGINT UNSIGNED NOT NULL,

  status ENUM(
    'UPLOADED',
    'PROCESSING',
    'SUCCEEDED',
    'FAILED',
    'CONFIRMED',
    'DISCARDED'
  ) NOT NULL DEFAULT 'UPLOADED',

  provider_name VARCHAR(150) NOT NULL DEFAULT 'GOOGLE_DOCUMENT_AI',
  provider_request_id VARCHAR(255) NULL,
  provider_processor_id VARCHAR(255) NULL,
  provider_location VARCHAR(50) NULL,

  raw_text_encrypted LONGTEXT NULL,
  parsed_json_encrypted LONGTEXT NULL,

  parsed_full_name VARCHAR(150) NULL,
  parsed_email VARCHAR(150) NULL,
  parsed_phone VARCHAR(50) NULL,
  parsed_job_title VARCHAR(150) NULL,
  parsed_department_name VARCHAR(150) NULL,
  parsed_organization VARCHAR(255) NULL,
  parsed_website_url VARCHAR(500) NULL,
  parsed_address VARCHAR(500) NULL,

  confidence_score DECIMAL(5,2) NULL,

  matched_partner_id BIGINT UNSIGNED NULL,
  confirmed_partner_id BIGINT UNSIGNED NULL,
  confirmed_contact_id BIGINT UNSIGNED NULL,

  source_visit_instance_id BIGINT UNSIGNED NULL,
  source_guest_member_id BIGINT UNSIGNED NULL,
  source_minute_participant_id BIGINT UNSIGNED NULL,

  file_sha256 CHAR(64) NULL,

  error_code VARCHAR(100) NULL,
  error_message TEXT NULL,

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  processed_at DATETIME NULL,
  confirmed_at DATETIME NULL,
  confirmed_by BIGINT UNSIGNED NULL,
  expires_at DATETIME NULL,
  deleted_at DATETIME NULL,

  PRIMARY KEY (ocr_job_id),

  KEY idx_bc_ocr_file (scanned_card_file_id),
  KEY idx_bc_ocr_config_status (api_config_id, status),
  KEY idx_bc_ocr_status_time (status, created_at),
  KEY idx_bc_ocr_file_hash (file_sha256),
  KEY idx_bc_ocr_matched_partner (matched_partner_id),
  KEY idx_bc_ocr_confirmed_partner (confirmed_partner_id),
  KEY idx_bc_ocr_confirmed_contact (confirmed_contact_id),
  KEY idx_bc_ocr_visit_context (source_visit_instance_id, source_guest_member_id, source_minute_participant_id),
  KEY idx_bc_ocr_created_by_time (created_by, created_at),

  CONSTRAINT fk_bc_ocr_file
    FOREIGN KEY (scanned_card_file_id) REFERENCES files(file_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_bc_ocr_api_config
    FOREIGN KEY (api_config_id) REFERENCES api_configurations(api_config_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,

  CONSTRAINT fk_bc_ocr_matched_partner
    FOREIGN KEY (matched_partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_confirmed_partner
    FOREIGN KEY (confirmed_partner_id) REFERENCES partners(partner_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_confirmed_contact
    FOREIGN KEY (confirmed_contact_id) REFERENCES partner_contacts(contact_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_visit_instance
    FOREIGN KEY (source_visit_instance_id) REFERENCES visit_request_campuses(visit_instance_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_guest_member
    FOREIGN KEY (source_guest_member_id) REFERENCES visit_guest_members(guest_member_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_minute_participant
    FOREIGN KEY (source_minute_participant_id) REFERENCES minute_participants(minute_participant_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_created_by
    FOREIGN KEY (created_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,

  CONSTRAINT fk_bc_ocr_confirmed_by
    FOREIGN KEY (confirmed_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Cloud OCR job for business cards. OCR draft must be reviewed before creating partner_contacts.';

CREATE TABLE api_configuration_headers (
  api_configuration_header_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  api_config_id BIGINT UNSIGNED NOT NULL,
  header_name VARCHAR(150) NOT NULL,
  header_value_encrypted VARCHAR(1000) NULL,
  is_secret BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (api_configuration_header_id),
  UNIQUE KEY uq_api_header_name (api_config_id, header_name),
  KEY idx_api_headers_config (api_config_id),
  CONSTRAINT fk_api_headers_config
    FOREIGN KEY (api_config_id) REFERENCES api_configurations(api_config_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Explicit API request headers; replaces api_configurations.headers_json.';

CREATE TABLE api_usage_quotas (
  api_usage_quota_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  api_config_id BIGINT UNSIGNED NOT NULL,
  campus_id BIGINT UNSIGNED NULL COMMENT 'NULL = global quota',
  campus_scope_key VARCHAR(36) NOT NULL DEFAULT 'GLOBAL',
  period_yyyymm CHAR(6) NOT NULL COMMENT 'YYYYMM',
  monthly_limit INT UNSIGNED NOT NULL,
  used_count INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Merged api_usage_counters table',
  last_used_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by BIGINT UNSIGNED NULL,
  updated_at DATETIME NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  updated_by BIGINT UNSIGNED NULL,
  PRIMARY KEY (api_usage_quota_id),
  UNIQUE KEY uq_api_quota_config_scope_period (api_config_id, campus_scope_key, period_yyyymm),
  KEY idx_api_quota_campus_period (campus_id, period_yyyymm),
  KEY idx_api_quota_period (period_yyyymm),
  CONSTRAINT fk_api_quota_config
    FOREIGN KEY (api_config_id) REFERENCES api_configurations(api_config_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_api_quota_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='API quota + counter per campus/month';

CREATE TABLE api_request_logs (
  api_request_log_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  api_config_id BIGINT UNSIGNED NOT NULL,
  campus_id BIGINT UNSIGNED NULL,
  requested_by BIGINT UNSIGNED NULL,
  related_type VARCHAR(80) NULL,
  related_id BIGINT UNSIGNED NULL,
  endpoint VARCHAR(500) NOT NULL,
  method ENUM('GET','POST','PUT','PATCH','DELETE') NOT NULL,
  http_status INT NULL,
  response_time_ms INT UNSIGNED NULL,
  request_size_bytes BIGINT UNSIGNED NULL,
  response_size_bytes BIGINT UNSIGNED NULL,
  success BOOLEAN NOT NULL DEFAULT FALSE,
  error_code VARCHAR(100) NULL,
  error_message TEXT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (api_request_log_id),
  KEY idx_api_logs_config_time (api_config_id, created_at),
  KEY idx_api_logs_campus_time (campus_id, created_at),
  KEY idx_api_logs_user_time (requested_by, created_at),
  KEY idx_api_logs_success_time (success, created_at),
  KEY idx_api_logs_related (related_type, related_id),
  CONSTRAINT fk_api_logs_config
    FOREIGN KEY (api_config_id) REFERENCES api_configurations(api_config_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT fk_api_logs_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_api_logs_user
    FOREIGN KEY (requested_by) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='External API request logs. Never log full secret/token.';

-- agenda_templates / agenda_template_items / agenda_template_defaults are defined
-- earlier (just before visit_agendas) so visit_agendas.source_template_item_id can
-- reference agenda_template_items. See the AGENDA TEMPLATE MODULE block above.

-- =====================================================================
-- 11. AUDIT
-- =====================================================================

CREATE TABLE audit_logs (
  audit_log_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  actor_user_id BIGINT UNSIGNED NULL,
  campus_id BIGINT UNSIGNED NULL,
  action VARCHAR(100) NOT NULL,
  entity_type VARCHAR(100) NOT NULL,
  entity_id BIGINT UNSIGNED NULL,
  ip_address VARCHAR(45) NULL,
  user_agent VARCHAR(500) NULL,
  request_id VARCHAR(100) NULL,
  -- Per-campus form v2 audit context (§4.7). visit_request_id / visit_instance_id
  -- carry NO FK: audit must survive business-row deletion (never cascade-deleted).
  correlation_id VARCHAR(100) NULL,
  visit_request_id BIGINT UNSIGNED NULL,
  visit_instance_id BIGINT UNSIGNED NULL,
  source_type VARCHAR(80) NULL,
  source_id BIGINT UNSIGNED NULL,
  reason VARCHAR(500) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (audit_log_id),
  KEY idx_audit_actor_time (actor_user_id, created_at),
  KEY idx_audit_entity (entity_type, entity_id),
  KEY idx_audit_action_time (action, created_at),
  KEY idx_audit_campus_time (campus_id, created_at),
  KEY idx_audit_request (request_id),
  KEY idx_audit_visit_request_time (visit_request_id, created_at),
  KEY idx_audit_visit_instance_time (visit_instance_id, created_at),
  KEY idx_audit_correlation (correlation_id),
  KEY idx_audit_source (source_type, source_id),
  CONSTRAINT fk_audit_actor
    FOREIGN KEY (actor_user_id) REFERENCES users(user_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT fk_audit_campus
    FOREIGN KEY (campus_id) REFERENCES campuses(campus_id)
    ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='General audit log';

CREATE TABLE audit_log_changes (
  audit_log_change_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  audit_log_id BIGINT UNSIGNED NOT NULL,
  field_name VARCHAR(150) NOT NULL,
  -- Per-campus form v2 audit metadata (§4.7).
  change_category VARCHAR(40) NULL,
  value_format VARCHAR(20) NOT NULL DEFAULT 'TEXT',
  is_sensitive TINYINT(1) NOT NULL DEFAULT 0,
  display_order INT UNSIGNED NOT NULL DEFAULT 0,
  old_value_text LONGTEXT NULL,
  new_value_text LONGTEXT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (audit_log_change_id),
  KEY idx_audit_changes_log (audit_log_id),
  KEY idx_audit_changes_field (field_name),
  CONSTRAINT fk_audit_changes_log
    FOREIGN KEY (audit_log_id) REFERENCES audit_logs(audit_log_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='Field-level audit changes; replaces audit_logs old/new JSON values.';


-- =====================================================================
-- 12. VALIDATION TRIGGERS
-- =====================================================================

DELIMITER $$

CREATE TRIGGER trg_departments_one_ic_bi
BEFORE INSERT ON departments
FOR EACH ROW
BEGIN
  DECLARE v_exists INT DEFAULT 0;

  IF NEW.department_type = 'IC' AND NEW.status = 'ACTIVE' THEN
    SELECT COUNT(*) INTO v_exists
    FROM departments
    WHERE campus_id = NEW.campus_id
      AND department_type = 'IC'
      AND status = 'ACTIVE';

    IF v_exists > 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Each campus can have only one active IC department';
    END IF;
  END IF;
END$$

CREATE TRIGGER trg_departments_one_ic_bu
BEFORE UPDATE ON departments
FOR EACH ROW
BEGIN
  DECLARE v_exists INT DEFAULT 0;

  IF NEW.department_type = 'IC' AND NEW.status = 'ACTIVE' THEN
    SELECT COUNT(*) INTO v_exists
    FROM departments
    WHERE campus_id = NEW.campus_id
      AND department_type = 'IC'
      AND status = 'ACTIVE'
      AND department_id <> NEW.department_id;

    IF v_exists > 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Each campus can have only one active IC department';
    END IF;
  END IF;
END$$

CREATE TRIGGER trg_users_validate_bi
BEFORE INSERT ON users
FOR EACH ROW
BEGIN
  DECLARE v_role_code VARCHAR(30);
  DECLARE v_department_type VARCHAR(20);
  DECLARE v_department_campus_id BIGINT UNSIGNED;

  SELECT role_code INTO v_role_code
  FROM roles
  WHERE role_id = NEW.role_id
    AND status = 'ACTIVE';

  IF v_role_code IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid role_id';
  END IF;

  IF v_role_code = 'VISITOR' THEN
    IF NEW.sub_role IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have sub_role';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have department_id';
    END IF;
    IF NEW.primary_campus_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have primary_campus_id';
    END IF;
  ELSEIF v_role_code IN ('STAFF','DEPARTMENT') THEN
    IF NEW.sub_role IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF/DEPARTMENT must have sub_role';
    END IF;
    IF NEW.department_id IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF/DEPARTMENT must have department_id';
    END IF;

    SELECT department_type, campus_id
      INTO v_department_type, v_department_campus_id
    FROM departments
    WHERE department_id = NEW.department_id;

    IF v_role_code = 'STAFF' AND v_department_type <> 'IC' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF must belong to IC department';
    END IF;

    IF v_role_code = 'DEPARTMENT' AND v_department_type <> 'GENERAL' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DEPARTMENT must belong to GENERAL department';
    END IF;

    IF NEW.primary_campus_id IS NULL THEN
      SET NEW.primary_campus_id = v_department_campus_id;
    ELSEIF NEW.primary_campus_id <> v_department_campus_id THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'primary_campus_id must match department campus';
    END IF;
  ELSE
    IF NEW.sub_role IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only STAFF/DEPARTMENT may have sub_role';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only STAFF/DEPARTMENT may have department_id';
    END IF;
    IF NEW.primary_campus_id IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Internal user must have primary_campus_id';
    END IF;
  END IF;
END$$

CREATE TRIGGER trg_users_validate_bu
BEFORE UPDATE ON users
FOR EACH ROW
BEGIN
  DECLARE v_role_code VARCHAR(30);
  DECLARE v_department_type VARCHAR(20);
  DECLARE v_department_campus_id BIGINT UNSIGNED;

  SELECT role_code INTO v_role_code
  FROM roles
  WHERE role_id = NEW.role_id
    AND status = 'ACTIVE';

  IF v_role_code IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid role_id';
  END IF;

  IF v_role_code = 'VISITOR' THEN
    IF NEW.sub_role IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have sub_role';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have department_id';
    END IF;
    IF NEW.primary_campus_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR must not have primary_campus_id';
    END IF;
  ELSEIF v_role_code IN ('STAFF','DEPARTMENT') THEN
    IF NEW.sub_role IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF/DEPARTMENT must have sub_role';
    END IF;
    IF NEW.department_id IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF/DEPARTMENT must have department_id';
    END IF;

    SELECT department_type, campus_id
      INTO v_department_type, v_department_campus_id
    FROM departments
    WHERE department_id = NEW.department_id;

    IF v_role_code = 'STAFF' AND v_department_type <> 'IC' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'STAFF must belong to IC department';
    END IF;

    IF v_role_code = 'DEPARTMENT' AND v_department_type <> 'GENERAL' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'DEPARTMENT must belong to GENERAL department';
    END IF;

    IF NEW.primary_campus_id IS NULL THEN
      SET NEW.primary_campus_id = v_department_campus_id;
    ELSEIF NEW.primary_campus_id <> v_department_campus_id THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'primary_campus_id must match department campus';
    END IF;
  ELSE
    IF NEW.sub_role IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only STAFF/DEPARTMENT may have sub_role';
    END IF;
    IF NEW.department_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only STAFF/DEPARTMENT may have department_id';
    END IF;
    IF NEW.primary_campus_id IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Internal user must have primary_campus_id';
    END IF;
  END IF;
END$$

CREATE TRIGGER trg_auth_providers_validate_bi
BEFORE INSERT ON user_auth_providers
FOR EACH ROW
BEGIN
  IF NEW.provider_type IN ('GOOGLE_SSO','FEID')
     AND (NEW.provider_subject IS NULL OR NEW.provider_subject = '') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SSO/FEID provider_subject is required';
  END IF;
END$$

CREATE TRIGGER trg_auth_providers_validate_bu
BEFORE UPDATE ON user_auth_providers
FOR EACH ROW
BEGIN
  IF NEW.provider_type IN ('GOOGLE_SSO','FEID')
     AND (NEW.provider_subject IS NULL OR NEW.provider_subject = '') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SSO/FEID provider_subject is required';
  END IF;
END$$

CREATE TRIGGER trg_sessions_validate_bi
BEFORE INSERT ON user_sessions
FOR EACH ROW
BEGIN
  DECLARE v_role_code VARCHAR(30);
  DECLARE v_primary_campus_id BIGINT UNSIGNED;

  SELECT r.role_code, u.primary_campus_id
    INTO v_role_code, v_primary_campus_id
  FROM users u
  JOIN roles r ON r.role_id = u.role_id
  WHERE u.user_id = NEW.user_id;

  IF NEW.login_portal = 'VISITOR' THEN
    IF v_role_code <> 'VISITOR' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only VISITOR can login via Visitor Portal';
    END IF;
    IF NEW.selected_campus_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Visitor Portal must not have selected_campus_id';
    END IF;
  ELSEIF NEW.login_portal = 'INTERNAL' THEN
    IF v_role_code = 'VISITOR' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'VISITOR cannot login via Internal Portal';
    END IF;
    IF v_primary_campus_id IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Internal user must have primary_campus_id';
    END IF;
    IF NEW.selected_campus_id IS NULL THEN
      SET NEW.selected_campus_id = v_primary_campus_id;
    ELSEIF NEW.selected_campus_id <> v_primary_campus_id THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Internal user can only login to their own primary campus';
    END IF;
  END IF;
END$$


