INSERT INTO notifications (notification_id, recipient_user_id, title, message, notification_type, related_type, related_id, is_read, read_at, created_at) VALUES
  (1, 2, 'Cập nhật tiến độ đơn liên cơ sở', 'VR-MC-HN-DN-0002 đã hoàn tất quyết định tại từng campus. Head Office chỉ theo dõi kết quả tổng hợp.', 'VISIT_MONITORING_UPDATE', 'VISIT_REQUEST', 2002, TRUE, '2026-06-23 09:10:00', '2026-06-23 09:01:00'),
  (2, 3, 'Đơn đơn cơ sở mới tại HN', 'VR-SC-HN-0001 đang chờ Staff Leader HN duyệt.', 'VISIT_WAITING_STAFF_LEADER_APPROVAL', 'VISIT_REQUEST', 1001, FALSE, NULL, '2026-06-23 08:01:00'),
  (3, 4, 'Bạn được phân công Host', 'Bạn là host của VR-SC-HN-0003 và các chặng liên quan.', 'HOST_ASSIGNMENT', 'VISIT_INSTANCE', 3003, TRUE, '2026-06-12 17:00:00', '2026-06-12 16:45:00'),
  (4, 5, 'Yêu cầu hỗ trợ roundtable', 'Bạn cần điều phối Department Staff cho danh sách sinh viên.', 'DEPARTMENT_TASK', 'VISIT_INSTANCE', 3005, FALSE, NULL, '2026-06-20 08:15:00'),
  (5, 6, 'Bạn được giao hỗ trợ roundtable', 'Chuẩn bị danh sách sinh viên tham gia Mobility Forum.', 'DEPARTMENT_ASSIGNMENT', 'VISIT_INSTANCE', 3005, TRUE, '2026-06-20 09:00:00', '2026-06-20 08:20:00'),
