INSERT INTO visit_agendas (agenda_id, visit_instance_id, sequence_order, title, description, start_time, end_time, location, responsible_user_id, created_at, created_by, updated_at, updated_by) VALUES
  (8001, 5003, 1, 'Đón đoàn và xác nhận thành phần tham dự', 'Host gặp trưởng đoàn, đối chiếu danh sách khách và giới thiệu đầu mối hỗ trợ trong chương trình.', '2026-08-10 08:30:00', '2026-08-10 09:00:00', 'Sảnh Alpha, FPT University Hà Nội', 4, '2026-07-03 08:00:00', 3, NULL, NULL),
  (8002, 5003, 2, 'Đối sánh chương trình đào tạo và chuẩn đầu ra', 'Hai bên so sánh cấu trúc học phần, phương pháp đánh giá và khả năng công nhận tín chỉ.', '2026-08-10 09:15:00', '2026-08-10 11:30:00', 'Phòng seminar Alpha 201', 4, '2026-07-03 08:10:00', 3, NULL, NULL),
  (8003, 5004, 1, 'Giới thiệu mục tiêu và chương trình làm việc', 'Đại diện FPTU trình bày mục tiêu, agenda và các kết quả mong đợi của phiên trao đổi.', '2026-08-11 08:30:00', '2026-08-11 09:00:00', 'Phòng seminar Alpha 201', 101, '2026-07-03 08:00:00', 3, NULL, NULL),
  (8004, 5004, 2, 'Thảo luận cơ hội trao đổi sinh viên', 'Các bên thống nhất điều kiện tham gia, lịch học, hỗ trợ hòa nhập và đầu mối xử lý hồ sơ.', '2026-08-11 09:15:00', '2026-08-11 11:30:00', 'Innovation Hub Hà Nội', 101, '2026-07-03 08:10:00', 3, NULL, NULL),
  (8005, 5005, 1, 'Briefing an toàn và lộ trình campus', 'Host hướng dẫn quy tắc ra vào, điểm tập trung và phương án di chuyển giữa các khu vực.', '2026-08-12 08:30:00', '2026-08-12 09:00:00', 'Innovation Hub Hà Nội', 4, '2026-07-03 08:00:00', 3, NULL, NULL),
  (8006, 5005, 2, 'Trình diễn dự án công nghệ của sinh viên', 'Nhóm sinh viên giới thiệu sản phẩm, nhận góp ý và trao đổi cơ hội kết nối cố vấn.', '2026-08-12 09:15:00', '2026-08-12 11:30:00', 'Phòng họp Alpha 202', 4, '2026-07-03 08:10:00', 3, NULL, NULL),
  (8007, 5006, 1, 'Kết nối đại biểu và giới thiệu đơn vị', 'Các thành viên giới thiệu vai trò, lĩnh vực phụ trách và nội dung muốn trao đổi.', '2026-08-13 08:30:00', '2026-08-13 09:00:00', 'Phòng họp Alpha 202', 101, '2026-07-03 08:00:00', 3, NULL, NULL),
  (8008, 5006, 2, 'Trao đổi hợp tác nghiên cứu ứng dụng', 'Giảng viên xác định chủ đề ưu tiên, dữ liệu cần chia sẻ và lộ trình xây dựng đề cương chung.', '2026-08-13 09:15:00', '2026-08-13 11:30:00', 'Sảnh Alpha, FPT University Hà Nội', 101, '2026-07-03 08:10:00', 3, NULL, NULL),
  (8009, 5007, 1, 'Tổng quan về FPT University', 'Đại diện campus giới thiệu mô hình đào tạo, hệ sinh thái sinh viên và định hướng hợp tác quốc tế.', '2026-08-14 08:30:00', '2026-08-14 09:00:00', 'Sảnh Alpha, FPT University Hà Nội', 4, '2026-07-03 08:00:00', 3, NULL, NULL),
  (8010, 5007, 2, 'Khảo sát mô hình campus xanh', 'Đoàn tìm hiểu quản lý năng lượng, giao thông nội khu và hoạt động nâng cao nhận thức cho sinh viên.', '2026-08-14 09:15:00', '2026-08-14 11:30:00', 'Phòng seminar Alpha 201', 4, '2026-07-03 08:10:00', 3, NULL, NULL),
  (8011, 5012, 1, 'Xác nhận nhu cầu chuyên môn của đoàn', 'Host rà soát câu hỏi ưu tiên và chuyển nội dung tới giảng viên, đơn vị liên quan.', '2026-08-19 08:30:00', '2026-08-19 09:00:00', 'Phòng seminar Beta 301', 103, '2026-07-03 08:00:00', 9, NULL, NULL),
