  (9001, 5003, 'ROOM', 'Phòng họp Alpha cho phiên trao đổi học thuật', 'Yêu cầu đã được gửi tới đơn vị phụ trách để xác nhận nguồn lực và thời gian phục vụ. Phòng cần được bố trí đủ chỗ ngồi, nước uống và biển tên trước phiên làm việc.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REQUESTED', 'LOW', NULL, 2, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-07-04 08:00:00', 4, NULL, NULL),
  (9002, 5004, 'TRANSPORT', 'Xe 16 chỗ đón đoàn tại sân bay Nội Bài', 'Yêu cầu đã được gửi tới đơn vị phụ trách để xác nhận nguồn lực và thời gian phục vụ. Lộ trình, điểm đón và số điện thoại lái xe phải được gửi cho đầu mối đoàn trước một ngày.', 2, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REQUESTED', 'MEDIUM', NULL, 2, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-07-04 08:00:00', 101, NULL, NULL),
  (9003, 5005, 'MEAL', 'Tea break giữa hai phiên làm việc', 'Yêu cầu đã được gửi tới đơn vị phụ trách để xác nhận nguồn lực và thời gian phục vụ. Thực đơn cần ghi nhận yêu cầu ăn chay, dị ứng thực phẩm và số lượng khách đã xác nhận.', 3, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REQUESTED', 'HIGH', NULL, 2, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-07-04 08:00:00', 4, NULL, NULL),
  (9004, 5006, 'EQUIPMENT', 'Màn hình trình chiếu và micro không dây', 'Yêu cầu đã được gửi tới đơn vị phụ trách để xác nhận nguồn lực và thời gian phục vụ. Thiết bị cần được chạy thử với máy tính của người trình bày trước giờ đón đoàn.', 4, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REQUESTED', 'URGENT', NULL, 2, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-07-04 08:00:00', 101, NULL, NULL),
