  (9057, 5014, 'ROOM', 'Phòng họp trực tuyến kết nối hai cơ sở', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Phòng cần được bố trí đủ chỗ ngồi, nước uống và biển tên trước phiên làm việc.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'LOW', 103, 105, '2026-07-04 08:00:00', 127, '2026-07-04 09:00:00', 128, 127, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 103, '2026-07-05 16:30:00', 127),
  (9058, 5015, 'TRANSPORT', 'Phương tiện hỗ trợ khách lớn tuổi trong campus', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Lộ trình, điểm đón và số điện thoại lái xe phải được gửi cho đầu mối đoàn trước một ngày.', 2, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'MEDIUM', 10, 105, '2026-07-04 08:00:00', 127, '2026-07-04 09:00:00', 128, 127, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 10, '2026-07-05 16:30:00', 127),
  (9059, 5016, 'MEAL', 'Bữa trưa giao lưu cùng đại diện khoa', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Thực đơn cần ghi nhận yêu cầu ăn chay, dị ứng thực phẩm và số lượng khách đã xác nhận.', 3, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'HIGH', 103, 105, '2026-07-04 08:00:00', 127, '2026-07-04 09:00:00', 128, 127, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 103, '2026-07-05 16:30:00', 127),
  (9060, 5021, 'EQUIPMENT', 'Hệ thống âm thanh cho phiên chia sẻ', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Thiết bị cần được chạy thử với máy tính của người trình bày trước giờ đón đoàn.', 4, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'URGENT', 12, 108, '2026-07-04 08:00:00', 133, '2026-07-04 09:00:00', 134, 133, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 12, '2026-07-05 16:30:00', 133),
  (9061, 5022, 'BANNER', 'Backdrop cho phiên ký kết hợp tác', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Nội dung nhận diện phải dùng đúng tên đối tác và được duyệt trước khi in.', 5, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'LOW', 105, 108, '2026-07-04 08:00:00', 133, '2026-07-04 09:00:00', 134, 133, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 105, '2026-07-05 16:30:00', 133),
  (9062, 5023, 'LED', 'Video giới thiệu campus trên màn hình lớn', 'Hạng mục đã hoàn tất và được Host xác nhận đáp ứng đúng yêu cầu của đoàn. Tệp hiển thị cần đúng tỷ lệ màn hình và có phiên bản tiếng Anh.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'DONE', 'MEDIUM', 12, 108, '2026-07-04 08:00:00', 133, '2026-07-04 09:00:00', 134, 133, '2026-07-04 10:00:00', '2026-07-04 10:30:00', 'Người được phân công đã kiểm tra nguồn lực và xác nhận có thể hoàn tất đúng thời hạn.', '2026-08-09 17:00:00', '2026-07-05 16:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-07-04 08:00:00', 12, '2026-07-05 16:30:00', 133),
