  (9064, 5025, 'ROOM', 'Khu vực đón tiếp và trao đổi cùng giảng viên', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Phòng cần được bố trí đủ chỗ ngồi, nước uống và biển tên trước phiên làm việc.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'MEDIUM', 12, 108, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 12, NULL, NULL),
  (9065, 5030, 'TRANSPORT', 'Xe trung chuyển cho lịch trình liên cơ sở', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Lộ trình, điểm đón và số điện thoại lái xe phải được gửi cho đầu mối đoàn trước một ngày.', 2, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'HIGH', 107, 110, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 107, NULL, NULL),
  (9066, 5031, 'MEAL', 'Thực đơn chay cho thành viên đăng ký trước', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Thực đơn cần ghi nhận yêu cầu ăn chay, dị ứng thực phẩm và số lượng khách đã xác nhận.', 3, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'URGENT', 14, 110, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 14, NULL, NULL),
  (9067, 5032, 'EQUIPMENT', 'Bảng viết và bộ dụng cụ workshop', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Thiết bị cần được chạy thử với máy tính của người trình bày trước giờ đón đoàn.', 4, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'LOW', 107, 110, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 107, NULL, NULL),
  (9068, 5033, 'BANNER', 'Bảng tên đại biểu tại phòng họp', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Nội dung nhận diện phải dùng đúng tên đối tác và được duyệt trước khi in.', 5, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'MEDIUM', 14, 110, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 14, NULL, NULL),
  (9069, 5034, 'LED', 'Thông điệp chào mừng song ngữ tại sảnh', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Tệp hiển thị cần đúng tỷ lệ màn hình và có phiên bản tiếng Anh.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'HIGH', 107, 110, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 107, NULL, NULL),
  (9070, 5039, 'OTHER', 'Tủ lưu trữ hành lý trong thời gian tham quan', 'Đơn vị phụ trách từ chối vì không đủ nguồn lực trong khung thời gian đã đăng ký. Host chịu trách nhiệm xác nhận đầu mối thực hiện và thời hạn bàn giao.', 2, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'REJECTED', 'URGENT', 16, 112, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Không thể đáp ứng trong thời gian yêu cầu; Host đã được thông báo để chọn phương án khác.', 9, '2026-07-04 08:00:00', 16, NULL, NULL),
  (9071, 5040, 'ROOM', 'Phòng họp Alpha cho phiên trao đổi học thuật', 'Hạng mục được hủy sau khi lịch trình hoặc nhu cầu của đoàn thay đổi. Phòng cần được bố trí đủ chỗ ngồi, nước uống và biển tên trước phiên làm việc.', 1, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'CANCELLED', 'HIGH', 109, 112, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Nhu cầu không còn sau khi lịch trình được cập nhật.', 10, '2026-07-04 08:00:00', 109, NULL, NULL),
  (9072, 5041, 'TRANSPORT', 'Xe 16 chỗ đón đoàn tại sân bay Nội Bài', 'Hạng mục được hủy sau khi lịch trình hoặc nhu cầu của đoàn thay đổi. Lộ trình, điểm đón và số điện thoại lái xe phải được gửi cho đầu mối đoàn trước một ngày.', 2, '2026-08-10 08:00:00', '2026-08-10 12:00:00', 'CANCELLED', 'URGENT', 16, 112, '2026-07-04 08:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-09 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Nhu cầu không còn sau khi lịch trình được cập nhật.', 10, '2026-07-04 08:00:00', 16, NULL, NULL),
