INSERT INTO minutes (minutes_id, visit_instance_id, title, content, status, edit_locked_by, edit_locked_at, edit_lock_expires_at, edit_lock_token, row_version, created_at, created_by, updated_at, updated_by) VALUES
  (10001, 5005, 'Biên bản phiên trao đổi về khởi nghiệp sinh viên', 'Hai bên thống nhất chia sẻ mô hình ươm tạo dự án, kết nối cố vấn doanh nghiệp và tổ chức một phiên pitching trực tuyến cho sinh viên.', 'DRAFT', 4, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10001', 0, '2026-08-10 14:00:00', 4, NULL, NULL),
  (10002, 5006, 'Biên bản chương trình giới thiệu du lịch và dịch vụ', 'Đoàn trao đổi về đào tạo thực hành, tiêu chuẩn phục vụ khách quốc tế và cơ hội tổ chức workshop chuyên đề cho sinh viên.', 'SAVED', NULL, NULL, NULL, NULL, 1, '2026-08-10 14:00:00', 101, '2026-08-10 15:30:00', 101),
  (10003, 5007, 'Biên bản hoạt động gắn kết cộng đồng khu vực mekong', 'Các bên thống nhất phối hợp một chương trình học tập phục vụ cộng đồng và chia sẻ tài liệu đánh giá tác động.', 'SAVED', NULL, NULL, NULL, NULL, 2, '2026-08-10 14:00:00', 4, '2026-08-10 15:30:00', 4),
  (10004, 5014, 'Biên bản phiên làm việc về trung tâm đổi mới sáng tạo', 'Nội dung tập trung vào không gian maker, cơ chế cố vấn dự án và khả năng tổ chức chương trình thử nghiệm chung.', 'DRAFT', 103, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10004', 3, '2026-08-10 14:00:00', 103, NULL, NULL),
  (10005, 5015, 'Biên bản quan sát mô hình sinh viên hỗ trợ song ngữ', 'Đoàn ghi nhận quy trình đón khách, cách phân công sinh viên và các tài liệu cần chuẩn hóa trước chương trình tiếp theo.', 'SAVED', NULL, NULL, NULL, NULL, 4, '2026-08-10 14:00:00', 10, '2026-08-10 15:30:00', 10),
  (10006, 5016, 'Biên bản trao đổi về vận hành campus bền vững', 'Các bên thảo luận quản lý năng lượng, phân loại rác, giao thông nội khu và phương án truyền thông cho người học.', 'SAVED', NULL, NULL, NULL, NULL, 5, '2026-08-10 14:00:00', 103, '2026-08-10 15:30:00', 103),
  (10007, 5023, 'Biên bản trình diễn lớp học robot ứng dụng', 'Giảng viên giới thiệu thiết bị, bài tập thực hành và yêu cầu an toàn; đối tác đề xuất một buổi chuyên đề tiếp nối.', 'DRAFT', 12, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10007', 6, '2026-08-10 14:00:00', 12, NULL, NULL),
  (10008, 5024, 'Biên bản đối sánh chương trình đào tạo trí tuệ nhân tạo', 'Hai bên rà soát cấu trúc học phần, chuẩn đầu ra và điều kiện công nhận tín chỉ cho sinh viên trao đổi.', 'SAVED', NULL, NULL, NULL, NULL, 7, '2026-08-10 14:00:00', 105, '2026-08-10 15:30:00', 105),
  (10009, 5025, 'Biên bản chương trình kết nối cố vấn doanh nghiệp', 'Đại diện doanh nghiệp thống nhất phạm vi cố vấn, lịch làm việc và tiêu chí lựa chọn nhóm sinh viên tham gia.', 'SAVED', NULL, NULL, NULL, NULL, 8, '2026-08-10 14:00:00', 12, '2026-08-10 15:30:00', 12),
  (10010, 5032, 'Biên bản thảo luận về trao đổi học thuật quốc tế', 'Các bên thống nhất đầu mối, mốc gửi hồ sơ và nội dung học thuật ưu tiên cho kỳ hợp tác tiếp theo.', 'DRAFT', 107, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10010', 9, '2026-08-10 14:00:00', 107, NULL, NULL),
  (10011, 5033, 'Biên bản phiên chia sẻ về chuyển đổi số trong giáo dục', 'Đoàn trao đổi về nền tảng học tập, quản trị dữ liệu và các nguyên tắc bảo vệ thông tin người học.', 'SAVED', NULL, NULL, NULL, NULL, 10, '2026-08-10 14:00:00', 14, '2026-08-10 15:30:00', 14),
  (10012, 5034, 'Biên bản khảo sát không gian học tập mở', 'Các bên ghi nhận nhu cầu bố trí không gian, thiết bị và quy tắc vận hành cho các hoạt động liên ngành.', 'SAVED', NULL, NULL, NULL, NULL, 11, '2026-08-10 14:00:00', 107, '2026-08-10 15:30:00', 107),
  (10013, 5041, 'Biên bản trao đổi hợp tác nghiên cứu ứng dụng', 'Nhóm chuyên môn thống nhất chủ đề ưu tiên, cách chia sẻ dữ liệu và kế hoạch xây dựng đề cương nghiên cứu chung.', 'DRAFT', 16, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10013', 12, '2026-08-10 14:00:00', 16, NULL, NULL),
  (10014, 5042, 'Biên bản chương trình kết nối sinh viên quốc tế', 'Nội dung tập trung vào buddy programme, hỗ trợ hòa nhập và các hoạt động giao lưu trong học kỳ đầu.', 'SAVED', NULL, NULL, NULL, NULL, 13, '2026-08-10 14:00:00', 109, '2026-08-10 15:30:00', 109),
  (10015, 5043, 'Biên bản khảo sát phòng thí nghiệm công nghệ', 'Đoàn xem xét năng lực thiết bị, quy trình an toàn và cơ hội triển khai dự án sinh viên có cố vấn chung.', 'SAVED', NULL, NULL, NULL, NULL, 14, '2026-08-10 14:00:00', 16, '2026-08-10 15:30:00', 16),
  (10016, 5068, 'Biên bản phiên làm việc về quản trị sự kiện campus', 'Hai bên thống nhất quy trình tiếp nhận yêu cầu, phân công Host và cơ chế phối hợp hậu cần theo từng campus.', 'DRAFT', 12, '2026-08-10 15:00:00', '2026-08-10 16:00:00', 'lock-token-10016', 15, '2026-08-10 14:00:00', 12, NULL, NULL),
  (10017, 5077, 'Biên bản thảo luận chương trình thực tập doanh nghiệp', 'Đối tác nêu nhu cầu tuyển dụng, tiêu chí sinh viên và lịch phỏng vấn; nhà trường thống nhất đầu mối triển khai.', 'SAVED', NULL, NULL, NULL, NULL, 16, '2026-08-10 14:00:00', 101, '2026-08-10 15:30:00', 101),
  (10018, 5078, 'Biên bản tổng kết chuyến thăm và kế hoạch tiếp nối', 'Các bên xác nhận kết quả chính, danh sách tài liệu cần trao đổi và lịch họp trực tuyến tiếp theo.', 'SAVED', NULL, NULL, NULL, NULL, 17, '2026-08-10 14:00:00', 107, '2026-08-10 15:30:00', 107);

