INSERT INTO news_translations (news_translation_id, news_id, language_code, title, slug, summary, seo_title, seo_description, created_at, updated_at) VALUES
  (15101, 15001, 'vi', 'Bản nháp: mở rộng chương trình trao đổi sinh viên với đối tác Ấn Độ', 'ban-nhap-mo-rong-chuong-trinh-trao-oi-sinh-vien-voi-oi-tac-an-o', 'Bài viết đang tổng hợp các nội dung về công nhận tín chỉ, hỗ trợ sinh viên và lịch triển khai dự kiến.', 'Bản nháp: mở rộng chương trình trao đổi sinh viên với đối tác Ấn Độ', 'Bài viết đang tổng hợp các nội dung về công nhận tín chỉ, hỗ trợ sinh viên và lịch triển khai dự kiến.', '2026-08-16 08:05:00', NULL),
  (15102, 15001, 'en', 'Draft: expanding the student exchange programme with an Indian partner', 'draft-expanding-the-student-exchange-programme-with-an-indian-partner', 'The article is consolidating details on credit recognition, student support and the proposed implementation timeline.', 'Draft: expanding the student exchange programme with an Indian partner', 'The article is consolidating details on credit recognition, student support and the proposed implementation timeline.', '2026-08-16 08:05:00', NULL),
  (15103, 15002, 'vi', 'Đề xuất bài viết về chuyến tham quan phòng lab chưa đủ minh chứng', 'e-xuat-bai-viet-ve-chuyen-tham-quan-phong-lab-chua-u-minh-chung', 'Bản thảo chưa có đủ ảnh được cấp quyền sử dụng và thiếu xác nhận của đơn vị chuyên môn.', 'Đề xuất bài viết về chuyến tham quan phòng lab chưa đủ minh chứng', 'Bản thảo chưa có đủ ảnh được cấp quyền sử dụng và thiếu xác nhận của đơn vị chuyên môn.', '2026-08-16 08:05:00', NULL),
  (15104, 15002, 'en', 'Proposed lab-visit article needs additional evidence', 'proposed-lab-visit-article-needs-additional-evidence', 'The draft lacks approved photographs and confirmation from the academic unit.', 'Proposed lab-visit article needs additional evidence', 'The draft lacks approved photographs and confirmation from the academic unit.', '2026-08-16 08:05:00', NULL),
  (15105, 15003, 'vi', 'Sinh viên FPTU cùng đối tác quốc tế trao đổi về khởi nghiệp', 'sinh-vien-fptu-cung-oi-tac-quoc-te-trao-oi-ve-khoi-nghiep', 'Phiên làm việc kết nối sinh viên, giảng viên và chuyên gia để chia sẻ kinh nghiệm phát triển dự án.', 'Sinh viên FPTU cùng đối tác quốc tế trao đổi về khởi nghiệp', 'Phiên làm việc kết nối sinh viên, giảng viên và chuyên gia để chia sẻ kinh nghiệm phát triển dự án.', '2026-08-16 08:05:00', NULL),
  (15106, 15003, 'en', 'FPTU students discuss entrepreneurship with an international partner', 'fptu-students-discuss-entrepreneurship-with-an-international-partner', 'The session connected students, lecturers and experts to exchange practical project-development experience.', 'FPTU students discuss entrepreneurship with an international partner', 'The session connected students, lecturers and experts to exchange practical project-development experience.', '2026-08-16 08:05:00', NULL),
  (15107, 15004, 'vi', 'Ẩn bài viết cũ về lịch trình đã thay đổi', 'an-bai-viet-cu-ve-lich-trinh-a-thay-oi', 'Bài viết được ẩn vì lịch trình và danh sách đại biểu đã thay đổi trước ngày diễn ra.', 'Ẩn bài viết cũ về lịch trình đã thay đổi', 'Bài viết được ẩn vì lịch trình và danh sách đại biểu đã thay đổi trước ngày diễn ra.', '2026-08-16 08:05:00', NULL),
  (15108, 15004, 'en', 'Archived article about an outdated programme schedule', 'archived-article-about-an-outdated-programme-schedule', 'The article was hidden because the programme schedule and delegate list changed before the event.', 'Archived article about an outdated programme schedule', 'The article was hidden because the programme schedule and delegate list changed before the event.', '2026-08-16 08:05:00', NULL),
  (15109, 15005, 'vi', 'Bản nháp về mô hình campus xanh và giao thông nội khu', 'ban-nhap-ve-mo-hinh-campus-xanh-va-giao-thong-noi-khu', 'Nội dung giới thiệu giải pháp tiết kiệm năng lượng, xe điện và lộ trình tham quan ít phát thải.', 'Bản nháp về mô hình campus xanh và giao thông nội khu', 'Nội dung giới thiệu giải pháp tiết kiệm năng lượng, xe điện và lộ trình tham quan ít phát thải.', '2026-08-16 08:05:00', NULL),
  (15110, 15005, 'en', 'Draft on green-campus operations and internal mobility', 'draft-on-green-campus-operations-and-internal-mobility', 'The draft presents energy-saving initiatives, electric mobility and a lower-emission visitor route.', 'Draft on green-campus operations and internal mobility', 'The draft presents energy-saving initiatives, electric mobility and a lower-emission visitor route.', '2026-08-16 08:05:00', NULL),
  (15111, 15006, 'vi', 'Bài viết hợp tác du lịch cần chỉnh lại nguồn trích dẫn', 'bai-viet-hop-tac-du-lich-can-chinh-lai-nguon-trich-dan', 'Ban biên tập yêu cầu kiểm tra lại số liệu và bổ sung ý kiến xác nhận từ đơn vị chuyên môn.', 'Bài viết hợp tác du lịch cần chỉnh lại nguồn trích dẫn', 'Ban biên tập yêu cầu kiểm tra lại số liệu và bổ sung ý kiến xác nhận từ đơn vị chuyên môn.', '2026-08-16 08:05:00', NULL),
  (15112, 15006, 'en', 'Tourism partnership article requires source corrections', 'tourism-partnership-article-requires-source-corrections', 'Editors requested verified figures and confirmation from the relevant academic unit.', 'Tourism partnership article requires source corrections', 'Editors requested verified figures and confirmation from the relevant academic unit.', '2026-08-16 08:05:00', NULL),
  (15113, 15007, 'vi', 'Đoàn đối tác trải nghiệm mô hình học tập gắn với doanh nghiệp', 'oan-oi-tac-trai-nghiem-mo-hinh-hoc-tap-gan-voi-doanh-nghiep', 'Chuyến thăm tập trung vào học phần dự án, vai trò cố vấn doanh nghiệp và cơ hội thực tập.', 'Đoàn đối tác trải nghiệm mô hình học tập gắn với doanh nghiệp', 'Chuyến thăm tập trung vào học phần dự án, vai trò cố vấn doanh nghiệp và cơ hội thực tập.', '2026-08-16 08:05:00', NULL),
  (15114, 15007, 'en', 'Partner delegation explores industry-linked learning', 'partner-delegation-explores-industry-linked-learning', 'The visit focused on project-based courses, industry mentoring and internship opportunities.', 'Partner delegation explores industry-linked learning', 'The visit focused on project-based courses, industry mentoring and internship opportunities.', '2026-08-16 08:05:00', NULL),
  (15115, 15008, 'vi', 'Ẩn tin sau khi đối tác đề nghị cập nhật hình ảnh', 'an-tin-sau-khi-oi-tac-e-nghi-cap-nhat-hinh-anh', 'Tin tạm ẩn để thay ảnh chưa phù hợp và rà soát lại phạm vi đồng ý sử dụng hình ảnh.', 'Ẩn tin sau khi đối tác đề nghị cập nhật hình ảnh', 'Tin tạm ẩn để thay ảnh chưa phù hợp và rà soát lại phạm vi đồng ý sử dụng hình ảnh.', '2026-08-16 08:05:00', NULL),
  (15116, 15008, 'en', 'Article hidden while partner photographs are being updated', 'article-hidden-while-partner-photographs-are-being-updated', 'The article is temporarily hidden while unsuitable photographs and consent scope are reviewed.', 'Article hidden while partner photographs are being updated', 'The article is temporarily hidden while unsuitable photographs and consent scope are reviewed.', '2026-08-16 08:05:00', NULL),
  (15117, 15009, 'vi', 'Bản nháp về chương trình sinh viên hỗ trợ đoàn quốc tế', 'ban-nhap-ve-chuong-trinh-sinh-vien-ho-tro-oan-quoc-te', 'Bài viết ghi nhận cách sinh viên hỗ trợ check-in, phiên dịch và hướng dẫn lộ trình trong campus.', 'Bản nháp về chương trình sinh viên hỗ trợ đoàn quốc tế', 'Bài viết ghi nhận cách sinh viên hỗ trợ check-in, phiên dịch và hướng dẫn lộ trình trong campus.', '2026-08-16 08:05:00', NULL),
  (15118, 15009, 'en', 'Draft on the international visitor student-buddy programme', 'draft-on-the-international-visitor-student-buddy-programme', 'The article describes how students support check-in, interpretation and campus navigation.', 'Draft on the international visitor student-buddy programme', 'The article describes how students support check-in, interpretation and campus navigation.', '2026-08-16 08:05:00', NULL),
  (15119, 15010, 'vi', 'Bản thảo sự kiện công nghệ cần bổ sung nội dung chuyên môn', 'ban-thao-su-kien-cong-nghe-can-bo-sung-noi-dung-chuyen-mon', 'Bản thảo bị trả lại để bổ sung kết quả trình diễn, tên diễn giả và nội dung follow-up.', 'Bản thảo sự kiện công nghệ cần bổ sung nội dung chuyên môn', 'Bản thảo bị trả lại để bổ sung kết quả trình diễn, tên diễn giả và nội dung follow-up.', '2026-08-16 08:05:00', NULL),
  (15120, 15010, 'en', 'Technology-event draft needs stronger academic detail', 'technology-event-draft-needs-stronger-academic-detail', 'The draft was returned for clearer demonstration outcomes, speaker details and follow-up actions.', 'Technology-event draft needs stronger academic detail', 'The draft was returned for clearer demonstration outcomes, speaker details and follow-up actions.', '2026-08-16 08:05:00', NULL),
  (15121, 15011, 'vi', 'FPTU và đối tác trao đổi cơ hội nghiên cứu ứng dụng', 'fptu-va-oi-tac-trao-oi-co-hoi-nghien-cuu-ung-dung', 'Hai bên xác định các chủ đề ưu tiên, đầu mối chuyên môn và kế hoạch xây dựng đề cương chung.', 'FPTU và đối tác trao đổi cơ hội nghiên cứu ứng dụng', 'Hai bên xác định các chủ đề ưu tiên, đầu mối chuyên môn và kế hoạch xây dựng đề cương chung.', '2026-08-16 08:05:00', NULL),
  (15122, 15011, 'en', 'FPTU and partner discuss applied research opportunities', 'fptu-and-partner-discuss-applied-research-opportunities', 'Both sides identified priority themes, academic contacts and a plan for a joint proposal.', 'FPTU and partner discuss applied research opportunities', 'Both sides identified priority themes, academic contacts and a plan for a joint proposal.', '2026-08-16 08:05:00', NULL),
  (15123, 15012, 'vi', 'Ẩn bài viết do chuyến thăm được dời lịch', 'an-bai-viet-do-chuyen-tham-uoc-doi-lich', 'Nội dung được lưu lại để cập nhật sau khi hai bên thống nhất ngày làm việc mới.', 'Ẩn bài viết do chuyến thăm được dời lịch', 'Nội dung được lưu lại để cập nhật sau khi hai bên thống nhất ngày làm việc mới.', '2026-08-16 08:05:00', NULL),
  (15124, 15012, 'en', 'Article hidden after the visit was rescheduled', 'article-hidden-after-the-visit-was-rescheduled', 'The content is retained for revision after both parties confirm a new visit date.', 'Article hidden after the visit was rescheduled', 'The content is retained for revision after both parties confirm a new visit date.', '2026-08-16 08:05:00', NULL),
  (15125, 15013, 'vi', 'Bản nháp về workshop kỹ năng số cho sinh viên', 'ban-nhap-ve-workshop-ky-nang-so-cho-sinh-vien', 'Bài viết đang chờ xác nhận danh sách diễn giả và kết quả khảo sát nhu cầu người học.', 'Bản nháp về workshop kỹ năng số cho sinh viên', 'Bài viết đang chờ xác nhận danh sách diễn giả và kết quả khảo sát nhu cầu người học.', '2026-08-16 08:05:00', NULL),
  (15126, 15013, 'en', 'Draft on a digital-skills workshop for students', 'draft-on-a-digital-skills-workshop-for-students', 'The article is awaiting speaker confirmation and findings from the student-needs survey.', 'Draft on a digital-skills workshop for students', 'The article is awaiting speaker confirmation and findings from the student-needs survey.', '2026-08-16 08:05:00', NULL),
  (15127, 15014, 'vi', 'Đề xuất tin về hợp tác cộng đồng chưa đúng phạm vi', 'e-xuat-tin-ve-hop-tac-cong-ong-chua-ung-pham-vi', 'Ban biên tập yêu cầu thu hẹp nội dung về đúng hoạt động đã được hai bên xác nhận.', 'Đề xuất tin về hợp tác cộng đồng chưa đúng phạm vi', 'Ban biên tập yêu cầu thu hẹp nội dung về đúng hoạt động đã được hai bên xác nhận.', '2026-08-16 08:05:00', NULL),
  (15128, 15014, 'en', 'Community-partnership article does not yet match the agreed scope', 'community-partnership-article-does-not-yet-match-the-agreed-scope', 'Editors asked for the story to be narrowed to activities formally confirmed by both parties.', 'Community-partnership article does not yet match the agreed scope', 'Editors asked for the story to be narrowed to activities formally confirmed by both parties.', '2026-08-16 08:05:00', NULL),
  (15129, 15015, 'vi', 'Đoàn quốc tế tìm hiểu hệ sinh thái đổi mới sáng tạo tại FPTU', 'oan-quoc-te-tim-hieu-he-sinh-thai-oi-moi-sang-tao-tai-fptu', 'Đoàn tham quan không gian maker, gặp nhóm dự án sinh viên và trao đổi với cố vấn doanh nghiệp.', 'Đoàn quốc tế tìm hiểu hệ sinh thái đổi mới sáng tạo tại FPTU', 'Đoàn tham quan không gian maker, gặp nhóm dự án sinh viên và trao đổi với cố vấn doanh nghiệp.', '2026-08-16 08:05:00', NULL),
  (15130, 15015, 'en', 'International delegation explores FPTU''s innovation ecosystem', 'international-delegation-explores-fptu-s-innovation-ecosystem', 'The delegation visited maker spaces, met student project teams and spoke with industry mentors.', 'International delegation explores FPTU''s innovation ecosystem', 'The delegation visited maker spaces, met student project teams and spoke with industry mentors.', '2026-08-16 08:05:00', NULL),
  (15131, 15016, 'vi', 'Ẩn bản tin nội bộ sau khi hoàn tất giai đoạn thử nghiệm', 'an-ban-tin-noi-bo-sau-khi-hoan-tat-giai-oan-thu-nghiem', 'Bài viết được ẩn khỏi trang công khai nhưng vẫn lưu để phục vụ báo cáo và đối chiếu lịch sử.', 'Ẩn bản tin nội bộ sau khi hoàn tất giai đoạn thử nghiệm', 'Bài viết được ẩn khỏi trang công khai nhưng vẫn lưu để phục vụ báo cáo và đối chiếu lịch sử.', '2026-08-16 08:05:00', NULL),
  (15132, 15016, 'en', 'Internal story archived after the pilot phase', 'internal-story-archived-after-the-pilot-phase', 'The story was removed from the public page but retained for reporting and historical reference.', 'Internal story archived after the pilot phase', 'The story was removed from the public page but retained for reporting and historical reference.', '2026-08-16 08:05:00', NULL);

INSERT INTO news_content_sections (section_id, news_translation_id, section_order, section_title, section_body_html, section_body_text, created_at, updated_at) VALUES
  (15201, 15101, 1, 'Bối cảnh và mục tiêu', '<p>Bài viết đang tổng hợp các nội dung về công nhận tín chỉ, hỗ trợ sinh viên và lịch triển khai dự kiến. Đại diện hai bên đã thống nhất phạm vi trao đổi trước khi chương trình diễn ra.</p>', 'Bài viết đang tổng hợp các nội dung về công nhận tín chỉ, hỗ trợ sinh viên và lịch triển khai dự kiến. Đại diện hai bên đã thống nhất phạm vi trao đổi trước khi chương trình diễn ra.', '2026-08-16 08:10:00', NULL),
  (15202, 15101, 2, 'Kết quả và bước tiếp theo', '<p>Các nội dung cần tiếp tục được giao cho đầu mối phụ trách, kèm thời hạn cập nhật và tài liệu đối chiếu sau chuyến thăm.</p>', 'Các nội dung cần tiếp tục được giao cho đầu mối phụ trách, kèm thời hạn cập nhật và tài liệu đối chiếu sau chuyến thăm.', '2026-08-16 08:10:00', NULL),
  (15203, 15102, 1, 'Context and objectives', '<p>The article is consolidating details on credit recognition, student support and the proposed implementation timeline. Representatives from both sides agreed on the discussion scope before the programme.</p>', 'The article is consolidating details on credit recognition, student support and the proposed implementation timeline. Representatives from both sides agreed on the discussion scope before the programme.', '2026-08-16 08:10:00', NULL),
