INSERT INTO sent_emails (sent_email_id, email_template_id, related_type, related_id, subject, body_snapshot, provider_thread_id, provider_message_id, retry_count, last_attempt_at, delivered_at, status, error_message, sent_by, sent_at, created_at) VALUES
  (18001, 1, 'VISIT_REQUEST', 3001, 'PEMS đã tiếp nhận yêu cầu tham quan VR-2026-3001', '<p>Yêu cầu tham quan của SeoulTech Global Engagement Center đã được ghi nhận. Email xác nhận đang chờ gửi; tiến độ từng campus có thể theo dõi trực tiếp trong PEMS.</p>', NULL, NULL, 0, NULL, NULL, 'QUEUED', NULL, 4, NULL, '2026-08-19 08:00:00'),
  (18002, 1, 'VISIT_REQUEST', 3002, 'Thông tin yêu cầu tham quan VR-2026-3002 đã được gửi', '<p>Thông tin yêu cầu tham quan đã được gửi tới người đăng ký và các đầu mối liên quan. Kết quả xử lý tại mỗi campus được cập nhật độc lập trên PEMS.</p>', 'conversation-091ad7dc-d69f-571b-a41f-f308706a027c', 'resend-191a7ffd-edbf-5959-89a2-97bd047b5df7', 0, '2026-08-19 08:10:00', '2026-08-19 08:20:00', 'SENT', NULL, 4, '2026-08-19 08:05:00', '2026-08-19 08:00:00'),
  (18003, 1, 'VISIT_REQUEST', 3003, 'Chưa gửi được email xác nhận cho yêu cầu VR-2026-3003', '<p>Yêu cầu đã được lưu thành công nhưng nhà cung cấp email chưa phản hồi. PEMS sẽ tiếp tục thử lại; trạng thái nghiệp vụ của yêu cầu không bị thay đổi.</p>', NULL, NULL, 3, '2026-08-19 08:10:00', NULL, 'FAILED', 'Nhà cung cấp email không phản hồi sau ba lần thử; bản ghi được giữ để hệ thống tiếp tục xử lý.', 4, NULL, '2026-08-19 08:00:00');

INSERT INTO sent_email_recipients (sent_email_recipient_id, sent_email_id, recipient_email, recipient_name, recipient_type, delivery_status, provider_message_id, error_message, sent_at, delivered_at, created_at) VALUES
  (18101, 18001, 'kim.minjae@seoultech.example', 'Kim Min Jae', 'TO', 'QUEUED', NULL, NULL, NULL, NULL, '2026-08-19 08:00:00'),
