INSERT INTO notifications (notification_id, recipient_user_id, title, message, notification_type, related_type, related_id, is_read, read_at, created_at) VALUES
  (19001, 2, 'Cập nhật tiến độ đơn liên cơ sở', 'Dashboard tổng hợp đã có thay đổi mới. Head Office theo dõi kết quả nhưng không thay Staff Leader quyết định tại campus.', 'VISIT_MONITORING_UPDATE', 'VISIT_REQUEST', 3042, FALSE, NULL, '2026-08-20 08:00:00'),
  (19002, 3, 'Có yêu cầu cần xử lý tại campus', 'Đầu mối đoàn khách đã hoàn tất xác nhận. Vui lòng xem chi tiết campus, quyết định duyệt hoặc từ chối và chọn người phụ trách tiếp đón.', 'VISIT_WAITING_STAFF_LEADER_APPROVAL', 'VISIT_REQUEST', 3043, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00'),
  (19003, 4, 'Bạn được phân công phụ trách tiếp đón', 'Một campus đã được giao cho bạn. Hãy kiểm tra lịch trình và bấm Bắt đầu chuẩn bị trước khi cập nhật agenda hoặc hậu cần.', 'HOST_ASSIGNMENT', 'VISIT_REQUEST', 3044, FALSE, NULL, '2026-08-20 08:00:00'),
  (19004, 5, 'Có yêu cầu phối hợp từ Host', 'Host đã gửi yêu cầu hỗ trợ chuyên môn hoặc hậu cần. Vui lòng phân công người xử lý trong đơn vị.', 'DEPARTMENT_TASK', 'VISIT_REQUEST', 3045, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00'),
  (19005, 6, 'Bạn được giao nhiệm vụ hỗ trợ đoàn', 'Nhiệm vụ mới đã được phân công. Hãy kiểm tra thời hạn, phản hồi khả năng tiếp nhận và cập nhật tiến độ.', 'DEPARTMENT_ASSIGNMENT', 'VISIT_REQUEST', 3046, FALSE, NULL, '2026-08-20 08:00:00'),
  (19006, 7, 'Lời mời hỗ trợ chương trình tiếp khách', 'Bạn được mời hỗ trợ một hoạt động tại campus. Vui lòng xem lịch và phản hồi tham gia trước thời hạn.', 'STUDENT_INVITATION', 'VISIT_REQUEST', 3047, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00'),
  (19007, 8, 'Yêu cầu tham quan có cập nhật mới', 'Trạng thái xử lý tại một campus đã thay đổi. Bạn có thể mở chi tiết để theo dõi từng campus trong đơn.', 'VISIT_MONITORING_UPDATE', 'VISIT_REQUEST', 3048, FALSE, NULL, '2026-08-20 08:00:00'),
  (19008, 101, 'Bạn được phân công phụ trách tiếp đón', 'Một campus đã được giao cho bạn. Hãy kiểm tra lịch trình và bấm Bắt đầu chuẩn bị trước khi cập nhật agenda hoặc hậu cần.', 'HOST_ASSIGNMENT', 'VISIT_REQUEST', 3049, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00'),
  (19009, 121, 'Có yêu cầu phối hợp từ Host', 'Host đã gửi yêu cầu hỗ trợ chuyên môn hoặc hậu cần. Vui lòng phân công người xử lý trong đơn vị.', 'DEPARTMENT_TASK', 'VISIT_REQUEST', 3050, FALSE, NULL, '2026-08-20 08:00:00'),
  (19010, 151, 'Lời mời hỗ trợ chương trình tiếp khách', 'Bạn được mời hỗ trợ một hoạt động tại campus. Vui lòng xem lịch và phản hồi tham gia trước thời hạn.', 'STUDENT_INVITATION', 'VISIT_REQUEST', 3051, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00'),
  (19011, 201, 'Yêu cầu tham quan có cập nhật mới', 'Trạng thái xử lý tại một campus đã thay đổi. Bạn có thể mở chi tiết để theo dõi từng campus trong đơn.', 'VISIT_MONITORING_UPDATE', 'VISIT_REQUEST', 3052, FALSE, NULL, '2026-08-20 08:00:00'),
  (19012, 213, 'Yêu cầu tham quan có cập nhật mới', 'Trạng thái xử lý tại một campus đã thay đổi. Bạn có thể mở chi tiết để theo dõi từng campus trong đơn.', 'VISIT_MONITORING_UPDATE', 'VISIT_REQUEST', 3053, TRUE, '2026-08-20 09:00:00', '2026-08-20 08:00:00');

INSERT INTO calendar_events (calendar_event_id, owner_user_id, campus_id, visit_instance_id, logistics_item_id, source_type, title, description, location, start_at, end_at, timezone, is_all_day, recurrence_rule, visibility, status, created_at, created_by, updated_at, updated_by, deleted_at, deleted_by) VALUES
  (20001, 4, 1, NULL, NULL, 'PERSONAL', 'Rà soát tài liệu trước buổi đón đoàn', 'Kiểm tra danh sách khách, tài liệu giới thiệu và các đầu việc cá nhân trước chương trình.', 'Phòng Hợp tác Quốc tế', '2026-08-21 09:00:00', '2026-08-21 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, 'RRULE:FREQ=WEEKLY;COUNT=3', 'PRIVATE', 'ACTIVE', '2026-08-20 08:00:00', 4, NULL, NULL, NULL, NULL),
  (20002, 101, 1, 5004, NULL, 'VISIT', 'Đón đoàn và xác nhận chương trình', 'Host gặp trưởng đoàn tại sảnh, xác nhận danh sách khách và thời gian các phiên làm việc.', 'Sảnh Alpha', '2026-08-22 09:00:00', '2026-08-22 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'CANCELLED', '2026-08-20 08:00:00', 101, NULL, NULL, '2026-08-21 11:00:00', 101),
  (20003, 4, 1, NULL, 9003, 'LOGISTICS', 'Kiểm tra phòng và thiết bị', 'Đội hỗ trợ chạy thử màn hình, micro và kết nối trình chiếu trước giờ đón đoàn.', 'Phòng họp Alpha', '2026-08-23 09:00:00', '2026-08-23 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'PRIVATE', 'DONE', '2026-08-20 08:00:00', 4, NULL, NULL, NULL, NULL),
  (20004, 101, 1, 5006, NULL, 'DEADLINE', 'Hạn xác nhận danh sách khách', 'Đầu mối đoàn khách cần hoàn tất danh sách trước thời điểm chốt thẻ ra vào campus.', 'PEMS', '2026-08-24 09:00:00', '2026-08-24 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'ACTIVE', '2026-08-20 08:00:00', 101, NULL, NULL, NULL, NULL),
  (20005, 4, 1, NULL, NULL, 'PERSONAL', 'Chuẩn bị nội dung trao đổi với đối tác', 'Tổng hợp câu hỏi, tài liệu tham khảo và các điểm cần xác nhận trong phiên làm việc.', 'Phòng làm việc cá nhân', '2026-08-25 09:00:00', '2026-08-25 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, 'RRULE:FREQ=WEEKLY;COUNT=3', 'PRIVATE', 'CANCELLED', '2026-08-20 08:00:00', 4, NULL, NULL, '2026-08-21 11:00:00', 4),
  (20006, 103, 2, 5012, NULL, 'VISIT', 'Phiên trao đổi học thuật với đối tác', 'Giảng viên và đại diện đoàn thảo luận nội dung chuyên môn theo agenda đã duyệt.', 'Phòng seminar', '2026-08-21 09:00:00', '2026-08-21 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'DONE', '2026-08-20 08:00:00', 103, NULL, NULL, NULL, NULL),
  (20007, 10, 2, NULL, 9007, 'LOGISTICS', 'Xác nhận phương án xe đón đoàn', 'Host đối chiếu giờ đón, điểm tập trung và số điện thoại lái xe với đầu mối khách.', 'Khu vực lễ tân', '2026-08-22 09:00:00', '2026-08-22 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'PRIVATE', 'ACTIVE', '2026-08-20 08:00:00', 10, NULL, NULL, NULL, NULL),
  (20008, 103, 2, 5014, NULL, 'DEADLINE', 'Hạn phản hồi lời mời tham gia', 'Người được mời cần xác nhận tham gia để Host hoàn thiện thành phần chương trình.', 'PEMS', '2026-08-23 09:00:00', '2026-08-23 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'CANCELLED', '2026-08-20 08:00:00', 103, NULL, NULL, '2026-08-21 11:00:00', 103),
  (20009, 10, 2, NULL, NULL, 'PERSONAL', 'Họp nhanh với nhóm hỗ trợ', 'Thống nhất vai trò, kênh liên lạc và phương án xử lý tình huống trong ngày tiếp khách.', 'Phòng họp nội bộ', '2026-08-24 09:00:00', '2026-08-24 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, 'RRULE:FREQ=WEEKLY;COUNT=3', 'PRIVATE', 'DONE', '2026-08-20 08:00:00', 10, NULL, NULL, NULL, NULL),
  (20010, 103, 2, 5016, NULL, 'VISIT', 'Tổng kết chuyến thăm', 'Hai bên xác nhận kết quả chính, đầu việc follow-up và thông tin liên hệ sau chương trình.', 'Phòng họp Alpha', '2026-08-25 09:00:00', '2026-08-25 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'ACTIVE', '2026-08-20 08:00:00', 103, NULL, NULL, NULL, NULL),
  (20011, 12, 3, NULL, 9011, 'LOGISTICS', 'Bàn giao hạng mục hậu cần', 'Nhân sự phụ trách cập nhật kết quả và bàn giao hạng mục cho Host kiểm tra.', 'Kho thiết bị sự kiện', '2026-08-21 09:00:00', '2026-08-21 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'PRIVATE', 'CANCELLED', '2026-08-20 08:00:00', 12, NULL, NULL, '2026-08-21 11:00:00', 12),
  (20012, 105, 3, 5022, NULL, 'DEADLINE', 'Hạn hoàn tất chuẩn bị campus', 'Host kiểm tra agenda, người tham gia và hậu cần trước khi chương trình bắt đầu.', 'PEMS', '2026-08-22 09:00:00', '2026-08-22 10:00:00', 'Asia/Ho_Chi_Minh', FALSE, NULL, 'INTERNAL', 'DONE', '2026-08-20 08:00:00', 105, NULL, NULL, NULL, NULL);

