INSERT INTO faqs (faq_id, faq_type, question, answer, display_order, status, created_at, created_by, updated_at, updated_by) VALUES
  (16033, 'DELEGATION_MANAGEMENT', 'Làm sao theo dõi trạng thái xử lý một đoàn tiếp khách?', 'Người dùng vào màn quản lý đoàn, lọc theo trạng thái và campus trong phạm vi được phân quyền. Hệ thống chỉ hiển thị đoàn thuộc scope của người dùng.', 33, 'PUBLISHED', '2026-08-17 09:00:00', 2, NULL, NULL),
  (16034, 'DELEGATION_MANAGEMENT', 'Vì sao tôi không thấy một đoàn ở campus khác?', 'PEMS giới hạn dữ liệu theo role, sub-role, campus, department và quan hệ được phân công. Người dùng không thuộc scope sẽ không thấy đoàn đó.', 34, 'HIDDEN', '2026-08-17 09:05:00', 2, NULL, NULL),
  (16035, 'DOCUMENT_MEDIA', 'Tôi có thể tải tài liệu hoặc ảnh chuyến thăm ở đâu?', 'Tài liệu, ảnh và gallery liên quan đến chuyến thăm được truy cập tại màn chi tiết đoàn hoặc module Document/Gallery nếu người dùng có quyền trong phạm vi phù hợp.', 35, 'PUBLISHED', '2026-08-17 09:10:00', 2, NULL, NULL),
  (16036, 'DOCUMENT_MEDIA', 'Vì sao một số ảnh hoặc tài liệu không hiển thị công khai?', 'Một số file chỉ có visibility nội bộ hoặc riêng tư. Hệ thống không hiển thị công khai nếu file chưa được duyệt hoặc không thuộc phạm vi xem của người dùng.', 36, 'HIDDEN', '2026-08-17 09:15:00', 2, NULL, NULL),
  (16037, 'NOTIFICATION_EMAIL', 'Tôi cần làm gì khi nhận email xác nhận từ PEMS?', 'Người nhận bấm nút Xác nhận, Từ chối hoặc Thương lượng trong email. Hệ thống ghi nhận phản hồi qua token một lần và không yêu cầu đăng nhập cho hành động email được cấp token.', 37, 'PUBLISHED', '2026-08-17 09:20:00', 2, NULL, NULL),
  (16038, 'NOTIFICATION_EMAIL', 'Nếu bấm lại nút trong email cũ thì chuyện gì xảy ra?', 'Nếu phản hồi đã được ghi nhận, hệ thống không cập nhật lần hai và hiển thị thông báo rằng bạn đã trả lời yêu cầu này rồi.', 38, 'PUBLISHED', '2026-08-17 09:25:00', 2, NULL, NULL);

