-- 3) Seed multilingual titles/summaries. vi is primary; en/ja/ko/zh-CN cover language switch and translation cases.
INSERT INTO news_translations (news_translation_id, news_id, language_code, title, slug, summary, seo_title, seo_description, created_at, updated_at) VALUES
  (171001, 17001, 'vi', 'SeoulTech và FPTU Hà Nội mở rộng trao đổi sinh viên về AI ứng dụng', 'seoultech-fptu-ha-noi-mo-rong-trao-doi-sinh-vien-ai-ung-dung', 'Chuyến thăm của SeoulTech tại FPTU Hà Nội tập trung vào mô hình lớp học AI ứng dụng, hoạt động student buddy và kế hoạch trao đổi sinh viên trong học kỳ tới.', 'SeoulTech và FPTU Hà Nội mở rộng trao đổi sinh viên về AI ứng dụng', 'Chuyến thăm của SeoulTech tại FPTU Hà Nội tập trung vào mô hình lớp học AI ứng dụng, hoạt động student buddy và kế hoạch trao đổi sinh viên trong học kỳ tới.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171002, 17001, 'en', 'SeoulTech and FPTU Hanoi expand applied AI student exchange discussions', 'seoultech-fptu-hanoi-expand-applied-ai-student-exchange', 'The SeoulTech visit to FPTU Hanoi focused on applied AI classrooms, student buddy support and a practical exchange roadmap for the next semester.', 'SeoulTech and FPTU Hanoi expand applied AI student exchange discussions', 'The SeoulTech visit to FPTU Hanoi focused on applied AI classrooms, student buddy support and a practical exchange roadmap for the next semester.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171003, 17001, 'ko', '서울과기대와 FPTU 하노이, 응용 AI 학생 교류 논의 확대', 'seoultech-fptu-hanoi-applied-ai-student-exchange-ko', '서울과기대 방문단은 FPTU 하노이의 응용 AI 수업, 학생 버디 활동, 단기 교류 가능성을 중점적으로 논의했다.', '서울과기대와 FPTU 하노이, 응용 AI 학생 교류 논의 확대', '서울과기대 방문단은 FPTU 하노이의 응용 AI 수업, 학생 버디 활동, 단기 교류 가능성을 중점적으로 논의했다.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171004, 17002, 'vi', 'FPTU TP.HCM giới thiệu mô hình campus xanh với đối tác Nordic Green', 'fptu-hcm-gioi-thieu-mo-hinh-campus-xanh-nordic-green', 'Buổi làm việc tại FPTU TP.HCM tập trung vào vận hành campus xanh, logistics sự kiện và khả năng xây dựng workshop về phát triển bền vững cho sinh viên.', 'FPTU TP.HCM giới thiệu mô hình campus xanh với đối tác Nordic Green', 'Buổi làm việc tại FPTU TP.HCM tập trung vào vận hành campus xanh, logistics sự kiện và khả năng xây dựng workshop về phát triển bền vững cho sinh viên.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171005, 17002, 'en', 'FPTU Ho Chi Minh City presents green campus operations to Nordic Green partners', 'fptu-hcm-green-campus-operations-nordic-green', 'The meeting in Ho Chi Minh City focused on sustainable campus operations, event logistics and a potential workshop for students.', 'FPTU Ho Chi Minh City presents green campus operations to Nordic Green partners', 'The meeting in Ho Chi Minh City focused on sustainable campus operations, event logistics and a potential workshop for students.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171006, 17003, 'vi', 'Workshop robotics tại FPTU Đà Nẵng kết nối lớp học và phòng lab', 'workshop-robotics-fptu-da-nang-ket-noi-lop-hoc-va-phong-lab', 'Đoàn Osaka Design Institute tham gia workshop robotics, trao đổi về mô hình học qua nguyên mẫu và quan sát cách sinh viên trình bày sản phẩm trong phòng lab.', 'Workshop robotics tại FPTU Đà Nẵng kết nối lớp học và phòng lab', 'Đoàn Osaka Design Institute tham gia workshop robotics, trao đổi về mô hình học qua nguyên mẫu và quan sát cách sinh viên trình bày sản phẩm trong phòng lab.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171007, 17003, 'en', 'Robotics workshop at FPTU Da Nang connects classrooms and laboratories', 'robotics-workshop-fptu-da-nang-classroom-lab', 'Osaka Design Institute joined a robotics workshop to observe prototype-based learning and student demonstrations in the lab.', 'Robotics workshop at FPTU Da Nang connects classrooms and laboratories', 'Osaka Design Institute joined a robotics workshop to observe prototype-based learning and student demonstrations in the lab.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171008, 17003, 'ja', 'FPTUダナンのロボティクス・ワークショップ、授業とラボをつなぐ', 'fptu-da-nang-robotics-workshop-ja', '大阪デザイン学院の訪問団は、ロボティクスの試作型学習と学生によるデモ発表を見学した。', 'FPTUダナンのロボティクス・ワークショップ、授業とラボをつなぐ', '大阪デザイン学院の訪問団は、ロボティクスの試作型学習と学生によるデモ発表を見学した。', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171009, 17004, 'vi', 'FPTU Cần Thơ trao đổi về nông nghiệp số cùng đối tác Mekong Innovation', 'fptu-can-tho-trao-doi-nong-nghiep-so-mekong-innovation', 'Chương trình tại FPTU Cần Thơ mở ra hướng hợp tác về nông nghiệp số, dữ liệu cộng đồng và trải nghiệm học tập gắn với bối cảnh Đồng bằng sông Cửu Long.', 'FPTU Cần Thơ trao đổi về nông nghiệp số cùng đối tác Mekong Innovation', 'Chương trình tại FPTU Cần Thơ mở ra hướng hợp tác về nông nghiệp số, dữ liệu cộng đồng và trải nghiệm học tập gắn với bối cảnh Đồng bằng sông Cửu Long.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171010, 17004, 'en', 'FPTU Can Tho discusses digital agriculture with Mekong Innovation partners', 'fptu-can-tho-digital-agriculture-mekong-innovation', 'The Can Tho meeting explored digital agriculture, community data and learning experiences connected with the Mekong Delta context.', 'FPTU Can Tho discusses digital agriculture with Mekong Innovation partners', 'The Can Tho meeting explored digital agriculture, community data and learning experiences connected with the Mekong Delta context.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171011, 17005, 'vi', 'FPTU Quy Nhơn giới thiệu trải nghiệm hospitality cho đoàn đối tác quốc tế', 'fptu-quy-nhon-gioi-thieu-trai-nghiem-hospitality-doi-tac-quoc-te', 'Đoàn đối tác tìm hiểu mô hình đón tiếp, trải nghiệm không gian ven biển và cách sinh viên tham gia hỗ trợ hoạt động hospitality tại FPTU Quy Nhơn.', 'FPTU Quy Nhơn giới thiệu trải nghiệm hospitality cho đoàn đối tác quốc tế', 'Đoàn đối tác tìm hiểu mô hình đón tiếp, trải nghiệm không gian ven biển và cách sinh viên tham gia hỗ trợ hoạt động hospitality tại FPTU Quy Nhơn.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171012, 17005, 'en', 'FPTU Quy Nhon presents hospitality experience for international partners', 'fptu-quy-nhon-hospitality-experience-international-partners', 'The partner delegation explored visitor reception, coastal learning spaces and student-supported hospitality activities at FPTU Quy Nhon.', 'FPTU Quy Nhon presents hospitality experience for international partners', 'The partner delegation explored visitor reception, coastal learning spaces and student-supported hospitality activities at FPTU Quy Nhon.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171013, 17006, 'vi', 'Hậu trường student buddy trong chuyến thăm học thuật tại Hà Nội', 'hau-truong-student-buddy-chuyen-tham-hoc-thuat-ha-noi', 'Bản chờ duyệt ghi lại quy trình chuẩn bị của nhóm student buddy: phân vai, kiểm tra tuyến tham quan, chuẩn bị nội dung giới thiệu và ghi nhận phản hồi sau sự kiện.', 'Hậu trường student buddy trong chuyến thăm học thuật tại Hà Nội', 'Bản chờ duyệt ghi lại quy trình chuẩn bị của nhóm student buddy: phân vai, kiểm tra tuyến tham quan, chuẩn bị nội dung giới thiệu và ghi nhận phản hồi sau sự kiện.', '2026-08-21 09:00:00', NULL),
  (171014, 17007, 'vi', 'Bản nháp hội thảo fintech cần chỉnh sửa trước khi công bố', 'ban-nhap-hoi-thao-fintech-can-chinh-sua-truoc-khi-cong-bo', 'Bài viết bị từ chối vì còn thông tin ngân sách nội bộ và một số tên cá nhân chưa được xác nhận quyền công bố hình ảnh.', 'Bản nháp hội thảo fintech cần chỉnh sửa trước khi công bố', 'Bài viết bị từ chối vì còn thông tin ngân sách nội bộ và một số tên cá nhân chưa được xác nhận quyền công bố hình ảnh.', '2026-08-15 08:30:00', '2026-08-15 10:00:00'),
  (171015, 17008, 'vi', 'Bộ ảnh lab tour Đà Nẵng tạm ẩn để xác nhận quyền sử dụng hình ảnh', 'bo-anh-lab-tour-da-nang-tam-an-xac-nhan-quyen-hinh-anh', 'Bản tin ghi lại tour phòng lab tại Đà Nẵng nhưng hiện tạm ẩn khỏi public để hoàn tất xác nhận media consent với đối tác.', 'Bộ ảnh lab tour Đà Nẵng tạm ẩn để xác nhận quyền sử dụng hình ảnh', 'Bản tin ghi lại tour phòng lab tại Đà Nẵng nhưng hiện tạm ẩn khỏi public để hoàn tất xác nhận media consent với đối tác.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171016, 17008, 'en', 'Da Nang lab tour photo story hidden while media consent is verified', 'da-nang-lab-tour-hidden-media-consent-verification', 'The Da Nang lab tour story is temporarily hidden from public view while image usage consent is confirmed with the partner.', 'Da Nang lab tour photo story hidden while media consent is verified', 'The Da Nang lab tour story is temporarily hidden from public view while image usage consent is confirmed with the partner.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171017, 17009, 'vi', 'PEMS cải tiến quy trình xuất bản tin tức sau mỗi chuyến tiếp khách', 'pems-cai-tien-quy-trinh-xuat-ban-tin-tuc-sau-moi-chuyen-tiep-khach', 'Hệ thống PEMS bổ sung quy trình quản lý tin tức với upload ảnh qua Drive, bản dịch đa ngôn ngữ và kiểm soát trạng thái public rõ ràng.', 'PEMS cải tiến quy trình xuất bản tin tức sau mỗi chuyến tiếp khách', 'Hệ thống PEMS bổ sung quy trình quản lý tin tức với upload ảnh qua Drive, bản dịch đa ngôn ngữ và kiểm soát trạng thái public rõ ràng.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171018, 17009, 'en', 'PEMS improves news publishing workflow after delegation visits', 'pems-improves-news-publishing-workflow-after-visit', 'PEMS now supports Drive-based image upload, multilingual article copies and clear public visibility control for news after visits.', 'PEMS improves news publishing workflow after delegation visits', 'PEMS now supports Drive-based image upload, multilingual article copies and clear public visibility control for news after visits.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171019, 17009, 'zh-CN', 'PEMS优化接待后新闻发布流程', 'pems-news-publishing-workflow-zh-cn', 'PEMS支持通过Drive上传图片、多语言文章副本以及清晰的公开可见性控制。', 'PEMS优化接待后新闻发布流程', 'PEMS支持通过Drive上传图片、多语言文章副本以及清晰的公开可见性控制。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171020, 17010, 'vi', 'Bản nháp song ngữ về chương trình kết nối mentor doanh nghiệp', 'ban-nhap-song-ngu-ket-noi-mentor-doanh-nghiep', 'Bài đang chờ duyệt mô tả cách FPTU TP.HCM kết nối mentor doanh nghiệp với sinh viên trong hoạt động hậu sự kiện.', 'Bản nháp song ngữ về chương trình kết nối mentor doanh nghiệp', 'Bài đang chờ duyệt mô tả cách FPTU TP.HCM kết nối mentor doanh nghiệp với sinh viên trong hoạt động hậu sự kiện.', '2026-08-11 10:10:00', NULL),
  (171021, 17010, 'en', 'Bilingual draft on the industry mentor connection program', 'bilingual-draft-industry-mentor-connection-program', 'This pending article describes how FPTU Ho Chi Minh City connects industry mentors with students after partner visits.', 'Bilingual draft on the industry mentor connection program', 'This pending article describes how FPTU Ho Chi Minh City connects industry mentors with students after partner visits.', '2026-08-11 10:10:00', NULL),
  (171022, 17011, 'vi', 'FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng', 'fptu-ha-noi-porto-ai-hub-thong-nhat-chuoi-seminar-ai-ung-dung', 'Chuỗi seminar AI ứng dụng dự kiến giúp sinh viên tiếp cận case study từ đối tác quốc tế, kết hợp thảo luận học thuật và bài tập thực hành.', 'FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng', 'Chuỗi seminar AI ứng dụng dự kiến giúp sinh viên tiếp cận case study từ đối tác quốc tế, kết hợp thảo luận học thuật và bài tập thực hành.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171023, 17011, 'en', 'FPTU Hanoi and Porto AI Hub agree on applied AI seminar series', 'fptu-hanoi-porto-ai-hub-applied-ai-seminar-series', 'The applied AI seminar series will expose students to international case studies, academic discussion and practical exercises.', 'FPTU Hanoi and Porto AI Hub agree on applied AI seminar series', 'The applied AI seminar series will expose students to international case studies, academic discussion and practical exercises.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171024, 17011, 'ko', 'FPTU 하노이와 Porto AI Hub, 응용 AI 세미나 시리즈 합의', 'fptu-hanoi-porto-ai-hub-applied-ai-seminar-ko', '응용 AI 세미나 시리즈는 학생들에게 국제 사례, 학술 토론, 실습 과제를 제공할 예정이다.', 'FPTU 하노이와 Porto AI Hub, 응용 AI 세미나 시리즈 합의', '응용 AI 세미나 시리즈는 학생들에게 국제 사례, 학술 토론, 실습 과제를 제공할 예정이다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171025, 17012, 'vi', 'Bài follow-up cần bổ sung nguồn trước khi đăng public', 'bai-follow-up-can-bo-sung-nguon-truoc-khi-dang-public', 'Bản tin follow-up sau buổi làm việc tại Cần Thơ chưa được duyệt vì cần bổ sung nguồn cho số liệu phản hồi và điều chỉnh giọng văn.', 'Bài follow-up cần bổ sung nguồn trước khi đăng public', 'Bản tin follow-up sau buổi làm việc tại Cần Thơ chưa được duyệt vì cần bổ sung nguồn cho số liệu phản hồi và điều chỉnh giọng văn.', '2026-08-09 09:20:00', '2026-08-09 11:00:00');

-- 4) Seed long-form rich-text sections. No base64/data:image is used.
INSERT INTO news_content_sections (section_id, news_translation_id, section_order, section_title, section_body_html, section_body_text, created_at, updated_at) VALUES
  (171001, 171001, 1, 'Bối cảnh chuyến thăm', '<p>Đoàn SeoulTech Global Engagement Center đã làm việc với đại diện FPTU Hà Nội trong khuôn khổ chương trình khảo sát mô hình đào tạo công nghệ tại Việt Nam. Nội dung trọng tâm là cách nhà trường kết hợp <strong>AI ứng dụng</strong>, học theo dự án và trải nghiệm doanh nghiệp trong chương trình đào tạo.</p><p>Hai bên dành thời gian trao đổi về khả năng thiết kế một học kỳ ngắn hạn cho sinh viên quốc tế, trong đó sinh viên được tham gia lớp chuyên đề, tham quan phòng lab và làm việc cùng nhóm sinh viên FPTU.</p>', 'Đoàn SeoulTech Global Engagement Center đã làm việc với đại diện FPTU Hà Nội trong khuôn khổ chương trình khảo sát mô hình đào tạo công nghệ tại Việt Nam. Nội dung trọng tâm là cách nhà trường kết hợp AI ứng dụng , học theo dự án và trải nghiệm doanh nghiệp trong chương trình đào tạo. Hai bên dành thời gian trao đổi về khả năng thiết kế một học kỳ ngắn hạn cho sinh viên quốc tế, trong đó sinh viên được tham gia lớp chuyên đề, tham quan phòng lab và làm việc cùng nhóm sinh viên FPTU.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171002, 171001, 2, 'Những điểm thống nhất chính', '<p>Cuộc họp ghi nhận ba nhóm nội dung có thể triển khai trước: trao đổi sinh viên ngắn hạn, seminar trực tuyến về AI trong giáo dục và hoạt động mentor giữa sinh viên hai trường. Đại diện hai bên thống nhất cần xây dựng lịch trình có mục tiêu học thuật rõ ràng thay vì chỉ dừng ở hoạt động tham quan.</p><ul><li>FPTU Hà Nội đề xuất mô hình 5 ngày kết hợp lab tour, workshop và thảo luận dự án.</li><li>SeoulTech quan tâm tới hoạt động sinh viên hỗ trợ sinh viên, đặc biệt là quy trình student buddy.</li><li>Hai bên sẽ trao đổi đề cương học phần thử nghiệm trước cuối tháng 9.</li></ul>', 'Cuộc họp ghi nhận ba nhóm nội dung có thể triển khai trước: trao đổi sinh viên ngắn hạn, seminar trực tuyến về AI trong giáo dục và hoạt động mentor giữa sinh viên hai trường. Đại diện hai bên thống nhất cần xây dựng lịch trình có mục tiêu học thuật rõ ràng thay vì chỉ dừng ở hoạt động tham quan. FPTU Hà Nội đề xuất mô hình 5 ngày kết hợp lab tour, workshop và thảo luận dự án. SeoulTech quan tâm tới hoạt động sinh viên hỗ trợ sinh viên, đặc biệt là quy trình student buddy. Hai bên sẽ trao đổi đề cương học phần thử nghiệm trước cuối tháng 9.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171003, 171001, 3, 'Vai trò của sinh viên hỗ trợ', '<p>Nhóm student buddy hỗ trợ check-in, điều phối di chuyển trong campus và giới thiệu các không gian học tập. Hoạt động này giúp đoàn khách có góc nhìn thực tế hơn về đời sống sinh viên, đồng thời tạo cơ hội cho sinh viên FPTU rèn luyện kỹ năng giao tiếp quốc tế.</p><blockquote>Điểm đáng chú ý của buổi làm việc là sự tham gia chủ động của sinh viên, không chỉ với vai trò hỗ trợ hậu cần mà còn là người chia sẻ trải nghiệm học tập.</blockquote>', 'Nhóm student buddy hỗ trợ check-in, điều phối di chuyển trong campus và giới thiệu các không gian học tập. Hoạt động này giúp đoàn khách có góc nhìn thực tế hơn về đời sống sinh viên, đồng thời tạo cơ hội cho sinh viên FPTU rèn luyện kỹ năng giao tiếp quốc tế. Điểm đáng chú ý của buổi làm việc là sự tham gia chủ động của sinh viên, không chỉ với vai trò hỗ trợ hậu cần mà còn là người chia sẻ trải nghiệm học tập.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171004, 171001, 4, 'Bước tiếp theo', '<p>Sau chuyến thăm, hai bên sẽ hoàn thiện bản ghi nhớ nội dung trao đổi, thống nhất đầu mối học thuật và chuẩn bị tài liệu giới thiệu chương trình bằng tiếng Anh. Các nội dung có thể triển khai thử nghiệm sẽ được ưu tiên theo mức độ phù hợp với lịch học của sinh viên.</p>', 'Sau chuyến thăm, hai bên sẽ hoàn thiện bản ghi nhớ nội dung trao đổi, thống nhất đầu mối học thuật và chuẩn bị tài liệu giới thiệu chương trình bằng tiếng Anh. Các nội dung có thể triển khai thử nghiệm sẽ được ưu tiên theo mức độ phù hợp với lịch học của sinh viên.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171005, 171002, 1, 'Visit context', '<p>The SeoulTech Global Engagement Center delegation met with FPTU Hanoi to explore how technology education is delivered in Vietnam. The discussion focused on <strong>applied AI</strong>, project-based learning and industry-connected student experiences.</p><p>Both sides reviewed the possibility of a short-term international semester in which students attend thematic classes, visit laboratories and work with FPTU student teams.</p>', 'The SeoulTech Global Engagement Center delegation met with FPTU Hanoi to explore how technology education is delivered in Vietnam. The discussion focused on applied AI , project-based learning and industry-connected student experiences. Both sides reviewed the possibility of a short-term international semester in which students attend thematic classes, visit laboratories and work with FPTU student teams.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171006, 171002, 2, 'Key agreements', '<p>The meeting identified three practical tracks: short-term student exchange, online seminars on AI in education and peer mentoring between students. Both institutions agreed that the future program should have clear academic outcomes rather than being limited to campus tours.</p><ul><li>FPTU Hanoi proposed a five-day model combining lab tours, workshops and project discussions.</li><li>SeoulTech showed strong interest in the student buddy process.</li><li>A draft academic outline will be exchanged before the end of September.</li></ul>', 'The meeting identified three practical tracks: short-term student exchange, online seminars on AI in education and peer mentoring between students. Both institutions agreed that the future program should have clear academic outcomes rather than being limited to campus tours. FPTU Hanoi proposed a five-day model combining lab tours, workshops and project discussions. SeoulTech showed strong interest in the student buddy process. A draft academic outline will be exchanged before the end of September.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171007, 171002, 3, 'Student buddy contribution', '<p>Student buddies supported check-in, campus navigation and informal conversations about student life. Their participation gave the delegation a more practical view of the learning environment and helped FPTU students practice international communication.</p>', 'Student buddies supported check-in, campus navigation and informal conversations about student life. Their participation gave the delegation a more practical view of the learning environment and helped FPTU students practice international communication.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171008, 171002, 4, 'Next steps', '<p>The two sides will prepare a follow-up note, confirm academic contacts and finalize English materials for the pilot program. Activities that fit the academic calendar will be prioritized.</p>', 'The two sides will prepare a follow-up note, confirm academic contacts and finalize English materials for the pilot program. Activities that fit the academic calendar will be prioritized.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171009, 171003, 1, '방문 개요', '<p>서울과기대 글로벌 교류 담당자들은 FPTU 하노이를 방문해 베트남의 기술 교육 모델을 살펴보았다. 논의의 핵심은 <strong>응용 AI</strong>, 프로젝트 기반 학습, 산업 연계 경험이었다.</p>', '서울과기대 글로벌 교류 담당자들은 FPTU 하노이를 방문해 베트남의 기술 교육 모델을 살펴보았다. 논의의 핵심은 응용 AI , 프로젝트 기반 학습, 산업 연계 경험이었다.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171010, 171003, 2, '주요 논의 내용', '<p>양 기관은 단기 학생 교류, 온라인 세미나, 학생 간 멘토링을 우선 협력 과제로 검토했다. 프로그램은 단순한 캠퍼스 투어가 아니라 명확한 학습 성과를 가져야 한다는 점에 의견을 모았다.</p>', '양 기관은 단기 학생 교류, 온라인 세미나, 학생 간 멘토링을 우선 협력 과제로 검토했다. 프로그램은 단순한 캠퍼스 투어가 아니라 명확한 학습 성과를 가져야 한다는 점에 의견을 모았다.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171011, 171003, 3, '후속 계획', '<p>방문 이후 양측은 파일럿 프로그램의 일정, 담당자, 영어 자료를 정리해 다음 학기 교류 가능성을 검토할 예정이다.</p>', '방문 이후 양측은 파일럿 프로그램의 일정, 담당자, 영어 자료를 정리해 다음 학기 교류 가능성을 검토할 예정이다.', '2026-08-20 08:30:00', '2026-08-20 10:30:00'),
  (171012, 171004, 1, 'Campus xanh trong trải nghiệm tiếp khách', '<p>Đoàn Nordic Green Education Network tham quan các khu vực học tập mở, tuyến di chuyển nội khu và không gian sinh hoạt chung tại FPTU TP.HCM. Đội ngũ host giới thiệu cách nhà trường tổ chức hoạt động tiếp khách theo hướng <strong>thân thiện môi trường</strong>, giảm giấy tờ in ấn và tăng sử dụng tài liệu số.</p>', 'Đoàn Nordic Green Education Network tham quan các khu vực học tập mở, tuyến di chuyển nội khu và không gian sinh hoạt chung tại FPTU TP.HCM. Đội ngũ host giới thiệu cách nhà trường tổ chức hoạt động tiếp khách theo hướng thân thiện môi trường , giảm giấy tờ in ấn và tăng sử dụng tài liệu số.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171013, 171004, 2, 'Trao đổi về logistics bền vững', '<p>Hai bên thảo luận về cách thiết kế sự kiện học thuật có ít rác thải, tối ưu tuyến di chuyển và kiểm soát năng lượng trong các khu vực đón tiếp. Đại diện đối tác đánh giá cao việc hệ thống hóa yêu cầu hậu cần trong PEMS, giúp thông tin được chuyển từ host tới các bộ phận hỗ trợ nhanh hơn.</p><ol><li>Chuẩn hóa checklist trước sự kiện.</li><li>Ưu tiên vật dụng tái sử dụng.</li><li>Ghi nhận phản hồi sau chương trình để cải tiến.</li></ol>', 'Hai bên thảo luận về cách thiết kế sự kiện học thuật có ít rác thải, tối ưu tuyến di chuyển và kiểm soát năng lượng trong các khu vực đón tiếp. Đại diện đối tác đánh giá cao việc hệ thống hóa yêu cầu hậu cần trong PEMS, giúp thông tin được chuyển từ host tới các bộ phận hỗ trợ nhanh hơn. Chuẩn hóa checklist trước sự kiện. Ưu tiên vật dụng tái sử dụng. Ghi nhận phản hồi sau chương trình để cải tiến.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171014, 171004, 3, 'Khả năng triển khai workshop', '<p>Sau buổi làm việc, hai bên đề xuất một workshop ngắn về <em>green campus operations</em> cho sinh viên quan tâm tới quản trị bền vững. Nội dung dự kiến kết hợp case study quốc tế với bài toán vận hành thực tế tại campus.</p>', 'Sau buổi làm việc, hai bên đề xuất một workshop ngắn về green campus operations cho sinh viên quan tâm tới quản trị bền vững. Nội dung dự kiến kết hợp case study quốc tế với bài toán vận hành thực tế tại campus.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171015, 171005, 1, 'Green campus visitor experience', '<p>The Nordic Green Education Network delegation visited open learning spaces, internal walking routes and student community areas at FPTU Ho Chi Minh City. The host team explained how visitor programs can reduce printed materials and make better use of digital documents.</p>', 'The Nordic Green Education Network delegation visited open learning spaces, internal walking routes and student community areas at FPTU Ho Chi Minh City. The host team explained how visitor programs can reduce printed materials and make better use of digital documents.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171016, 171005, 2, 'Sustainable logistics discussion', '<p>Both sides discussed low-waste academic events, optimized visitor movement and energy awareness during reception activities. The partner noted that PEMS helps connect host requirements with supporting departments in a transparent way.</p>', 'Both sides discussed low-waste academic events, optimized visitor movement and energy awareness during reception activities. The partner noted that PEMS helps connect host requirements with supporting departments in a transparent way.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171017, 171005, 3, 'Workshop opportunity', '<p>A short workshop on <em>green campus operations</em> is being considered for students interested in sustainability management and campus services.</p>', 'A short workshop on green campus operations is being considered for students interested in sustainability management and campus services.', '2026-08-19 14:00:00', '2026-08-19 15:45:00'),
  (171018, 171006, 1, 'Từ lớp học đến nguyên mẫu', '<p>Workshop robotics được tổ chức tại khu lab của FPTU Đà Nẵng với sự tham gia của giảng viên, sinh viên và đại diện Osaka Design Institute. Điểm nhấn của chương trình là cách sinh viên chuyển yêu cầu thiết kế thành nguyên mẫu có thể trình diễn trong thời gian ngắn.</p>', 'Workshop robotics được tổ chức tại khu lab của FPTU Đà Nẵng với sự tham gia của giảng viên, sinh viên và đại diện Osaka Design Institute. Điểm nhấn của chương trình là cách sinh viên chuyển yêu cầu thiết kế thành nguyên mẫu có thể trình diễn trong thời gian ngắn.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171019, 171006, 2, 'Cách tổ chức phiên demo', '<p>Thay vì chỉ giới thiệu thiết bị, host chia chương trình thành ba trạm: cảm biến, điều khiển và trình bày sản phẩm. Mỗi trạm có nhóm sinh viên phụ trách giải thích quy trình, khó khăn và phương án cải tiến.</p><ul><li>Trạm cảm biến trình bày cách thu thập dữ liệu môi trường.</li><li>Trạm điều khiển giải thích logic vận hành robot.</li><li>Trạm trình bày sản phẩm tập trung vào phản hồi của người dùng.</li></ul>', 'Thay vì chỉ giới thiệu thiết bị, host chia chương trình thành ba trạm: cảm biến, điều khiển và trình bày sản phẩm. Mỗi trạm có nhóm sinh viên phụ trách giải thích quy trình, khó khăn và phương án cải tiến. Trạm cảm biến trình bày cách thu thập dữ liệu môi trường. Trạm điều khiển giải thích logic vận hành robot. Trạm trình bày sản phẩm tập trung vào phản hồi của người dùng.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171020, 171006, 3, 'Kết quả sau workshop', '<p>Đối tác đề xuất tiếp tục tổ chức seminar trực tuyến về thiết kế tương tác trong robotics. Hai bên cũng thống nhất chia sẻ tài liệu hướng dẫn lab bằng tiếng Anh để phục vụ các đoàn tham quan học thuật tiếp theo.</p>', 'Đối tác đề xuất tiếp tục tổ chức seminar trực tuyến về thiết kế tương tác trong robotics. Hai bên cũng thống nhất chia sẻ tài liệu hướng dẫn lab bằng tiếng Anh để phục vụ các đoàn tham quan học thuật tiếp theo.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171021, 171007, 1, 'From classroom to prototype', '<p>The robotics workshop took place in the FPTU Da Nang laboratory with lecturers, students and Osaka Design Institute representatives. The session highlighted how students turn design requirements into demonstrable prototypes.</p>', 'The robotics workshop took place in the FPTU Da Nang laboratory with lecturers, students and Osaka Design Institute representatives. The session highlighted how students turn design requirements into demonstrable prototypes.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171022, 171007, 2, 'Demo station format', '<p>The host team divided the program into sensor, control and product presentation stations. Each station was led by students who explained the process, technical challenges and possible improvements.</p>', 'The host team divided the program into sensor, control and product presentation stations. Each station was led by students who explained the process, technical challenges and possible improvements.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171023, 171007, 3, 'Follow-up outcome', '<p>The partner proposed an online seminar on interaction design for robotics. English lab guidance materials will also be prepared for future academic visits.</p>', 'The partner proposed an online seminar on interaction design for robotics. English lab guidance materials will also be prepared for future academic visits.', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171024, 171008, 1, '授業から試作へ', '<p>ワークショップでは、学生が設計要件を短時間で動作可能なプロトタイプに変えるプロセスを紹介した。</p>', 'ワークショップでは、学生が設計要件を短時間で動作可能なプロトタイプに変えるプロセスを紹介した。', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171025, 171008, 2, 'デモの進め方', '<p>プログラムはセンサー、制御、製品発表の三つのステーションに分けられ、学生がそれぞれ説明を担当した。</p>', 'プログラムはセンサー、制御、製品発表の三つのステーションに分けられ、学生がそれぞれ説明を担当した。', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171026, 171008, 3, '今後の連携', '<p>両者は、ロボティクスにおけるインタラクションデザインをテーマにしたオンラインセミナーの可能性を検討する。</p>', '両者は、ロボティクスにおけるインタラクションデザインをテーマにしたオンラインセミナーの可能性を検討する。', '2026-08-18 09:20:00', '2026-08-18 11:20:00'),
  (171027, 171009, 1, 'Chủ đề gắn với vùng Mekong', '<p>Đại diện Mekong Innovation Network quan tâm tới cách FPTU Cần Thơ kết nối đào tạo công nghệ với bài toán địa phương. Buổi làm việc tập trung vào nông nghiệp số, dữ liệu cộng đồng và các dự án sinh viên có thể triển khai tại khu vực Đồng bằng sông Cửu Long.</p>', 'Đại diện Mekong Innovation Network quan tâm tới cách FPTU Cần Thơ kết nối đào tạo công nghệ với bài toán địa phương. Buổi làm việc tập trung vào nông nghiệp số, dữ liệu cộng đồng và các dự án sinh viên có thể triển khai tại khu vực Đồng bằng sông Cửu Long.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171028, 171009, 2, 'Dữ liệu, cộng đồng và sinh viên', '<p>Host giới thiệu một số hướng dự án phù hợp cho sinh viên như dashboard theo dõi mùa vụ, ứng dụng ghi nhận phản hồi nông hộ và mô hình truyền thông dữ liệu dễ hiểu cho cộng đồng. Các nội dung này được đánh giá phù hợp với workshop thực hành ngắn hạn.</p>', 'Host giới thiệu một số hướng dự án phù hợp cho sinh viên như dashboard theo dõi mùa vụ, ứng dụng ghi nhận phản hồi nông hộ và mô hình truyền thông dữ liệu dễ hiểu cho cộng đồng. Các nội dung này được đánh giá phù hợp với workshop thực hành ngắn hạn.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171029, 171009, 3, 'Đề xuất sau chuyến thăm', '<p>Hai bên thống nhất sẽ bắt đầu bằng một buổi seminar mở, sau đó chọn nhóm sinh viên quan tâm để phát triển đề tài thử nghiệm. Việc triển khai sẽ ưu tiên dữ liệu mô phỏng hoặc dữ liệu đã được ẩn danh nhằm bảo vệ quyền riêng tư của người tham gia.</p>', 'Hai bên thống nhất sẽ bắt đầu bằng một buổi seminar mở, sau đó chọn nhóm sinh viên quan tâm để phát triển đề tài thử nghiệm. Việc triển khai sẽ ưu tiên dữ liệu mô phỏng hoặc dữ liệu đã được ẩn danh nhằm bảo vệ quyền riêng tư của người tham gia.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171030, 171010, 1, 'A Mekong-focused topic', '<p>Mekong Innovation Network explored how FPTU Can Tho connects technology education with local challenges. The meeting focused on digital agriculture, community data and student projects for the Mekong Delta.</p>', 'Mekong Innovation Network explored how FPTU Can Tho connects technology education with local challenges. The meeting focused on digital agriculture, community data and student projects for the Mekong Delta.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171031, 171010, 2, 'Data, community and students', '<p>The host introduced possible student projects such as crop-season dashboards, farmer feedback tools and accessible data communication models. These ideas are suitable for short practical workshops.</p>', 'The host introduced possible student projects such as crop-season dashboards, farmer feedback tools and accessible data communication models. These ideas are suitable for short practical workshops.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171032, 171010, 3, 'Proposed next step', '<p>Both sides will begin with an open seminar and then select interested student groups for pilot projects using simulated or anonymized datasets.</p>', 'Both sides will begin with an open seminar and then select interested student groups for pilot projects using simulated or anonymized datasets.', '2026-08-17 13:20:00', '2026-08-17 15:25:00'),
  (171033, 171011, 1, 'Đón tiếp gắn với bản sắc địa phương', '<p>FPTU Quy Nhơn giới thiệu cách kết hợp hoạt động tiếp khách với đặc trưng địa phương, từ không gian học tập gần biển tới trải nghiệm giao lưu văn hóa. Đoàn khách đánh giá cao cách host chuẩn bị tuyến tham quan ngắn gọn nhưng vẫn đủ chiều sâu.</p>', 'FPTU Quy Nhơn giới thiệu cách kết hợp hoạt động tiếp khách với đặc trưng địa phương, từ không gian học tập gần biển tới trải nghiệm giao lưu văn hóa. Đoàn khách đánh giá cao cách host chuẩn bị tuyến tham quan ngắn gọn nhưng vẫn đủ chiều sâu.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171034, 171011, 2, 'Sinh viên trong hoạt động hospitality', '<p>Nhóm sinh viên hỗ trợ không chỉ đảm nhiệm check-in và hướng dẫn di chuyển mà còn tham gia giới thiệu góc nhìn của người học. Điều này giúp buổi tham quan trở nên gần gũi hơn và tạo thêm cơ hội rèn luyện kỹ năng dịch, thuyết trình, xử lý tình huống.</p>', 'Nhóm sinh viên hỗ trợ không chỉ đảm nhiệm check-in và hướng dẫn di chuyển mà còn tham gia giới thiệu góc nhìn của người học. Điều này giúp buổi tham quan trở nên gần gũi hơn và tạo thêm cơ hội rèn luyện kỹ năng dịch, thuyết trình, xử lý tình huống.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171035, 171011, 3, 'Hướng hợp tác tiếp theo', '<p>Hai bên thảo luận khả năng tổ chức một chương trình giao lưu ngắn về hospitality, truyền thông điểm đến và dịch vụ khách quốc tế dành cho sinh viên các ngành liên quan.</p>', 'Hai bên thảo luận khả năng tổ chức một chương trình giao lưu ngắn về hospitality, truyền thông điểm đến và dịch vụ khách quốc tế dành cho sinh viên các ngành liên quan.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171036, 171012, 1, 'Reception with local identity', '<p>FPTU Quy Nhon introduced how visitor programs can reflect local identity, from coastal learning spaces to cultural exchange moments. The delegation appreciated a concise but meaningful campus route.</p>', 'FPTU Quy Nhon introduced how visitor programs can reflect local identity, from coastal learning spaces to cultural exchange moments. The delegation appreciated a concise but meaningful campus route.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171037, 171012, 2, 'Students in hospitality activities', '<p>Student supporters handled check-in and navigation while also sharing the learner perspective. This made the visit more personal and gave students practice in translation, presentation and situational communication.</p>', 'Student supporters handled check-in and navigation while also sharing the learner perspective. This made the visit more personal and gave students practice in translation, presentation and situational communication.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171038, 171012, 3, 'Future cooperation', '<p>The two sides discussed a short program on hospitality, destination communication and international visitor services for students.</p>', 'The two sides discussed a short program on hospitality, destination communication and international visitor services for students.', '2026-08-16 10:00:00', '2026-08-16 12:00:00'),
  (171039, 171013, 1, 'Chuẩn bị trước khi đón đoàn', '<p>Nhóm student buddy nhận lịch trình từ host, chia vai theo từng điểm dừng và rà soát các câu hỏi thường gặp của khách. Việc chuẩn bị trước giúp các bạn tự tin hơn khi giới thiệu không gian học tập, khu lab và hoạt động câu lạc bộ.</p>', 'Nhóm student buddy nhận lịch trình từ host, chia vai theo từng điểm dừng và rà soát các câu hỏi thường gặp của khách. Việc chuẩn bị trước giúp các bạn tự tin hơn khi giới thiệu không gian học tập, khu lab và hoạt động câu lạc bộ.', '2026-08-21 09:00:00', NULL),
  (171040, 171013, 2, 'Trong lúc diễn ra chương trình', '<p>Các bạn sinh viên hỗ trợ check-in, điều phối ảnh, nhắc thời gian và chủ động kết nối khách với đại diện nhà trường. Một số bạn đảm nhiệm phần phiên dịch ngắn khi khách trao đổi trực tiếp với sinh viên đang học tại lab.</p>', 'Các bạn sinh viên hỗ trợ check-in, điều phối ảnh, nhắc thời gian và chủ động kết nối khách với đại diện nhà trường. Một số bạn đảm nhiệm phần phiên dịch ngắn khi khách trao đổi trực tiếp với sinh viên đang học tại lab.', '2026-08-21 09:00:00', NULL),
  (171041, 171013, 3, 'Điểm cần cải thiện', '<p>Bản nháp đề xuất bổ sung checklist song ngữ cho từng loại đoàn và một template ghi nhận câu hỏi sau sự kiện. Nội dung này đang chờ Staff Leader rà soát để đảm bảo không nêu thông tin nội bộ trước khi công khai.</p>', 'Bản nháp đề xuất bổ sung checklist song ngữ cho từng loại đoàn và một template ghi nhận câu hỏi sau sự kiện. Nội dung này đang chờ Staff Leader rà soát để đảm bảo không nêu thông tin nội bộ trước khi công khai.', '2026-08-21 09:00:00', NULL),
  (171042, 171014, 1, 'Lý do bài chưa được duyệt', '<p>Bản nháp mô tả đầy đủ diễn biến hội thảo fintech nhưng còn lẫn thông tin không phù hợp để đăng public. Staff Leader yêu cầu loại bỏ số liệu ngân sách, tên đầu mối nội bộ và các ảnh chưa xác nhận consent.</p>', 'Bản nháp mô tả đầy đủ diễn biến hội thảo fintech nhưng còn lẫn thông tin không phù hợp để đăng public. Staff Leader yêu cầu loại bỏ số liệu ngân sách, tên đầu mối nội bộ và các ảnh chưa xác nhận consent.', '2026-08-15 08:30:00', '2026-08-15 10:00:00'),
  (171043, 171014, 2, 'Phần nội dung có thể giữ lại', '<p>Các đoạn giới thiệu chủ đề học thuật, hoạt động trao đổi giữa giảng viên và khách mời, cũng như phản hồi chung của sinh viên có thể được giữ lại sau khi biên tập. Nội dung cần chuyển sang giọng văn truyền thông khách quan hơn.</p>', 'Các đoạn giới thiệu chủ đề học thuật, hoạt động trao đổi giữa giảng viên và khách mời, cũng như phản hồi chung của sinh viên có thể được giữ lại sau khi biên tập. Nội dung cần chuyển sang giọng văn truyền thông khách quan hơn.', '2026-08-15 08:30:00', '2026-08-15 10:00:00'),
  (171044, 171014, 3, 'Hướng sửa đề xuất', '<p>Người viết nên thay số liệu chi tiết bằng mô tả tổng quát, chỉ dùng ảnh đã được gắn trong hệ thống files và kiểm tra lại phần tóm tắt để tránh hứa hẹn hợp tác chưa được xác nhận.</p>', 'Người viết nên thay số liệu chi tiết bằng mô tả tổng quát, chỉ dùng ảnh đã được gắn trong hệ thống files và kiểm tra lại phần tóm tắt để tránh hứa hẹn hợp tác chưa được xác nhận.', '2026-08-15 08:30:00', '2026-08-15 10:00:00'),
  (171045, 171015, 1, 'Lý do tạm ẩn', '<p>Bài viết có nội dung phù hợp nhưng một số ảnh nhóm cần được đối tác xác nhận lại phạm vi sử dụng. Vì vậy Staff Leader chuyển bài sang trạng thái <strong>HIDDEN</strong> để không xuất hiện ở trang public trong thời gian rà soát.</p>', 'Bài viết có nội dung phù hợp nhưng một số ảnh nhóm cần được đối tác xác nhận lại phạm vi sử dụng. Vì vậy Staff Leader chuyển bài sang trạng thái HIDDEN để không xuất hiện ở trang public trong thời gian rà soát.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171046, 171015, 2, 'Nội dung chính của chuyến lab tour', '<p>Đoàn khách tham quan khu robotics, lớp học mô phỏng và không gian tự học. Các trao đổi tập trung vào cách sinh viên thực hành theo nhóm và cách giảng viên phản hồi trong từng sprint dự án.</p>', 'Đoàn khách tham quan khu robotics, lớp học mô phỏng và không gian tự học. Các trao đổi tập trung vào cách sinh viên thực hành theo nhóm và cách giảng viên phản hồi trong từng sprint dự án.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171047, 171015, 3, 'Kế hoạch mở lại bài', '<p>Sau khi nhận xác nhận từ đối tác, host sẽ thay thế hoặc giữ lại ảnh phù hợp rồi chuyển trạng thái bài về public. Nội dung chữ hiện không cần chỉnh sửa lớn.</p>', 'Sau khi nhận xác nhận từ đối tác, host sẽ thay thế hoặc giữ lại ảnh phù hợp rồi chuyển trạng thái bài về public. Nội dung chữ hiện không cần chỉnh sửa lớn.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171048, 171016, 1, 'Reason for hiding', '<p>The article content is suitable, but several group photos require additional confirmation from the partner. Staff Leader therefore moved the article to <strong>HIDDEN</strong> status during review.</p>', 'The article content is suitable, but several group photos require additional confirmation from the partner. Staff Leader therefore moved the article to HIDDEN status during review.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171049, 171016, 2, 'Lab tour highlights', '<p>The delegation visited robotics spaces, simulation classrooms and self-study areas. Discussions focused on team-based practice and lecturer feedback during project sprints.</p>', 'The delegation visited robotics spaces, simulation classrooms and self-study areas. Discussions focused on team-based practice and lecturer feedback during project sprints.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171050, 171016, 3, 'Plan to republish', '<p>After consent is confirmed, the host will update the photo set and make the article visible again if appropriate.</p>', 'After consent is confirmed, the host will update the photo set and make the article visible again if appropriate.', '2026-08-13 09:00:00', '2026-08-13 11:30:00'),
  (171051, 171017, 1, 'Tin tức gắn với vòng đời chuyến thăm', '<p>News module trong PEMS được thiết kế để kết nối trực tiếp với vòng đời tiếp khách: sau khi chuyến thăm hoàn tất, host có thể tạo bài, gắn ảnh, gửi duyệt và xuất bản lên trang public khi đủ điều kiện.</p>', 'News module trong PEMS được thiết kế để kết nối trực tiếp với vòng đời tiếp khách: sau khi chuyến thăm hoàn tất, host có thể tạo bài, gắn ảnh, gửi duyệt và xuất bản lên trang public khi đủ điều kiện.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171052, 171017, 2, 'Kiểm soát ảnh và nội dung', '<p>Ảnh được lưu dưới dạng metadata trong bảng files và liên kết với section qua news_section_files. Cách này giúp tránh lưu base64 trong database, đồng thời cho phép kiểm soát quyền xem ảnh theo trạng thái bài viết.</p><ul><li>PUBLISHED: public có thể xem.</li><li>PENDING_REVIEW và REJECTED: chỉ dashboard nội bộ xem theo quyền.</li><li>HIDDEN: bài từng có thể publish nhưng đang bị ẩn khỏi public.</li></ul>', 'Ảnh được lưu dưới dạng metadata trong bảng files và liên kết với section qua news_section_files. Cách này giúp tránh lưu base64 trong database, đồng thời cho phép kiểm soát quyền xem ảnh theo trạng thái bài viết. PUBLISHED: public có thể xem. PENDING_REVIEW và REJECTED: chỉ dashboard nội bộ xem theo quyền. HIDDEN: bài từng có thể publish nhưng đang bị ẩn khỏi public.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171053, 171017, 3, 'Đa ngôn ngữ và dịch tự động', '<p>Mỗi bài có thể có nhiều bản dịch trong news_translations. Khi cấu hình Google Cloud Translation, người dùng có thể tạo bản dịch nháp, kiểm tra lại nội dung và lưu thành bản copy mới mà không ảnh hưởng bản gốc.</p>', 'Mỗi bài có thể có nhiều bản dịch trong news_translations. Khi cấu hình Google Cloud Translation, người dùng có thể tạo bản dịch nháp, kiểm tra lại nội dung và lưu thành bản copy mới mà không ảnh hưởng bản gốc.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171054, 171018, 1, 'News connected to visit lifecycle', '<p>The News module is linked to the reception lifecycle. After a visit is completed, hosts can create an article, attach images, submit for review and publish when all conditions are satisfied.</p>', 'The News module is linked to the reception lifecycle. After a visit is completed, hosts can create an article, attach images, submit for review and publish when all conditions are satisfied.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171055, 171018, 2, 'Content and image control', '<p>Images are stored as file metadata and connected to article sections through news_section_files. This avoids base64 payloads in the database and allows public access to be controlled by article status.</p>', 'Images are stored as file metadata and connected to article sections through news_section_files. This avoids base64 payloads in the database and allows public access to be controlled by article status.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171056, 171018, 3, 'Multilingual publishing', '<p>Each article can have multiple translations. With Google Cloud Translation configured, users can generate a draft translation, review it and save it as a new language copy.</p>', 'Each article can have multiple translations. With Google Cloud Translation configured, users can generate a draft translation, review it and save it as a new language copy.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171057, 171019, 1, '与接待流程联动', '<p>新闻模块与接待生命周期相连接。访问结束后，host可以创建文章、添加图片、提交审核并在符合条件后发布。</p>', '新闻模块与接待生命周期相连接。访问结束后，host可以创建文章、添加图片、提交审核并在符合条件后发布。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171058, 171019, 2, '内容和图片管理', '<p>图片以文件元数据形式保存，并通过 news_section_files 与文章 section 建立关系，避免在数据库中保存 base64 内容。</p>', '图片以文件元数据形式保存，并通过 news_section_files 与文章 section 建立关系，避免在数据库中保存 base64 内容。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171059, 171019, 3, '多语言发布', '<p>每篇文章可以拥有多个语言版本。配置翻译服务后，用户可以生成翻译草稿并保存为新的语言副本。</p>', '每篇文章可以拥有多个语言版本。配置翻译服务后，用户可以生成翻译草稿并保存为新的语言副本。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
  (171060, 171020, 1, 'Mục tiêu chương trình mentor', '<p>Chương trình hướng tới việc duy trì kết nối sau buổi tiếp khách, giúp sinh viên có kênh đặt câu hỏi về nghề nghiệp, kỹ năng dự án và tiêu chuẩn làm việc trong môi trường quốc tế.</p>', 'Chương trình hướng tới việc duy trì kết nối sau buổi tiếp khách, giúp sinh viên có kênh đặt câu hỏi về nghề nghiệp, kỹ năng dự án và tiêu chuẩn làm việc trong môi trường quốc tế.', '2026-08-11 10:10:00', NULL),
  (171061, 171020, 2, 'Cách vận hành đề xuất', '<p>Host đề xuất tạo lịch mentor theo nhóm nhỏ, mỗi buổi có chủ đề cụ thể và form ghi nhận câu hỏi trước. Nội dung nhạy cảm về doanh nghiệp sẽ không đưa vào bản public.</p>', 'Host đề xuất tạo lịch mentor theo nhóm nhỏ, mỗi buổi có chủ đề cụ thể và form ghi nhận câu hỏi trước. Nội dung nhạy cảm về doanh nghiệp sẽ không đưa vào bản public.', '2026-08-11 10:10:00', NULL),
  (171062, 171020, 3, 'Trạng thái hiện tại', '<p>Bài đã có bản tiếng Việt và tiếng Anh nhưng vẫn đang chờ Staff Leader rà soát giọng văn, mức độ công khai và tên đối tác trước khi xuất bản.</p>', 'Bài đã có bản tiếng Việt và tiếng Anh nhưng vẫn đang chờ Staff Leader rà soát giọng văn, mức độ công khai và tên đối tác trước khi xuất bản.', '2026-08-11 10:10:00', NULL),
  (171063, 171021, 1, 'Program objective', '<p>The program aims to maintain post-visit connections and give students a channel to ask about careers, project skills and international workplace standards.</p>', 'The program aims to maintain post-visit connections and give students a channel to ask about careers, project skills and international workplace standards.', '2026-08-11 10:10:00', NULL),
  (171064, 171021, 2, 'Proposed operation', '<p>The host suggests small-group mentor sessions with clear themes and a pre-collected question form. Sensitive business information will not be included in the public article.</p>', 'The host suggests small-group mentor sessions with clear themes and a pre-collected question form. Sensitive business information will not be included in the public article.', '2026-08-11 10:10:00', NULL),
  (171065, 171021, 3, 'Current status', '<p>The article already has Vietnamese and English versions but is waiting for Staff Leader review before publication.</p>', 'The article already has Vietnamese and English versions but is waiting for Staff Leader review before publication.', '2026-08-11 10:10:00', NULL),
  (171066, 171022, 1, 'Lễ ký kết và định hướng seminar', '<p>Đại diện FPTU Hà Nội và Porto AI Hub thống nhất kế hoạch tổ chức chuỗi seminar về AI ứng dụng. Thay vì chỉ tập trung vào lý thuyết, chương trình sẽ đưa vào các case study về xử lý dữ liệu, thiết kế sản phẩm AI và đánh giá rủi ro đạo đức.</p>', 'Đại diện FPTU Hà Nội và Porto AI Hub thống nhất kế hoạch tổ chức chuỗi seminar về AI ứng dụng. Thay vì chỉ tập trung vào lý thuyết, chương trình sẽ đưa vào các case study về xử lý dữ liệu, thiết kế sản phẩm AI và đánh giá rủi ro đạo đức.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171067, 171022, 2, 'Cấu trúc chương trình dự kiến', '<p>Chuỗi seminar gồm ba phần: bài nói mở đầu từ chuyên gia, phiên thảo luận nhóm và bài tập thực hành ngắn. Sinh viên có thể chuẩn bị câu hỏi trước thông qua form đăng ký để buổi seminar đi vào vấn đề cụ thể.</p>', 'Chuỗi seminar gồm ba phần: bài nói mở đầu từ chuyên gia, phiên thảo luận nhóm và bài tập thực hành ngắn. Sinh viên có thể chuẩn bị câu hỏi trước thông qua form đăng ký để buổi seminar đi vào vấn đề cụ thể.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171068, 171022, 3, 'Ý nghĩa với sinh viên', '<p>Hoạt động này giúp sinh viên nhìn thấy cách kiến thức AI được chuyển thành sản phẩm, đồng thời hiểu rõ hơn về yêu cầu giao tiếp khi làm việc trong nhóm quốc tế.</p>', 'Hoạt động này giúp sinh viên nhìn thấy cách kiến thức AI được chuyển thành sản phẩm, đồng thời hiểu rõ hơn về yêu cầu giao tiếp khi làm việc trong nhóm quốc tế.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171069, 171023, 1, 'Signing and seminar direction', '<p>FPTU Hanoi and Porto AI Hub agreed to develop a seminar series on applied AI. The program will include case studies on data processing, AI product design and ethical risk assessment.</p>', 'FPTU Hanoi and Porto AI Hub agreed to develop a seminar series on applied AI. The program will include case studies on data processing, AI product design and ethical risk assessment.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171070, 171023, 2, 'Expected program structure', '<p>Each seminar will include an expert talk, a group discussion and a short practical exercise. Students can submit questions in advance to make the session more focused.</p>', 'Each seminar will include an expert talk, a group discussion and a short practical exercise. Students can submit questions in advance to make the session more focused.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171071, 171023, 3, 'Meaning for students', '<p>The activity helps students understand how AI knowledge becomes real products and how communication works in international project teams.</p>', 'The activity helps students understand how AI knowledge becomes real products and how communication works in international project teams.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171072, 171024, 1, '세미나 방향', '<p>FPTU 하노이와 Porto AI Hub는 응용 AI 세미나 시리즈를 함께 추진하기로 했다. 프로그램에는 데이터 처리, AI 제품 설계, 윤리적 위험 평가 사례가 포함된다.</p>', 'FPTU 하노이와 Porto AI Hub는 응용 AI 세미나 시리즈를 함께 추진하기로 했다. 프로그램에는 데이터 처리, AI 제품 설계, 윤리적 위험 평가 사례가 포함된다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171073, 171024, 2, '프로그램 구성', '<p>각 세미나는 전문가 발표, 그룹 토론, 짧은 실습으로 구성될 예정이다.</p>', '각 세미나는 전문가 발표, 그룹 토론, 짧은 실습으로 구성될 예정이다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171074, 171024, 3, '학생에게 주는 의미', '<p>학생들은 AI 지식이 실제 제품으로 연결되는 과정을 이해하고 국제 프로젝트 팀에서의 소통 방식을 경험할 수 있다.</p>', '학생들은 AI 지식이 실제 제품으로 연결되는 과정을 이해하고 국제 프로젝트 팀에서의 소통 방식을 경험할 수 있다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
  (171075, 171025, 1, 'Nội dung đã có', '<p>Bài viết ghi nhận các hoạt động chính sau chuyến thăm, bao gồm seminar mở, trao đổi với sinh viên và đề xuất nhóm dự án thử nghiệm. Phần mô tả bối cảnh và định hướng hợp tác được đánh giá có thể giữ lại.</p>', 'Bài viết ghi nhận các hoạt động chính sau chuyến thăm, bao gồm seminar mở, trao đổi với sinh viên và đề xuất nhóm dự án thử nghiệm. Phần mô tả bối cảnh và định hướng hợp tác được đánh giá có thể giữ lại.', '2026-08-09 09:20:00', '2026-08-09 11:00:00'),
  (171076, 171025, 2, 'Điểm cần chỉnh sửa', '<p>Một số nhận định về mức độ hài lòng của khách cần có nguồn rõ ràng, chẳng hạn từ form feedback hoặc biên bản sau chuyến thăm. Ngoài ra, các câu nhận xét cá nhân nên chuyển sang giọng văn trung lập để phù hợp với trang public.</p>', 'Một số nhận định về mức độ hài lòng của khách cần có nguồn rõ ràng, chẳng hạn từ form feedback hoặc biên bản sau chuyến thăm. Ngoài ra, các câu nhận xét cá nhân nên chuyển sang giọng văn trung lập để phù hợp với trang public.', '2026-08-09 09:20:00', '2026-08-09 11:00:00'),
  (171077, 171025, 3, 'Hướng gửi lại', '<p>Người viết cần bổ sung liên kết tới dữ liệu feedback nội bộ, rút gọn đoạn đánh giá chủ quan và kiểm tra lại consent ảnh trước khi gửi duyệt lần tiếp theo.</p>', 'Người viết cần bổ sung liên kết tới dữ liệu feedback nội bộ, rút gọn đoạn đánh giá chủ quan và kiểm tra lại consent ảnh trước khi gửi duyệt lần tiếp theo.', '2026-08-09 09:20:00', '2026-08-09 11:00:00');

-- 5) Validation helpers. Expected: data_image_rows = 0.
SELECT status, COUNT(*) AS total FROM news GROUP BY status ORDER BY status;
SELECT language_code, COUNT(*) AS translations FROM news_translations GROUP BY language_code ORDER BY language_code;
SELECT COUNT(*) AS data_image_rows FROM news_content_sections WHERE section_body_html LIKE '%data:image%';
SELECT n.news_id, nt.language_code, COUNT(s.section_id) AS section_count FROM news n JOIN news_translations nt ON nt.news_id = n.news_id LEFT JOIN news_content_sections s ON s.news_translation_id = nt.news_translation_id GROUP BY n.news_id, nt.language_code ORDER BY n.news_id, nt.language_code;

-- Extra integrity checks for rich News seed. Expected values: all *_issues = 0.
SELECT COUNT(*) AS seeded_news_file_reference_issues
FROM news
WHERE news_id BETWEEN 17001 AND 17012
  AND cover_file_id IS NOT NULL;
SELECT COUNT(*) AS duplicate_news_translation_lang_issues
FROM (
  SELECT news_id, language_code FROM news_translations WHERE news_id BETWEEN 17001 AND 17012 GROUP BY news_id, language_code HAVING COUNT(*) > 1
) x;
SELECT COUNT(*) AS duplicate_news_section_order_issues
FROM (
  SELECT news_translation_id, section_order FROM news_content_sections WHERE section_id BETWEEN 171001 AND 171999 GROUP BY news_translation_id, section_order HAVING COUNT(*) > 1
) x;

COMMIT;

-- Restore previous Safe Updates mode for this session.
SET SQL_SAFE_UPDATES = @OLD_SQL_SAFE_UPDATES;

-- =============================================================================
-- Verify
-- =============================================================================

SELECT
    vrc.visit_instance_id,
    vr.request_code,
    seed_detail.delegation_name,
    vrc.status AS campus_status,
    COUNT(DISTINCT n.news_id) AS published_news_count,
    COUNT(DISTINCT f.feedback_id) AS visitor_feedback_count
FROM visit_request_campuses vrc
JOIN visit_requests vr ON vr.visit_request_id = vrc.visit_request_id
JOIN visit_instance_form_details seed_detail ON seed_detail.visit_instance_id = vrc.visit_instance_id
JOIN users visitor
    ON visitor.user_id = vr.registrant_user_id
LEFT JOIN news n
    ON n.visit_instance_id = vrc.visit_instance_id
   AND n.status = 'PUBLISHED'
LEFT JOIN feedbacks f
    ON f.visit_instance_id = vrc.visit_instance_id
   AND f.submitted_by_user_id = visitor.user_id
   AND f.submitter_role = 'VISITOR'
WHERE visitor.email = 'kim.minjae@seoultech.example'
  AND vrc.status = 'CLOSED'
GROUP BY
    vrc.visit_instance_id,
    vr.request_code,
    seed_detail.delegation_name,
    vrc.status
ORDER BY vrc.visit_instance_id;

