  (7142, 5046, 101, 'IC_SUPPORT', FALSE, 'ACCEPTED', 4, '2026-07-07 10:05:00', '2026-07-07 10:20:00', NULL, NULL, 'Đã xác nhận tham gia và được cung cấp lịch trình cùng thông tin liên hệ của Host.', '2026-07-07 10:05:00', 4, '2026-07-07 10:20:00', 101);

