  );

-- Fixed participant rows in this generated SQL:
-- 7002, 7016, 7022, 7034, 7048, 7054, 7060, 7066, 7080, 7092, 7098, 7112, 7124, 7130, 7144, 7150, 7166, 7182, 7198, 7214, 7232, 7238, 7256, 7262, 7280, 7286, 7300, 7306, 7320, 7326, 99014, 99213, 99218, 99223


-- =====================================================================
-- CONTACT / VISITOR ROLE GUARD — ROLLBACK-SAFE DATABASE SELF-TESTS
-- All negative mutations are isolated in transactions and rolled back. Results are
-- emitted as rows; no intentionally invalid relation remains in the final seed.
-- =====================================================================
DROP TEMPORARY TABLE IF EXISTS pems_contact_guard_test_results;
CREATE TEMPORARY TABLE pems_contact_guard_test_results (
  sequence_no INT UNSIGNED NOT NULL AUTO_INCREMENT,
  test_type VARCHAR(20) NOT NULL,
  test_case VARCHAR(30) NOT NULL,
  operation_summary VARCHAR(500) NOT NULL,
  expected_sqlstate VARCHAR(10) NOT NULL,
  expected_message VARCHAR(255) NOT NULL,
  actual_sqlstate VARCHAR(10) NOT NULL,
  actual_message VARCHAR(1000) NOT NULL,
  result ENUM('PASS','FAIL') NOT NULL,
  PRIMARY KEY (sequence_no)
) ENGINE=MEMORY;

DROP PROCEDURE IF EXISTS sp_pems_contact_guard_tests;
DELIMITER $$
CREATE PROCEDURE sp_pems_contact_guard_tests()
BEGIN
  DECLARE v_sqlstate CHAR(5) DEFAULT NULL;
  DECLARE v_message VARCHAR(1000) DEFAULT NULL;
  DECLARE v_raised BOOLEAN DEFAULT FALSE;
  DECLARE v_condition_ok INT DEFAULT 0;
  DECLARE v_open_instance BIGINT UNSIGNED DEFAULT NULL;
  DECLARE v_open_request BIGINT UNSIGNED DEFAULT NULL;
  DECLARE v_registrant BIGINT UNSIGNED DEFAULT NULL;

  -- Every handler below reads GET DIAGNOSTICS *before* setting any flag. MySQL clears the
  -- diagnostics area on the first successful statement inside the handler, so a
  -- `SET v_raised = TRUE;` first ordering leaves RETURNED_SQLSTATE and MESSAGE_TEXT NULL.
  -- The comparison `v_sqlstate = '45000'` then evaluates to UNKNOWN and every negative case
  -- is scored FAIL while the triggers had in fact rejected all of them. Do not reorder.

  -- A campus instance that is past confirmation, under a live request, plus its registrant.
  SELECT vrc.visit_instance_id, vrc.visit_request_id, vr.registrant_user_id
    INTO v_open_instance, v_open_request, v_registrant
  FROM visit_request_campuses vrc
  JOIN visit_requests vr ON vr.visit_request_id = vrc.visit_request_id
  WHERE vrc.status = 'WAITING_REQUEST_APPROVAL'
    AND vrc.operational_contact_user_id IS NOT NULL
    AND vr.status <> 'CANCELLED'
  ORDER BY vrc.visit_instance_id
  LIMIT 1;

  -- NEG-01: a campus past confirmation may not drop its operational contact
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_request_campuses SET operational_contact_user_id = NULL
    WHERE visit_instance_id = v_open_instance;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-01', 'Clear operational contact on a campus past confirmation', '45000',
     'CAMPUS_BEYOND_CONFIRMATION_REQUIRES_OPERATIONAL_CONTACT',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'CAMPUS_BEYOND_CONFIRMATION_REQUIRES_OPERATIONAL_CONTACT', 'PASS', 'FAIL'));

  -- NEG-02: a campus still WAITING_CONTACT_CONFIRMATION may not carry a contact
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_request_campuses SET status = 'WAITING_CONTACT_CONFIRMATION'
    WHERE visit_instance_id = v_open_instance;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-02', 'Move a confirmed campus back to WAITING_CONTACT_CONFIRMATION', '45000',
     'WAITING_CONTACT_CONFIRMATION_MUST_NOT_HAVE_OPERATIONAL_CONTACT',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'WAITING_CONTACT_CONFIRMATION_MUST_NOT_HAVE_OPERATIONAL_CONTACT', 'PASS', 'FAIL'));

  -- NEG-03: operational contact must reference a real user
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_request_campuses SET operational_contact_user_id = 99999999
    WHERE visit_instance_id = v_open_instance;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-03', 'Point operational contact at a non-existent user', 'ANY',
     'REJECTED_BY_FK_OR_TRIGGER',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised, 'PASS', 'FAIL'));

  -- NEG-04: a linked, ACTIVE operational contact cannot be deactivated
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE users SET status = 'INACTIVE'
    WHERE user_id = (SELECT operational_contact_user_id FROM visit_request_campuses
                     WHERE visit_instance_id = v_open_instance);
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-04', 'Deactivate an account still holding a live campus', '45000',
     'LINKED_OPERATIONAL_CONTACT_CANNOT_BE_DEACTIVATED',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'LINKED_OPERATIONAL_CONTACT_CANNOT_BE_DEACTIVATED', 'PASS', 'FAIL'));

  -- NEG-05: the global confirmation gate blocks approval while a sibling is unconfirmed
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    -- force the parent back behind the gate, then try to decide the campus
    UPDATE visit_requests SET status = 'PENDING_CONTACT_CONFIRMATION'
    WHERE visit_request_id = v_open_request;
    UPDATE visit_request_campuses
    SET status = 'REJECTED', decided_by = 3, decided_at = NOW(),
        decision_actor_role = 'STAFF_LEADER', decision_note = 'guard probe'
    WHERE visit_instance_id = v_open_instance;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-05', 'Decide a campus while the request is behind the confirmation gate', '45000',
     'CONTACT_CONFIRMATION_REQUIRED',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'CONTACT_CONFIRMATION_REQUIRED', 'PASS', 'FAIL'));

  -- NEG-06: a request cannot leave the gate while a campus is still unconfirmed
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_request_campuses
    SET status = 'WAITING_CONTACT_CONFIRMATION', operational_contact_user_id = NULL
    WHERE visit_instance_id = v_open_instance;
    UPDATE visit_requests SET status = 'PENDING_CONTACT_CONFIRMATION'
    WHERE visit_request_id = v_open_request;
    UPDATE visit_requests SET status = 'PENDING_APPROVAL'
    WHERE visit_request_id = v_open_request;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-06', 'Open the gate while a campus still has no operational contact', '45000',
     'CONTACT_CONFIRMATION_REQUIRED',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'CONTACT_CONFIRMATION_REQUIRED', 'PASS', 'FAIL'));

  -- NEG-07: only the registrant may cancel the whole request
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_requests
    SET status = 'CANCELLED', cancelled_by = 2, cancelled_at = NOW(),
        cancellation_reason = 'guard probe: HO must never cancel'
    WHERE visit_request_id = v_open_request;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-07', 'Cancel the whole request as a non-registrant (HO)', '45000',
     'Only the registrant can cancel the whole request',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'Only the registrant can cancel the whole request', 'PASS', 'FAIL'));

  -- NEG-08: an identity change must belong to a campus of its own request
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    INSERT INTO visit_request_identity_changes
      (visit_request_id, visit_instance_id, change_kind, confirmation_method,
       new_email_normalized, new_email_masked, status, expected_request_row_version,
       requested_by, expires_at)
    VALUES
      (v_open_request,
       (SELECT MAX(visit_instance_id) + 1000 FROM visit_request_campuses),
       'INITIAL_CONFIRMATION', 'GOOGLE_SSO', 'cross@example.com', 'c***@example.com',
       'PENDING', 0, v_registrant, NOW() + INTERVAL 3 DAY);
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-08', 'Identity change pointing at a foreign campus instance', 'ANY',
     'REJECTED_BY_COMPOSITE_FK',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised, 'PASS', 'FAIL'));

  -- NEG-09: only one PENDING identity change per campus
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    INSERT INTO visit_request_identity_changes
      (visit_request_id, visit_instance_id, change_kind, confirmation_method,
       new_email_normalized, new_email_masked, status, expected_request_row_version,
       requested_by, expires_at)
    VALUES
      (v_open_request, v_open_instance, 'INITIAL_CONFIRMATION', 'GOOGLE_SSO',
       'first@example.com', 'f***@example.com', 'PENDING', 0, v_registrant, NOW() + INTERVAL 3 DAY),
      (v_open_request, v_open_instance, 'INITIAL_CONFIRMATION', 'GOOGLE_SSO',
       'second@example.com', 's***@example.com', 'PENDING', 0, v_registrant, NOW() + INTERVAL 3 DAY);
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-09', 'Two PENDING identity changes on one campus', 'ANY',
     'REJECTED_BY_PENDING_GUARD',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised, 'PASS', 'FAIL'));

  -- NEG-10: INITIAL_CONFIRMATION must not carry an old owner
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    INSERT INTO visit_request_identity_changes
      (visit_request_id, visit_instance_id, change_kind, confirmation_method, old_user_id,
       new_email_normalized, new_email_masked, status, expected_request_row_version,
       requested_by, expires_at)
    VALUES
      (v_open_request, v_open_instance, 'INITIAL_CONFIRMATION', 'GOOGLE_SSO', v_registrant,
       'third@example.com', 't***@example.com', 'PENDING', 0, v_registrant, NOW() + INTERVAL 3 DAY);
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-10', 'INITIAL_CONFIRMATION carrying old_user_id', '45000',
     'INITIAL_CONFIRMATION identity change must not carry old_user_id',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'INITIAL_CONFIRMATION identity change must not carry old_user_id', 'PASS', 'FAIL'));

  -- NEG-11: TRANSFER requires the current owner
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    INSERT INTO visit_request_identity_changes
      (visit_request_id, visit_instance_id, change_kind, confirmation_method,
       new_email_normalized, new_email_masked, status, expected_request_row_version,
       requested_by, expires_at)
    VALUES
      (v_open_request, v_open_instance, 'TRANSFER', 'GOOGLE_SSO',
       'fourth@example.com', 'f***@example.com', 'PENDING', 0, v_registrant, NOW() + INTERVAL 3 DAY);
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('NEGATIVE', 'NEG-11', 'TRANSFER without old_user_id', '45000',
     'TRANSFER identity change requires old_user_id (the current owner)',
     COALESCE(v_sqlstate, 'NO_ERROR'), COALESCE(v_message, 'Operation unexpectedly succeeded'),
     IF(v_raised AND v_sqlstate = '45000'
        AND v_message = 'TRANSFER identity change requires old_user_id (the current owner)', 'PASS', 'FAIL'));

  -- POS-01: an internal (STAFF) account may be an operational contact — plan §1.7
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE; SET v_condition_ok = 0;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    UPDATE visit_request_campuses
    SET operational_contact_user_id = (
          SELECT u.user_id FROM users u JOIN roles r ON r.role_id = u.role_id
          WHERE r.role_code = 'STAFF' AND u.status = 'ACTIVE' ORDER BY u.user_id LIMIT 1)
    WHERE visit_instance_id = v_open_instance;
    IF NOT v_raised THEN
      SELECT COUNT(*) INTO v_condition_ok
      FROM visit_request_campuses vrc
      JOIN users u ON u.user_id = vrc.operational_contact_user_id
      JOIN roles r ON r.role_id = u.role_id
      WHERE vrc.visit_instance_id = v_open_instance AND r.role_code = 'STAFF';
    END IF;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('POSITIVE', 'POS-01', 'Internal STAFF account as operational contact', 'NONE', 'ACCEPTED',
     COALESCE(v_sqlstate, 'NONE'),
     IF(v_raised, COALESCE(v_message, 'Unexpected SQL exception'),
        IF(v_condition_ok = 1, 'ACCEPTED', 'Post-condition failed')),
     IF(NOT v_raised AND v_condition_ok = 1, 'PASS', 'FAIL'));

  -- POS-02: one account may hold several campuses at once (no UNIQUE on the column)
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE; SET v_condition_ok = 0;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    -- Only campuses still awaiting a decision: moving an operational campus would trip the
    -- unrelated agenda guard and score this probe FAIL for the wrong reason.
    UPDATE visit_request_campuses
    SET operational_contact_user_id = v_registrant
    WHERE status = 'WAITING_REQUEST_APPROVAL'
      AND operational_contact_user_id IS NOT NULL;
    IF NOT v_raised THEN
      SELECT IF(COUNT(*) > 1, 1, 0) INTO v_condition_ok
      FROM visit_request_campuses WHERE operational_contact_user_id = v_registrant;
    END IF;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('POSITIVE', 'POS-02', 'One account holding many campuses', 'NONE', 'ACCEPTED',
     COALESCE(v_sqlstate, 'NONE'),
     IF(v_raised, COALESCE(v_message, 'Unexpected SQL exception'),
        IF(v_condition_ok = 1, 'ACCEPTED', 'Post-condition failed')),
     IF(NOT v_raised AND v_condition_ok = 1, 'PASS', 'FAIL'));

  -- POS-03: the registrant may cancel their own request
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE; SET v_condition_ok = 0;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    -- push every campus of this request outside the 24h window first
    UPDATE visit_request_campuses
    SET planned_start_at = NOW() + INTERVAL 30 DAY,
        planned_end_at = NOW() + INTERVAL 30 DAY + INTERVAL 2 HOUR
    WHERE visit_request_id = v_open_request;
    UPDATE visit_requests
    SET status = 'CANCELLED', cancelled_by = v_registrant, cancelled_at = NOW(),
        cancellation_reason = 'guard probe: registrant self-service cancel'
    WHERE visit_request_id = v_open_request;
    IF NOT v_raised THEN
      SELECT COUNT(*) INTO v_condition_ok
      FROM visit_requests
      WHERE visit_request_id = v_open_request AND status = 'CANCELLED';
    END IF;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('POSITIVE', 'POS-03', 'Registrant cancels their own request', 'NONE', 'ACCEPTED',
     COALESCE(v_sqlstate, 'NONE'),
     IF(v_raised, COALESCE(v_message, 'Unexpected SQL exception'),
        IF(v_condition_ok = 1, 'ACCEPTED', 'Post-condition failed')),
     IF(NOT v_raised AND v_condition_ok = 1, 'PASS', 'FAIL'));

  -- POS-04: a PENDING identity change may exist without any account yet
  SET v_sqlstate = NULL; SET v_message = NULL; SET v_raised = FALSE; SET v_condition_ok = 0;
  START TRANSACTION;
  BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1 v_sqlstate = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      SET v_raised = TRUE;
    END;
    INSERT INTO visit_request_identity_changes
      (visit_request_id, visit_instance_id, change_kind, confirmation_method,
       new_email_normalized, new_email_masked, status, expected_request_row_version,
       requested_by, expires_at)
    VALUES
      (v_open_request, v_open_instance, 'INITIAL_CONFIRMATION', 'GOOGLE_SSO',
       'nobody.yet@example.com', 'n***@example.com', 'PENDING', 0, v_registrant,
       NOW() + INTERVAL 3 DAY);
    IF NOT v_raised THEN
      SELECT COUNT(*) INTO v_condition_ok
      FROM visit_request_identity_changes
      WHERE visit_instance_id = v_open_instance AND status = 'PENDING'
        AND new_user_id IS NULL;
    END IF;
  END;
  ROLLBACK;
  INSERT INTO pems_contact_guard_test_results
    (test_type, test_case, operation_summary, expected_sqlstate, expected_message,
     actual_sqlstate, actual_message, result)
  VALUES
    ('POSITIVE', 'POS-04', 'PENDING invitation with no account behind it yet', 'NONE', 'ACCEPTED',
     COALESCE(v_sqlstate, 'NONE'),
     IF(v_raised, COALESCE(v_message, 'Unexpected SQL exception'),
        IF(v_condition_ok = 1, 'ACCEPTED', 'Post-condition failed')),
     IF(NOT v_raised AND v_condition_ok = 1, 'PASS', 'FAIL'));

END$$
DELIMITER ;

CALL sp_pems_contact_guard_tests();
DROP PROCEDURE IF EXISTS sp_pems_contact_guard_tests;

SELECT sequence_no, test_type, test_case, operation_summary,
       expected_sqlstate, expected_message, actual_sqlstate, actual_message, result
FROM pems_contact_guard_test_results
ORDER BY sequence_no;

SELECT 'contact_guard_negative_failures' AS check_name,
       COUNT(*) AS issue_count
FROM pems_contact_guard_test_results
WHERE test_type = 'NEGATIVE' AND result <> 'PASS';

SELECT 'contact_guard_positive_failures' AS check_name,
       COUNT(*) AS issue_count
FROM pems_contact_guard_test_results
WHERE test_type = 'POSITIVE' AND result <> 'PASS';

-- =====================================================================
-- CONTACT / VISITOR ROLE GUARD — FINAL VERIFICATION QUERIES
-- Every issue_count must be 0 and every row-returning invalid query must return 0 rows.
-- =====================================================================

-- 12.1 Đầu mối vận hành đã liên kết phải là tài khoản ACTIVE. Expected: 0 rows.
--      KHÔNG kiểm tra role: tài khoản nội bộ được phép làm đầu mối (plan §1.7).
SELECT
    vrc.visit_instance_id,
    vrc.visit_request_id,
    vrc.status AS campus_status,
    vrc.operational_contact_user_id,
    u.email,
    u.status AS user_status
FROM visit_request_campuses vrc
JOIN users u
  ON u.user_id = vrc.operational_contact_user_id
WHERE u.status <> 'ACTIVE';

-- 12.2 Campus đã qua bước xác nhận mà thiếu đầu mối. Expected issue_count: 0.
SELECT COUNT(*) AS issue_count
FROM visit_request_campuses
WHERE status NOT IN ('WAITING_CONTACT_CONFIRMATION','CANCELLED')
  AND operational_contact_user_id IS NULL;

-- 12.3 Campus còn chờ xác nhận nhưng đã có đầu mối. Expected issue_count: 0.
SELECT COUNT(*) AS issue_count
FROM visit_request_campuses
WHERE status = 'WAITING_CONTACT_CONFIRMATION'
  AND operational_contact_user_id IS NOT NULL;

-- 12.4 Cổng xác nhận toàn cục: request rời PENDING_CONTACT_CONFIRMATION khi còn campus
--      active thiếu đầu mối. Expected: 0 rows.
SELECT
    vr.visit_request_id,
    vr.request_code,
    vr.status AS request_status,
    COUNT(vrc.visit_instance_id) AS unconfirmed_campus_count
FROM visit_requests vr
JOIN visit_request_campuses vrc
  ON vrc.visit_request_id = vr.visit_request_id
WHERE vr.status NOT IN ('PENDING_CONTACT_CONFIRMATION','CANCELLED')
  AND vrc.status <> 'CANCELLED'
  AND vrc.operational_contact_user_id IS NULL
GROUP BY vr.visit_request_id, vr.request_code, vr.status;

-- 12.5 Chiều ngược lại: request đứng ở PENDING_CONTACT_CONFIRMATION dù mọi campus đã có
--      đầu mối. Expected issue_count: 0.
SELECT COUNT(*) AS issue_count
FROM visit_requests vr
WHERE vr.status = 'PENDING_CONTACT_CONFIRMATION'
  AND NOT EXISTS (
    SELECT 1 FROM visit_request_campuses vrc
    WHERE vrc.visit_request_id = vr.visit_request_id
      AND vrc.status <> 'CANCELLED'
      AND vrc.operational_contact_user_id IS NULL
  );

-- 12.6 Identity change APPLIED phải trỏ tới tài khoản ACTIVE. Expected: 0 rows.
SELECT
    ic.identity_change_id,
    ic.visit_request_id,
    ic.visit_instance_id,
    ic.change_kind,
    ic.status,
    ic.new_user_id,
    u.status AS user_status
FROM visit_request_identity_changes ic
JOIN users u
  ON u.user_id = ic.new_user_id
WHERE ic.status = 'APPLIED'
  AND u.status <> 'ACTIVE';

-- 12.7 Identity change phải thuộc đúng campus của đúng request. Expected: 0 rows.
SELECT ic.identity_change_id, ic.visit_request_id, ic.visit_instance_id
FROM visit_request_identity_changes ic
LEFT JOIN visit_request_campuses vrc
  ON vrc.visit_instance_id = ic.visit_instance_id
 AND vrc.visit_request_id  = ic.visit_request_id
WHERE vrc.visit_instance_id IS NULL;

-- 12.8 Mỗi campus tối đa một identity change PENDING. Expected issue_count: 0.
SELECT COUNT(*) AS issue_count FROM (
  SELECT visit_instance_id
  FROM visit_request_identity_changes
  WHERE status = 'PENDING'
  GROUP BY visit_instance_id
  HAVING COUNT(*) > 1
) dup;

-- 12.9 ASSIGNED phải CÓ trong vòng đời campus (Staff Leader duyệt + gán Host, Host chưa bắt đầu
-- chuẩn bị). Expected issue_count: 0.
SELECT 'campus_status_enum_missing_assigned' AS check_name,
       CASE WHEN LOCATE('''ASSIGNED''', column_type) > 0 THEN 0 ELSE 1 END AS issue_count
FROM information_schema.columns
WHERE table_schema = DATABASE()
  AND table_name = 'visit_request_campuses'
  AND column_name = 'status';

-- 12.9b Campus ở ASSIGNED nghĩa là Host CHƯA bắt đầu chuẩn bị, nên không được có dữ liệu setup nào.
-- Một dòng ở đây nghĩa là mutation setup đã lọt qua cổng chuẩn bị. Expected issue_count: 0.
SELECT 'assigned_campus_with_setup_data' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses c
WHERE c.status = 'ASSIGNED'
  AND (EXISTS (SELECT 1 FROM visit_agendas a WHERE a.visit_instance_id = c.visit_instance_id)
    OR EXISTS (SELECT 1 FROM visit_participants p WHERE p.visit_instance_id = c.visit_instance_id)
    OR EXISTS (SELECT 1 FROM visit_logistics_items l WHERE l.visit_instance_id = c.visit_instance_id)
    OR EXISTS (SELECT 1 FROM visit_instance_reminder_settings r WHERE r.visit_instance_id = c.visit_instance_id));

-- 12.9c Campus ở ASSIGNED phải có Host và quyết định — đó chính là nghĩa của trạng thái này.
-- Expected issue_count: 0.
SELECT 'assigned_campus_without_host_or_decision' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses
WHERE status = 'ASSIGNED'
  AND (current_host_user_id IS NULL OR decided_by IS NULL OR decided_at IS NULL);

-- 12.10 Các cột mô hình đầu mối cấp request phải biến mất hoàn toàn. Expected issue_count: 0.
SELECT 'request_level_contact_columns_remaining' AS check_name,
       COUNT(*) AS issue_count
FROM information_schema.columns
WHERE table_schema = DATABASE()
  AND table_name = 'visit_requests'
  AND column_name IN (
    'visitor_user_id',
    'contact_person_full_name', 'contact_person_organization',
    'contact_person_phone', 'contact_person_email',
    'primary_contact_access_status', 'primary_contact_verified_at'
  );

-- 12.11 note_to_fptu đã bị xóa. Expected issue_count: 0.
SELECT 'note_to_fptu_column_remaining' AS check_name,
       COUNT(*) AS issue_count
FROM information_schema.columns
WHERE table_schema = DATABASE()
  AND column_name = 'note_to_fptu';

SELECT 'required_contact_guard_triggers_present' AS check_name,
       6 - COUNT(*) AS issue_count
FROM information_schema.triggers
WHERE trigger_schema = DATABASE()
  AND trigger_name IN (
    'trg_visit_campuses_op_contact_guard_bi',
    'trg_visit_campuses_op_contact_guard_bu',
    'trg_visit_requests_contact_gate_guard_bu',
    'trg_users_protect_operational_contact_bu',
    'trg_visit_request_identity_changes_user_guard_bi',
    'trg_visit_request_identity_changes_user_guard_bu'
  );

-- =====================================================================
-- MERGED ADDITIVE SEED — PARTNER/GALLERY I18N + GOOGLE CLOUD APIS
-- =====================================================================
-- FAQ translation contract:
--   * faqs.question/answer remain the canonical Vietnamese source.
--   * faq_translations stores normalized VI and persisted EN rows for public reads.
--   * Translation API is invoked on create/update when EN needs regeneration, not on each public read.
--   * Missing/FAILED/OUTDATED EN falls back to VI in application code.

-- 1. Backfill canonical Vietnamese FAQ rows without calling an external API.
INSERT INTO faq_translations (
  faq_id,
  language_code,
  question,
  answer,
  translation_source,
  translation_status,
  source_hash,
  translated_at,
  created_at,
  created_by,
  updated_at,
  updated_by
)
SELECT
  f.faq_id,
  'vi',
  f.question,
  f.answer,
  'LEGACY',
  'READY',
  SHA2(CONCAT_WS(CHAR(31), f.question, f.answer), 256),
  COALESCE(f.updated_at, f.created_at),
  f.created_at,
  f.created_by,
  f.updated_at,
  f.updated_by
FROM faqs f
WHERE NOT EXISTS (
  SELECT 1
  FROM faq_translations ft
  WHERE ft.faq_id = f.faq_id
    AND ft.language_code = 'vi'
);

-- 2. Backfill canonical Vietnamese Partner rows.
INSERT INTO partner_translations (
  partner_id, language_code, name, short_name, country, city, description, address,
  translation_source, translation_status, source_hash, translated_at,
  created_at, created_by, updated_at, updated_by
)
SELECT
  p.partner_id,
  'vi',
  p.name,
  p.short_name,
  p.country,
  p.city,
  p.description,
  p.address,
  'LEGACY',
  'READY',
  SHA2(CONCAT_WS(CHAR(31), p.name, COALESCE(p.short_name, ''),
    COALESCE(p.country, ''), COALESCE(p.city, ''),
    COALESCE(p.description, ''), COALESCE(p.address, '')), 256),
  COALESCE(p.updated_at, p.created_at),
  p.created_at,
  p.created_by,
  p.updated_at,
  p.updated_by
FROM partners p
WHERE NOT EXISTS (
  SELECT 1 FROM partner_translations pt
  WHERE pt.partner_id = p.partner_id AND pt.language_code = 'vi'
);

-- 3. Seed reviewed English FAQ rows from the I18N donor build.
INSERT INTO faq_translations (
  faq_id,
  language_code,
  question,
  answer,
  translation_source,
  translation_status,
  source_hash,
  translated_at,
  created_at,
  created_by,
  updated_at,
  updated_by
) VALUES
  (1, 'en', 'How far in advance should I submit a visit request?', 'Submit the request at least 72 hours before the planned visit. Each campus checks its own schedule and reception capacity independently.', 'MANUAL', 'READY', '0de434980e36cb801f4ddb899ba3e13ac5feb08583df7a7b3b1d239e4153d2fc', '2026-03-10 09:00:00', '2026-03-10 09:00:00', 2, NULL, NULL),
  (2, 'en', 'Why does each campus need its own delegation contact?', 'The delegation contact is confirmed separately for each campus so the Host has a direct person to coordinate schedules, guest lists and changes.', 'MANUAL', 'READY', '016e554eaec6d00ecf73f18c0270142396f50b1d673df0d660b8684199e193a3', '2026-03-10 09:05:00', '2026-03-10 09:05:00', 2, NULL, NULL),
  (3, 'en', 'What should I do if I have not received the account confirmation email?', 'Check the spam folder and use Resend after the cooldown. Each confirmation code is single-use and expires.', 'MANUAL', 'READY', '80b524f9459ae06d6c35f2e2da367e3e473aef42d714835b7d6d7628274bf66d', '2026-03-10 09:10:00', '2026-03-10 09:10:00', 1, NULL, NULL),
  (4, 'en', 'When can a Host create a logistics request?', 'Logistics can be updated only after the Host starts preparation and the campus reaches BEFORE_VISIT.', 'MANUAL', 'READY', '58b145db0026b594f9d1f86cdf2641ced9d8c4f0a7bcb9739926885d1f2f41af', '2026-03-10 09:15:00', '2026-03-10 09:15:00', 5, NULL, NULL),
  (5, 'en', 'Where can I read news about partner visits?', 'Approved and published stories appear on the News page. Hidden or pending content is available only to authorised users.', 'MANUAL', 'READY', 'b35e7db446f84da8e0d6737c721d942eb2b2c6f44a9cd147aa3b05a4300bc6a6', '2026-03-10 09:20:00', '2026-03-10 09:20:00', 2, NULL, NULL),
  (6, 'en', 'How may delegation photographs be used?', 'Only images covered by valid consent may be published. Removed face tags must not be used for identification in the interface.', 'MANUAL', 'READY', '6ed0017c59e20acfcde6ac930a36119bec022683d349643a1fa49f121924e91e', '2026-03-10 09:25:00', '2026-03-10 09:25:00', 2, NULL, NULL),
  (7, 'en', 'Where are visit minutes stored?', 'Minutes belong to the relevant campus instance and are visible only to users with an authorised relationship, right or task.', 'MANUAL', 'READY', 'f44815c2f162659d2a3a2752ccef082cc36e27a3816739280ed07fd7c62aae82', '2026-03-10 09:30:00', '2026-03-10 09:30:00', 2, NULL, NULL),
  (8, 'en', 'Who can send a preparation-progress email?', 'The campus Current Host can prepare, preview and send the email under the configured recipient and history policies.', 'MANUAL', 'READY', '1fa88042df62b7eae8678a883b84d4b26e679774aced1f74f4c0cf203f52a2c3', '2026-03-10 09:35:00', '2026-03-10 09:35:00', 1, NULL, NULL),
  (16001, 'en', 'Can Head Office process a request instead of the Staff Leader?', 'No. Head Office monitors progress and reads aggregate reports but does not make campus decisions.', 'MANUAL', 'READY', 'ce45132e3932877b1847275b952f52b9860360bf03dda0c9b3164ff9df0e42f1', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16002, 'en', 'When is a partner profile published?', 'Sources, active contacts and visibility scope must be reviewed before the profile is published.', 'MANUAL', 'READY', 'c68adf775caf125c1a431b7af24725b1edd4405b1aaac222fa8a1d702c07b190', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16003, 'en', 'Can I search by a guest''s name?', 'Search respects access scope. Data from a hidden campus cannot affect results, counts or ordering.', 'MANUAL', 'READY', '676dd1a7a2ba849ea944c77df62b638b9608f07d1bae09986dce24f2130f178d', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16004, 'en', 'Do calendar events support reminders?', 'Users may receive reminders based on event configuration and their participation relationship.', 'MANUAL', 'READY', '0dbd3530483bc8e2645a0a540cb2e40b62d6e9f0c3a22784f52e6853b50c75e6', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16005, 'en', 'How is post-visit feedback used?', 'Feedback helps evaluate the Host, logistics and overall experience, subject to role-based visibility.', 'MANUAL', 'READY', 'bb2d293562e230b33d2de244be4cd2edf2c4166153756f72f6e49f64d7ec5f1c', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16006, 'en', 'Why is a news story hidden?', 'A story may be hidden after a schedule change, missing photo consent or a required correction to published information.', 'MANUAL', 'READY', 'd1aef4e7d2b59e8183d1372ffc8ce6a34f96ef7612f3abe11b6cc9fd202fcc9e', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16007, 'en', 'Where are uploaded documents stored?', 'Files are stored through the configured provider and linked to the correct business owner for access checks.', 'MANUAL', 'READY', 'c67c41169589bf3eddf28cca4cd203400a48e2e34ad733f5772ab8390c38d44e', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16008, 'en', 'Can I view the request''s change history?', 'Important changes are recorded in revision history and audit logs within the viewer''s authorised scope.', 'MANUAL', 'READY', '4f9d794b6a0c7f42a638717e3cfdf68e5cd5ae1530f27df18beb8dbe382df976', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16009, 'en', 'Can an invited participant decline?', 'Yes. The participant can accept or decline, and the Host sees the response when adjusting the programme.', 'MANUAL', 'READY', '12e16d7611b83d82771adb7495cfc7b2bd7e096cc980c38792fb28b5cb30bec2', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16010, 'en', 'How is a Proposed Host different from the Current Host?', 'A Proposed Host is only a pre-gate proposal. The Current Host is the person activated or officially assigned after the gate.', 'MANUAL', 'READY', '78fafc4829110c3471fa56e865222c66cd6220844ca47434f99aa8021f277c9d', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16011, 'en', 'Why is an action button not displayed?', 'Buttons are rendered only from backend capabilities. The client does not infer permission from a role or status label.', 'MANUAL', 'READY', 'ddf801a8c76a34dd61e9e31d754b57f48350ff579556f1e3a586363aa5a484d7', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16012, 'en', 'Can the Current Host be transferred?', 'The Staff Leader may transfer the Host under lifecycle and time rules. A Host transfer does not automatically change the campus stage.', 'MANUAL', 'READY', 'f5896c110e6d772a53e8b19c4e341e4c17c931e67646d849817b91b18f1b809c', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16013, 'en', 'Where does contact information in an email come from?', 'Email uses the sender or contact source allowed by the template policy. Unsupported system blocks cannot be inserted.', 'MANUAL', 'READY', '16966af0d081fc4d6e8acc375e5506a13184f3b7732da239dd94cf1d911ef6a5', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16014, 'en', 'How can incorrect news content be reported?', 'An authorised editor can hide the story, correct its sources and submit it through review again.', 'MANUAL', 'READY', '4613e52bb60457685e8d9f78de8d5999dcbe2b5b0b5cb445b2d3fa981d79c577', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16015, 'en', 'Why can a file not be previewed?', 'The file may have been deleted, no longer be authorised, or have an invalid provider identifier.', 'MANUAL', 'READY', 'ac7b7ad20571e6484afd87e37fbe6e6bfad375979e0370905a32b31b4da870c1', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16016, 'en', 'How is English content managed?', 'Bilingual content uses separate translations. When an approved translation is unavailable, the configured fallback rule applies.', 'MANUAL', 'READY', 'f576ee6f82a21249853808cfbd2b9b2baddb0409774300ded218569178da120d', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16017, 'en', 'Who decides a visit request at each campus?', 'The Staff Leader of that campus makes the decision. Head Office monitors the overall request but does not approve or reject on behalf of a campus.', 'MANUAL', 'READY', '4f1791bc9d6660de9cae96f044ade8981afb025494466881ce78d241cea3f170', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16018, 'en', 'Can I edit a visit request after submitting it?', 'You can edit it while the current state and time limit allow. The latest row version is required to prevent overwriting another change.', 'MANUAL', 'READY', '6fe78a6185b60459e2d9cc23522db0a57f087764532cfd94cfe58434eda0c0ed', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16019, 'en', 'If one campus rejects the request, are the other campuses cancelled?', 'No. Each campus is processed independently, and the request-level result is calculated from all campus outcomes.', 'MANUAL', 'READY', '361d8232c1c71ef6fa90ee59474e8bd23741bb7227362f20adf313da2f234ecc', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16020, 'en', 'When can the reception Host start preparing?', 'After the campus is approved and a Current Host exists, the Host must select Start preparation. Agenda and logistics updates are allowed only in BEFORE_VISIT.', 'MANUAL', 'READY', '505758586d1e1db5509764aa5b1a6a44079d6340d657af613c88e89573b6d823', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16021, 'en', 'Why is sign-in refused even though the email is correct?', 'The account may still be awaiting confirmation, be locked, or lack access to the selected portal. The error message explains the applicable next step.', 'MANUAL', 'READY', 'd7fce44ddc71b08069fb08e70a37f629b5454be5f91320e497ae4f9d815f1d60', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16022, 'en', 'Can I change an email address that is awaiting confirmation?', 'Yes, while the confirmation is still pending. Saving the new address invalidates the previous confirmation code.', 'MANUAL', 'READY', 'eb554eb0fb5fc2f669ed3d2f5a77fecc6d664944807c9130d8bc5d7d7561d9ea', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16023, 'en', 'Can an internal account submit a visit request?', 'Only roles allowed by policy may register visits. Permission to register does not grant campus approval or Host-assignment rights.', 'MANUAL', 'READY', '1e8b473aa0b6e4b3bc033abcd051942f400848849708d261839bc4852c5b97b6', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16024, 'en', 'How do I reset my password?', 'Use Forgot password to receive an OTP. Sensitive email content is not retained in sent-email history.', 'MANUAL', 'READY', '330302b5100fb932e9a27ae9ce9f490b17c01c150ba41037526b907e74d91ee2', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16025, 'en', 'Who receives a logistics request from the Host?', 'The request is routed to the appropriate department or staff member. The recipient may accept, decline or propose a change.', 'MANUAL', 'READY', '1e430c5e8e0af6687cc46e64e45b75c4898be0eab04205c22b1c41c3aefc0066', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16026, 'en', 'Can the quantity be changed after a department receives the request?', 'The supporting unit may propose a new quantity or service time. The Host reviews the proposal before it is applied.', 'MANUAL', 'READY', '29b586dcb29af5be2be997ab1e874ebd4d88ca53aebb8f1b5a3cb0a8b2c7b3d2', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16027, 'en', 'How do I know that a logistics item is complete?', 'The assignee updates the status and handover note. The Host checks the result before the programme begins.', 'MANUAL', 'READY', 'a38f0a61d175f975e1e5bbc16ed756f4ecf1fca9f028f2e414e042b1a2bbd708', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16028, 'en', 'Can I cancel a logistics item?', 'Cancellation is allowed only in eligible states and time windows. The reason is retained for related users.', 'MANUAL', 'READY', '5c94742c5b0e6efe82ce004a420fc28356e604781992bf4e649754bafdfa3ddf', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16029, 'en', 'Who closes a visit record?', 'An authorised post-visit actor closes the record after required minutes, feedback and follow-up items are complete.', 'MANUAL', 'READY', '54aee808331be2a4155eb070a43c86333df571c5d6ef159c5397a0a18b0c22c9', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16030, 'en', 'Can a guest list be imported from Excel?', 'Use a supported template. Imported data must still pass name, email and campus-scope validation.', 'MANUAL', 'READY', 'f90101a8e080c33c7fba987884a60b29c35903094c23ac4352f23d9f1ff6346e', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16031, 'en', 'Why is the request status different from a campus status?', 'The request status is an aggregate outcome, while each campus has its own lifecycle. Scoped users see only their campus result.', 'MANUAL', 'READY', 'd1170089043d23811c2755842d88753c648434312b90e73afff76bc0baefc98c', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16032, 'en', 'Can a notification be marked as read?', 'Yes. Read state is stored per recipient and does not change the business state of the visit request.', 'MANUAL', 'READY', 'e3b8009f7f72ca468e6573cf8811805f8b376b0c67a723be45b35972a0d48906', '2026-08-17 08:00:00', '2026-08-17 08:00:00', 2, NULL, NULL),
  (16033, 'en', 'How can I track the processing status of a visiting delegation?', 'Users open the delegation management screen and filter by status and campus within their authorized scope. The system only displays delegations that fall within the user''s scope.', 'MANUAL', 'READY', '76154e0e6c91b32abf15e1c7f332fe5b7378b0df54f3a82b5cbf3dfe3c8161bc', '2026-08-17 09:00:00', '2026-08-17 09:00:00', 2, NULL, NULL),
  (16034, 'en', 'Why can''t I see a delegation at another campus?', 'PEMS restricts data by role, sub-role, campus, department, and assignment relationships. Users outside the relevant scope cannot see that delegation.', 'MANUAL', 'READY', '4e89174d4476e672848b7233ee1be6cbc2e026f392d363cff89e0286680d1060', '2026-08-17 09:05:00', '2026-08-17 09:05:00', 2, NULL, NULL),
  (16035, 'en', 'Where can I download documents or photos from a visit?', 'Documents, photos, and gallery content related to a visit can be accessed from the delegation detail screen or the Document/Gallery module when the user has permission for the relevant scope.', 'MANUAL', 'READY', '3016e97ca13fdf4d9a410e6d9270f4f4539118fb81fb44c592c1fc0af42b5e1a', '2026-08-17 09:10:00', '2026-08-17 09:10:00', 2, NULL, NULL),
  (16036, 'en', 'Why are some photos or documents not displayed publicly?', 'Some files have internal or private visibility. The system does not display them publicly if they have not been approved or are outside the user''s viewing scope.', 'MANUAL', 'READY', '165a8e76029501525c380b4ca2cb4ec247f5cbbbc82de319b1333dbe88bd9643', '2026-08-17 09:15:00', '2026-08-17 09:15:00', 2, NULL, NULL),
  (16037, 'en', 'What should I do when I receive a confirmation email from PEMS?', 'The recipient clicks Confirm, Decline, or Negotiate in the email. The system records the response using a one-time token and does not require login for the token-authorized email action.', 'MANUAL', 'READY', '3b3b65c09342554bcd926b7ec0b1b9e4fd68585459d4d2d05aa7efa1e8249fd6', '2026-08-17 09:20:00', '2026-08-17 09:20:00', 2, NULL, NULL),
  (16038, 'en', 'What happens if I click a button in an old email again?', 'If the response has already been recorded, the system does not update it a second time and shows a message that you have already responded to this request.', 'MANUAL', 'READY', '328678c09baa2c23a619dd7129975143b2cbfc810eeae6bdf7abd69833559edb', '2026-08-17 09:25:00', '2026-08-17 09:25:00', 2, NULL, NULL)
