INSERT INTO api_usage_quotas (
  api_config_id,
  campus_id,
  campus_scope_key,
  period_yyyymm,
  monthly_limit,
  used_count,
  created_by
)
SELECT
  c.api_config_id,
  NULL,
  'GLOBAL',
  DATE_FORMAT(CURRENT_DATE(), '%Y%m'),
  c.monthly_quota,
  0,
  1
FROM api_configurations c
WHERE c.api_code = 'FACE_DETECTION_GOOGLE_VISION'
  AND c.monthly_quota IS NOT NULL
  AND NOT EXISTS (
    SELECT 1
    FROM api_usage_quotas q
    WHERE q.api_config_id = c.api_config_id
      AND q.campus_scope_key = 'GLOBAL'
      AND q.period_yyyymm = DATE_FORMAT(CURRENT_DATE(), '%Y%m')
  );

-- ---------------------------------------------------------------------
-- 6. Google Vision / face-scan additive verification.
-- ---------------------------------------------------------------------
SELECT 'google_vision_face_scan_schema' AS check_name,
       CASE
         WHEN EXISTS (
           SELECT 1
           FROM information_schema.tables
           WHERE table_schema = DATABASE()
             AND table_name = 'visit_photo_face_scans'
         )
          AND EXISTS (
           SELECT 1
           FROM information_schema.tables
           WHERE table_schema = DATABASE()
             AND table_name = 'visit_photo_face_detections'
         )
         THEN 0 ELSE 1
       END AS issue_count;

SELECT 'google_vision_api_config_seeded' AS check_name,
       CASE WHEN COUNT(*) = 1 THEN 0 ELSE 1 END AS issue_count
FROM api_configurations
WHERE api_config_id = 21009
  AND api_code = 'FACE_DETECTION_GOOGLE_VISION'
  AND provider_name = 'GOOGLE_CLOUD_VISION'
  AND purpose = 'FACE_DETECTION'
  AND secret_ref = 'GOOGLE_VISION_SERVICE_ACCOUNT'
  AND credentials_json_encrypted IS NULL;

SELECT 'google_vision_quota_seeded' AS check_name,
       CASE WHEN COUNT(*) = 1 THEN 0 ELSE 1 END AS issue_count
FROM api_usage_quotas q
JOIN api_configurations c
  ON c.api_config_id = q.api_config_id
WHERE c.api_code = 'FACE_DETECTION_GOOGLE_VISION'
  AND q.campus_scope_key = 'GLOBAL'
  AND q.period_yyyymm = DATE_FORMAT(CURRENT_DATE(), '%Y%m');

-- ---------------------------------------------------------------------
-- 7. Merged feature verification. Every issue_count must be 0.
-- ---------------------------------------------------------------------
SELECT 'partner_translation_orphans' AS check_name, COUNT(*) AS issue_count
FROM partner_translations pt
LEFT JOIN partners p ON p.partner_id = pt.partner_id
WHERE p.partner_id IS NULL;

SELECT 'partner_vi_en_seed_coverage' AS check_name, COUNT(*) AS issue_count
FROM partners p
WHERE NOT EXISTS (
  SELECT 1 FROM partner_translations pt
  WHERE pt.partner_id = p.partner_id
    AND pt.language_code = 'vi'
    AND pt.translation_status = 'READY'
)
OR NOT EXISTS (
  SELECT 1 FROM partner_translations pt
  WHERE pt.partner_id = p.partner_id
    AND pt.language_code = 'en'
    AND pt.translation_status = 'READY'
);

SELECT 'gallery_i18n_columns_present' AS check_name,
       25 - COUNT(*) AS issue_count
FROM information_schema.columns
WHERE table_schema = DATABASE()
  AND (
       (table_name = 'gallery_areas' AND column_name IN
         ('area_name_en','translation_source','translation_status','translation_source_hash','translated_at'))
    OR (table_name = 'gallery_locations' AND column_name IN
         ('location_name_en','translation_source','translation_status','translation_source_hash','translated_at'))
    OR (table_name = 'gallery_items' AND column_name IN
         ('title_en','translation_source','translation_status','translation_source_hash','translated_at'))
    OR (table_name = 'gallery_item_media' AND column_name IN
         ('caption_en','alt_text_en','translation_source','translation_status','translation_source_hash','translated_at'))
    OR (table_name = 'gallery_item_contents' AND column_name IN
         ('translation_source','translation_status','translation_source_hash','translated_at'))
  );

SELECT 'faq_translation_orphans' AS check_name, COUNT(*) AS issue_count
FROM faq_translations ft
LEFT JOIN faqs f ON f.faq_id = ft.faq_id
WHERE f.faq_id IS NULL;

SELECT 'faq_vi_en_seed_coverage' AS check_name,
       COUNT(*) AS issue_count
FROM faqs f
WHERE NOT EXISTS (
  SELECT 1
  FROM faq_translations ft
  WHERE ft.faq_id = f.faq_id
    AND ft.language_code = 'vi'
    AND ft.translation_status = 'READY'
)
OR NOT EXISTS (
  SELECT 1
  FROM faq_translations ft
  WHERE ft.faq_id = f.faq_id
    AND ft.language_code = 'en'
    AND ft.translation_status = 'READY'
);

SELECT 'translation_api_config_seeded' AS check_name,
       CASE WHEN COUNT(*) = 1 THEN 0 ELSE 1 END AS issue_count
FROM api_configurations
WHERE api_config_id = 21008
  AND api_code = 'NEWS_TRANSLATION_GOOGLE_CLOUD'
  AND provider_name = 'GOOGLE_CLOUD_TRANSLATION'
  AND secret_ref = 'GOOGLE_TRANSLATION_SERVICE_ACCOUNT'
  AND credentials_json_encrypted IS NULL
  AND status = 'INACTIVE'
  AND last_test_status IS NULL
  AND last_tested_at IS NULL
  AND last_test_message IS NULL;

SELECT 'face_scan_orphans' AS check_name, COUNT(*) AS issue_count
FROM visit_photo_face_scans s
LEFT JOIN visit_photos p
  ON p.visit_photo_id = s.visit_photo_id
 AND p.visit_request_id = s.visit_request_id
 AND p.visit_instance_id = s.visit_instance_id
 AND p.file_id = s.file_id
WHERE p.visit_photo_id IS NULL;

SELECT 'face_detection_orphans' AS check_name, COUNT(*) AS issue_count
FROM visit_photo_face_detections d
LEFT JOIN visit_photo_face_scans s
  ON s.face_scan_id = d.face_scan_id
 AND s.visit_request_id = d.visit_request_id
 AND s.visit_instance_id = d.visit_instance_id
 AND s.file_id = d.file_id
WHERE s.face_scan_id IS NULL;

SELECT 'fingerprint_guard_table_present' AS check_name,
       CASE WHEN COUNT(*) = 1 THEN 0 ELSE 1 END AS issue_count
FROM information_schema.tables
WHERE table_schema = DATABASE()
  AND table_name = 'visit_request_fingerprint_guards'
  AND table_type = 'BASE TABLE';

-- 81 since the three email_draft* tables were dropped (compose no longer persists a draft).
-- This assertion also stops being off by one: it read 83 while the script produced 84, so every
-- import reported a permanent issue_count of 1.
SELECT 'merged_runtime_table_count' AS check_name,
       CASE WHEN COUNT(*) = 81 THEN 0 ELSE ABS(COUNT(*) - 81) END AS issue_count
FROM information_schema.tables
WHERE table_schema = DATABASE()
  AND table_type = 'BASE TABLE';

-- =====================================================================
-- PURE V2-ONLY FINAL ASSERTIONS
-- =====================================================================
DROP PROCEDURE IF EXISTS sp_pems_assert_pure_v2_only;
DELIMITER $$
CREATE PROCEDURE sp_pems_assert_pure_v2_only()
BEGIN
  DECLARE v_issue_count BIGINT DEFAULT 0;

  SELECT COUNT(*) INTO v_issue_count
  FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'visit_requests'
    AND column_name IN (
      'delegation_name','visit_type','visit_type_other','purpose','working_content',
      'working_language','transportation_note','media_consent_status',
      'media_consent_note','note_to_fptu',
      -- hard cutover: mô hình đầu mối cấp request
      'visitor_user_id','contact_person_full_name','contact_person_organization',
      'contact_person_phone','contact_person_email',
      'primary_contact_access_status','primary_contact_verified_at'
    );
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_LEGACY_COLUMNS_PRESENT';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_requests vr
  LEFT JOIN visit_request_campuses vrc
    ON vrc.visit_request_id = vr.visit_request_id
  WHERE vrc.visit_instance_id IS NULL;
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_REQUEST_WITHOUT_CAMPUS';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  LEFT JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
  WHERE d.visit_instance_id IS NULL;
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_MISSING_INSTANCE_DETAILS';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_instance_form_details d
  LEFT JOIN visit_request_campuses vrc ON vrc.visit_instance_id = d.visit_instance_id
  WHERE vrc.visit_instance_id IS NULL;
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_ORPHAN_INSTANCE_DETAILS';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_requests vr
  LEFT JOIN (
    SELECT visit_request_id, COUNT(*) AS campus_count
    FROM visit_request_campuses
    GROUP BY visit_request_id
  ) c ON c.visit_request_id = vr.visit_request_id
  WHERE c.campus_count IS NULL
     OR (vr.visit_scope = 'SINGLE_CAMPUS' AND c.campus_count <> 1)
     OR (vr.visit_scope = 'MULTI_CAMPUS' AND c.campus_count < 2);
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_SCOPE_INSTANCE_MISMATCH';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_guest_members m
  JOIN visit_request_campuses vrc ON vrc.visit_request_id = m.visit_request_id
  LEFT JOIN visit_instance_guest_members l
    ON l.visit_instance_id = vrc.visit_instance_id
   AND l.guest_member_id = m.guest_member_id
  WHERE l.guest_member_id IS NULL;
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_MEMBER_LINK_GAPS';
  END IF;

  -- Cổng xác nhận đầu mối phải nhất quán hai chiều.
  SELECT COUNT(*) INTO v_issue_count
  FROM visit_requests vr
  WHERE (vr.status <> 'PENDING_CONTACT_CONFIRMATION' AND vr.status <> 'CANCELLED' AND EXISTS (
          SELECT 1 FROM visit_request_campuses c
          WHERE c.visit_request_id = vr.visit_request_id
            AND c.status <> 'CANCELLED' AND c.operational_contact_user_id IS NULL))
     OR (vr.status = 'PENDING_CONTACT_CONFIRMATION' AND NOT EXISTS (
          SELECT 1 FROM visit_request_campuses c
          WHERE c.visit_request_id = vr.visit_request_id
            AND c.status <> 'CANCELLED' AND c.operational_contact_user_id IS NULL));
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_CONTACT_GATE_MISMATCH';
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM information_schema.tables
  WHERE table_schema = DATABASE()
    AND LEFT(table_name, 10) = 'pems_seed_';
  IF v_issue_count <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PURE_V2_REFUSED_SEED_HELPER_OBJECT_PRESENT';
  END IF;
END$$
DELIMITER ;

CALL sp_pems_assert_pure_v2_only();
DROP PROCEDURE IF EXISTS sp_pems_assert_pure_v2_only;

-- Final evidence: every issue_count must be 0.
SELECT 'pure_v2_legacy_columns' AS check_name, COUNT(*) AS issue_count
FROM information_schema.columns
WHERE table_schema = DATABASE()
  AND table_name = 'visit_requests'
  AND column_name IN (
    'delegation_name','visit_type','visit_type_other','purpose','working_content',
    'working_language','transportation_note','media_consent_status',
    'media_consent_note','note_to_fptu',
    'visitor_user_id','contact_person_full_name','contact_person_organization',
    'contact_person_phone','contact_person_email',
    'primary_contact_access_status','primary_contact_verified_at'
  );

SELECT 'pure_v2_requests_without_campus' AS check_name, COUNT(*) AS issue_count
FROM visit_requests vr
LEFT JOIN visit_request_campuses vrc
  ON vrc.visit_request_id = vr.visit_request_id
WHERE vrc.visit_instance_id IS NULL;

SELECT 'pure_v2_scope_instance_count_mismatch' AS check_name, COUNT(*) AS issue_count
FROM visit_requests vr
LEFT JOIN (
  SELECT visit_request_id, COUNT(*) AS campus_count
  FROM visit_request_campuses
  GROUP BY visit_request_id
) c ON c.visit_request_id = vr.visit_request_id
WHERE c.campus_count IS NULL
   OR (vr.visit_scope = 'SINGLE_CAMPUS' AND c.campus_count <> 1)
   OR (vr.visit_scope = 'MULTI_CAMPUS' AND c.campus_count < 2);

SELECT 'pure_v2_missing_instance_details' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
LEFT JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
WHERE d.visit_instance_id IS NULL;

SELECT 'pure_v2_seed_helper_objects' AS check_name, COUNT(*) AS issue_count
FROM information_schema.tables
WHERE table_schema = DATABASE()
  AND LEFT(table_name, 10) = 'pems_seed_';

-- Restore the session setting that existed before this full seed started.
SET SESSION SQL_SAFE_UPDATES = @pems_previous_sql_safe_updates;

-- ============================================================================
-- PEMS CURATED SEED REBUILD — HANOI ACTOR JOURNEYS / NO SPAM
-- Seed-only DML patch. It does NOT CREATE, ALTER, DROP, TRUNCATE, or rename any
-- persistent table. Apply after the supplied full-create SQL, or use the bundled
-- full file PEMS_FULL_V2_CURATED_SEED_FIXED.sql.
--
-- Design goals:
--   * remove the 3001..3090 / 5001..5160 repeated "coverage" request factory;
--   * remove numbered FAQ/news/feedback rows that differ only by an ID/status;
--   * add deliberate, named, business-readable cases for the screenshot accounts;
--   * preserve canonical per-campus approval, self-host, ownership and feedback rules;
--   * keep each seed row explicit: no loops, no generated SQL procedures, no fake #N text.
-- ============================================================================

SET NAMES utf8mb4;
SET time_zone = '+07:00';
SET @pems_old_fk_checks := @@FOREIGN_KEY_CHECKS;
SET @pems_old_safe_updates := @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

-- ---------------------------------------------------------------------------
-- A. Remove the old repetitive visit factory and every dependent business row.
-- ---------------------------------------------------------------------------

-- Feedback and normalized criteria.
DELETE fri FROM feedback_rating_items fri
JOIN feedbacks f ON f.feedback_id = fri.feedback_id
WHERE f.visit_request_id BETWEEN 3001 AND 3090
   OR f.visit_instance_id BETWEEN 5001 AND 5160
   OR f.feedback_id BETWEEN 13001 AND 13018;
