INSERT INTO visit_agendas (agenda_id, visit_instance_id, sequence_order, title, description, start_time, end_time, location, responsible_user_id, source_template_item_id, created_at, created_by, updated_at, updated_by) VALUES
  (45001, 42002, 1, 'Đón đoàn British Council Digital Skills Roundtable', 'Host xác nhận thành phần của British Council Digital Skills Roundtable, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Chuẩn bị chương trình kỹ năng số cho sinh viên và cơ chế đồng tổ chức hoạt động tại campus Hà Nội.', CURRENT_DATE + INTERVAL 14 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 14 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 4 DAY, @u_sl_hn, NULL, NULL),
  (45002, 42002, 2, 'Phiên làm việc chuyên môn với British Council Digital Skills Roundtable', 'Hai bên thống nhất phạm vi workshop, tiêu chí lựa chọn giảng viên, phương án truyền thông và mốc rà soát nội dung trước ngày tổ chức. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 14 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 14 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 4 DAY, @u_sl_hn, NULL, NULL),
  (45003, 42003, 1, 'Đón đoàn Osaka AI Laboratories Academic Visit', 'Host xác nhận thành phần của Osaka AI Laboratories Academic Visit, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Khảo sát phòng lab trí tuệ nhân tạo và thảo luận cơ hội đồng hướng dẫn đồ án sinh viên.', CURRENT_DATE + INTERVAL 3 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 3 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 5 DAY, @u_sl_hn, NULL, NULL),
  (45004, 42003, 2, 'Phiên làm việc chuyên môn với Osaka AI Laboratories Academic Visit', 'Đoàn tham quan AI Lab, gặp nhóm giảng viên phụ trách computer vision và rà soát đề cương ba đề tài có thể triển khai trong năm học tới. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 3 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 3 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 5 DAY, @u_sl_hn, NULL, NULL),
  (45005, 42004, 1, 'Đón đoàn Korea Foundation Culture Exchange Mission', 'Host xác nhận thành phần của Korea Foundation Culture Exchange Mission, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Tổ chức phiên giao lưu văn hóa Hàn Quốc - Việt Nam và trao đổi kế hoạch học kỳ trải nghiệm.', CURRENT_DATE + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 6 DAY, @u_sl_hn, NULL, NULL),
  (45006, 42004, 2, 'Phiên làm việc chuyên môn với Korea Foundation Culture Exchange Mission', 'Chương trình gồm giới thiệu campus, đối thoại sinh viên, trình diễn văn hóa và phiên làm việc riêng về chương trình mobility ngắn hạn. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 6 DAY, @u_sl_hn, NULL, NULL),
  (45007, 42005, 1, 'Đón đoàn Aalto University Service Design Delegation', 'Host xác nhận thành phần của Aalto University Service Design Delegation, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Thực hành service design cho trải nghiệm sinh viên quốc tế tại campus.', CURRENT_DATE - INTERVAL 2 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 2 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 7 DAY, @u_sl_hn, NULL, NULL),
  (45008, 42005, 2, 'Phiên làm việc chuyên môn với Aalto University Service Design Delegation', 'Workshop hoàn thành bản đồ hành trình sinh viên, xác định điểm nghẽn trong onboarding và thống nhất nhóm phụ trách thử nghiệm hai cải tiến ưu tiên. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 2 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 2 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 7 DAY, @u_sl_hn, NULL, NULL),
  (45009, 42006, 1, 'Đón đoàn University of Queensland Partnership Review', 'Host xác nhận thành phần của University of Queensland Partnership Review, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Đánh giá kết quả hợp tác năm học trước và thống nhất ba ưu tiên cho giai đoạn tiếp theo.', CURRENT_DATE - INTERVAL 16 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 16 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 8 DAY, @u_sl_hn, NULL, NULL),
  (45010, 42006, 2, 'Phiên làm việc chuyên môn với University of Queensland Partnership Review', 'Biên bản ghi nhận kết quả trao đổi sinh viên, kế hoạch nghiên cứu chung và đầu mối phụ trách chương trình đào tạo ngắn hạn. Hồ sơ đã hoàn tất hậu kiểm. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 16 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 16 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 8 DAY, @u_sl_hn, NULL, NULL),
  (45011, 42009, 1, 'Đón đoàn Erasmus Applied Learning Consortium', 'Host xác nhận thành phần của Erasmus Applied Learning Consortium, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Khảo sát mô hình học tập dự án tại Hà Nội và hệ sinh thái doanh nghiệp tại TP.HCM.', CURRENT_DATE + INTERVAL 12 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 12 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 11 DAY, @u_sl_hn, NULL, NULL),
  (45012, 42009, 2, 'Phiên làm việc chuyên môn với Erasmus Applied Learning Consortium', 'Campus Hà Nội tập trung vào phương pháp triển khai capstone; campus TP.HCM dự kiến làm việc với mạng lưới doanh nghiệp và trung tâm đổi mới. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 12 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 12 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 11 DAY, @u_sl_hn, NULL, NULL),
  (45013, 42011, 1, 'Đón đoàn SeoulTech Semiconductor Education Visit', 'Host xác nhận thành phần của SeoulTech Semiconductor Education Visit, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Trao đổi cấu trúc chương trình bán dẫn và nhu cầu phát triển phòng lab thực hành.', CURRENT_DATE + INTERVAL 4 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 4 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 12 DAY, @u_staff_hn, NULL, NULL),
  (45014, 42011, 2, 'Phiên làm việc chuyên môn với SeoulTech Semiconductor Education Visit', 'Đoàn làm việc với IC và nhóm đào tạo về học phần nền tảng, thiết bị mô phỏng và cơ chế mời chuyên gia doanh nghiệp tham gia giảng dạy. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 4 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 4 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 12 DAY, @u_staff_hn, NULL, NULL),
  (45015, 42012, 1, 'Đón đoàn Taiwan Smart Campus Working Group', 'Host xác nhận thành phần của Taiwan Smart Campus Working Group, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Chia sẻ kinh nghiệm vận hành smart campus và thiết kế dashboard tiêu thụ năng lượng.', CURRENT_DATE - INTERVAL 3 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 3 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_staff_hn, NULL, NULL),
  (45016, 42012, 2, 'Phiên làm việc chuyên môn với Taiwan Smart Campus Working Group', 'Nhóm đã hoàn thành workshop về cảm biến, dữ liệu thời gian thực và bộ chỉ số giám sát vận hành; đang tổng hợp đầu việc sau chuyến thăm. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 3 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 3 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_staff_hn, NULL, NULL),
  (45017, 42013, 1, 'Đón đoàn Jeju Tourism Technology Delegation', 'Host xác nhận thành phần của Jeju Tourism Technology Delegation, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Tìm hiểu chương trình công nghệ du lịch và trải nghiệm không gian đào tạo thực hành.', CURRENT_DATE + INTERVAL 20 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 20 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 14 DAY, @u_staff_hn, NULL, NULL),
  (45018, 42013, 2, 'Phiên làm việc chuyên môn với Jeju Tourism Technology Delegation', 'Đoàn dự kiến tham quan campus, gặp giảng viên chuyên ngành và thảo luận một học phần trải nghiệm chung về dữ liệu du lịch. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 20 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 20 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 14 DAY, @u_staff_hn, NULL, NULL),
  (45019, 42015, 1, 'Đón đoàn Temasek Polytechnic Learning Innovation Workshop', 'Host xác nhận thành phần của Temasek Polytechnic Learning Innovation Workshop, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Trao đổi cách tổ chức studio học tập và đánh giá dự án liên ngành.', CURRENT_DATE + INTERVAL 10 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 10 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 16 DAY, @u_staff_hn, NULL, NULL),
  (45020, 42015, 2, 'Phiên làm việc chuyên môn với Temasek Polytechnic Learning Innovation Workshop', 'Staff Hà Nội tạo đơn nội bộ và tự nhận làm host trong cùng transaction; agenda gồm phiên giới thiệu studio và thảo luận rubric đánh giá. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 10 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 10 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 16 DAY, @u_staff_hn, NULL, NULL),
  (45021, 42016, 1, 'Đón đoàn Porto Data Partnership Delegation', 'Host xác nhận thành phần của Porto Data Partnership Delegation, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Tổng kết thử nghiệm chia sẻ dữ liệu nghiên cứu và thảo luận nguyên tắc quản trị bộ dữ liệu chung.', CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 17 DAY, @u_staff_hn, NULL, NULL),
  (45022, 42016, 2, 'Phiên làm việc chuyên môn với Porto Data Partnership Delegation', 'Chuyến thăm đã đóng sau khi hoàn thành biên bản, hạng mục phòng họp, thiết bị trình chiếu và danh sách hành động hậu kỳ. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 17 DAY, @u_staff_hn, NULL, NULL),
  (45023, 42020, 1, 'Đón đoàn SeoulTech AI Education Multi-Campus Mission', 'Host xác nhận thành phần của SeoulTech AI Education Multi-Campus Mission, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Làm việc về AI education tại Hà Nội và khảo sát chương trình kỹ thuật phần mềm tại Đà Nẵng.', CURRENT_DATE + INTERVAL 11 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 11 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 4 DAY, @u_sl_hn, NULL, NULL),
  (45024, 42020, 2, 'Phiên làm việc chuyên môn với SeoulTech AI Education Multi-Campus Mission', 'Hà Nội đã duyệt và gán Staff Leader làm host; Đà Nẵng đang chờ xử lý độc lập nên request hiển thị trạng thái phê duyệt một phần. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 11 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 11 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 4 DAY, @u_sl_hn, NULL, NULL),
  (45025, 42024, 1, 'Đón đoàn SeoulTech Robotics Collaboration Delegation', 'Host xác nhận thành phần của SeoulTech Robotics Collaboration Delegation, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Tổ chức workshop robot di động và xác định đề tài nghiên cứu chung cho sinh viên.', CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 7 DAY, @u_staff_hn, NULL, NULL),
  (45026, 42024, 2, 'Phiên làm việc chuyên môn với SeoulTech Robotics Collaboration Delegation', 'Chuyến thăm đã hoàn tất, biên bản và thiết bị được bàn giao đầy đủ; Visitor đã gửi feedback tổng thể sau khi hồ sơ đóng. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 7 DAY, @u_staff_hn, NULL, NULL),
  (45027, 42026, 1, 'Đón đoàn Tokyo Metropolitan Smart Campus Delegation', 'Host xác nhận thành phần của Tokyo Metropolitan Smart Campus Delegation, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Khảo sát hạ tầng thông minh, khu học tập số và quy trình vận hành sự kiện.', CURRENT_DATE + INTERVAL 2 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 2 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 9 DAY, @u_staff_hn, NULL, NULL),
  (45028, 42026, 2, 'Phiên làm việc chuyên môn với Tokyo Metropolitan Smart Campus Delegation', 'Host đang hoàn thiện biển đón, xác nhận điểm tập kết xe và phân công sinh viên hỗ trợ theo từng chặng tham quan. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 2 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 2 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_staff_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 9 DAY, @u_staff_hn, NULL, NULL),
  (45029, 42029, 1, 'Đón đoàn National Chengchi University Partnership Visit', 'Host xác nhận thành phần của National Chengchi University Partnership Visit, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Rà soát nội dung hợp tác và tổ chức phiên ký biên bản ghi nhớ cấp đơn vị.', CURRENT_DATE - INTERVAL 25 DAY + INTERVAL 9 HOUR, CURRENT_DATE - INTERVAL 25 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 12 DAY, @u_sl_hn, NULL, NULL),
  (45030, 42029, 2, 'Phiên làm việc chuyên môn với National Chengchi University Partnership Visit', 'Hồ sơ đã đóng sau lễ ký, biên bản và danh sách đầu việc được xác nhận; Staff Leader Hà Nội là host chính của chuyến thăm. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE - INTERVAL 25 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE - INTERVAL 25 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 12 DAY, @u_sl_hn, NULL, NULL),
  (45031, 42030, 1, 'Đón đoàn Asia-Pacific Academic Alliance Mission', 'Host xác nhận thành phần của Asia-Pacific Academic Alliance Mission, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Làm việc tại Hà Nội về hợp tác học thuật và tại TP.HCM về kết nối doanh nghiệp.', CURRENT_DATE + INTERVAL 24 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 24 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_sl_hn, NULL, NULL),
  (45032, 42030, 2, 'Phiên làm việc chuyên môn với Asia-Pacific Academic Alliance Mission', 'Hai campus đã phê duyệt độc lập và gán host phù hợp; nội dung, lịch và đầu mối vận hành được lưu thành snapshot riêng cho từng campus. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 24 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 24 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Alpha Building - FPTU Hà Nội', @u_sl_hn, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_sl_hn, NULL, NULL),
  (45033, 42031, 1, 'Đón đoàn Asia-Pacific Academic Alliance Mission', 'Host xác nhận thành phần của Asia-Pacific Academic Alliance Mission, giới thiệu đầu mối campus TP.HCM và thống nhất mục tiêu: Làm việc tại Hà Nội về hợp tác học thuật và tại TP.HCM về kết nối doanh nghiệp.', CURRENT_DATE + INTERVAL 27 DAY + INTERVAL 9 HOUR, CURRENT_DATE + INTERVAL 27 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, 'Innovation Hall - FPTU TP.HCM', @u_staff_hcm, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_staff_hcm, NULL, NULL),
  (45034, 42031, 2, 'Phiên làm việc chuyên môn với Asia-Pacific Academic Alliance Mission', 'Hai campus đã phê duyệt độc lập và gán host phù hợp; nội dung, lịch và đầu mối vận hành được lưu thành snapshot riêng cho từng campus. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', CURRENT_DATE + INTERVAL 27 DAY + INTERVAL 9 HOUR + INTERVAL 30 MINUTE, CURRENT_DATE + INTERVAL 27 DAY + INTERVAL 11 HOUR + INTERVAL 30 MINUTE, 'Innovation Hall - FPTU TP.HCM', @u_staff_hcm, NULL, CURRENT_TIMESTAMP - INTERVAL 13 DAY, @u_staff_hcm, NULL, NULL);

