  (48002, 42016, 'EQUIPMENT', 'Bộ trình chiếu dữ liệu nghiên cứu', 'Chuẩn bị máy chiếu, bộ chuyển đổi HDMI, micro cầm tay và máy tính dự phòng cho phiên làm việc Porto.', 'SYSTEM_REQUEST', NULL, 1, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 8 HOUR, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 13 HOUR, 'DONE', 'MEDIUM', @u_staff_hn, 2, CURRENT_DATE - INTERVAL 16 DAY, @u_dept_lead_hn, CURRENT_DATE - INTERVAL 15 DAY, @u_dept_hn, @u_dept_lead_hn, CURRENT_DATE - INTERVAL 14 DAY, CURRENT_DATE - INTERVAL 14 DAY, 'Thiết bị đã kiểm tra âm thanh và kết nối với slide của đối tác.', CURRENT_DATE - INTERVAL 13 DAY, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 14 HOUR, 'Không có sự cố kỹ thuật trong phiên làm việc.', 0, CURRENT_DATE - INTERVAL 16 DAY, @u_staff_hn, CURRENT_DATE - INTERVAL 12 DAY + INTERVAL 14 HOUR, @u_dept_hn),
  (48003, 42024, 'MEAL', 'Teabreak workshop robotics', 'Chuẩn bị teabreak có lựa chọn không thịt và ghi chú dị ứng cho đoàn SeoulTech Robotics.', 'SYSTEM_REQUEST', NULL, 18, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 10 HOUR, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 10 HOUR + INTERVAL 30 MINUTE, 'DONE', 'MEDIUM', @u_staff_hn, 2, CURRENT_DATE - INTERVAL 24 DAY, @u_dept_lead_hn, CURRENT_DATE - INTERVAL 23 DAY, @u_dept_hn, @u_dept_lead_hn, CURRENT_DATE - INTERVAL 22 DAY, CURRENT_DATE - INTERVAL 22 DAY, 'Đã nhận danh sách dị ứng và xác nhận thực đơn với host.', CURRENT_DATE - INTERVAL 21 DAY, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 12 HOUR, 'Đủ số lượng và đúng yêu cầu dinh dưỡng.', 0, CURRENT_DATE - INTERVAL 24 DAY, @u_staff_hn, CURRENT_DATE - INTERVAL 20 DAY + INTERVAL 12 HOUR, @u_dept_hn);

-- L. Immutable per-campus form baselines
INSERT INTO visit_instance_form_revision_history (revision_history_id, visit_request_id, visit_instance_id, form_revision, approval_revision, source_type, source_id, snapshot_json, applied_by, applied_at, reason) VALUES
  (46001, 41001, 42001, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Helsinki Education Governance Delegation','purpose','Trao đổi mô hình quản trị dữ liệu học vụ và cơ chế phối hợp giữa trường với cơ quan quản lý giáo dục.','workingContent','Phiên làm việc tập trung vào governance framework, phân quyền truy cập dữ liệu, quy trình phê duyệt báo cáo và kế hoạch thử nghiệm chung trong học kỳ mùa thu.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 3 DAY, 'Baseline form của Helsinki Education Governance Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46002, 41002, 42002, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','British Council Digital Skills Roundtable','purpose','Chuẩn bị chương trình kỹ năng số cho sinh viên và cơ chế đồng tổ chức hoạt động tại campus Hà Nội.','workingContent','Hai bên thống nhất phạm vi workshop, tiêu chí lựa chọn giảng viên, phương án truyền thông và mốc rà soát nội dung trước ngày tổ chức.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 4 DAY, 'Baseline form của British Council Digital Skills Roundtable tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46003, 41003, 42003, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Osaka AI Laboratories Academic Visit','purpose','Khảo sát phòng lab trí tuệ nhân tạo và thảo luận cơ hội đồng hướng dẫn đồ án sinh viên.','workingContent','Đoàn tham quan AI Lab, gặp nhóm giảng viên phụ trách computer vision và rà soát đề cương ba đề tài có thể triển khai trong năm học tới.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 5 DAY, 'Baseline form của Osaka AI Laboratories Academic Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46004, 41004, 42004, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Korea Foundation Culture Exchange Mission','purpose','Tổ chức phiên giao lưu văn hóa Hàn Quốc - Việt Nam và trao đổi kế hoạch học kỳ trải nghiệm.','workingContent','Chương trình gồm giới thiệu campus, đối thoại sinh viên, trình diễn văn hóa và phiên làm việc riêng về chương trình mobility ngắn hạn.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 6 DAY, 'Baseline form của Korea Foundation Culture Exchange Mission tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46005, 41005, 42005, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Aalto University Service Design Delegation','purpose','Thực hành service design cho trải nghiệm sinh viên quốc tế tại campus.','workingContent','Workshop hoàn thành bản đồ hành trình sinh viên, xác định điểm nghẽn trong onboarding và thống nhất nhóm phụ trách thử nghiệm hai cải tiến ưu tiên.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 7 DAY, 'Baseline form của Aalto University Service Design Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46006, 41006, 42006, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','University of Queensland Partnership Review','purpose','Đánh giá kết quả hợp tác năm học trước và thống nhất ba ưu tiên cho giai đoạn tiếp theo.','workingContent','Biên bản ghi nhận kết quả trao đổi sinh viên, kế hoạch nghiên cứu chung và đầu mối phụ trách chương trình đào tạo ngắn hạn. Hồ sơ đã hoàn tất hậu kiểm.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 8 DAY, 'Baseline form của University of Queensland Partnership Review tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46007, 41007, 42007, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Warsaw Exchange Planning Team','purpose','Đề xuất phiên làm việc gấp về trao đổi học kỳ mùa đông.','workingContent','Đề nghị ban đầu thiếu danh sách thành viên chính thức và trùng lịch thi cuối kỳ của campus Hà Nội nên chưa thể tiếp nhận ở mốc thời gian đề xuất.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 9 DAY, 'Baseline form của Warsaw Exchange Planning Team tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46008, 41008, 42008, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Thai Nguyen Innovation Network Courtesy Visit','purpose','Tham quan mô hình không gian đổi mới và kết nối nhóm khởi nghiệp sinh viên.','workingContent','Đoàn chủ động hủy do lịch công tác của trưởng đoàn thay đổi; hai bên thống nhất sẽ gửi lại đề nghị vào tháng sau.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 10 DAY, 'Baseline form của Thai Nguyen Innovation Network Courtesy Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46009, 41009, 42009, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Erasmus Applied Learning Consortium','purpose','Khảo sát mô hình học tập dự án tại Hà Nội và hệ sinh thái doanh nghiệp tại TP.HCM.','workingContent','Campus Hà Nội tập trung vào phương pháp triển khai capstone; campus TP.HCM dự kiến làm việc với mạng lưới doanh nghiệp và trung tâm đổi mới.','campusId',1), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 11 DAY, 'Baseline form của Erasmus Applied Learning Consortium tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46010, 41009, 42010, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Erasmus Applied Learning Consortium','purpose','Khảo sát mô hình học tập dự án tại Hà Nội và hệ sinh thái doanh nghiệp tại TP.HCM.','workingContent','Campus Hà Nội tập trung vào phương pháp triển khai capstone; campus TP.HCM dự kiến làm việc với mạng lưới doanh nghiệp và trung tâm đổi mới.','campusId',2), @u_sl_hn, CURRENT_TIMESTAMP - INTERVAL 11 DAY, 'Baseline form của Erasmus Applied Learning Consortium tại campus TP.HCM; snapshot này không dùng thay cho campus khác.'),
  (46011, 41010, 42011, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech Semiconductor Education Visit','purpose','Trao đổi cấu trúc chương trình bán dẫn và nhu cầu phát triển phòng lab thực hành.','workingContent','Đoàn làm việc với IC và nhóm đào tạo về học phần nền tảng, thiết bị mô phỏng và cơ chế mời chuyên gia doanh nghiệp tham gia giảng dạy.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 12 DAY, 'Baseline form của SeoulTech Semiconductor Education Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46012, 41011, 42012, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Taiwan Smart Campus Working Group','purpose','Chia sẻ kinh nghiệm vận hành smart campus và thiết kế dashboard tiêu thụ năng lượng.','workingContent','Nhóm đã hoàn thành workshop về cảm biến, dữ liệu thời gian thực và bộ chỉ số giám sát vận hành; đang tổng hợp đầu việc sau chuyến thăm.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 13 DAY, 'Baseline form của Taiwan Smart Campus Working Group tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46013, 41012, 42013, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Jeju Tourism Technology Delegation','purpose','Tìm hiểu chương trình công nghệ du lịch và trải nghiệm không gian đào tạo thực hành.','workingContent','Đoàn dự kiến tham quan campus, gặp giảng viên chuyên ngành và thảo luận một học phần trải nghiệm chung về dữ liệu du lịch.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 14 DAY, 'Baseline form của Jeju Tourism Technology Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46014, 41013, 42014, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Daegu Global Seminar Organizing Team','purpose','Chuẩn bị seminar về kỹ năng nghề nghiệp quốc tế cho sinh viên khối công nghệ.','workingContent','Hồ sơ đang chờ Staff Leader rà soát lịch, thành phần diễn giả và phương án sử dụng hội trường trước khi phê duyệt.','campusId',1), @u_staff_hn, CURRENT_TIMESTAMP - INTERVAL 15 DAY, 'Baseline form của Daegu Global Seminar Organizing Team tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46015, 41014, 42015, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Temasek Polytechnic Learning Innovation Workshop','purpose','Trao đổi cách tổ chức studio học tập và đánh giá dự án liên ngành.','workingContent','Staff Hà Nội tạo đơn nội bộ và tự nhận làm host trong cùng transaction; agenda gồm phiên giới thiệu studio và thảo luận rubric đánh giá.','campusId',1), @u_staff_hn, CURRENT_TIMESTAMP - INTERVAL 16 DAY, 'Baseline form của Temasek Polytechnic Learning Innovation Workshop tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46016, 41015, 42016, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Porto Data Partnership Delegation','purpose','Tổng kết thử nghiệm chia sẻ dữ liệu nghiên cứu và thảo luận nguyên tắc quản trị bộ dữ liệu chung.','workingContent','Chuyến thăm đã đóng sau khi hoàn thành biên bản, hạng mục phòng họp, thiết bị trình chiếu và danh sách hành động hậu kỳ.','campusId',1), @u_staff_hn, CURRENT_TIMESTAMP - INTERVAL 17 DAY, 'Baseline form của Porto Data Partnership Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46017, 41016, 42017, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Pacific Language Center Observation Visit','purpose','Quan sát lớp tiếng Anh và tìm hiểu mô hình kiểm tra năng lực đầu vào.','workingContent','Yêu cầu chưa nêu rõ mục tiêu hợp tác, thành phần đoàn thay đổi liên tục và thời gian đề xuất trùng kỳ kiểm tra nên bị từ chối.','campusId',1), @u_staff_hn, CURRENT_TIMESTAMP - INTERVAL 18 DAY, 'Baseline form của Pacific Language Center Observation Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46018, 41017, 42018, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Ritsumeikan APU Student Mobility Briefing','purpose','Trao đổi thủ tục mobility và hỗ trợ sinh viên trước kỳ trao đổi.','workingContent','Đầu mối chính hủy vì lịch đoàn chuyển sang hình thức trực tuyến; Staff vẫn nhìn thấy lịch sử ở tab đơn đã đăng ký.','campusId',1), @u_staff_hn, CURRENT_TIMESTAMP - INTERVAL 2 DAY, 'Baseline form của Ritsumeikan APU Student Mobility Briefing tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46019, 41018, 42019, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech Summer School Planning Visit','purpose','Thảo luận lịch trình summer school và tiêu chí tuyển chọn sinh viên tham gia.','workingContent','Visitor đã xác minh email và gửi đơn; campus Hà Nội đang kiểm tra lịch phòng, giảng viên tham gia và phương án di chuyển nội bộ.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 3 DAY, 'Baseline form của SeoulTech Summer School Planning Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46020, 41019, 42020, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech AI Education Multi-Campus Mission','purpose','Làm việc về AI education tại Hà Nội và khảo sát chương trình kỹ thuật phần mềm tại Đà Nẵng.','workingContent','Hà Nội đã duyệt và gán Staff Leader làm host; Đà Nẵng đang chờ xử lý độc lập nên request hiển thị trạng thái phê duyệt một phần.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 4 DAY, 'Baseline form của SeoulTech AI Education Multi-Campus Mission tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46021, 41019, 42021, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech AI Education Multi-Campus Mission','purpose','Làm việc về AI education tại Hà Nội và khảo sát chương trình kỹ thuật phần mềm tại Đà Nẵng.','workingContent','Hà Nội đã duyệt và gán Staff Leader làm host; Đà Nẵng đang chờ xử lý độc lập nên request hiển thị trạng thái phê duyệt một phần.','campusId',3), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 4 DAY, 'Baseline form của SeoulTech AI Education Multi-Campus Mission tại campus Đà Nẵng; snapshot này không dùng thay cho campus khác.'),
  (46022, 41020, 42022, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Busan Design Council Campus Visit','purpose','Khảo sát không gian thiết kế và đề xuất cuộc thi sáng tạo liên trường.','workingContent','Đơn bị từ chối vì danh sách 48 khách vượt khả năng bố trí tại thời điểm đề xuất và chưa có phương án chia nhóm tham quan.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 5 DAY, 'Baseline form của Busan Design Council Campus Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46023, 41021, 42023, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech August Courtesy Visit','purpose','Thăm campus và gặp gỡ sinh viên đã tham gia chương trình trao đổi.','workingContent','Người đăng ký hủy trước thời hạn vì chuyến bay quốc tế bị điều chỉnh; lý do được lưu trong lịch sử yêu cầu.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 6 DAY, 'Baseline form của SeoulTech August Courtesy Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46024, 41022, 42024, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','SeoulTech Robotics Collaboration Delegation','purpose','Tổ chức workshop robot di động và xác định đề tài nghiên cứu chung cho sinh viên.','workingContent','Chuyến thăm đã hoàn tất, biên bản và thiết bị được bàn giao đầy đủ; Visitor đã gửi feedback tổng thể sau khi hồ sơ đóng.','campusId',1), @u_visitor_main, CURRENT_TIMESTAMP - INTERVAL 7 DAY, 'Baseline form của SeoulTech Robotics Collaboration Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46025, 41023, 42025, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Vietnam–Japan Startup Network Delegation','purpose','Kết nối startup sinh viên với cố vấn Nhật Bản và khảo sát không gian ươm tạo.','workingContent','Đơn mới đã xác minh email, đang chờ Staff Leader Hà Nội kiểm tra thành phần mentor và lịch sử dụng khu innovation hub.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 8 DAY, 'Baseline form của Vietnam–Japan Startup Network Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46026, 41024, 42026, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Tokyo Metropolitan Smart Campus Delegation','purpose','Khảo sát hạ tầng thông minh, khu học tập số và quy trình vận hành sự kiện.','workingContent','Host đang hoàn thiện biển đón, xác nhận điểm tập kết xe và phân công sinh viên hỗ trợ theo từng chặng tham quan.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 9 DAY, 'Baseline form của Tokyo Metropolitan Smart Campus Delegation tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46027, 41025, 42027, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','ASEAN Youth Forum Study Visit','purpose','Tổ chức đối thoại thanh niên ASEAN và tham quan campus trong một buổi chiều.','workingContent','Đơn chưa cung cấp xác nhận số lượng khách quốc tế, yêu cầu an ninh và thông tin trưởng đoàn nên campus chưa thể phê duyệt.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 10 DAY, 'Baseline form của ASEAN Youth Forum Study Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46028, 41026, 42028, 1, 0, 'CREATE', NULL, JSON_OBJECT('delegationName','Kyoto Creative Lab Campus Exchange','purpose','Tổ chức workshop thiết kế sáng tạo với sinh viên ngành multimedia.','workingContent','Người đăng ký hủy vì đoàn chuyển kế hoạch sang quý sau; yêu cầu được giữ để tra cứu lịch sử.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 11 DAY, 'Baseline form của Kyoto Creative Lab Campus Exchange tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46029, 41027, 42029, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','National Chengchi University Partnership Visit','purpose','Rà soát nội dung hợp tác và tổ chức phiên ký biên bản ghi nhớ cấp đơn vị.','workingContent','Hồ sơ đã đóng sau lễ ký, biên bản và danh sách đầu việc được xác nhận; Staff Leader Hà Nội là host chính của chuyến thăm.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 12 DAY, 'Baseline form của National Chengchi University Partnership Visit tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46030, 41028, 42030, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Asia-Pacific Academic Alliance Mission','purpose','Làm việc tại Hà Nội về hợp tác học thuật và tại TP.HCM về kết nối doanh nghiệp.','workingContent','Hai campus đã phê duyệt độc lập và gán host phù hợp; nội dung, lịch và đầu mối vận hành được lưu thành snapshot riêng cho từng campus.','campusId',1), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 13 DAY, 'Baseline form của Asia-Pacific Academic Alliance Mission tại campus Hà Nội; snapshot này không dùng thay cho campus khác.'),
  (46031, 41028, 42031, 1, 1, 'CREATE', NULL, JSON_OBJECT('delegationName','Asia-Pacific Academic Alliance Mission','purpose','Làm việc tại Hà Nội về hợp tác học thuật và tại TP.HCM về kết nối doanh nghiệp.','workingContent','Hai campus đã phê duyệt độc lập và gán host phù hợp; nội dung, lịch và đầu mối vận hành được lưu thành snapshot riêng cho từng campus.','campusId',2), @u_nvt, CURRENT_TIMESTAMP - INTERVAL 13 DAY, 'Baseline form của Asia-Pacific Academic Alliance Mission tại campus TP.HCM; snapshot này không dùng thay cho campus khác.');

