-- P. Meaningful FAQ replacements (no numbered test text)
INSERT INTO faqs (faq_id, faq_type, question, answer, display_order, status, created_at, created_by, updated_at, updated_by) VALUES
  (16101, 'VISIT_REQUEST', 'Sau khi gửi đơn thăm, ai sẽ xử lý yêu cầu của tôi?', 'Mỗi campus trong đơn được chuyển trực tiếp tới Staff Leader của campus đó. Các campus duyệt hoặc từ chối độc lập; HO chỉ theo dõi và không thay campus xử lý.', 1, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16102, 'VISIT_REQUEST', 'Vì sao một đơn liên cơ sở hiển thị trạng thái phê duyệt một phần?', 'Trạng thái này xuất hiện khi ít nhất một campus đã phê duyệt nhưng campus khác vẫn đang chờ xử lý hoặc đã từ chối. Bạn có thể mở chi tiết để xem trạng thái từng campus.', 2, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16103, 'ACCOUNT_ACCESS', 'Tài khoản đang chờ xác nhận email có đăng nhập được không?', 'Không. Người dùng phải mở liên kết xác nhận được gửi tới đúng email đã đăng ký. Sau khi xác nhận thành công, trạng thái tài khoản mới chuyển sang hoạt động.', 3, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16104, 'DELEGATION_MANAGEMENT', 'Staff Leader có thể tự làm host cho đoàn không?', 'Có. Khi phê duyệt campus instance, Staff Leader có thể gán một IC Staff phù hợp hoặc tự gán chính mình làm host trong cùng thao tác.', 4, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16105, 'LOGISTICS_RESOURCE', 'Ai được theo dõi trạng thái yêu cầu hậu cần?', 'Host theo dõi các hạng mục của campus instance; Department Leader và Department Staff chỉ thấy yêu cầu thuộc phòng ban hoặc nhiệm vụ được giao cho họ.', 5, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16106, 'DOCUMENT_MEDIA', 'Ảnh chuyến thăm có tự động xuất hiện ở gallery công khai không?', 'Không. Ảnh chuyến thăm là dữ liệu nội bộ theo đoàn. Nội dung gallery công khai phải được tạo và duyệt theo quy trình riêng.', 6, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16107, 'NOTIFICATION_EMAIL', 'Tại sao liên kết phản hồi trong email chỉ dùng được một lần?', 'Token email được thiết kế dùng một lần để tránh một người phản hồi nhiều lựa chọn mâu thuẫn. Lần bấm sau chỉ hiển thị kết quả đã được ghi nhận.', 7, 'PUBLISHED', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16108, 'OTHER', 'Tôi nên liên hệ ai khi thông tin campus trong đơn chưa chính xác?', 'Hãy liên hệ đầu mối vận hành hiển thị trong chi tiết campus instance. Thay đổi ảnh hưởng lịch hoặc nội dung đã duyệt có thể cần gửi yêu cầu sửa đổi.', 8, 'HIDDEN', CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL);

-- Q. Persisted VI/EN FAQ content
INSERT INTO faq_translations (faq_id, language_code, question, answer, translation_source, translation_status, source_hash, translated_at, created_at, created_by, updated_at, updated_by) VALUES
  (16101, 'vi', 'Sau khi gửi đơn thăm, ai sẽ xử lý yêu cầu của tôi?', 'Mỗi campus trong đơn được chuyển trực tiếp tới Staff Leader của campus đó. Các campus duyệt hoặc từ chối độc lập; HO chỉ theo dõi và không thay campus xử lý.', 'MANUAL', 'READY', SHA2(CONCAT('Sau khi gửi đơn thăm, ai sẽ xử lý yêu cầu của tôi?','|','Mỗi campus trong đơn được chuyển trực tiếp tới Staff Leader của campus đó. Các campus duyệt hoặc từ chối độc lập; HO chỉ theo dõi và không thay campus xử lý.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16101, 'en', 'After I submit a visit request, who processes it?', 'Each campus is routed directly to its own Staff Leader. Campuses approve or reject independently; HO monitors the process but does not decide for a campus.', 'MANUAL', 'READY', SHA2(CONCAT('Sau khi gửi đơn thăm, ai sẽ xử lý yêu cầu của tôi?','|','Mỗi campus trong đơn được chuyển trực tiếp tới Staff Leader của campus đó. Các campus duyệt hoặc từ chối độc lập; HO chỉ theo dõi và không thay campus xử lý.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16102, 'vi', 'Vì sao một đơn liên cơ sở hiển thị trạng thái phê duyệt một phần?', 'Trạng thái này xuất hiện khi ít nhất một campus đã phê duyệt nhưng campus khác vẫn đang chờ xử lý hoặc đã từ chối. Bạn có thể mở chi tiết để xem trạng thái từng campus.', 'MANUAL', 'READY', SHA2(CONCAT('Vì sao một đơn liên cơ sở hiển thị trạng thái phê duyệt một phần?','|','Trạng thái này xuất hiện khi ít nhất một campus đã phê duyệt nhưng campus khác vẫn đang chờ xử lý hoặc đã từ chối. Bạn có thể mở chi tiết để xem trạng thái từng campus.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16102, 'en', 'Why does a multi-campus request show Partially Approved?', 'This appears when at least one campus has approved while another is still pending or has rejected. Open the request detail to see each campus status.', 'MANUAL', 'READY', SHA2(CONCAT('Vì sao một đơn liên cơ sở hiển thị trạng thái phê duyệt một phần?','|','Trạng thái này xuất hiện khi ít nhất một campus đã phê duyệt nhưng campus khác vẫn đang chờ xử lý hoặc đã từ chối. Bạn có thể mở chi tiết để xem trạng thái từng campus.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16103, 'vi', 'Tài khoản đang chờ xác nhận email có đăng nhập được không?', 'Không. Người dùng phải mở liên kết xác nhận được gửi tới đúng email đã đăng ký. Sau khi xác nhận thành công, trạng thái tài khoản mới chuyển sang hoạt động.', 'MANUAL', 'READY', SHA2(CONCAT('Tài khoản đang chờ xác nhận email có đăng nhập được không?','|','Không. Người dùng phải mở liên kết xác nhận được gửi tới đúng email đã đăng ký. Sau khi xác nhận thành công, trạng thái tài khoản mới chuyển sang hoạt động.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16103, 'en', 'Can an account pending email confirmation sign in?', 'No. The user must open the confirmation link sent to the registered email. The account becomes active only after successful confirmation.', 'MANUAL', 'READY', SHA2(CONCAT('Tài khoản đang chờ xác nhận email có đăng nhập được không?','|','Không. Người dùng phải mở liên kết xác nhận được gửi tới đúng email đã đăng ký. Sau khi xác nhận thành công, trạng thái tài khoản mới chuyển sang hoạt động.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16104, 'vi', 'Staff Leader có thể tự làm host cho đoàn không?', 'Có. Khi phê duyệt campus instance, Staff Leader có thể gán một IC Staff phù hợp hoặc tự gán chính mình làm host trong cùng thao tác.', 'MANUAL', 'READY', SHA2(CONCAT('Staff Leader có thể tự làm host cho đoàn không?','|','Có. Khi phê duyệt campus instance, Staff Leader có thể gán một IC Staff phù hợp hoặc tự gán chính mình làm host trong cùng thao tác.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16104, 'en', 'Can a Staff Leader be the host?', 'Yes. When approving a campus instance, the Staff Leader may assign an eligible IC Staff member or assign themself as the host in the same action.', 'MANUAL', 'READY', SHA2(CONCAT('Staff Leader có thể tự làm host cho đoàn không?','|','Có. Khi phê duyệt campus instance, Staff Leader có thể gán một IC Staff phù hợp hoặc tự gán chính mình làm host trong cùng thao tác.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16105, 'vi', 'Ai được theo dõi trạng thái yêu cầu hậu cần?', 'Host theo dõi các hạng mục của campus instance; Department Leader và Department Staff chỉ thấy yêu cầu thuộc phòng ban hoặc nhiệm vụ được giao cho họ.', 'MANUAL', 'READY', SHA2(CONCAT('Ai được theo dõi trạng thái yêu cầu hậu cần?','|','Host theo dõi các hạng mục của campus instance; Department Leader và Department Staff chỉ thấy yêu cầu thuộc phòng ban hoặc nhiệm vụ được giao cho họ.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16105, 'en', 'Who can track a logistics request?', 'The host tracks items for the campus instance. Department Leaders and Department Staff see only requests in their department or tasks assigned to them.', 'MANUAL', 'READY', SHA2(CONCAT('Ai được theo dõi trạng thái yêu cầu hậu cần?','|','Host theo dõi các hạng mục của campus instance; Department Leader và Department Staff chỉ thấy yêu cầu thuộc phòng ban hoặc nhiệm vụ được giao cho họ.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16106, 'vi', 'Ảnh chuyến thăm có tự động xuất hiện ở gallery công khai không?', 'Không. Ảnh chuyến thăm là dữ liệu nội bộ theo đoàn. Nội dung gallery công khai phải được tạo và duyệt theo quy trình riêng.', 'MANUAL', 'READY', SHA2(CONCAT('Ảnh chuyến thăm có tự động xuất hiện ở gallery công khai không?','|','Không. Ảnh chuyến thăm là dữ liệu nội bộ theo đoàn. Nội dung gallery công khai phải được tạo và duyệt theo quy trình riêng.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16106, 'en', 'Are visit photos automatically published to the public gallery?', 'No. Visit photos remain internal delegation data. Public gallery content follows a separate creation and approval workflow.', 'MANUAL', 'READY', SHA2(CONCAT('Ảnh chuyến thăm có tự động xuất hiện ở gallery công khai không?','|','Không. Ảnh chuyến thăm là dữ liệu nội bộ theo đoàn. Nội dung gallery công khai phải được tạo và duyệt theo quy trình riêng.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16107, 'vi', 'Tại sao liên kết phản hồi trong email chỉ dùng được một lần?', 'Token email được thiết kế dùng một lần để tránh một người phản hồi nhiều lựa chọn mâu thuẫn. Lần bấm sau chỉ hiển thị kết quả đã được ghi nhận.', 'MANUAL', 'READY', SHA2(CONCAT('Tại sao liên kết phản hồi trong email chỉ dùng được một lần?','|','Token email được thiết kế dùng một lần để tránh một người phản hồi nhiều lựa chọn mâu thuẫn. Lần bấm sau chỉ hiển thị kết quả đã được ghi nhận.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16107, 'en', 'Why can an email response link be used only once?', 'The one-time token prevents conflicting responses. Later clicks only show the result that was already recorded.', 'MANUAL', 'READY', SHA2(CONCAT('Tại sao liên kết phản hồi trong email chỉ dùng được một lần?','|','Token email được thiết kế dùng một lần để tránh một người phản hồi nhiều lựa chọn mâu thuẫn. Lần bấm sau chỉ hiển thị kết quả đã được ghi nhận.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16108, 'vi', 'Tôi nên liên hệ ai khi thông tin campus trong đơn chưa chính xác?', 'Hãy liên hệ đầu mối vận hành hiển thị trong chi tiết campus instance. Thay đổi ảnh hưởng lịch hoặc nội dung đã duyệt có thể cần gửi yêu cầu sửa đổi.', 'MANUAL', 'READY', SHA2(CONCAT('Tôi nên liên hệ ai khi thông tin campus trong đơn chưa chính xác?','|','Hãy liên hệ đầu mối vận hành hiển thị trong chi tiết campus instance. Thay đổi ảnh hưởng lịch hoặc nội dung đã duyệt có thể cần gửi yêu cầu sửa đổi.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL),
  (16108, 'en', 'Who should I contact when campus information is incorrect?', 'Contact the operational contact shown in the campus instance detail. Changes to an approved schedule or content may require an amendment request.', 'MANUAL', 'READY', SHA2(CONCAT('Tôi nên liên hệ ai khi thông tin campus trong đơn chưa chính xác?','|','Hãy liên hệ đầu mối vận hành hiển thị trong chi tiết campus instance. Thay đổi ảnh hưởng lịch hoặc nội dung đã duyệt có thể cần gửi yêu cầu sửa đổi.'),256), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, @u_sl_hn, NULL, NULL);

-- ---------------------------------------------------------------------------
-- R. Code-grounded document, contact, email and workflow stories
-- Base code snapshot: 242d54215ac8ec6540ca9d3e7666b6baeed1dd00
--
-- Important implementation contracts mirrored here:
--   * visit detail email history reads VISIT_PARTICIPANT and LOGISTICS_ITEM only;
--   * report email history uses CAMPUS / DEPARTMENT / USER;
--   * OTP bodies are never retained; action-bearing bodies below are already
--     stripped of their action block and contain no raw token or action URL;
--   * provider acceptance is SENT, never DELIVERED (there is no webhook);
--   * approve/reject/cancel/host assignment remain notification-only.
-- ---------------------------------------------------------------------------

-- R0. Replace the obsolete 16-template demo catalog and its contradictory
-- delivery history with the 30 template codes registered by the application.
-- This is a full rebuild script, so the global cleanup below affects seed data
-- only. Every new automated history row later resolves its template by code.
DELETE FROM email_action_tokens;
DELETE FROM sent_email_attachments;
DELETE FROM sent_email_recipients;
DELETE FROM sent_emails;
DELETE FROM email_templates;

INSERT INTO email_templates
  (email_template_id, template_code, name, purpose, campus_id, description,
   status, subject_vi, body_vi, subject_en, body_en, body_format, variables_text,
   created_at, created_by, updated_at, updated_by)
VALUES
  (70001, 'ACCOUNT_EMAIL_CONFIRMATION', 'Xác nhận email để kích hoạt tài khoản', 'ACCOUNT', NULL, 'Gửi cho tài khoản vừa tạo ở trạng thái chờ xác nhận email. Là email đầu tiên của mọi luồng tạo tài khoản.', 'ACTIVE',
   '[PEMS] Xác nhận email để kích hoạt tài khoản PEMS', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Một tài khoản PEMS đã được khởi tạo cho bạn. Tài khoản đang ở trạng thái chờ xác nhận email và chưa đăng nhập được.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Vai trò</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{roleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn xác nhận</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Bấm nút bên dưới để xác nhận địa chỉ email này. Sau khi xác nhận, tài khoản sẽ chuyển sang trạng thái hoạt động.</p>{{actionBlock}}</div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Liên kết xác nhận có hiệu lực trong <strong>{{expiresInHours}}</strong> giờ và chỉ dùng được một lần.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Không chia sẻ liên kết này với bất kỳ ai. Nếu bạn không mong đợi email này, vui lòng bỏ qua và không bấm vào liên kết.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Confirm your email to activate your PEMS account', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">A PEMS account has been created for you. It is pending email confirmation and cannot be signed in to yet.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Role</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{roleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Confirmation required</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Use the button below to confirm this email address. The account becomes active once it is confirmed.</p>{{actionBlock}}</div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The confirmation link is valid for <strong>{{expiresInHours}}</strong> hours and can be used once.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> Do not share this link with anyone. If you were not expecting this email, please ignore it and do not open the link.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,roleName,campusName,expiresInHours', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70002, 'ACCOUNT_PENDING_EMAIL_CHANGED_OLD_NOTICE', 'Báo địa chỉ cũ khi đổi email tài khoản chờ xác nhận', 'ACCOUNT', NULL, 'Gửi tới địa chỉ cũ khi email của một tài khoản còn chờ xác nhận bị đổi. Cố tình ẩn danh: địa chỉ cũ có thể là người gõ nhầm, không liên quan tới tài khoản.', 'ACTIVE',
   '[PEMS] Địa chỉ email đăng ký đã được thay đổi', '<p style="margin:0 0 16px;color:#334155">Kính gửi Quý vị,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Một tài khoản PEMS trước đây được đăng ký với địa chỉ email này đã được chuyển sang một địa chỉ khác trước khi kích hoạt.</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Địa chỉ này sẽ không được dùng để đăng nhập. Quý vị không cần thực hiện thêm thao tác nào.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Nếu Quý vị không biết về tài khoản này hoặc cho rằng đây là sự nhầm lẫn, vui lòng liên hệ người gửi email này hoặc bộ phận quản trị hệ thống PEMS.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] The registration email has been changed', '<p style="margin:0 0 16px;color:#334155">Dear Sir or Madam,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">A PEMS account previously registered with this email address was moved to a different address before activation.</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This address will not be used to sign in. No action is needed from you.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> If you do not recognise this account, or believe this is a mistake, please contact the sender of this email or the PEMS system administrator.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70003, 'ACCOUNT_ACTIVATED', 'Thông báo tài khoản đã kích hoạt', 'ACCOUNT', NULL, 'Gửi sau khi người dùng xác nhận email thành công và tài khoản chuyển sang hoạt động.', 'ACTIVE',
   '[PEMS] Tài khoản PEMS của bạn đã được kích hoạt', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Địa chỉ email của bạn đã được xác nhận. Tài khoản PEMS đã sẵn sàng sử dụng.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Vai trò</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{roleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bạn có thể đăng nhập bằng chính địa chỉ email này và sử dụng các chức năng thuộc vai trò được cấp.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu bạn gặp khó khăn khi truy cập hệ thống, vui lòng liên hệ người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your PEMS account is now active', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your email address has been confirmed and your PEMS account is ready to use.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Role</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{roleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">You can sign in with this email address and use the features assigned to your role.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If you have trouble signing in, please contact the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,roleName,campusName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70004, 'ACCOUNT_EMAIL_CHANGED_OLD_NOTICE', 'Báo địa chỉ cũ khi đổi email tài khoản đang hoạt động', 'ACCOUNT', NULL, 'Gửi tới địa chỉ vừa bị gỡ khỏi một tài khoản đang hoạt động. Cố tình ẩn danh: không nêu tên chủ tài khoản, địa chỉ mới, vai trò hay cơ sở.', 'ACTIVE',
   '[PEMS] Địa chỉ email này đã được gỡ khỏi một tài khoản PEMS', '<p style="margin:0 0 16px;color:#334155">Kính gửi Quý vị,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Địa chỉ email này không còn được dùng để đăng nhập vào tài khoản PEMS đã liên kết trước đó.</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Mọi phiên đăng nhập bằng địa chỉ này đã được thu hồi. Quý vị không cần thực hiện thêm thao tác nào.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Nếu Quý vị không biết về tài khoản này hoặc cho rằng đây là sự nhầm lẫn, vui lòng liên hệ người gửi email này hoặc bộ phận quản trị hệ thống PEMS.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] This address has been removed from a PEMS account', '<p style="margin:0 0 16px;color:#334155">Dear Sir or Madam,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This email address is no longer used to sign in to the PEMS account it was previously linked to.</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Any sessions opened with this address have been revoked. No action is needed from you.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> If you do not recognise this account, or believe this is a mistake, please contact the sender of this email or the PEMS system administrator.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70005, 'ACCOUNT_EMAIL_CHANGED_NEW_NOTICE', 'Báo địa chỉ mới khi đổi email tài khoản đang hoạt động', 'ACCOUNT', NULL, 'Gửi tới địa chỉ mới khi email của một tài khoản đang hoạt động được chuyển sang địa chỉ đó.', 'ACTIVE',
   '[PEMS] Địa chỉ email này đã được gắn với tài khoản PEMS của bạn', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Địa chỉ email này đã trở thành địa chỉ đăng nhập cho tài khoản PEMS của bạn.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Địa chỉ trước đây</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{oldEmailMasked}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Từ lần đăng nhập kế tiếp, vui lòng dùng chính địa chỉ email này. Mọi phiên đăng nhập bằng địa chỉ cũ đã được thu hồi.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Nếu bạn không yêu cầu thay đổi này, hãy liên hệ ngay người gửi email này hoặc bộ phận quản trị hệ thống PEMS.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] This address is now the sign-in email for your PEMS account', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This email address is now the sign-in address for your PEMS account.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Previous address</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{oldEmailMasked}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Please use this address from your next sign-in. Any sessions opened with the previous address have been revoked.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> If you did not request this change, contact the sender of this email or the PEMS system administrator immediately.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,oldEmailMasked,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70006, 'ACCOUNT_ROLE_CHANGED', 'Thông báo thay đổi vai trò tài khoản', 'ACCOUNT', NULL, 'Gửi cho người dùng khi vai trò trên hệ thống của họ được thay đổi.', 'ACTIVE',
   '[PEMS] Vai trò tài khoản PEMS của bạn đã thay đổi', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Vai trò của bạn trên hệ thống PEMS vừa được cập nhật.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Vai trò trước đây</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{oldRoleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Vai trò hiện tại</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{newRoleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Quyền truy cập của bạn thay đổi theo vai trò mới ngay từ lần đăng nhập kế tiếp. Một số màn hình trước đây bạn mở được có thể không còn hiển thị.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu bạn cho rằng thay đổi này chưa đúng, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your PEMS account role has changed', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your role in PEMS has been updated.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Previous role</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{oldRoleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Current role</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{newRoleName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your access follows the new role from your next sign-in. Some screens you could open before may no longer appear.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If this change does not look right, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,oldRoleName,newRoleName,campusName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70007, 'ACCOUNT_STAFF_LEADER_ASSIGNED', 'Thông báo được phân công làm Staff Leader', 'ACCOUNT', NULL, 'Gửi cho người được phân công làm Staff Leader của một campus.', 'ACTIVE',
   '[PEMS] Bạn được phân công làm Staff Leader', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bạn được phân công đảm nhiệm vai trò Staff Leader trên hệ thống PEMS.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hiệu lực từ</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{effectiveDate}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Lý do phân công</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Từ thời điểm hiệu lực, bạn tiếp nhận việc duyệt yêu cầu tham quan của cơ sở này, phân công host và theo dõi tiến độ chuẩn bị.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu thông tin phân công chưa chính xác, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] You have been assigned as Staff Leader', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">You have been assigned the Staff Leader role in PEMS.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Effective from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{effectiveDate}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Reason</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">From the effective date you take over approving this campus visit requests, assigning hosts and tracking preparation.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If any of this is incorrect, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,campusName,effectiveDate,reason,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70008, 'ACCOUNT_STAFF_LEADER_REPLACED', 'Thông báo kết thúc vai trò Staff Leader', 'ACCOUNT', NULL, 'Gửi cho Staff Leader cũ khi vai trò của họ được chuyển cho người khác.', 'ACTIVE',
   '[PEMS] Vai trò Staff Leader của bạn đã kết thúc', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Vai trò Staff Leader của bạn đã được chuyển cho người khác.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Người tiếp nhận</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{successorName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hiệu lực từ</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{effectiveDate}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Lý do thay đổi</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Các yêu cầu đang chờ xử lý của cơ sở này được chuyển sang người tiếp nhận. Bạn vẫn xem được lịch sử công việc đã thực hiện.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu bạn cho rằng thay đổi này chưa đúng, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your Staff Leader role has ended', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your Staff Leader role has been transferred to someone else.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Successor</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{successorName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Effective from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{effectiveDate}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Reason</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Pending requests for this campus move to the successor. You keep read access to the work you already handled.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If this change does not look right, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,campusName,successorName,effectiveDate,reason,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70009, 'DEPT_PERSONNEL_ACCOUNT_DISABLED', 'Thông báo tài khoản bị vô hiệu hóa', 'ACCOUNT', NULL, 'Gửi cho nhân sự khi Trưởng phòng vô hiệu hóa tài khoản của họ.', 'ACTIVE',
   '[PEMS] Tài khoản PEMS của bạn đã bị vô hiệu hóa', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tài khoản PEMS của bạn đã được chuyển sang trạng thái vô hiệu hóa.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Lý do</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bạn sẽ không đăng nhập được cho tới khi tài khoản được kích hoạt lại. Các nhiệm vụ đang được giao cho bạn sẽ do phòng ban điều phối lại.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu bạn cho rằng đây là sự nhầm lẫn, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your PEMS account has been disabled', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your PEMS account has been set to disabled.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Reason</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{reason}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">You will not be able to sign in until the account is enabled again. Tasks currently assigned to you will be reassigned by your department.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If you believe this is a mistake, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,departmentName,reason,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70010, 'DEPT_PERSONNEL_ACCOUNT_ENABLED', 'Thông báo tài khoản được kích hoạt lại', 'ACCOUNT', NULL, 'Gửi cho nhân sự khi Trưởng phòng kích hoạt lại tài khoản của họ.', 'ACTIVE',
   '[PEMS] Tài khoản PEMS của bạn đã được kích hoạt lại', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tài khoản PEMS của bạn đã được kích hoạt lại và có thể đăng nhập bình thường.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bạn tiếp tục nhận và xử lý các nhiệm vụ thuộc phòng ban như trước.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your PEMS account has been re-enabled', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your PEMS account has been re-enabled and you can sign in as usual.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">You will continue to receive and handle your department tasks as before.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,departmentName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70011, 'DEPT_LEADERSHIP_GRANTED', 'Thông báo được bổ nhiệm Trưởng phòng', 'ACCOUNT', NULL, 'Gửi cho người nhận vai trò Trưởng phòng sau khi bàn giao được ghi nhận.', 'ACTIVE',
   '[PEMS] Bạn được bổ nhiệm làm Trưởng phòng', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Việc bàn giao vai trò Trưởng phòng đã được ghi nhận trên hệ thống PEMS. Bạn là Trưởng phòng đương nhiệm.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Từ bây giờ bạn tiếp nhận các yêu cầu hậu cần gửi tới phòng ban, phân công nhân sự xử lý và theo dõi tiến độ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu thông tin bàn giao chưa chính xác, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] You have been appointed Department Leader', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The Department Leader handover has been recorded in PEMS. You are the current Department Leader.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">You now receive logistics requests addressed to the department, assign staff to handle them and track progress.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If the handover details are incorrect, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,departmentName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70012, 'DEPT_LEADERSHIP_HANDED_OVER', 'Thông báo đã bàn giao vai trò Trưởng phòng', 'ACCOUNT', NULL, 'Gửi cho Trưởng phòng cũ sau khi bàn giao được ghi nhận.', 'ACTIVE',
   '[PEMS] Bạn đã bàn giao vai trò Trưởng phòng', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Việc bàn giao vai trò Trưởng phòng của bạn đã được ghi nhận trên hệ thống PEMS.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Các yêu cầu hậu cần mới sẽ được chuyển tới Trưởng phòng đương nhiệm. Bạn vẫn xem được lịch sử công việc đã thực hiện.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Nếu thông tin bàn giao chưa chính xác, vui lòng phản hồi cho người gửi email này.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] You have handed over the Department Leader role', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your handover of the Department Leader role has been recorded in PEMS.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">New logistics requests will go to the current Department Leader. You keep read access to the work you already handled.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">If the handover details are incorrect, please reply to the sender of this email.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,departmentName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70013, 'AUTH_PASSWORD_RESET_OTP', 'Mã đặt lại mật khẩu', 'AUTH', NULL, 'Gửi mã OTP đặt lại mật khẩu. Chỉ gửi riêng cho một người nhận, cấm CC/BCC.', 'ACTIVE',
   '[PEMS] Mã đặt lại mật khẩu', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Chúng tôi nhận được yêu cầu đặt lại mật khẩu cho tài khoản PEMS của bạn. Dùng mã dưới đây để tiếp tục.</p><div style="margin:18px 0;padding:18px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;text-align:center"><span style="font-family:Courier New,monospace;font-size:28px;font-weight:700;color:#0f3d67;letter-spacing:6px">{{otpCode}}</span></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Mã có hiệu lực trong <strong>{{expireMinutes}}</strong> phút và chỉ dùng được một lần.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Không chia sẻ mã này với bất kỳ ai, kể cả người tự nhận là nhân sự PEMS. Nếu bạn không yêu cầu đặt lại mật khẩu, hãy bỏ qua email này; mật khẩu hiện tại vẫn giữ nguyên.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Your password reset code', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">We received a request to reset the password for your PEMS account. Use the code below to continue.</p><div style="margin:18px 0;padding:18px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;text-align:center"><span style="font-family:Courier New,monospace;font-size:28px;font-weight:700;color:#0f3d67;letter-spacing:6px">{{otpCode}}</span></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The code is valid for <strong>{{expireMinutes}}</strong> minutes and can be used once.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> Do not share this code with anyone, including someone claiming to be PEMS staff. If you did not request a password reset, ignore this email; your current password stays unchanged.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,otpCode,expireMinutes', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70014, 'VISIT_REQUEST_OTP', 'Mã xác thực đăng ký tham quan', 'VISIT_REQUEST', NULL, 'Gửi mã OTP xác thực email cho người đăng ký tham quan trước khi tạo yêu cầu. Cấm CC/BCC.', 'ACTIVE',
   '[PEMS] Mã xác thực email đăng ký tham quan', '<p style="margin:0 0 16px;color:#334155">Kính gửi <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Cảm ơn Quý vị đã gửi đăng ký tham quan tới FPT University. Vui lòng dùng mã dưới đây để xác thực địa chỉ email trước khi yêu cầu được tạo.</p><div style="margin:18px 0;padding:18px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;text-align:center"><span style="font-family:Courier New,monospace;font-size:28px;font-weight:700;color:#0f3d67;letter-spacing:6px">{{otpCode}}</span></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Mã có hiệu lực trong <strong>{{expireMinutes}}</strong> phút và chỉ dùng được một lần.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Không chia sẻ mã này với bất kỳ ai. Nếu Quý vị không gửi đăng ký nào, vui lòng bỏ qua email này.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Verification code for your visit registration', '<p style="margin:0 0 16px;color:#334155">Dear <strong>{{fullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Thank you for registering a visit to FPT University. Please use the code below to verify this email address before the request is created.</p><div style="margin:18px 0;padding:18px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;text-align:center"><span style="font-family:Courier New,monospace;font-size:28px;font-weight:700;color:#0f3d67;letter-spacing:6px">{{otpCode}}</span></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The code is valid for <strong>{{expireMinutes}}</strong> minutes and can be used once.</p><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> Do not share this code with anyone. If you did not submit a registration, please ignore this email.</div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'fullName,otpCode,expireMinutes', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70015, 'VISIT_CONTACT_CLAIM', 'Xác nhận vai trò đầu mối liên hệ', 'VISIT_REQUEST', NULL, 'Gửi cho người được ghi nhận là đầu mối liên hệ của một yêu cầu tham quan để họ xác nhận vai trò. Có liên kết dùng một lần.', 'ACTIVE',
   '[PEMS] Xác nhận vai trò đầu mối liên hệ cho yêu cầu {{requestCode}}', '<p style="margin:0 0 16px;color:#334155">Kính gửi <strong>{{contactFullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Quý vị được ghi nhận là đầu mối liên hệ của một yêu cầu tham quan tại FPT University. Chúng tôi cần Quý vị xác nhận vai trò này trước khi trao đổi các thông tin tiếp theo.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Mã yêu cầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{requestCode}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{plannedTime}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần Quý vị xác nhận</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng dùng các nút bên dưới để chấp nhận hoặc từ chối vai trò đầu mối liên hệ. Quý vị không cần đăng nhập PEMS. Mỗi nút mở một trang xác nhận bằng liên kết dùng một lần để Quý vị xem thông tin chuyến thăm mới nhất trước khi quyết định.</p>{{actionBlock}}</div><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Các liên kết có thời hạn và mỗi liên kết chỉ dùng được một lần. Vui lòng không chuyển tiếp email hoặc các liên kết này cho người khác.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Confirm you are the contact for visit request {{requestCode}}', '<p style="margin:0 0 16px;color:#334155">Dear <strong>{{contactFullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">You have been recorded as the contact person for a visit request at FPT University. We need you to confirm this role before we continue.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Request code</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{requestCode}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{plannedTime}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Confirmation required</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Use the buttons below to accept or decline the contact role. You do not need to sign in to PEMS. Each button opens a confirmation page using a one-time link, so you can review the latest visit details before deciding.</p>{{actionBlock}}</div><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> The links expire and each can be used once. Do not forward the email or its links.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'contactFullName,requestCode,delegationName,campusName,plannedTime,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70016, 'VISIT_CONTACT_TRANSFER', 'Lời mời nhận vai trò đầu mối liên hệ', 'VISIT_REQUEST', NULL, 'Gửi cho người được đề nghị tiếp nhận vai trò đầu mối liên hệ từ người hiện tại. Có liên kết dùng một lần.', 'ACTIVE',
   '[PEMS] Lời mời nhận vai trò đầu mối liên hệ cho yêu cầu {{requestCode}}', '<p style="margin:0 0 16px;color:#334155">Kính gửi <strong>{{contactFullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Quý vị được đề nghị tiếp nhận vai trò đầu mối liên hệ của một yêu cầu tham quan tại FPT University.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Mã yêu cầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{requestCode}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Đầu mối hiện tại</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{currentContactName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần Quý vị phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng dùng các nút bên dưới để chấp nhận hoặc từ chối. Quý vị không cần đăng nhập PEMS để phản hồi lời mời này. Nếu Quý vị chấp nhận, các trao đổi tiếp theo về yêu cầu này sẽ được gửi tới địa chỉ email này.</p>{{actionBlock}}</div><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Lưu ý bảo mật:</strong> Các liên kết có thời hạn và mỗi liên kết chỉ dùng được một lần. Vui lòng không chuyển tiếp email hoặc các liên kết này cho người khác.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Invitation to take over the contact role for request {{requestCode}}', '<p style="margin:0 0 16px;color:#334155">Dear <strong>{{contactFullName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">You have been asked to take over the contact role for a visit request at FPT University.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Request code</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{requestCode}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Current contact</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{currentContactName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Use the buttons below to accept or decline. You do not need to sign in to PEMS to respond. If you accept, further correspondence about this request will be sent to this address.</p>{{actionBlock}}</div><div style="margin:18px 0;padding:14px 16px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;line-height:1.6"><strong>Security note:</strong> The links expire and each can be used once. Please do not forward the email or its links.</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'contactFullName,currentContactName,requestCode,delegationName,campusName,plannedTime,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70017, 'VISIT_PARTICIPANT_INVITATION', 'Mời nhân sự tham gia hỗ trợ tiếp khách', 'VISIT_PARTICIPANT', NULL, 'Email mời nhân sự IC tham gia hỗ trợ một chuyến tiếp khách. Mỗi người nhận có liên kết chấp nhận/từ chối riêng.', 'ACTIVE',
   '[PEMS] Mời tham gia hỗ trợ tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} mời bạn tham gia hỗ trợ một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi chốt danh sách nhân sự tham gia.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Invitation to support the visit of {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} invites you to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Your role</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so we can confirm the supporting team.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,hostName,roleLabel,hostMessage,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70018, 'VISIT_STUDENT_INVITATION', 'Mời sinh viên hỗ trợ tiếp khách', 'VISIT_PARTICIPANT', NULL, 'Email mời sinh viên hỗ trợ một chuyến tiếp khách. Mỗi người nhận có liên kết chấp nhận/từ chối riêng.', 'ACTIVE',
   '[PEMS] Mời sinh viên hỗ trợ tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} mời bạn tham gia hỗ trợ một chuyến tiếp khách tại {{campusName}}. Đây là hoạt động tự nguyện dành cho sinh viên.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn nhận lời, thông tin tập trung và hướng dẫn chi tiết sẽ được gửi trước ngày diễn ra.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Student invitation to support the visit of {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} invites you to help host a visit at {{campusName}}. Taking part is voluntary.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Your role</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. If you accept, the meeting point and detailed instructions will be sent before the day.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,hostName,roleLabel,hostMessage,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70019, 'VISIT_DEPARTMENT_LEADER_INVITATION', 'Mời phòng ban phối hợp tiếp khách', 'VISIT_PARTICIPANT', NULL, 'Email mời Trưởng phòng ban phối hợp tiếp khách; ngoài chấp nhận/từ chối còn có liên kết gán nhân sự yêu cầu đăng nhập.', 'ACTIVE',
   '[PEMS] Mời phòng ban phối hợp tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} đề nghị phòng ban của bạn phối hợp cho một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Nội dung phối hợp</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Bạn cũng có thể gán trực tiếp một nhân sự của phòng ban để tiếp nhận công việc này.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Request for department support for the visit of {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{hostName}} asks your department to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Support requested</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{roleLabel}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em>{{hostMessage}}</em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. You can also assign a member of your department to take this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,hostName,roleLabel,hostMessage,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70020, 'VISIT_DEPARTMENT_STAFF_ASSIGNMENT', 'Phân công nhân sự phòng ban hỗ trợ tiếp khách', 'VISIT_PARTICIPANT', NULL, 'Gửi cho nhân sự được Trưởng phòng ban gán vào một chuyến tiếp khách. Khác với lời mời: đây là phân công.', 'ACTIVE',
   '[PEMS] Bạn được phân công hỗ trợ tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trưởng phòng {{departmentName}} đã phân công bạn hỗ trợ một chuyến tiếp khách tại {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để phòng ban biết bạn có nhận nhiệm vụ này hay không.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] You have been assigned to support the visit of {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The head of {{departmentName}} has assigned you to support a visit at {{campusName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Planned time</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedTime}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{departmentName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so your department knows whether you are taking this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedTime,departmentName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70021, 'VISIT_REMINDER_HOST', 'Nhắc lịch tiếp khách cho người phụ trách', 'VISIT_REMINDER', NULL, 'Nhắc người phụ trách tiếp đón trước giờ tiếp khách theo cấu hình nhắc lịch của chuyến.', 'ACTIVE',
   '[PEMS] Nhắc lịch tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Đây là email nhắc lịch cho chuyến tiếp khách bạn đang phụ trách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Kết thúc</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trước ngày diễn ra, vui lòng rà soát:</p><ul style="margin:0 0 14px;padding-left:20px;color:#334155;line-height:1.7"><li>Danh sách khách và thành phần phía FPT đã đầy đủ.</li><li>Lịch trình từng mốc thời gian đã được chốt.</li><li>Các hạng mục hậu cần đã được phòng ban xác nhận.</li></ul><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở chuyến tiếp khách trong hệ thống để kiểm tra và cập nhật phần còn thiếu.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: hosting {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This is a reminder for the visit you are hosting.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Starts</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Ends</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Before the day, please check that:</p><ul style="margin:0 0 14px;padding-left:20px;color:#334155;line-height:1.7"><li>the guest list and the FPT participants are complete;</li><li>every step of the agenda is confirmed;</li><li>the logistics items have been accepted by the departments.</li></ul><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the visit in the system to review it and fill in whatever is still missing.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'hostName,delegationName,campusName,plannedStart,plannedEnd,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70022, 'VISIT_REMINDER_PARTICIPANTS', 'Nhắc lịch tiếp khách cho người tham gia', 'VISIT_REMINDER', NULL, 'Nhắc từng người đã nhận lời mời hoặc được gán, trước giờ tiếp khách. Gửi riêng từng người, không liệt kê người khác.', 'ACTIVE',
   '[PEMS] Nhắc lịch tham gia tiếp đón đoàn {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Đây là email nhắc lịch cho chuyến tiếp khách bạn đã nhận lời tham gia.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Kết thúc</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Vui lòng có mặt đúng giờ và mang theo thẻ nhân sự hoặc thẻ sinh viên.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở chuyến tiếp khách trong hệ thống để xem lịch trình chi tiết và điểm tập trung.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: supporting the visit of {{delegationName}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">This is a reminder for the visit you agreed to support.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Starts</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedStart}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Ends</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{plannedEnd}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Please arrive on time and bring your staff or student card.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the visit in the system to see the detailed agenda and the meeting point.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,delegationName,campusName,plannedStart,plannedEnd,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70023, 'LOGISTICS_REQUEST_TO_DEPARTMENT', 'Gửi yêu cầu hậu cần tới phòng ban', 'LOGISTICS', NULL, 'Gửi Trưởng phòng ban khi người phụ trách tiếp đón tạo một yêu cầu hậu cần. Có liên kết đồng ý/từ chối dùng một lần.', 'ACTIVE',
   '[PEMS] Yêu cầu hậu cần: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{departmentLeaderName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{requesterName}} gửi tới phòng ban của bạn một yêu cầu hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Loại</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsItemType}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{quantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{usageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{usageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Nội dung chi tiết công việc:</strong> {{logisticsDescription}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi tiếp tục xử lý. Nếu cần điều chỉnh số lượng hoặc thời gian, hãy chọn thao tác trong hệ thống để gửi đề xuất thay đổi.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Logistics request: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{departmentLeaderName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{requesterName}} has sent your department a logistics request for a campus visit.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Type</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsItemType}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{quantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Use from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{usageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Use until</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{usageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Description:</strong> {{logisticsDescription}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so we can proceed. If the quantity or the timing needs to change, use the in-system action to send a counter-proposal.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'departmentLeaderName,requesterName,logisticsTitle,logisticsItemType,quantity,usageStartAt,usageEndAt,logisticsDescription,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70024, 'LOGISTICS_ASSIGNEE_ASSIGNMENT', 'Phân công nhân sự xử lý hậu cần', 'LOGISTICS', NULL, 'Gửi nhân sự phòng ban khi Trưởng phòng ban phân công họ xử lý một hạng mục hậu cần. Có liên kết nhận/từ chối dùng một lần.', 'ACTIVE',
   '[PEMS] Bạn được giao hạng mục hậu cần: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{assigneeName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Trưởng phòng đã giao cho bạn một hạng mục hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạn xử lý</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để phòng ban biết bạn có nhận hạng mục này hay không.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Logistics task assigned to you: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{assigneeName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Your department head has assigned you a logistics item for a campus visit.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Due</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{delegationName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{campusName}}</td></tr></tbody></table><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below so your department knows whether you are taking this on.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'assigneeName,logisticsTitle,dueAt,campusName,delegationName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70025, 'LOGISTICS_CHANGE_PROPOSAL_TO_HOST', 'Đề xuất thay đổi yêu cầu hậu cần gửi người phụ trách', 'LOGISTICS', NULL, 'Gửi người phụ trách tiếp đón khi phòng ban đề xuất thay đổi một yêu cầu hậu cần. Có liên kết chấp nhận/từ chối dùng một lần.', 'ACTIVE',
   '[PEMS] Đề xuất thay đổi hạng mục hậu cần: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Phòng {{departmentName}} đề xuất điều chỉnh một hạng mục hậu cần của đoàn {{delegationName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng ban đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{originalQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedUsageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{proposedUsageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Mô tả đề xuất:</strong> {{proposedDescription}}</p><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Lý do đề xuất:</strong> {{proposalNote}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn chấp nhận, hạng mục sẽ được cập nhật theo nội dung đề xuất.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Change proposed for logistics item: {{logisticsTitle}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{hostName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">{{departmentName}} proposes a change to a logistics item for {{delegationName}}.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{logisticsTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Original quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{originalQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Proposed quantity</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedQuantity}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Proposed use from</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{proposedUsageStartAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Proposed use until</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{proposedUsageEndAt}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Proposed description:</strong> {{proposedDescription}}</p><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Reason:</strong> {{proposalNote}}</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Your response is needed</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Please choose one of the options below. If you accept, the item will be updated to match the proposal.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'hostName,logisticsTitle,departmentName,delegationName,originalQuantity,proposedQuantity,proposedUsageStartAt,proposedUsageEndAt,proposedDescription,proposalNote,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70026, 'LOGISTICS_EXPENSE_REPORT_REMINDER', 'Nhắc kê khai chi phí hậu cần', 'LOGISTICS', NULL, 'Nhắc người phụ trách hạng mục hoàn tất kê khai chi phí sau chuyến tiếp khách.', 'ACTIVE',
   '[PEMS] Nhắc kê khai chi phí hạng mục: {{itemTitle}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Một hạng mục hậu cần bạn phụ trách đã hoàn tất nhưng chưa có kê khai chi phí.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{itemTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạn kê khai</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{delegationName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Kê khai chi phí là căn cứ để phòng ban tổng hợp quyết toán cho đoàn. Nếu hạng mục không phát sinh chi phí, vui lòng ghi nhận rõ điều đó.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Việc cần làm</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Mở biên bản trong hệ thống để kê khai chi phí thực tế của hạng mục này.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Reminder: record the expenses for {{itemTitle}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">A logistics item you are responsible for is complete but has no expense record yet.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Item</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{itemTitle}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Due</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{dueAt}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Delegation</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{delegationName}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The expense record is what the department uses to settle the visit. If the item cost nothing, please record that explicitly.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">What to do</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Open the record in the system and enter the actual expenses for this item.</p>{{actionBlock}}</div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,itemTitle,dueAt,delegationName,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70027, 'REPORT_CAMPUS_OPERATION', 'Báo cáo vận hành campus', 'REPORT', NULL, 'Gửi báo cáo vận hành tiếp khách của một campus kèm tệp PDF đính kèm.', 'ACTIVE',
   '[PEMS] Báo cáo vận hành cơ sở {{campusName}} kỳ {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Báo cáo vận hành theo cơ sở đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Vận hành theo cơ sở</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm gồm số lượng đoàn đã tiếp đón, tiến độ chuẩn bị và các hạng mục hậu cần trong kỳ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Số liệu được kết xuất tại thời điểm gửi email. Nếu dữ liệu trong kỳ được cập nhật sau đó, vui lòng kết xuất lại từ hệ thống.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Campus operation report for {{campusName}}, {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The campus operation report has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Campus operation</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Campus</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{campusName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment covers the delegations received, preparation progress and logistics items for the period.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The figures were exported when this email was sent. If the data changes afterwards, please export again from the system.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,campusName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70028, 'REPORT_DEPARTMENT_COLLABORATION', 'Báo cáo phối hợp tiếp khách của phòng ban', 'REPORT', NULL, 'Gửi Trưởng phòng ban báo cáo mức độ phối hợp tiếp khách của phòng ban kèm tệp PDF đính kèm.', 'ACTIVE',
   '[PEMS] Báo cáo phối hợp phòng {{departmentName}} kỳ {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Báo cáo phối hợp theo phòng ban đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Phối hợp theo phòng ban</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm gồm các yêu cầu hậu cần phòng ban đã tiếp nhận, tỷ lệ chấp nhận và tiến độ hoàn thành trong kỳ.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Số liệu được kết xuất tại thời điểm gửi email. Nếu dữ liệu trong kỳ được cập nhật sau đó, vui lòng kết xuất lại từ hệ thống.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Department collaboration report for {{departmentName}}, {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The department collaboration report has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Department collaboration</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment covers the logistics requests the department received, the acceptance rate and completion progress for the period.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">The figures were exported when this email was sent. If the data changes afterwards, please export again from the system.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,departmentName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70029, 'REPORT_DEPARTMENT_INVOICE', 'Hóa đơn hậu cần tiếp khách của phòng ban', 'REPORT', NULL, 'Gửi hóa đơn hậu cần tiếp khách của phòng ban kèm tệp PDF. Dùng chung cho hai chiều gửi: phòng ban gửi lên và campus gửi xuống.', 'ACTIVE',
   '[PEMS] Bảng kê chi phí phòng {{departmentName}} kỳ {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Xin chào <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Bảng kê chi phí theo phòng ban đã được lập và gửi kèm email này.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Bảng kê chi phí</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Phòng ban</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kỳ báo cáo</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">Tệp đính kèm liệt kê từng hạng mục hậu cần đã kê khai chi phí trong kỳ, kèm tổng cộng.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Bảng kê chỉ gồm các hạng mục đã được kê khai. Hạng mục chưa kê khai sẽ không xuất hiện cho tới khi người phụ trách hoàn tất.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p>',
   '[PEMS] Expense statement for {{departmentName}}, {{periodFrom}} - {{periodTo}}', '<p style="margin:0 0 16px;color:#334155">Hello <strong>{{recipientName}}</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">The department expense statement has been generated and is attached to this email.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Report</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Expense statement</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Department</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">{{departmentName}}</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Period</td><td style="padding:10px 14px;font-weight:600;color:#334155">{{periodFrom}} - {{periodTo}}</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65">The attachment lists every logistics item with a recorded expense in the period, with a total.</p><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Only items with a recorded expense appear. An item stays off the statement until whoever is responsible records it.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Sender</p><p style="margin:0;line-height:1.65;color:#334155"><strong>{{senderName}}</strong><br/>{{senderRole}}<br/>{{senderDepartment}}<br/>{{senderEmail}}</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Best regards,<br/><strong>PEMS - FPT University</strong></p>',
   'HTML', 'recipientName,departmentName,periodFrom,periodTo,senderName,senderRole,senderEmail,senderPhone,senderDepartment,senderCampus', CURRENT_TIMESTAMP, NULL, NULL, NULL),
  (70030, 'REPORT_PERSONNEL_PERFORMANCE', 'Báo cáo hiệu suất nhân sự tiếp khách', 'REPORT', NULL, 'Gửi từng cá nhân báo cáo hiệu suất tham gia tiếp khách kèm tệp PDF. Phạm vi thống kê do người gửi truyền vào qua scopeLabel.', 'ACTIVE',
