-- ---------------------------------------------------------------------------
-- R. Verification report — every invalid_* count must be 0.
-- ---------------------------------------------------------------------------
SELECT 'curated_requests' AS metric, COUNT(*) AS value
FROM visit_requests WHERE visit_request_id BETWEEN 41001 AND 41028;

SELECT 'curated_instances' AS metric, COUNT(*) AS value
FROM visit_request_campuses WHERE visit_instance_id BETWEEN 42001 AND 42031;

SELECT 'staff_leader_hn_registered_cases' AS metric, COUNT(*) AS value
FROM visit_requests WHERE registrant_user_id=@u_sl_hn AND visit_request_id BETWEEN 41001 AND 41028;

SELECT 'staff_leader_hn_host_cases' AS metric, COUNT(*) AS value
FROM visit_request_campuses WHERE current_host_user_id=@u_sl_hn AND visit_instance_id BETWEEN 42001 AND 42031;

SELECT 'staff_leader_hn_invitation_cases' AS metric, COUNT(*) AS value
FROM visit_participants WHERE user_id=@u_sl_hn AND is_host=0 AND visit_instance_id BETWEEN 42001 AND 42031;

SELECT 'staff_hn_registered_cases' AS metric, COUNT(*) AS value
FROM visit_requests WHERE registrant_user_id=@u_staff_hn AND visit_request_id BETWEEN 41001 AND 41028;

SELECT 'visitor_example_registered_cases' AS metric, COUNT(*) AS value
FROM visit_requests WHERE registrant_user_id=@u_visitor_main AND visit_request_id BETWEEN 41001 AND 41028;

SELECT 'nvt_registered_cases' AS metric, COUNT(*) AS value
FROM visit_requests WHERE registrant_user_id=@u_nvt AND visit_request_id BETWEEN 41001 AND 41028;

SELECT 'hanoi_feedback_cases' AS metric, COUNT(*) AS value
FROM feedbacks f JOIN visit_request_campuses vrc ON vrc.visit_instance_id=f.visit_instance_id
WHERE vrc.campus_id=1 AND f.feedback_id BETWEEN 47001 AND 47050;

SELECT 'invalid_operational_contact_not_active' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
JOIN users u ON u.user_id=vrc.operational_contact_user_id
WHERE vrc.visit_request_id BETWEEN 41001 AND 41028
  AND u.status<>'ACTIVE';

SELECT 'invalid_hanoi_host_relation' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
JOIN users u ON u.user_id=vrc.current_host_user_id
JOIN roles r ON r.role_id=u.role_id
WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
  AND vrc.current_host_user_id IS NOT NULL
  AND NOT (r.role_code='STAFF' AND u.sub_role IN ('STAFF','LEADER') AND u.primary_campus_id=vrc.campus_id);

SELECT 'invalid_operational_without_agenda' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
  AND vrc.status IN ('DURING_VISIT','AFTER_VISIT','CLOSED')
  AND NOT EXISTS (SELECT 1 FROM visit_agendas va WHERE va.visit_instance_id=vrc.visit_instance_id);

SELECT 'invalid_host_participant_mismatch' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
  AND vrc.current_host_user_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM visit_participants vp
    WHERE vp.visit_instance_id=vrc.visit_instance_id
      AND vp.user_id=vrc.current_host_user_id
      AND vp.is_host=1 AND vp.status='ASSIGNED'
  );

SELECT 'remaining_numbered_faq_spam' AS check_name, COUNT(*) AS issue_count
FROM faqs
WHERE question REGEXP 'số[[:space:]]+[0-9]+\\?$'
   OR question LIKE 'Câu hỏi kiểm thử nhóm%';

SELECT 'remaining_generated_request_factory' AS check_name, COUNT(*) AS issue_count
FROM visit_requests WHERE visit_request_id BETWEEN 3001 AND 3090;

SELECT 'remaining_generated_feedback_factory' AS check_name, COUNT(*) AS issue_count
FROM feedbacks WHERE feedback_id BETWEEN 13001 AND 13018;

SELECT 'remaining_generated_news_factory' AS check_name, COUNT(*) AS issue_count
FROM news WHERE news_id BETWEEN 15001 AND 15016;

SELECT 'remaining_generated_document_factory' AS check_name, COUNT(*) AS issue_count
FROM documents WHERE document_id BETWEEN 1 AND 21;

SELECT 'staff_leader_hn_invitation_status_distribution' AS metric, status, COUNT(*) AS value
FROM visit_participants
WHERE user_id=@u_sl_hn AND is_host=0 AND visit_instance_id BETWEEN 42001 AND 42031
GROUP BY status ORDER BY status;

SELECT 'student_hn_invitation_status_distribution' AS metric, status, COUNT(*) AS value
FROM visit_participants
WHERE user_id=@u_student_hn AND is_host=0 AND visit_instance_id BETWEEN 42001 AND 42031
GROUP BY status ORDER BY status;

-- ---------------------------------------------------------------------------
-- R7.5. OPERATIONAL CONTACT SEED CANONICALIZATION — VISITOR ONLY
--
-- Seed invariant aligned with the current application write path:
--   * a confirmed operational_contact_user_id must reference an ACTIVE VISITOR;
--   * the per-campus snapshot name/email must describe that same account;
--   * an internal registrant/Host/Staff Leader is never reused as the guest-side contact.
--
-- Historical seed rows created before the hard cutover sometimes reused the registrant
-- or copied an FPTU Staff snapshot into operational_contact_*. Repair them deterministically:
--   1) keep an already ACTIVE VISITOR contact and repair only its stale snapshot;
--   2) for a cancelled campus, prefer the existing ACTIVE VISITOR cancellation actor when present;
--   3) otherwise provision a dedicated VISITOR seed account from the request's first guest.
-- Pending WAITING_CONTACT_CONFIRMATION rows keep operational_contact_user_id = NULL and are not touched.
-- ---------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_seed_operational_contact_repairs;
CREATE TEMPORARY TABLE tmp_seed_operational_contact_repairs (
  visit_instance_id BIGINT UNSIGNED NOT NULL,
  visit_request_id BIGINT UNSIGNED NOT NULL,
  registrant_user_id BIGINT UNSIGNED NULL,
  old_contact_user_id BIGINT UNSIGNED NOT NULL,
  replacement_user_id BIGINT UNSIGNED NULL,
  replacement_full_name VARCHAR(150) NOT NULL,
  replacement_organization VARCHAR(255) NOT NULL,
  replacement_job_title VARCHAR(150) NOT NULL,
  replacement_phone VARCHAR(50) NULL,
  replacement_email VARCHAR(150) NOT NULL,
  replacement_nationality VARCHAR(100) NULL,
  confirmed_at DATETIME NOT NULL,
  PRIMARY KEY (visit_instance_id),
  KEY idx_tmp_seed_op_contact_request (visit_request_id),
  KEY idx_tmp_seed_op_contact_email (replacement_email)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_unicode_ci;

INSERT INTO tmp_seed_operational_contact_repairs (
  visit_instance_id, visit_request_id, registrant_user_id, old_contact_user_id, replacement_user_id,
  replacement_full_name, replacement_organization, replacement_job_title,
  replacement_phone, replacement_email, replacement_nationality, confirmed_at
)
SELECT
  vrc.visit_instance_id,
  vrc.visit_request_id,
  vr.registrant_user_id,
  vrc.operational_contact_user_id,
  CASE
    WHEN current_role.role_code = 'VISITOR' AND current_contact.status = 'ACTIVE'
      THEN current_contact.user_id
    WHEN cancel_role.role_code = 'VISITOR' AND cancel_user.status = 'ACTIVE'
      THEN cancel_user.user_id
    ELSE NULL
  END AS replacement_user_id,
  CASE
    WHEN current_role.role_code = 'VISITOR' AND current_contact.status = 'ACTIVE'
      THEN current_contact.full_name
    WHEN cancel_role.role_code = 'VISITOR' AND cancel_user.status = 'ACTIVE'
      THEN cancel_user.full_name
    ELSE COALESCE(NULLIF(TRIM(first_guest.full_name), ''), CONCAT('Delegation Contact ', vrc.visit_request_id))
  END AS replacement_full_name,
  CASE
    WHEN current_role.role_code = 'VISITOR'
         AND current_contact.status = 'ACTIVE'
         AND current_contact.user_id = vr.registrant_user_id
      THEN COALESCE(NULLIF(TRIM(vr.registrant_organization), ''), NULLIF(TRIM(first_guest.organization), ''), 'External Delegation')
    ELSE COALESCE(NULLIF(TRIM(first_guest.organization), ''), 'External Delegation')
  END AS replacement_organization,
  CASE
    WHEN current_role.role_code = 'VISITOR'
         AND current_contact.status = 'ACTIVE'
         AND current_contact.user_id = vr.registrant_user_id
      THEN COALESCE(NULLIF(TRIM(vr.registrant_job_title), ''), NULLIF(TRIM(first_guest.job_title), ''), 'Delegation Coordinator')
    ELSE COALESCE(NULLIF(TRIM(first_guest.job_title), ''), 'Delegation Coordinator')
  END AS replacement_job_title,
  CASE
    WHEN current_role.role_code = 'VISITOR' AND current_contact.status = 'ACTIVE'
      THEN current_contact.phone
    WHEN cancel_role.role_code = 'VISITOR' AND cancel_user.status = 'ACTIVE'
      THEN cancel_user.phone
    ELSE NULL
  END AS replacement_phone,
  CASE
    WHEN current_role.role_code = 'VISITOR' AND current_contact.status = 'ACTIVE'
      THEN LOWER(TRIM(current_contact.email))
    WHEN cancel_role.role_code = 'VISITOR' AND cancel_user.status = 'ACTIVE'
      THEN LOWER(TRIM(cancel_user.email))
    ELSE CONCAT('visit.contact.', vrc.visit_request_id, '@delegation.example')
  END AS replacement_email,
  CASE
    WHEN current_role.role_code = 'VISITOR' AND current_contact.status = 'ACTIVE'
      THEN current_contact.nationality
    WHEN cancel_role.role_code = 'VISITOR' AND cancel_user.status = 'ACTIVE'
      THEN cancel_user.nationality
    ELSE first_guest.nationality
  END AS replacement_nationality,
  COALESCE(vrc.operational_contact_confirmed_at, vrc.created_at, vr.submitted_at, CURRENT_TIMESTAMP) AS confirmed_at
FROM visit_request_campuses vrc
JOIN visit_requests vr
  ON vr.visit_request_id = vrc.visit_request_id
JOIN visit_instance_form_details d
  ON d.visit_instance_id = vrc.visit_instance_id
LEFT JOIN users current_contact
  ON current_contact.user_id = vrc.operational_contact_user_id
LEFT JOIN roles current_role
  ON current_role.role_id = current_contact.role_id
LEFT JOIN users cancel_user
  ON cancel_user.user_id = vrc.cancelled_by
LEFT JOIN roles cancel_role
  ON cancel_role.role_id = cancel_user.role_id
LEFT JOIN visit_guest_members first_guest
  ON first_guest.guest_member_id = (
    SELECT gm2.guest_member_id
    FROM visit_guest_members gm2
    WHERE gm2.visit_request_id = vrc.visit_request_id
      AND gm2.member_type = 'GUEST'
    ORDER BY gm2.display_order, gm2.guest_member_id
    LIMIT 1
  )
WHERE vrc.operational_contact_user_id IS NOT NULL
  AND (
       current_role.role_code IS NULL
    OR current_role.role_code <> 'VISITOR'
    OR current_contact.status <> 'ACTIVE'
    OR LOWER(TRIM(d.operational_contact_email)) <> LOWER(TRIM(current_contact.email))
    OR TRIM(d.operational_contact_full_name) <> TRIM(current_contact.full_name)
  );

-- Provision only the replacement identities that do not already have a usable VISITOR account.
INSERT INTO users (
  full_name, email, phone, nationality, role_id, sub_role,
  primary_campus_id, department_id, status, email_verified_at,
  failed_login_count, created_via, created_at
)
SELECT
  t.replacement_full_name,
  t.replacement_email,
  t.replacement_phone,
  t.replacement_nationality,
  visitor_role.role_id,
  NULL,
  NULL,
  NULL,
  'ACTIVE',
  MIN(t.confirmed_at),
  0,
  'VISITOR_FORM',
  MIN(t.confirmed_at)
FROM tmp_seed_operational_contact_repairs t
JOIN roles visitor_role
  ON visitor_role.role_code = 'VISITOR'
WHERE t.replacement_user_id IS NULL
  AND NOT EXISTS (
    SELECT 1
    FROM users existing_user
    WHERE LOWER(existing_user.email) = LOWER(t.replacement_email)
  )
GROUP BY
  t.visit_request_id, t.replacement_full_name, t.replacement_email,
  t.replacement_phone, t.replacement_nationality, visitor_role.role_id;

-- Resolve generated/reused replacement accounts after provisioning.
UPDATE tmp_seed_operational_contact_repairs t
JOIN users replacement_user
  ON LOWER(replacement_user.email) = LOWER(t.replacement_email)
JOIN roles replacement_role
  ON replacement_role.role_id = replacement_user.role_id
 AND replacement_role.role_code = 'VISITOR'
SET t.replacement_user_id = replacement_user.user_id
WHERE t.replacement_user_id IS NULL
  AND replacement_user.status = 'ACTIVE';

-- Runtime relation: operational contact is always the ACTIVE VISITOR identity.
-- IMPORTANT: do NOT JOIN visit_requests in this UPDATE. The AFTER UPDATE aggregate trigger on
-- visit_request_campuses updates visit_requests; MySQL raises Error 1442 if the invoking statement
-- is already reading visit_requests. registrant_user_id was snapshotted into the temporary table
-- before this write specifically to keep the trigger-safe update isolated to visit_request_campuses.
UPDATE visit_request_campuses vrc
JOIN tmp_seed_operational_contact_repairs t
  ON t.visit_instance_id = vrc.visit_instance_id
SET vrc.operational_contact_user_id = t.replacement_user_id,
    vrc.operational_contact_confirmed_at = t.confirmed_at,
    vrc.operational_contact_confirmation_source = CASE
      WHEN t.replacement_user_id = t.registrant_user_id THEN 'REGISTRANT_SELF_MATCH'
      ELSE 'EMAIL_CONFIRMATION'
    END;

-- Read-model snapshot: name/email describe exactly the linked VISITOR account; organization/title
-- remain realistic guest-side data and never reuse FPTU Staff/Leader identity fields.
UPDATE visit_instance_form_details d
JOIN tmp_seed_operational_contact_repairs t
  ON t.visit_instance_id = d.visit_instance_id
SET d.operational_contact_full_name = t.replacement_full_name,
    d.operational_contact_organization = t.replacement_organization,
    d.operational_contact_job_title = t.replacement_job_title,
    d.operational_contact_phone = t.replacement_phone,
    d.operational_contact_email = t.replacement_email;

-- Keep immutable form-history snapshots semantically aligned when they contain the contact object.
UPDATE visit_instance_form_revision_history h
JOIN tmp_seed_operational_contact_repairs t
  ON t.visit_instance_id = h.visit_instance_id
SET h.snapshot_json = JSON_SET(
      h.snapshot_json,
      '$.operationalContact.fullName', t.replacement_full_name,
      '$.operationalContact.organization', t.replacement_organization,
      '$.operationalContact.jobTitle', t.replacement_job_title,
      '$.operationalContact.phone', t.replacement_phone,
      '$.operationalContact.email', t.replacement_email
    )
WHERE JSON_CONTAINS_PATH(h.snapshot_json, 'one', '$.operationalContact') = 1;

-- Some curated legacy request-history rows carried one request-level operationalContactEmail.
-- Single-campus history is synchronized; multi-campus history drops that obsolete request-level key.
UPDATE visit_request_revision_history h
JOIN visit_requests vr
  ON vr.visit_request_id = h.visit_request_id
JOIN (
  SELECT visit_request_id, MIN(replacement_email) AS replacement_email
  FROM tmp_seed_operational_contact_repairs
  GROUP BY visit_request_id
) t
  ON t.visit_request_id = h.visit_request_id
SET h.snapshot_json = CASE
      WHEN vr.visit_scope = 'MULTI_CAMPUS'
        THEN JSON_REMOVE(h.snapshot_json, '$.operationalContactEmail')
      ELSE JSON_SET(h.snapshot_json, '$.operationalContactEmail', t.replacement_email)
    END
WHERE JSON_CONTAINS_PATH(h.snapshot_json, 'one', '$.operationalContactEmail') = 1;

-- If a historical APPLIED confirmation row still points to the replaced identity, synchronize it too.
UPDATE visit_request_identity_changes ic
JOIN tmp_seed_operational_contact_repairs t
  ON t.visit_instance_id = ic.visit_instance_id
SET ic.new_user_id = t.replacement_user_id,
    ic.new_email_normalized = t.replacement_email,
    ic.new_email_masked = CONCAT(
      LEFT(t.replacement_email, 1), '***@', SUBSTRING_INDEX(t.replacement_email, '@', -1)
    )
WHERE ic.status = 'APPLIED'
  AND (ic.new_user_id <=> t.old_contact_user_id);

DROP TEMPORARY TABLE IF EXISTS tmp_seed_operational_contact_repairs;

-- ---------------------------------------------------------------------------
-- R7.6. REBUILD EMAIL HISTORY FROM TEMPLATES + ENFORCE NO FAKE FILE SEED
--
-- All file/document/media INSERT blocks are physically absent from this file.
-- Business rows use NULL for optional file foreign keys so the application uses
-- its normal no-image/no-document fallback without an insert-then-delete cycle.
--
-- Sent-email history is rebuilt from the same email_templates rows used by
-- SystemEmailDispatcher. Business variables are resolved from the related
-- identity change / participant / visit instance / logistics item. One-time
-- action blocks are intentionally absent from history snapshots.
-- ---------------------------------------------------------------------------
START TRANSACTION;

-- Contact invitation token identity follows the related
-- visit_request_identity_changes row instead of a hand-written story.
UPDATE email_action_tokens eat
JOIN sent_emails se ON se.sent_email_id = eat.sent_email_id
JOIN visit_request_identity_changes ic ON ic.identity_change_id = se.related_id
SET eat.action_group_key = CONCAT('VISIT_CONTACT_CLAIM:', ic.identity_change_id),
    eat.action_context = 'VISIT_CONTACT_CLAIM',
    eat.recipient_user_id = ic.new_user_id,
    eat.recipient_email = ic.new_email_normalized
WHERE se.sent_email_id BETWEEN 64001 AND 64003;

UPDATE sent_email_recipients ser
JOIN sent_emails se ON se.sent_email_id = ser.sent_email_id
JOIN visit_request_identity_changes ic ON ic.identity_change_id = se.related_id
LEFT JOIN users invited_user ON invited_user.user_id = ic.new_user_id
LEFT JOIN visit_instance_form_details d ON d.visit_instance_id = ic.visit_instance_id
SET ser.recipient_email = ic.new_email_normalized,
    ser.recipient_name = COALESCE(
      NULLIF(TRIM(invited_user.full_name), ''),
      NULLIF(TRIM(d.operational_contact_full_name), ''),
      NULLIF(TRIM(ser.recipient_name), ''),
      ic.new_email_normalized
    )
WHERE se.sent_email_id BETWEEN 64001 AND 64003
  AND ser.recipient_type = 'TO';

-- The 64030 mail is a Department Leader invitation and its recipient/action
-- token already point to the Department Leader. Align the related participant.
UPDATE visit_participants
SET user_id = @u_dept_lead_hn,
    note = 'Department Leader được current host mời phối hợp giao lưu văn hóa; chưa phản hồi.',
    updated_at = CURRENT_TIMESTAMP,
    updated_by = @u_sl_hn
WHERE participant_id = 44027;

-- Start from the actual active template content and the same branded shell as
-- EmailComposition.BrandedShell. The renderer below resolves every declared
-- business variable from the related seed object.
UPDATE sent_emails se
JOIN email_templates et ON et.email_template_id = se.email_template_id
SET se.subject = et.subject_vi,
    se.body_snapshot = CONCAT(
      '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n',
      '<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n',
      '  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n',
      '    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n',
      '      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n',
      '      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n',
      '    </div>\n    <div style="padding:32px;color:#374151;font-size:14px">',
      REPLACE(et.body_vi, '{{actionBlock}}', ''),
      '</div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n',
      '      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n',
      '    </div>\n  </div>\n</body></html>'
    ),
    se.body_format = 'HTML'
WHERE se.sent_email_id BETWEEN 64001 AND 64031;

DROP TEMPORARY TABLE IF EXISTS tmp_seed_email_render_variables;
CREATE TEMPORARY TABLE tmp_seed_email_render_variables (
  sent_email_id BIGINT UNSIGNED NOT NULL,
  variable_name VARCHAR(100) NOT NULL,
  variable_value LONGTEXT NOT NULL,
  PRIMARY KEY (sent_email_id, variable_name)
) ENGINE=InnoDB;

-- Sender variables are resolved from sent_by; automated reminders use the
-- configured PEMS system identity rather than inventing a staff sender.
INSERT INTO tmp_seed_email_render_variables
  (sent_email_id, variable_name, variable_value)
SELECT
  se.sent_email_id,
  names.variable_name,
  CASE names.variable_name
    WHEN 'senderName' THEN COALESCE(NULLIF(TRIM(sender.full_name), ''), 'PEMS System')
    WHEN 'senderRole' THEN COALESCE(NULLIF(TRIM(sender_role.name), ''), 'Hệ thống')
    WHEN 'senderEmail' THEN COALESCE(NULLIF(TRIM(sender.email), ''), 'no-reply@mail.pems-fpt.site')
    WHEN 'senderPhone' THEN COALESCE(sender.phone, '')
    WHEN 'senderDepartment' THEN COALESCE(NULLIF(TRIM(sender_department.name), ''), 'Ban quản trị PEMS')
    WHEN 'senderCampus' THEN COALESCE(NULLIF(TRIM(sender_campus.name), ''), 'FPT University')
  END
FROM sent_emails se
LEFT JOIN users sender ON sender.user_id = se.sent_by
LEFT JOIN roles sender_role ON sender_role.role_id = sender.role_id
LEFT JOIN departments sender_department ON sender_department.department_id = sender.department_id
LEFT JOIN campuses sender_campus ON sender_campus.campus_id = sender.primary_campus_id
CROSS JOIN (
  SELECT 'senderName' AS variable_name
  UNION ALL SELECT 'senderRole'
  UNION ALL SELECT 'senderEmail'
  UNION ALL SELECT 'senderPhone'
  UNION ALL SELECT 'senderDepartment'
  UNION ALL SELECT 'senderCampus'
) names
WHERE se.sent_email_id BETWEEN 64001 AND 64031;

-- Operational-contact claim variables.
INSERT INTO tmp_seed_email_render_variables
  (sent_email_id, variable_name, variable_value)
SELECT
  se.sent_email_id,
  names.variable_name,
  CASE names.variable_name
    WHEN 'contactFullName' THEN COALESCE(
      NULLIF(TRIM(invited_user.full_name), ''),
      NULLIF(TRIM(ser.recipient_name), ''),
      NULLIF(TRIM(d.operational_contact_full_name), ''),
      ic.new_email_normalized
    )
    WHEN 'currentContactName' THEN COALESCE(
      NULLIF(TRIM(old_user.full_name), ''),
      NULLIF(TRIM(vr.registrant_full_name), ''),
      'Đầu mối hiện tại'
    )
    WHEN 'requestCode' THEN vr.request_code
    WHEN 'delegationName' THEN d.delegation_name
    WHEN 'campusName' THEN campus.name
    WHEN 'plannedTime' THEN CONCAT(
      DATE_FORMAT(vrc.planned_start_at, '%H:%i %d/%m/%Y'),
      ' - ', DATE_FORMAT(vrc.planned_end_at, '%H:%i %d/%m/%Y')
    )
  END
FROM sent_emails se
JOIN visit_request_identity_changes ic ON ic.identity_change_id = se.related_id
JOIN visit_requests vr ON vr.visit_request_id = ic.visit_request_id
JOIN visit_request_campuses vrc ON vrc.visit_instance_id = ic.visit_instance_id
JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
JOIN campuses campus ON campus.campus_id = vrc.campus_id
LEFT JOIN users invited_user ON invited_user.user_id = ic.new_user_id
LEFT JOIN users old_user ON old_user.user_id = ic.old_user_id
JOIN sent_email_recipients ser
  ON ser.sent_email_id = se.sent_email_id AND ser.recipient_type = 'TO'
CROSS JOIN (
  SELECT 'contactFullName' AS variable_name
  UNION ALL SELECT 'currentContactName'
  UNION ALL SELECT 'requestCode'
  UNION ALL SELECT 'delegationName'
  UNION ALL SELECT 'campusName'
  UNION ALL SELECT 'plannedTime'
) names
WHERE se.sent_email_id BETWEEN 64001 AND 64003;

-- Participant invitation/assignment variables.
INSERT INTO tmp_seed_email_render_variables
  (sent_email_id, variable_name, variable_value)
SELECT
  se.sent_email_id,
  names.variable_name,
  CASE names.variable_name
    WHEN 'recipientName' THEN COALESCE(NULLIF(TRIM(ser.recipient_name), ''), recipient.full_name)
    WHEN 'delegationName' THEN d.delegation_name
    WHEN 'campusName' THEN campus.name
    WHEN 'plannedTime' THEN CONCAT(
      DATE_FORMAT(vrc.planned_start_at, '%H:%i %d/%m/%Y'),
      ' - ', DATE_FORMAT(vrc.planned_end_at, '%H:%i %d/%m/%Y')
    )
    WHEN 'hostName' THEN COALESCE(host_user.full_name, 'Người phụ trách tiếp đón')
    WHEN 'roleLabel' THEN CASE vp.participant_role
      WHEN 'IC_SUPPORT' THEN 'Hỗ trợ Hợp tác Quốc tế'
      WHEN 'DEPT_SUPPORT' THEN 'Phối hợp phòng ban'
      WHEN 'STUDENT' THEN 'Sinh viên hỗ trợ'
      ELSE vp.participant_role
    END
    WHEN 'hostMessage' THEN COALESCE(NULLIF(TRIM(vp.note), ''), 'Vui lòng phản hồi để chốt thành phần tham gia.')
    WHEN 'departmentName' THEN COALESCE(recipient_department.name, 'Phòng ban phối hợp')
  END
FROM sent_emails se
JOIN visit_participants vp
  ON se.related_type = 'VISIT_PARTICIPANT' AND vp.participant_id = se.related_id
JOIN visit_request_campuses vrc ON vrc.visit_instance_id = vp.visit_instance_id
JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
JOIN campuses campus ON campus.campus_id = vrc.campus_id
JOIN users recipient ON recipient.user_id = vp.user_id
LEFT JOIN departments recipient_department ON recipient_department.department_id = recipient.department_id
LEFT JOIN users host_user ON host_user.user_id = vrc.current_host_user_id
JOIN sent_email_recipients ser
  ON ser.sent_email_id = se.sent_email_id AND ser.recipient_type = 'TO'
CROSS JOIN (
  SELECT 'recipientName' AS variable_name
  UNION ALL SELECT 'delegationName'
  UNION ALL SELECT 'campusName'
  UNION ALL SELECT 'plannedTime'
  UNION ALL SELECT 'hostName'
  UNION ALL SELECT 'roleLabel'
  UNION ALL SELECT 'hostMessage'
  UNION ALL SELECT 'departmentName'
) names
WHERE se.sent_email_id BETWEEN 64001 AND 64031;

-- Visit reminder variables. These rows use VISIT_INSTANCE, not a participant id.
INSERT INTO tmp_seed_email_render_variables
  (sent_email_id, variable_name, variable_value)
SELECT
  se.sent_email_id,
  names.variable_name,
  CASE names.variable_name
    WHEN 'hostName' THEN COALESCE(host_user.full_name, 'Người phụ trách tiếp đón')
    WHEN 'recipientName' THEN COALESCE(NULLIF(TRIM(ser.recipient_name), ''), 'Người tham gia')
    WHEN 'delegationName' THEN d.delegation_name
    WHEN 'campusName' THEN campus.name
    WHEN 'plannedStart' THEN DATE_FORMAT(vrc.planned_start_at, '%H:%i %d/%m/%Y')
    WHEN 'plannedEnd' THEN DATE_FORMAT(vrc.planned_end_at, '%H:%i %d/%m/%Y')
  END
FROM sent_emails se
JOIN visit_request_campuses vrc
  ON se.related_type = 'VISIT_INSTANCE' AND vrc.visit_instance_id = se.related_id
JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
JOIN campuses campus ON campus.campus_id = vrc.campus_id
LEFT JOIN users host_user ON host_user.user_id = vrc.current_host_user_id
JOIN sent_email_recipients ser
  ON ser.sent_email_id = se.sent_email_id AND ser.recipient_type = 'TO'
CROSS JOIN (
  SELECT 'hostName' AS variable_name
  UNION ALL SELECT 'recipientName'
  UNION ALL SELECT 'delegationName'
  UNION ALL SELECT 'campusName'
  UNION ALL SELECT 'plannedStart'
  UNION ALL SELECT 'plannedEnd'
) names
WHERE se.sent_email_id IN (64018, 64019, 64029);

-- Logistics variables come from the exact related item and its campus instance.
INSERT INTO tmp_seed_email_render_variables
  (sent_email_id, variable_name, variable_value)
SELECT
  se.sent_email_id,
  names.variable_name,
  CASE names.variable_name
    WHEN 'departmentLeaderName' THEN COALESCE(NULLIF(TRIM(ser.recipient_name), ''), 'Trưởng phòng ban')
    WHEN 'requesterName' THEN COALESCE(requester.full_name, 'Người phụ trách tiếp đón')
    WHEN 'logisticsTitle' THEN item.title
    WHEN 'logisticsItemType' THEN item.item_type
    WHEN 'quantity' THEN CAST(item.quantity AS CHAR)
    WHEN 'usageStartAt' THEN DATE_FORMAT(item.usage_start_at, '%H:%i %d/%m/%Y')
    WHEN 'usageEndAt' THEN DATE_FORMAT(item.usage_end_at, '%H:%i %d/%m/%Y')
    WHEN 'logisticsDescription' THEN COALESCE(NULLIF(TRIM(item.description), ''), 'Không có mô tả bổ sung.')
    WHEN 'assigneeName' THEN COALESCE(NULLIF(TRIM(ser.recipient_name), ''), assignee.full_name, 'Nhân sự phụ trách')
    WHEN 'dueAt' THEN COALESCE(DATE_FORMAT(item.due_at, '%H:%i %d/%m/%Y'), 'Chưa xác định')
    WHEN 'campusName' THEN campus.name
    WHEN 'delegationName' THEN d.delegation_name
    WHEN 'hostName' THEN COALESCE(host_user.full_name, 'Người phụ trách tiếp đón')
    WHEN 'departmentName' THEN COALESCE(department.name, 'Phòng ban phối hợp')
    WHEN 'originalQuantity' THEN CAST(item.quantity AS CHAR)
    WHEN 'proposedQuantity' THEN COALESCE(CAST(item.proposed_quantity AS CHAR), 'Chưa xác định')
    WHEN 'proposedUsageStartAt' THEN COALESCE(DATE_FORMAT(item.proposed_usage_start_at, '%H:%i %d/%m/%Y'), 'Chưa xác định')
    WHEN 'proposedUsageEndAt' THEN COALESCE(DATE_FORMAT(item.proposed_usage_end_at, '%H:%i %d/%m/%Y'), 'Chưa xác định')
    WHEN 'proposedDescription' THEN COALESCE(NULLIF(TRIM(item.proposed_description), ''), 'Không có mô tả bổ sung.')
    WHEN 'proposalNote' THEN COALESCE(NULLIF(TRIM(item.proposal_note), ''), 'Không có ghi chú bổ sung.')
    WHEN 'recipientName' THEN COALESCE(NULLIF(TRIM(ser.recipient_name), ''), 'Người phụ trách')
    WHEN 'itemTitle' THEN item.title
  END
FROM sent_emails se
JOIN visit_logistics_items item
  ON se.related_type = 'LOGISTICS_ITEM' AND item.logistics_item_id = se.related_id
JOIN visit_request_campuses vrc ON vrc.visit_instance_id = item.visit_instance_id
JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
JOIN campuses campus ON campus.campus_id = vrc.campus_id
LEFT JOIN users requester ON requester.user_id = item.requested_by
LEFT JOIN users assignee ON assignee.user_id = item.assigned_to_user_id
LEFT JOIN users host_user ON host_user.user_id = vrc.current_host_user_id
LEFT JOIN departments department ON department.department_id = item.requested_to_department_id
JOIN sent_email_recipients ser
  ON ser.sent_email_id = se.sent_email_id AND ser.recipient_type = 'TO'
CROSS JOIN (
  SELECT 'departmentLeaderName' AS variable_name
  UNION ALL SELECT 'requesterName'
  UNION ALL SELECT 'logisticsTitle'
  UNION ALL SELECT 'logisticsItemType'
  UNION ALL SELECT 'quantity'
  UNION ALL SELECT 'usageStartAt'
  UNION ALL SELECT 'usageEndAt'
  UNION ALL SELECT 'logisticsDescription'
  UNION ALL SELECT 'assigneeName'
  UNION ALL SELECT 'dueAt'
  UNION ALL SELECT 'campusName'
  UNION ALL SELECT 'delegationName'
  UNION ALL SELECT 'hostName'
  UNION ALL SELECT 'departmentName'
  UNION ALL SELECT 'originalQuantity'
  UNION ALL SELECT 'proposedQuantity'
  UNION ALL SELECT 'proposedUsageStartAt'
  UNION ALL SELECT 'proposedUsageEndAt'
  UNION ALL SELECT 'proposedDescription'
  UNION ALL SELECT 'proposalNote'
  UNION ALL SELECT 'recipientName'
  UNION ALL SELECT 'itemTitle'
) names
WHERE se.sent_email_id BETWEEN 64001 AND 64031;

DROP PROCEDURE IF EXISTS pems_seed_render_email_history;
DELIMITER $$
CREATE PROCEDURE pems_seed_render_email_history()
BEGIN
  DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE v_sent_email_id BIGINT UNSIGNED;
  DECLARE v_variable_name VARCHAR(100);
  DECLARE v_variable_value LONGTEXT;

  DECLARE render_cursor CURSOR FOR
    SELECT sent_email_id, variable_name, variable_value
    FROM tmp_seed_email_render_variables
    ORDER BY sent_email_id, variable_name;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = TRUE;

  OPEN render_cursor;
  render_loop: LOOP
    FETCH render_cursor INTO v_sent_email_id, v_variable_name, v_variable_value;
    IF v_done THEN
      LEAVE render_loop;
    END IF;

    UPDATE sent_emails
    SET subject = REPLACE(subject, CONCAT('{{', v_variable_name, '}}'), v_variable_value),
        body_snapshot = REPLACE(body_snapshot, CONCAT('{{', v_variable_name, '}}'), v_variable_value)
    WHERE sent_email_id = v_sent_email_id;
  END LOOP;
  CLOSE render_cursor;
END$$
DELIMITER ;

CALL pems_seed_render_email_history();
DROP PROCEDURE IF EXISTS pems_seed_render_email_history;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_email_render_variables;

COMMIT;

-- ---------------------------------------------------------------------------
-- R8. Code-grounded verification. Every invalid_* result below must be 0.
-- ---------------------------------------------------------------------------
SELECT 'invalid_01_automated_email_without_template' AS check_name, COUNT(*) AS issue_count
FROM sent_emails
WHERE email_template_id IS NULL;

SELECT 'invalid_02_orphan_recipient' AS check_name, COUNT(*) AS issue_count
FROM sent_email_recipients ser
LEFT JOIN sent_emails se ON se.sent_email_id=ser.sent_email_id
WHERE se.sent_email_id IS NULL;

SELECT 'invalid_03_visit_detail_related_type' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
JOIN email_templates et ON et.email_template_id=se.email_template_id
WHERE (et.template_code IN (
         'VISIT_PARTICIPANT_INVITATION','VISIT_STUDENT_INVITATION',
         'VISIT_DEPARTMENT_LEADER_INVITATION','VISIT_DEPARTMENT_STAFF_ASSIGNMENT'
       ) AND se.related_type<>'VISIT_PARTICIPANT')
   OR (et.template_code IN (
         'VISIT_REMINDER_HOST','VISIT_REMINDER_PARTICIPANTS'
       ) AND se.related_type<>'VISIT_INSTANCE')
   OR (et.template_code IN (
         'LOGISTICS_REQUEST_TO_DEPARTMENT','LOGISTICS_ASSIGNEE_ASSIGNMENT',
         'LOGISTICS_CHANGE_PROPOSAL_TO_HOST','LOGISTICS_EXPENSE_REPORT_REMINDER'
       ) AND se.related_type<>'LOGISTICS_ITEM');

SELECT 'invalid_04_host_driven_email_wrong_sender' AS check_name,
       COALESCE(SUM(x.issue_count),0) AS issue_count
FROM (
  SELECT COUNT(*) AS issue_count
  FROM sent_emails se
  JOIN email_templates et ON et.email_template_id=se.email_template_id
  JOIN visit_participants vp
    ON se.related_type='VISIT_PARTICIPANT' AND vp.participant_id=se.related_id
  JOIN visit_request_campuses vrc ON vrc.visit_instance_id=vp.visit_instance_id
  WHERE et.template_code IN (
          'VISIT_PARTICIPANT_INVITATION','VISIT_STUDENT_INVITATION',
          'VISIT_DEPARTMENT_LEADER_INVITATION'
        )
    AND (se.sent_by IS NULL OR vrc.current_host_user_id IS NULL
         OR se.sent_by<>vrc.current_host_user_id)
  UNION ALL
  SELECT COUNT(*) AS issue_count
  FROM sent_emails se
  JOIN email_templates et ON et.email_template_id=se.email_template_id
  JOIN visit_logistics_items vli
    ON se.related_type='LOGISTICS_ITEM' AND vli.logistics_item_id=se.related_id
  JOIN visit_request_campuses vrc ON vrc.visit_instance_id=vli.visit_instance_id
  WHERE et.template_code='LOGISTICS_REQUEST_TO_DEPARTMENT'
    AND (se.sent_by IS NULL OR vrc.current_host_user_id IS NULL
         OR se.sent_by<>vrc.current_host_user_id)
) x;

SELECT 'invalid_05_host_email_before_assignment' AS check_name,
       COALESCE(SUM(x.issue_count),0) AS issue_count
FROM (
  SELECT COUNT(*) AS issue_count
  FROM sent_emails se
  JOIN email_templates et ON et.email_template_id=se.email_template_id
  JOIN visit_participants vp
    ON se.related_type='VISIT_PARTICIPANT' AND vp.participant_id=se.related_id
  JOIN visit_request_campuses vrc ON vrc.visit_instance_id=vp.visit_instance_id
  WHERE et.template_code IN (
          'VISIT_PARTICIPANT_INVITATION','VISIT_STUDENT_INVITATION',
          'VISIT_DEPARTMENT_LEADER_INVITATION'
        )
    AND (se.sent_at IS NULL OR se.sent_at<vrc.host_assigned_at)
  UNION ALL
  SELECT COUNT(*) AS issue_count
  FROM sent_emails se
  JOIN email_templates et ON et.email_template_id=se.email_template_id
  JOIN visit_logistics_items vli
    ON se.related_type='LOGISTICS_ITEM' AND vli.logistics_item_id=se.related_id
  JOIN visit_request_campuses vrc ON vrc.visit_instance_id=vli.visit_instance_id
  WHERE et.template_code='LOGISTICS_REQUEST_TO_DEPARTMENT'
    AND (se.sent_at IS NULL OR se.sent_at<vrc.host_assigned_at)
) x;

SELECT 'invalid_06_story_missing_queryable_email' AS check_name, COUNT(*) AS issue_count
FROM (
  SELECT CONCAT('PARTICIPANT:',vp.participant_id) AS story_key
  FROM visit_participants vp
  WHERE vp.participant_id BETWEEN 44018 AND 44033
    AND NOT EXISTS (
      SELECT 1 FROM sent_emails se
      WHERE se.related_type='VISIT_PARTICIPANT'
        AND se.related_id=vp.participant_id
    )
  UNION ALL
  SELECT CONCAT('LOGISTICS:',vli.logistics_item_id) AS story_key
  FROM visit_logistics_items vli
  WHERE vli.logistics_item_id BETWEEN 48004 AND 48007
    AND NOT EXISTS (
      SELECT 1 FROM sent_emails se
      WHERE se.related_type='LOGISTICS_ITEM'
        AND se.related_id=vli.logistics_item_id
    )
) missing_story;

SELECT 'invalid_07_sent_delivery_shape' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
WHERE se.status='SENT'
  AND (se.sent_at IS NULL OR se.provider_message_id IS NULL
       OR EXISTS (
         SELECT 1 FROM sent_email_recipients ser
         WHERE ser.sent_email_id=se.sent_email_id
           AND (ser.delivery_status<>'SENT' OR ser.sent_at IS NULL
                OR ser.provider_message_id IS NULL OR ser.delivered_at IS NOT NULL)
       ));

SELECT 'invalid_08_queued_delivery_shape' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
WHERE se.status='QUEUED'
  AND (se.sent_at IS NOT NULL OR se.provider_message_id IS NOT NULL
       OR EXISTS (
         SELECT 1 FROM sent_email_recipients ser
         WHERE ser.sent_email_id=se.sent_email_id
           AND (ser.delivery_status<>'QUEUED' OR ser.sent_at IS NOT NULL
                OR ser.provider_message_id IS NOT NULL)
       ));

SELECT 'invalid_09_delivered_without_webhook' AS check_name, COUNT(*) AS issue_count
FROM (
  SELECT sent_email_id AS row_id FROM sent_emails WHERE status='DELIVERED'
  UNION ALL
  SELECT sent_email_recipient_id AS row_id
  FROM sent_email_recipients WHERE delivery_status='DELIVERED'
) delivered_rows;

SELECT 'invalid_10_sensitive_artifact_in_history' AS check_name, COUNT(*) AS issue_count
FROM sent_emails
WHERE body_snapshot REGEXP '(https?://|[?&](token|otp)=|otpCode|raw[[:space:]]+token)';

SELECT 'invalid_11_token_hash_shape' AS check_name, COUNT(*) AS issue_count
FROM email_action_tokens
WHERE token_hash NOT REGEXP '^[0-9a-fA-F]{64}$';

SELECT 'invalid_12_document_without_file' AS check_name, COUNT(*) AS issue_count
FROM documents d
LEFT JOIN files f ON f.file_id=d.file_id
WHERE f.file_id IS NULL;

SELECT 'invalid_13_document_owner_missing' AS check_name, COUNT(*) AS issue_count
FROM documents d
WHERE (d.owner_type='VISIT' AND
       (d.owner_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM visit_requests vr WHERE vr.visit_request_id=d.owner_id)))
   OR (d.owner_type='MINUTES' AND
       (d.owner_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM minutes m WHERE m.minutes_id=d.owner_id)))
   OR (d.owner_type='PARTNER' AND
       (d.owner_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM partners p WHERE p.partner_id=d.owner_id)))
   OR (d.owner_type='LOGISTICS' AND
       (d.owner_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM visit_logistics_items vli WHERE vli.logistics_item_id=d.owner_id)));

SELECT 'invalid_14_document_campus_mismatch' AS check_name, COUNT(*) AS issue_count
FROM documents d
WHERE d.document_id BETWEEN 62001 AND 62015
  AND (
    (d.owner_type='VISIT' AND NOT EXISTS (
       SELECT 1 FROM visit_request_campuses vrc
       WHERE vrc.visit_request_id=d.owner_id AND vrc.campus_id=d.campus_id))
    OR
    (d.owner_type='MINUTES' AND NOT EXISTS (
       SELECT 1
       FROM minutes m
       JOIN visit_request_campuses vrc ON vrc.visit_instance_id=m.visit_instance_id
       WHERE m.minutes_id=d.owner_id AND vrc.campus_id=d.campus_id))
  );

SELECT 'invalid_15_attachment_without_file' AS check_name, COUNT(*) AS issue_count
FROM sent_email_attachments sea
LEFT JOIN files f ON f.file_id=sea.file_id
WHERE f.file_id IS NULL;

SELECT 'invalid_16_report_attachment_document_mismatch' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
JOIN email_templates et ON et.email_template_id=se.email_template_id
WHERE et.template_code IN (
        'REPORT_CAMPUS_OPERATION','REPORT_DEPARTMENT_COLLABORATION',
        'REPORT_DEPARTMENT_INVOICE','REPORT_PERSONNEL_PERFORMANCE'
      )
  AND NOT EXISTS (
    SELECT 1
    FROM sent_email_attachments sea
    JOIN documents d ON d.file_id=sea.file_id AND d.owner_type='REPORT'
    WHERE sea.sent_email_id=se.sent_email_id
      AND d.status='PUBLISHED'
      AND d.created_at<=se.created_at
  );

-- Campus chưa có đầu mối BẮT BUỘC có lời mời PENDING của đúng campus đó.
SELECT 'invalid_17_unconfirmed_campus_without_invitation' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
WHERE vrc.status='WAITING_CONTACT_CONFIRMATION'
  AND NOT EXISTS (
    SELECT 1 FROM visit_request_identity_changes ic
    WHERE ic.visit_instance_id=vrc.visit_instance_id
      AND ic.status='PENDING'
  );

-- Lời mời còn PENDING thì campus tương ứng KHÔNG được đã có đầu mối.
SELECT 'invalid_18_pending_invitation_on_confirmed_campus' AS check_name, COUNT(*) AS issue_count
FROM visit_request_identity_changes ic
JOIN visit_request_campuses vrc ON vrc.visit_instance_id=ic.visit_instance_id
WHERE ic.status='PENDING'
  AND vrc.operational_contact_user_id IS NOT NULL;

SELECT 'invalid_19_notification_only_seeded_as_email' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
JOIN email_templates et ON et.email_template_id=se.email_template_id
WHERE et.template_code IN (
  'VISIT_REQUEST_APPROVED','VISIT_REQUEST_REJECTED','VISIT_CANCELLED',
  'HOST_ASSIGNMENT','VISIT_REQUEST_SUBMITTED_NOTIFY',
  'LOGISTICS_REQUEST_SUBMITTED_NOTIFY'
);

SELECT 'invalid_20_generic_document_title' AS check_name, COUNT(*) AS issue_count
FROM documents
WHERE title REGEXP '(coverage[[:space:]]+[0-9]+|document[[:space:]]+coverage)';

-- Mỗi cơ sở phải có ít nhất 1 khách trong đoàn. Không write path nào tạo được cơ sở 0 khách
-- (CampusVisitFormDtoValidator dùng chung cho create / pending-edit / resubmit, và validator
-- amendment cũng vậy), nên seed cũng không được dựng ra trạng thái đó. Chạy SAU khối §4.4 để phủ
-- toàn bộ campus đã seed, không chỉ các dải cũ.
SELECT 'invalid_21_campus_without_visitor' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
WHERE NOT EXISTS (
  SELECT 1
  FROM visit_instance_guest_members l
  JOIN visit_guest_members m
    ON m.guest_member_id = l.guest_member_id
   AND m.visit_request_id = l.visit_request_id
  WHERE l.visit_instance_id = vrc.visit_instance_id
    AND m.member_type = 'GUEST'
);


SELECT 'invalid_22_operational_contact_non_visitor' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
JOIN users u ON u.user_id = vrc.operational_contact_user_id
JOIN roles r ON r.role_id = u.role_id
WHERE vrc.operational_contact_user_id IS NOT NULL
  AND (r.role_code <> 'VISITOR' OR u.status <> 'ACTIVE');

SELECT 'invalid_23_operational_contact_snapshot_identity_mismatch' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
JOIN users u ON u.user_id = vrc.operational_contact_user_id
JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
WHERE vrc.operational_contact_user_id IS NOT NULL
  AND (
       LOWER(TRIM(d.operational_contact_email)) <> LOWER(TRIM(u.email))
    OR TRIM(d.operational_contact_full_name) <> TRIM(u.full_name)
  );

SELECT 'invalid_24_invalid_registrant_self_match_source' AS check_name, COUNT(*) AS issue_count
FROM visit_request_campuses vrc
JOIN visit_requests vr ON vr.visit_request_id = vrc.visit_request_id
WHERE vrc.operational_contact_confirmation_source = 'REGISTRANT_SELF_MATCH'
  AND NOT (vrc.operational_contact_user_id <=> vr.registrant_user_id);

SELECT 'invalid_25_applied_contact_confirmation_non_visitor' AS check_name, COUNT(*) AS issue_count
FROM visit_request_identity_changes ic
LEFT JOIN users u ON u.user_id = ic.new_user_id
LEFT JOIN roles r ON r.role_id = u.role_id
WHERE ic.status = 'APPLIED'
  AND (
       ic.new_user_id IS NULL
    OR r.role_code IS NULL
    OR r.role_code <> 'VISITOR'
    OR u.status <> 'ACTIVE'
  );

SELECT 'invalid_26_non_materialized_file_seed' AS check_name, COUNT(*) AS issue_count
FROM files;

SELECT 'invalid_27_non_materialized_document_seed' AS check_name, COUNT(*) AS issue_count
FROM documents;

SELECT 'invalid_28_non_materialized_email_attachment_seed' AS check_name, COUNT(*) AS issue_count
FROM sent_email_attachments;

SELECT 'invalid_29_unresolved_email_template_variable' AS check_name, COUNT(*) AS issue_count
FROM sent_emails
WHERE subject REGEXP '\\{\\{[^}]+\\}\\}'
   OR body_snapshot REGEXP '\\{\\{[^}]+\\}\\}';

SELECT 'invalid_30_email_history_not_rendered_from_template' AS check_name, COUNT(*) AS issue_count
FROM sent_emails se
JOIN email_templates et ON et.email_template_id = se.email_template_id
WHERE se.sent_email_id BETWEEN 64001 AND 64031
  AND (
       se.body_format <> 'HTML'
    OR se.body_snapshot NOT LIKE '<!DOCTYPE html>%PEMS — Campus Visit%'
    OR se.subject IS NULL
    OR TRIM(se.subject) = ''
  );

SELECT 'curated_email_history_rows' AS metric, COUNT(*) AS value
FROM sent_emails
WHERE sent_email_id BETWEEN 64001 AND 64031;

-- Coverage output for role/relationship/status, template/event, visit-detail
-- email history and contact claims.
SELECT role_code, relationship_type, reachable_status, COUNT(*) AS story_count
FROM (
  SELECT r.role_code, 'REGISTRANT' AS relationship_type, vr.status AS reachable_status
  FROM visit_requests vr
  JOIN users u ON u.user_id=vr.registrant_user_id
  JOIN roles r ON r.role_id=u.role_id
  WHERE vr.visit_request_id BETWEEN 41001 AND 41028
  UNION ALL
  SELECT r.role_code, 'HOST' AS relationship_type, vrc.status AS reachable_status
  FROM visit_request_campuses vrc
  JOIN users u ON u.user_id=vrc.current_host_user_id
  JOIN roles r ON r.role_id=u.role_id
  WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
  UNION ALL
  SELECT r.role_code, vp.participant_role AS relationship_type, vp.status AS reachable_status
  FROM visit_participants vp
  JOIN users u ON u.user_id=vp.user_id
  JOIN roles r ON r.role_id=u.role_id
  WHERE vp.participant_id BETWEEN 44018 AND 44033
) role_story
GROUP BY role_code, relationship_type, reachable_status
ORDER BY role_code, relationship_type, reachable_status;

SELECT et.template_code, se.related_type, se.status, COUNT(*) AS seeded_event_count
FROM email_templates et
LEFT JOIN sent_emails se ON se.email_template_id=et.email_template_id
GROUP BY et.template_code, se.related_type, se.status
ORDER BY et.template_code, se.related_type, se.status;

SELECT vrc.visit_request_id, vrc.visit_instance_id,
       COUNT(DISTINCT se.sent_email_id) AS participant_email_count
FROM visit_request_campuses vrc
LEFT JOIN visit_participants vp ON vp.visit_instance_id=vrc.visit_instance_id
LEFT JOIN sent_emails se
  ON se.related_type='VISIT_PARTICIPANT' AND se.related_id=vp.participant_id
WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
GROUP BY vrc.visit_request_id, vrc.visit_instance_id
HAVING participant_email_count>0
ORDER BY vrc.visit_instance_id;

SELECT vrc.visit_request_id, vrc.visit_instance_id,
       COUNT(DISTINCT se.sent_email_id) AS logistics_email_count
FROM visit_request_campuses vrc
LEFT JOIN visit_logistics_items vli ON vli.visit_instance_id=vrc.visit_instance_id
LEFT JOIN sent_emails se
  ON se.related_type='LOGISTICS_ITEM' AND se.related_id=vli.logistics_item_id
WHERE vrc.visit_instance_id BETWEEN 42001 AND 42031
GROUP BY vrc.visit_request_id, vrc.visit_instance_id
HAVING logistics_email_count>0
ORDER BY vrc.visit_instance_id;

SELECT ic.identity_change_id, ic.visit_request_id, ic.change_kind, ic.status,
       ic.new_email_masked, ic.requested_at, ic.expires_at,
       COUNT(DISTINCT se.sent_email_id) AS email_count,
       COUNT(DISTINCT eat.email_action_token_id) AS action_token_count
FROM visit_request_identity_changes ic
LEFT JOIN sent_emails se
  ON se.related_type='VisitRequestIdentityChange' AND se.related_id=ic.identity_change_id
LEFT JOIN email_action_tokens eat ON eat.sent_email_id=se.sent_email_id
WHERE ic.identity_change_id BETWEEN 67001 AND 67003
GROUP BY ic.identity_change_id, ic.visit_request_id, ic.change_kind, ic.status,
         ic.new_email_masked, ic.requested_at, ic.expires_at
ORDER BY ic.identity_change_id;

-- ---------------------------------------------------------------------------
-- Request status recomputed from the campuses, for every seeded request.
--
-- The seed writes visit_requests.status by hand and visit_request_campuses.status by hand, and the
-- two drifted: 14 requests ended up claiming PENDING_APPROVAL over campuses that had all been
-- decided — request 2002 said "chờ duyệt" while both its campuses were REJECTED. A detail screen
-- shows the request badge and the campus outcome side by side, so the contradiction was on screen.
--
-- This is the SAME rule as VisitRequestAggregateStatusService.Compute, in the same order, so the
-- seed cannot disagree with what the application would have written:
--   CANCELLED wins outright · then the contact gate · then all-rejected · then partial · approved ·
--   pending. A campus that is CANCELLED leaves every denominator.
-- ---------------------------------------------------------------------------
UPDATE visit_requests r
JOIN (
  SELECT visit_request_id,
         SUM(status <> 'CANCELLED')                                        AS active,
         SUM(status IN ('ASSIGNED','BEFORE_VISIT','DURING_VISIT','AFTER_VISIT','CLOSED')) AS approved,
         SUM(status IN ('WAITING_CONTACT_CONFIRMATION','WAITING_REQUEST_APPROVAL'))       AS pending,
         SUM(status = 'REJECTED')                                          AS rejected,
         SUM(status <> 'CANCELLED' AND operational_contact_user_id IS NULL) AS unconfirmed
  FROM visit_request_campuses
  GROUP BY visit_request_id
) a ON a.visit_request_id = r.visit_request_id
SET r.status = CASE
  WHEN a.unconfirmed > 0                        THEN 'PENDING_CONTACT_CONFIRMATION'
  WHEN a.active > 0 AND a.rejected = a.active    THEN 'REJECTED'
  WHEN a.approved > 0 AND a.pending > 0          THEN 'PARTIALLY_APPROVED'
  WHEN a.approved > 0                            THEN 'APPROVED'
  WHEN a.pending > 0                             THEN 'PENDING_APPROVAL'
  ELSE r.status                                  -- every campus cancelled: leave it alone
END
WHERE r.status <> 'CANCELLED';                   -- request-level cancellation is final

SET FOREIGN_KEY_CHECKS = @pems_old_fk_checks;
SET SQL_SAFE_UPDATES = @pems_old_safe_updates;
-- ============================================================================
-- END PEMS CURATED SEED REBUILD
-- ============================================================================
--


-- Make phone numbers optional for visit requests
ALTER TABLE visit_requests
    MODIFY COLUMN registrant_phone VARCHAR(50) NULL;


-- ============================================================================
-- SEED DEFAULT CONFIGURATION FOR RESEND EMAIL SERVICE
