INSERT INTO api_configurations (
    api_code,
    name,
    provider_name,
    purpose,
    base_url,
    default_method,
    auth_type,
    status,
    data_sensitivity,
    settings_json,
    created_at
) VALUES (
    'RESEND_EMAIL_DELIVERY',
    'Resend - Gửi email hệ thống',
    'Resend',
    'EMAIL_DELIVERY',
    'https://api.resend.com',
    'POST',
    'BEARER_TOKEN',
    'INACTIVE',
    'CONFIDENTIAL',
    '{"from_email":"no-reply@mail.pems-fpt.site","from_name":"PEMS System","reply_to_email":"managementsystemvolunteer@gmail.com","reply_to_name":"Ban quản trị PEMS"}',
    NOW()
) ON DUPLICATE KEY UPDATE updated_at = NOW();

-- ============================================================================
-- CURATED SEED QUALITY GATE
-- Fails the import when the final data reintroduces the two known defects,
-- stale Head Office approval semantics, request/campus drift, blank Operational
-- Contact job titles, or obvious generated placeholder content.
-- ============================================================================
DROP PROCEDURE IF EXISTS sp_pems_assert_curated_seed_quality;
DELIMITER $$
CREATE PROCEDURE sp_pems_assert_curated_seed_quality()
BEGIN
  DECLARE v_issue_count INT DEFAULT 0;
  DECLARE v_message VARCHAR(255);

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  WHERE vrc.status IN ('DURING_VISIT','AFTER_VISIT','CLOSED')
    AND NOT EXISTS (
      SELECT 1
      FROM visit_agendas va
      WHERE va.visit_instance_id = vrc.visit_instance_id
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: operational campus instances without agenda = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  -- Mỗi campus phải có ít nhất 1 khách trong đoàn. Cùng hạng với check agenda ở trên: đây là ràng
  -- buộc "campus thiếu tập con bắt buộc", và không write path nào tạo được trạng thái này
  -- (CampusVisitFormDtoValidator dùng chung cho create/pending-edit/resubmit, validator amendment
  -- cũng vậy) — nên seed dựng ra nó là seed sai, phải dừng import chứ không chỉ in ra một con số.
  -- invalid_21_campus_without_visitor ở phần trên report cùng ràng buộc này, y như cặp
  -- operational_visit_instances_missing_agenda / check agenda ngay trên đây.
  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  WHERE NOT EXISTS (
      SELECT 1
      FROM visit_instance_guest_members l
      JOIN visit_guest_members m
        ON m.guest_member_id = l.guest_member_id
       AND m.visit_request_id = l.visit_request_id
      WHERE l.visit_instance_id = vrc.visit_instance_id
        AND m.member_type = 'GUEST'
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: campus instances without any guest = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COALESCE(SUM(x.issue_count), 0) INTO v_issue_count
  FROM (
    SELECT COUNT(*) AS issue_count
    FROM sent_emails se
    JOIN email_templates et
      ON et.email_template_id = se.email_template_id
    JOIN visit_participants vp
      ON se.related_type = 'VISIT_PARTICIPANT'
     AND vp.participant_id = se.related_id
    JOIN visit_request_campuses vrc
      ON vrc.visit_instance_id = vp.visit_instance_id
    WHERE et.template_code IN (
            'VISIT_PARTICIPANT_INVITATION',
            'VISIT_STUDENT_INVITATION',
            'VISIT_DEPARTMENT_LEADER_INVITATION'
          )
      AND (
        se.sent_by IS NULL
        OR vrc.current_host_user_id IS NULL
        OR se.sent_by <> vrc.current_host_user_id
      )

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM sent_emails se
    JOIN email_templates et
      ON et.email_template_id = se.email_template_id
    JOIN visit_logistics_items vli
      ON se.related_type = 'LOGISTICS_ITEM'
     AND vli.logistics_item_id = se.related_id
    JOIN visit_request_campuses vrc
      ON vrc.visit_instance_id = vli.visit_instance_id
    WHERE et.template_code = 'LOGISTICS_REQUEST_TO_DEPARTMENT'
      AND (
        se.sent_by IS NULL
        OR vrc.current_host_user_id IS NULL
        OR se.sent_by <> vrc.current_host_user_id
      )
  ) x;

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: Host-driven emails with wrong sender = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  JOIN users u ON u.user_id = vrc.operational_contact_user_id
  JOIN roles r ON r.role_id = u.role_id
  WHERE vrc.operational_contact_user_id IS NOT NULL
    AND (r.role_code <> 'VISITOR' OR u.status <> 'ACTIVE');

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: Operational Contacts not ACTIVE VISITOR = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  JOIN users u ON u.user_id = vrc.operational_contact_user_id
  JOIN visit_instance_form_details d ON d.visit_instance_id = vrc.visit_instance_id
  WHERE vrc.operational_contact_user_id IS NOT NULL
    AND (
         LOWER(TRIM(d.operational_contact_email)) <> LOWER(TRIM(u.email))
      OR TRIM(d.operational_contact_full_name) <> TRIM(u.full_name)
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: Operational Contact snapshot/account mismatches = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_campuses vrc
  JOIN visit_requests vr ON vr.visit_request_id = vrc.visit_request_id
  WHERE vrc.operational_contact_confirmation_source = 'REGISTRANT_SELF_MATCH'
    AND NOT (vrc.operational_contact_user_id <=> vr.registrant_user_id);

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: invalid REGISTRANT_SELF_MATCH contacts = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_request_identity_changes ic
  LEFT JOIN users u ON u.user_id = ic.new_user_id
  LEFT JOIN roles r ON r.role_id = u.role_id
  WHERE ic.status = 'APPLIED'
    AND (
         ic.new_user_id IS NULL
      OR r.role_code IS NULL
      OR r.role_code <> 'VISITOR'
      OR u.status <> 'ACTIVE'
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: APPLIED contact confirmations not ACTIVE VISITOR = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_instance_form_details d
  WHERE d.operational_contact_job_title IS NULL
     OR TRIM(d.operational_contact_job_title) = '';

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: blank Operational Contact job titles = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM visit_requests r
  JOIN (
    SELECT
      visit_request_id,
      SUM(status <> 'CANCELLED') AS active_count,
      SUM(status IN (
        'ASSIGNED','BEFORE_VISIT','DURING_VISIT','AFTER_VISIT','CLOSED'
      )) AS approved_count,
      SUM(status IN (
        'WAITING_CONTACT_CONFIRMATION','WAITING_REQUEST_APPROVAL'
      )) AS pending_count,
      SUM(status = 'REJECTED') AS rejected_count,
      SUM(
        status <> 'CANCELLED'
        AND operational_contact_user_id IS NULL
      ) AS unconfirmed_count
    FROM visit_request_campuses
    GROUP BY visit_request_id
  ) a
    ON a.visit_request_id = r.visit_request_id
  WHERE r.status <> 'CANCELLED'
    AND r.status <> CASE
      WHEN a.unconfirmed_count > 0
        THEN 'PENDING_CONTACT_CONFIRMATION'
      WHEN a.active_count > 0
       AND a.rejected_count = a.active_count
        THEN 'REJECTED'
      WHEN a.approved_count > 0
       AND a.pending_count > 0
        THEN 'PARTIALLY_APPROVED'
      WHEN a.approved_count > 0
        THEN 'APPROVED'
      WHEN a.pending_count > 0
        THEN 'PENDING_APPROVAL'
      ELSE r.status
    END;

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: request/campus status mismatches = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COALESCE(SUM(x.issue_count), 0) INTO v_issue_count
  FROM (
    SELECT COUNT(*) AS issue_count
    FROM notifications
    WHERE notification_type = 'VISIT_WAITING_HO_APPROVAL'
       OR LOWER(CONCAT_WS(' ', title, message)) REGEXP
          '(chờ[[:space:]]+ho|ho[[:space:]]+(duyệt|phê duyệt|từ chối)|head office[[:space:]]+(approval|approve|reject))'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM email_templates
    WHERE LOWER(CONCAT_WS(' ', name, description, subject_vi, body_vi, subject_en, body_en)) REGEXP
          '(chờ[[:space:]]+ho|ho[[:space:]]+(duyệt|phê duyệt|từ chối)|head office[[:space:]]+(approval|approve|reject))'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM calendar_events
    WHERE LOWER(CONCAT_WS(' ', title, description)) REGEXP
          '(chờ[[:space:]]+ho|ho[[:space:]]+(duyệt|phê duyệt|từ chối)|head office[[:space:]]+(approval|approve|reject))'
  ) x;

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: stale Head Office approval content = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;


  -- API configuration seed must mirror the current Dev runtime exactly: five
  -- well-known integrations, no legacy/factory rows, no fabricated request logs
  -- or custom headers, and quotas only for features that actually enforce them.
  SELECT COUNT(*) INTO v_issue_count
  FROM api_configurations
  WHERE deleted_at IS NULL;

  IF v_issue_count <> 5 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: live API configurations must equal 5, actual = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM api_configurations
  WHERE deleted_at IS NULL
    AND api_code NOT IN (
      'GOOGLE_DRIVE_STORAGE',
      'BUSINESS_CARD_OCR_GOOGLE_DOCUMENT_AI',
      'NEWS_TRANSLATION_GOOGLE_CLOUD',
      'FACE_DETECTION_GOOGLE_VISION',
      'RESEND_EMAIL_DELIVERY'
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: unsupported API configuration rows = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count FROM api_configuration_headers;
  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: seeded API configuration headers = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count FROM api_request_logs;
  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: fabricated API request logs = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM api_usage_quotas q
  JOIN api_configurations c ON c.api_config_id = q.api_config_id
  WHERE c.api_code NOT IN (
    'BUSINESS_CARD_OCR_GOOGLE_DOCUMENT_AI',
    'FACE_DETECTION_GOOGLE_VISION'
  );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: quotas seeded for non-enforced API integrations = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COUNT(*) INTO v_issue_count
  FROM api_configurations
  WHERE deleted_at IS NULL
    AND (
      last_test_status IS NOT NULL
      OR last_tested_at IS NOT NULL
      OR last_test_message IS NOT NULL
    );

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: fabricated API connection-test history rows = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;

  SELECT COALESCE(SUM(x.issue_count), 0) INTO v_issue_count
  FROM (
    SELECT COUNT(*) AS issue_count
    FROM photo_face_tags
    WHERE LOWER(COALESCE(display_name, '')) REGEXP
          '(người trong ảnh[[:space:]]*[0-9]+|person[[:space:]]*[0-9]+)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM visit_guest_members
    WHERE LOWER(CONCAT_WS(
      ' ', full_name, organization, job_title
    )) REGEXP
      '(coverage|dummy|sample|generated|placeholder|recipient[[:space:]]*[0-9]+|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM partner_contacts
    WHERE LOWER(CONCAT_WS(' ', full_name, note)) REGEXP
      '(coverage|dummy|sample|generated|placeholder|contact[[:space:]]*[0-9]+|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM minute_action_items
    WHERE LOWER(CONCAT_WS(' ', title, note)) REGEXP
      '(coverage|dummy|sample|generated|placeholder|action item .* minutes|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM visit_logistics_items
    WHERE LOWER(CONCAT_WS(' ', title, description)) REGEXP
      '(coverage item|dummy|sample item|generated item|placeholder|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM news_translations
    WHERE LOWER(CONCAT_WS(' ', title, summary)) REGEXP
      '(coverage news|bản tin kiểm thử|dummy|placeholder|plain text section[[:space:]]*[0-9]+)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM faqs
    WHERE LOWER(CONCAT_WS(' ', question, answer)) REGEXP
      '(test question|câu hỏi kiểm thử|dummy|placeholder|dữ liệu mẫu)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM notifications
    WHERE LOWER(CONCAT_WS(' ', title, message)) REGEXP
      '(coverage notification|dummy|placeholder|recipient[[:space:]]*[0-9]+|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM sent_emails
    WHERE LOWER(CONCAT_WS(' ', subject, body_snapshot)) REGEXP
      '(email coverage|dummy|placeholder|recipient[[:space:]]*[0-9]+|dữ liệu mẫu|kiểm thử)'

    UNION ALL

    SELECT COUNT(*) AS issue_count
    FROM documents
    WHERE LOWER(CONCAT_WS(' ', title, description)) REGEXP
      '(document coverage|coverage[[:space:]]+[0-9]+|dummy|placeholder|dữ liệu mẫu|kiểm thử)'
  ) x;

  IF v_issue_count <> 0 THEN
    SET v_message = CONCAT(
      'CURATED_SEED_INVALID: generated placeholder business content = ',
      v_issue_count
    );
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_message;
  END IF;
END$$
DELIMITER ;

CALL sp_pems_assert_curated_seed_quality();
DROP PROCEDURE IF EXISTS sp_pems_assert_curated_seed_quality;

SELECT
  'curated_seed_quality_gate' AS check_name,
  'PASS' AS result,
  'Operational agendas, Host email senders, campus statuses, Visitor-only operational contacts, API integration seed minimalism, HO semantics and visible seed content are valid.' AS details;
